window.HYMN_BOOKS={"louvai": {"name": "Louvai ao Senhor", "hymns": [{"number": 1, "title": "CANTAI AO SENHOR (Sl 98.1)", "page": 1, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Cantai ao Senhor, um cântico novo} (3 vezes)\nCantai ao Senhor, cantai ao Senhor."}, {"label": "Estrofe 2", "text": "{Porque Ele fez, Ele fez maravilhas} (3 vezes).\nCantai ao Senhor, cantai ao Senhor."}, {"label": "Estrofe 3", "text": "{É Ele quem dá o Espírito Santo} (3 vezes)\nCantai ao Senhor, cantai ao Senhor."}, {"label": "Estrofe 4", "text": "{Louvai ao Senhor, amém, aleluia} (3 vezes).\nLouvai ao Senhor, louvai ao Senhor."}], "reviewed": false}, {"number": 2, "title": "EU QUERO SER", "page": 1, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu quero ser, Senhor amado,\nComo um vaso nas mãos do oleiro.\nQuebra minha vida, e faze-a de novo.\nEu quero ser, eu quero ser, um vaso novo."}, {"label": "Estrofe 2", "text": "Como Tu queres, Senhor amado,\nTu és o oleiro e eu o vaso.\nQuebra minha vida, e faze-a de novo.\nEu quero ser, eu quero ser, um vaso novo."}], "reviewed": false}, {"number": 3, "title": "ENQUANTO ORAMOS", "page": 1, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ao orarmos Senhor, vem encher-nos com o Teu amor.\nPara o mundo agitado esquecer, cada dia tua vida viver.\nNossas vidas vem pois transformar, refrigério pra alma nos dá.\nE agora, com outros irmãos, nos unimos a Ti em oração."}], "reviewed": false}, {"number": 4, "title": "VISITANTE SEJA BEM VINDO", "page": 1, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Visitante seja bem vindo. Sua presença é um prazer.\nCom Jesus estamos dizendo: “Esta igreja ama você!”."}], "reviewed": false}, {"number": 5, "title": "CIDADÃO DO INFINITO", "page": 1, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Por escutar uma voz que disse que faltava gente pra semear,\nDeixei o meu lar e sai sorrindo e assobiando pra não chorar.\nFui me alistar entre os operários que deixam tudo pra Te levar,\n{E fui lutar por um mundo novo.\nNão tenho lar, mas ganhei um povo.} (Bis)"}, {"label": "Estrofe 2", "text": "Sou cidadão do infinito, do infinito, do infinito,\nE levo paz no meu caminho, no meu caminho, no meu caminho.\nEu procurei semear a paz, e onde fui andando falei de Deus.\nAbençoei quem fez pouco caso\nE espalhou cizânia onde eu semeei.\nNão recebi condecoração por haver buscado um país irmão.\n{Vou semeando por entre o povo,\nE vou sonhando este mundo novo.} (Bis)"}, {"label": "Estrofe 3", "text": "Sou cidadão do infinito, do infinito, do infinito,\nE levo paz no meu caminho, no meu caminho, no meu caminho."}], "reviewed": false}, {"number": 6, "title": "O AMOR DE JESUS", "page": 1, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{O amor de Jesus é maravilhoso} (3 vezes)\nSim, oh! Grande amor.\nAlto é, intransponível, profundo também, mas acessível,\nA sua extensão é incomparável.\nSim, oh! Grande amor."}], "reviewed": false}, {"number": 7, "title": "DEUS CUIDARÁ DE MIM", "page": 2, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cada dia meu Senhor, Deus cuidará de mim.\nCada dia meu Senhor, sim, paz dará a mim.\nEle vê o pardal nascer, e me ouvirá.\nSim, cada dia meu Senhor, Deus me protegerá."}], "reviewed": false}, {"number": 8, "title": "O SENHOR É GRANDE", "page": 2, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O Senhor é Grande! Aleluia! Ele é onipotente! Aleluia!\nÉ onisciente! Aleluia!\n{Grande, onipotente e onisciente Ele é} (Bis)\nA-le-lu-ia! A-le-lu-ia! Aleluia!"}], "reviewed": false}, {"number": 9, "title": "O POVO DE DEUS", "page": 2, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu venho do Sul e Norte,\nDo Oeste e do Leste, de todo lugar.\nEstrada da vida eu percorro,\nLevando socorro a quem precisar.\nAssunto de paz é meu forte.\nEu cruzo montanhas, e vou aprender.\nO mundo não me satisfaz. O que eu quero é a paz.\nO que eu quero é viver."}, {"label": "Coro", "text": "Coro: {Na vida eu levo uma luz,\nNo meu coração, o que disse Jesus.} (Bis)"}, {"label": "Estrofe 2", "text": "Eu venho trazer meu recado,\nNão tenho passado, mas sei entender.\nUm homem foi crucificado.\nPor ter ensinado a gente viver.\nEu grito ao meu mundo descrente\nQue eu quero ser crente, que eu creio na cruz.\nEu creio na força do homem\nQue segue o caminho de Cristo Jesus."}], "reviewed": false}, {"number": 10, "title": "CRISTO É MEU", "page": 2, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo é meu, sim Cristo é meu, minha vida se transformou.\nDesde que ouvi, crendo recebi, a eterna salvação.\nSeu perdão Jesus trouxe a mim, nova luz minha vida ganhou.\nDepois de buscar, tanto procurar, e achar só ilusão."}, {"label": "Estrofe 2", "text": "{Vivi sem motivo, vivi sem razão,\nMas, hoje a paz que eu sinto, quero ver em cada coração.\nQuero amar como Cristo amou.\nO Seu sangue por mim derramou.\nQuero então cantar, ao seu lado andar, Toda vida Lhe entregar.} (Bis)"}], "reviewed": false}, {"number": 11, "title": "OS CAMINHOS", "page": 2, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Os caminhos deste mundo, nos conduzem até Deus,\nAté o céu prometido, onde brilha o sol."}, {"label": "Coro", "text": "Coro: E cantam os prados, cantam as flores,\nCom harmoniosa voz;\nE sempre que cantam, os prados e flores,\nEu sou feliz, pensando em Deus."}, {"label": "Estrofe 2", "text": "Os caminhos desta terra, estão cheios de amizade.\nNão a negue a teu irmão, que espera em ti encontrar."}, {"label": "Estrofe 3", "text": "Os caminhos da planície, nos conduzem para o monte.\nHaja dor ou alegria, sempre há luz no horizonte."}, {"label": "Estrofe 4", "text": "Os caminhos desta vida, nos pedem pra esperar.\nÉ o Senhor que nos convida, ao banquete que vai dar."}], "reviewed": false}, {"number": 12, "title": "MINHA PAZ VOS DOU", "page": 3, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{ Minha paz vos dou.} (Bis)\nNão como o mundo, Eu vo-la dou. Minha paz vos dou."}, {"label": "Estrofe 2", "text": "{ A fé vos dou.} (Bis)\nNão como o mundo, Eu vo-la dou. A fé vos dou."}, {"label": "Estrofe 3", "text": "{ Esperança vos dou.} (Bis)\nNão como o mundo, Eu vo-la dou. Esperança vos dou."}, {"label": "Estrofe 4", "text": "{ Amor vos dou.} (Bis)\nNão como o mundo, Eu vo-la dou. Amor vos dou."}], "reviewed": false}, {"number": 13, "title": "ESTOU ALEGRE", "page": 3, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "(H) Estou Alegre! (M) Porque está alegre?\nEstou alegre! Conte-me porquê\nEstou alegre! Por que está alegre?\nPor isso quero já saber.\nVou contar-lhe Pode contar-me\nA razão de estar alegre assim."}, {"label": "Estrofe 2", "text": "(T) Lá, lá, lá, lá, lá, lá, lá. Jesus Cristo me salvou,\nE também me transformou, Por isso eu alegre estou."}], "reviewed": false}, {"number": 14, "title": "UM CORAÇÃO PURO (Sl 51.10)", "page": 3, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Cria em mim, ó Deus, um coração puro.} (Bis)\n{E renova dentro em mim,}\nUm espírito inabalável."}], "reviewed": false}, {"number": 15, "title": "NÃO POR FORÇA (Zc. 4.6)", "page": 3, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Não por força, nem por violência,\nMas pelo meu espírito.} (Bis)\n{Diz o Senhor dos Exércitos.} (Bis)\nNão por força, nem por violência, mas pelo Meu Espírito."}], "reviewed": false}, {"number": 16, "title": "QUERO APRENDER", "page": 3, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quero aprender a ser filho de Deus.\nQuero aprender a fazer Seu querer.\nEu quero aceitar Sua vontade pra mim.\nQuero ser sempre feliz."}, {"label": "Estrofe 2", "text": "Sempre confiando em Seu grande amor,\nTento viver neste mundo de dor,\nSempre esperando um lar que virá,\nSempre esperando este dia."}, {"label": "Coro", "text": "Coro: Sendo herdeiro do reino de Deus,\nSendo um exemplo em minha vida aqui,\nVou dependendo das bênçãos dos céus.\nEnsine-me, ó Deus, a fazer Seu querer."}, {"label": "Estrofe 3", "text": "Eu quero aprender a cumprir Sua lei.\nQuero viver como Ele ensinou.\nEu quero estar sempre junto a Deus.\nEu quero aprender a ser livre.\n(Coro)\nAprendo a ser o que Ele quer pra mim,\nA sua graça eu canto assim.\n{Reparto com outros o Seu grande amor,\nAprendo a viver sem tristeza} (3 vezes)"}], "reviewed": false}, {"number": 17, "title": "Ó CRISTO MEU", "page": 4, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Coro", "text": "Coro : Ó Cristo meu, anelo agradar-Te,\nTu que tens feito tanto para mim."}, {"label": "Estrofe 1", "text": "A minha vida quero entregar-Te,\nPura e perfeita, consagrada a Ti."}, {"label": "Estrofe 2", "text": "Tu és tão grande, eu sou pequeno,\nSem tua ajuda posso perecer."}], "reviewed": false}, {"number": 18, "title": "QUE ALEGRIA", "page": 4, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que alegria, estou em Cristo! Já posso sorrir,\nPois tenho vida eterna, e motivo pra existir."}], "reviewed": false}, {"number": 19, "title": "SEUS GRANDES SINAIS", "page": 4, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Quão grandes são os Seus sinais.\nQuão poderosas são as Suas maravilhas!} (Bis)"}, {"label": "Estrofe 2", "text": "Ó Deus, Seu reino é sempiterno,\nE o Seu domínio de geração em geração,\nQuão grandes são os Seus sinais.\nQuão poderosas são as Suas maravilhas!"}], "reviewed": false}, {"number": 20, "title": "RENDEI GRAÇAS (Sl 106.1)", "page": 4, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Rendei graças ao Senhor, porque Ele é bom;} (Bis)\n{Porque a Sua misericórdia dura para sempre.\nRendei graças ao Senhor.} (Bis)"}], "reviewed": false}, {"number": 21, "title": "ABENÇOA ESTA OFERTA", "page": 4, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Ó Senhor abençoa esta oferta.} (Bis)\nAbençoa aos Teus filhos, que ofertam de bom coração,\nDando a eles paz e alegria, abençoando seu pão de cada dia,\nÓ Senhor."}, {"label": "Estrofe 2", "text": "Quem dá com alegria\n{Lá no céu brilhará} (3 vezes)\nQuem dá com alegria\nLá no céu brilhará.\nE Deus recompensará."}], "reviewed": false}, {"number": 22, "title": "GRATO DEUS", "page": 4, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Grato, Deus, por me amar, Sou grato por me abençoar.\nGrato, Deus, por me curar e minha alma salvar. Aleluia!"}, {"label": "Coro", "text": "Coro: Grato, Deus, por me amar\nSou grato por minha alma salvar"}, {"label": "Estrofe 2", "text": "Unamo-nos de um amor, louvando a Jesus Senhor,\nUnamo-nos com hinos bons, de exaltados tons. Aleluia!"}, {"label": "Estrofe 3", "text": "Revela, pois, Teu santo Ser, pra eu contigo, então viver.\nUsa-me pra Teus fins; possui-me, enfim! Aleluia!"}], "reviewed": false}, {"number": 23, "title": "MARAVILHOSO", "page": 4, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Maravilhoso, maravilhoso é Jesus pra mim.\nConselheiro, Príncipe, Deus que não tem fim.\nSalva-me, guarda-me, com Seu grande amor.\nMaravilhoso é Jesus, louvai ao Senhor!"}], "reviewed": false}, {"number": 24, "title": "AS PALAVRAS DA MINHA BOCA (Sl 19.14)", "page": 5, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "As palavras da minha boca, e o meditar do meu coração,\nSejam gratos diante de Ti, ó Senhor.\nÓ Senhor, ó Senhor, ó Senhor, ó Senhor.\nAs palavras da minha boca, e o meditar do meu coração,\nSejam gratos diante de Ti, ó Senhor."}], "reviewed": false}, {"number": 25, "title": "O RENOVO", "page": 5, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus, desprezado, à cruz foi morrer.\nQuem creu nesta pregação?\nAli, rejeitado, pois quis padecer.\nPor causa da transgressão.\nLevou sobre Si, sofrimento de nós,\nJulgado sem condições.\nAflito, oprimido e ferido de Deus, Jesus suportou razões."}, {"label": "Estrofe 2", "text": "Mas, foi traspassado por nossa aversão,\nO que vamos nós fazer?\nJesus, com Seu sangue, comprou-nos, então:\nDevemo-lo receber.\nE foi humilhado o Cordeiro na cruz,\nLevado só pra sofrer,\nOvelha calada, ferida de Deus. Que o sangue nos dê poder!"}, {"label": "Estrofe 3", "text": "Jesus, Redentor, nosso amado Pastor,\nNós cremos na Salvação!\nDe Ti, nos concede esse grande valor.\nNo sangue da comunhão!\nPra sempre em memória de Ti, ó Jesus,\nFaremos de coração!\nQue neste momento nos dá Tua luz, e que venha Teu perdão."}], "reviewed": false}, {"number": 26, "title": "NO SANTUÁRIO", "page": 5, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Senhor, quem entrará no Santuário pra Te adorar?} (Bis)\n{Quem tem as mãos limpas, e o coração puro,\nQuem não tem vaidades e sabe amar.} (Bis)"}, {"label": "Estrofe 2", "text": "{Senhor, eu quero entrar no Santuário pra Te adorar!} (Bis)\n{Oh, dá-me mãos limpas e um coração puro.\nRetira as vaidades, ensina-me amar.} (Bis)"}], "reviewed": false}, {"number": 27, "title": "JESUS CELESTIAL", "page": 5, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Resplendente da vitória após a morte crucial,\nRelevante está na glória meu Jesus Celestial;\nVive, sim, a cada dia edificando a Sua grei\nE com muita alegria O bendirei!"}, {"label": "Coro", "text": "Coro: (M) Senhor de Paz; (H) Sim, de paz;\nO grande Rei! Grande rei!\nAssim verás Sim, verás!\nCom temor Te bendirei! Bendirei\nEu sou feliz Sou feliz\nEm meu Jesus Em Jesus\nPorque me quis Sim, me quis!\nCom amor trazer a luz. De Jesus."}, {"label": "Estrofe 2", "text": "É Jesus, o meu Amigo, meu irmão e Protetor.\nQue me ampara no perigo, dando paz e Seu amor.\nNesta vida eu prossigo jubiloso em Jesus\nMeditando no Bendito que reluz!."}], "reviewed": false}, {"number": 28, "title": "SE CONFESSARMOS (1 Jo 1.9)", "page": 5, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se confessarmos os nossos pecados, Ele é fiel e justo,\nPara nos perdoar os pecados, e nos purificar de toda injustiça."}], "reviewed": false}, {"number": 29, "title": "ALÔ", "page": 6, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Alô, alô, aqui estamos nós\nAlô, alô, ouvir de Cristo a voz.\nQuietinhos vamos, pois ficar e a Bíblia estudar,\nE aprender a Jesus amar."}], "reviewed": false}, {"number": 30, "title": "O SABÃO", "page": 6, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O sabão, lava meu rostinho,\nLava meu pezinho, lava minha mão.\nMas Jesus, pra me deixar limpinho,\nQuer lavar meu coração."}, {"label": "Estrofe 2", "text": "Quando o mal faz uma manchinha,\nEu sei muito bem, quem pode me limpar.\nÉ Jesus, eu não escondo nada.\nTudo Ele pode apagar."}], "reviewed": false}, {"number": 31, "title": "SOU UMA FLORZINHA", "page": 6, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Sou uma florzinha de Jesus.} (Bis)\nAbro a boquinha para cantar. Fecho os olhinhos para orar.\nSou uma florzinha de Jesus. Sim, de Jesus."}], "reviewed": false}, {"number": 32, "title": "PARE", "page": 6, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Pare! Eu vou contar-lhe, o que Cristo fez por mim} (Bis)\nEle me salvou e me deu perdão. Agora vive em meu coração.\nPare! Eu vou contar-lhe o que Cristo fez por mim"}], "reviewed": false}, {"number": 33, "title": "MARANATA! VEM JESUS!", "page": 6, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo vem me buscar, para o céu me levará.\nO Cordeiro prometido voltará.\nCristo manda atento estar, vigiar e sempre orar,\nPara o toque da trombeta escutar."}, {"label": "Coro", "text": "Coro: Oh! Glória! Aleluia! Maranata, vem Jesus!\nSou liberto pela força desta cruz.\nVem um Consolador. Sua glória é esplendor,\nSou liberto pelo sangue de Jesus."}, {"label": "Estrofe 2", "text": "Ó irmão, vem orar, pois Jesus há de voltar!\nDescerá dos céus ao mundo pra julgar.\nVamos todos preparar, para Cristo nos levar,\nVigilantes sempre à frente, trabalhar."}, {"label": "Estrofe 3", "text": "Ó Jesus, vem buscar Tua grei ao doce lar!\nConfiante no Senhor hei de estar.\nNovo céu e novo lar. Nova terra vou morar,\nPois contigo, meu Amigo, vou ficar!"}], "reviewed": false}, {"number": 34, "title": "COMO EU ANDAVA", "page": 6, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Como eu andava, já não ando mais.\nComo eu vivia, já não vivo mais.\n{Porque, porque, é Jesus que vive em mim.} (Bis)"}, {"label": "Estrofe 2", "text": "Larga, larga tudo, e segue a Jesus.\nLarga, larga tudo, e segue a Jesus.\n{E serás, e serás, desde já filho de Deus.} (Bis)\nAmém."}], "reviewed": false}, {"number": 35, "title": "UMA VOZ ME DISSE", "page": 7, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Uma voz me disse lá do céu, “Canta, canta, canta para Mim.\nOra, ora, ora uma vez mais. Segue, segue, segue após Mim.”"}, {"label": "Estrofe 2", "text": "“Vem, ser fiel até a morte, e Eu serei contigo até o fim.\n{Logo estarás aqui no céu,\nOnde tens uma coroa preparada para ti.” } (Bis)"}], "reviewed": false}, {"number": 36, "title": "FIRME NAS PROMESSAS", "page": 7, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Firme nas promessas do meu Salvador,\nCantarei louvores ao meu Criador\nFico, pelos séculos do Seu amor,\nFirme nas promessas de Jesus."}, {"label": "Coro", "text": "Coro: Firme, firme,\nFirme nas promessas de Jesus, meu Mestre.\nFirme, firme, sim, firme nas promessas de Jesus."}, {"label": "Estrofe 2", "text": "Firme nas promessas, não irei falhar,\nVindo as tempestades a me consternar,\nPelo verbo eterno eu hei de trabalhar,\nFirme nas promessas de Jesus."}, {"label": "Estrofe 3", "text": "Firme nas promessas, sempre vejo assim,\nPurificação no sangue para mim,\nPlena liberdade gozarei, sem fim,\nFirme nas promessas de Jesus."}, {"label": "Estrofe 4", "text": "Firme nas promessas do Senhor Jesus,\nEm amor ligado com a Sua cruz.\nCada dia mais alegro-me na luz,\nFirme nas promessas de Jesus."}], "reviewed": false}, {"number": 37, "title": "BASTA QUE ME TOQUES SENHOR", "page": 7, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Basta que me toques, Senhor, pra minh’alma cansada vencer.\nSe a noite escura está, Tua luz me guiará.\nBasta que toques, Senhor."}, {"label": "Estrofe 2", "text": "Basta neste culto, Senhor, Teu Espírito fazer derramar.\nSe tristes estamos nós, Tua graça bastará.\nBasta que me toques, Senhor."}, {"label": "Estrofe 3", "text": "Basta que me toques, Senhor.\nQuando forças não mais encontrar.\nRefúgio vou obter. Não mais vou perecer.\nBasta que me toques, Senhor."}], "reviewed": false}, {"number": 38, "title": "DÊ UM SORRISO", "page": 7, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Coro", "text": "Coro: {Dê um sorriso só, sorriso aberto;\nSorriso certo, cheio de amor!} (Bis)"}, {"label": "Estrofe 1", "text": "Quem tem Jesus, gosta de cantar.\nEstá sempre sorrindo, mesmo quando não dá.\nTropeça aqui, “oi”, cai acolá,\nMas de novo levanta, e começa a cantar."}], "reviewed": false}, {"number": 39, "title": "GRAÇAS TE RENDEMOS (Sl 75.1)", "page": 7, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Graças Te rendemos, ó Deus.} (Bis)\nE invocamos o Teu nome,\nE, declaramos as Tuas maravilhas.\nGraças Te rendemos, ó Deus."}], "reviewed": false}, {"number": 40, "title": "NÃO VOU FICAR SOZINHO", "page": 8, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Não vou ficar sozinho, agora sou feliz\nCom Cristo no meu coração.\nEle é meu grande amigo. Não temo o perigo,\nCom Cristo no meu coração."}, {"label": "Coro", "text": "Coro: (H) Ah! Eu sou feliz (M) Ah! Eu sou feliz\nAgora vou cantar Agora vou cantar\n(T) Pois contente estou. Com quem?\nCom meu Salvador. Amém!\nFeliz agora então eu viverei."}, {"label": "Estrofe 2", "text": "Jesus, há muito tempo, morreu em uma cruz.\nMorreu só pra me salvar.\nSeu sangue derramou, lavando meus pecados,\nE desta forma agora salvo estou."}, {"label": "Estrofe 3", "text": "Se quer você, amigo, ser como eu feliz,\nEntregue-Lhe o seu coração\nPois qualquer um que quis, Jesus tornou feliz,\nE vive no seu coração."}], "reviewed": false}, {"number": 41, "title": "TUA VONTADE", "page": 8, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quero Senhor, Tua vontade fazer, seja onde for, por Ti eu irei.\nSei que o Teu plano é perfeito, meu Senhor,\nJá me salvaste por Teu amor."}, {"label": "Coro", "text": "Coro: Muitas vezes não entendo o que queres me mostrar,\nMas creio em Ti, dependo de Ti, Senhor.\nTua vontade vou fazer."}, {"label": "Estrofe 2", "text": "Sei que irmãos vão estar me sustentando,\nEm todo o tempo por mim suplicando.\nNão vou temer pois eu tenho o poder,\nQue todo mal me ajuda vencer."}], "reviewed": false}, {"number": 42, "title": "BENDITO SEJA DEUS", "page": 8, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Bendito seja Deus, que não me rejeita a oração,\nNem aparta de mim a Sua graça.} (Bis)"}, {"label": "Estrofe 2", "text": "Pois me tem ouvido, e me tem atendido.\nBendito seja Deus, que não me rejeita a oração,\nNem aparta de mim a Sua graça."}], "reviewed": false}, {"number": 43, "title": "NOVA CRIATURA (2 Co 5.17)", "page": 8, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Se alguém está em Cristo, nova criatura é.} (Bis)\nAs coisas antigas já passaram, eis que se fizeram novas\nSe alguém está em Cristo, nova criatura é."}], "reviewed": false}, {"number": 44, "title": "DISSE JESUS ( Jo 14.6; 6.51)", "page": 9, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Disse Jesus,\n“Eu sou o Caminho, a Verdade e a Vida.”} (Bis)"}, {"label": "Estrofe 2", "text": "Eu sou pão vivo que desceu do céu,\nE quem comer deste pão viverá.\nEste pão é a Minha carne\nQue Eu darei pela vida do mundo."}, {"label": "Estrofe 3", "text": "{Disse Jesus,\n“Eu sou o Caminho, a Verdade e a Vida.”} (Bis)"}], "reviewed": false}, {"number": 45, "title": "O CÉU", "page": 9, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Lá, está o meu tesouro. Lá, onde não há choro.\nOnde todos, cantaremos juntos, hinos de louvor.} (Bis)"}, {"label": "Estrofe 2", "text": "Aleluia, aleluia, aleluia, aleluia, hinos de louvor,\nAo Senhor, ao Senhor, ao Senhor."}], "reviewed": false}, {"number": 46, "title": "FOI ASSIM", "page": 9, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Conheçi o mundo mau, e com ele seus ardis.\nMe arrastei no lamaçal, tudo isso porque eu quis,\nSaber mais que qualquer um, construir algum amor,\nOnde a paz pudesse ser a verdade pra eu ver."}, {"label": "Coro", "text": "Coro: Mas Jesus Cristo veio e me achou, assim, tão sujo.\nE numa cruz por mim derramou sangue, tão puro.\n{Foi assim que me salvou.} (Bis)"}, {"label": "Estrofe 2", "text": "Eu conheço agora, sim, a clareza de Jesus.\nFoi das trevas que eu vim, encontrei-me com a luz.\nHoje quero, sim, saber, do meu Mestre, Salvador.\nQuero dar-lhe meu louvor. Eu só nele posso crer."}], "reviewed": false}, {"number": 47, "title": "CAMINHANDO VOU PARA CANAÃ)", "page": 9, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Caminhando vou para Canaã.} (3 vezes)"}, {"label": "Coro", "text": "Coro: Gloria a Deus, caminhando vou para Canaã."}, {"label": "Estrofe 2", "text": "{Se você não vai, não impeça a mim.} (3 vezes)"}, {"label": "Estrofe 3", "text": "{Deus me convidou para Canaã.} (3 vezes)."}], "reviewed": false}, {"number": 48, "title": "SEGUIR A CRISTO", "page": 9, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Seguir a Cristo ó quanto anelo.\nTer minha vida cada dia com meu Deus.\nMas quão difícil é obedecê-Lo.\nAndar aqui como Ele mesmo quer.\nSou fraco eu sei, tropeço a todo instante,\nMas mesmo assim, confiante estou.\nQuero seguir-Te dentre os poucos que são Teus.\nOh, não permitas que meu coração me engane tanto ao ponto,\nDe tornar-me a ser mais um, na grande multidão."}], "reviewed": false}, {"number": 49, "title": "TU ÉS DEUS (Sl 90.1-2)", "page": 9, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Senhor, Tu tens sido o nosso refúgio,\nDe geração em geração.} (Bis)\nAntes que montes nascessem,\nE se formassem a terra e o mundo,\n{De eternidade a eternidade, Tu és Deus.} (Bis)."}], "reviewed": false}, {"number": 50, "title": "CONTENTE", "page": 9, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Contente está meu coração} (Bis)\nPorque meu Deus me guarda com amor,\nÉ por isso que eu vivo tão feliz!"}], "reviewed": false}, {"number": 51, "title": "QUÃO GRANDE ÉS TU", "page": 10, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Senhor meu Deus, quando eu maravilhado,\nFico a pensar nas obras de Tuas mãos.\nNo céu azul, de estrelas pontilhado,\nO Teu poder mostrando a criação."}, {"label": "Coro", "text": "Coro: Então minh’alma canta a Ti Senhor:\nQuão grande és Tu, quão grande és Tu!\nEntão minh’alma canta a Ti Senhor:\nQuão grande és Tu, quão grande és Tu."}, {"label": "Estrofe 2", "text": "Quando a vagar nas matas e florestas,\nO passaredo alegre ouço a cantar;\nOlhando os montes, vales e campinas,\nEm tudo vejo o Teu poder sem par."}, {"label": "Estrofe 3", "text": "Quando eu medito em Teu amor tão grande,\nTeu filho dando ao mundo pra salvar,\nNa cruz vertendo Seu precioso sangue,\nMinh’alma pode assim purificar."}, {"label": "Estrofe 4", "text": "E quando, enfim, Jesus vier em glória,\nE ao lar celeste, então me transportar,\nAdorarei prostrado e para sempre,\nQuão grande és Tu, meu Deus, hei de cantar!"}], "reviewed": false}, {"number": 52, "title": "POR MIM MORREU JESUS", "page": 10, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Por mim morreu Jesus, cravado numa cruz.\nNo monte do calvário, por mim morreu Jesus."}, {"label": "Estrofe 2", "text": "Por mim ressuscitou. Vitória sim, ganhou,\nE à destra do seu Pai está. Por mim ressuscitou."}, {"label": "Estrofe 3", "text": "Pra mim, sim, voltará, e ao céu me levará.\nPra sempre cantarei louvor. Pra mim, sim, voltará."}], "reviewed": false}, {"number": 53, "title": "COROAI", "page": 10, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Saudai o nome de Jesus! Arcanjos vos prostai!\n{O Filho do glorioso Deus, com glória coroai!} (Bis)"}, {"label": "Estrofe 2", "text": "Ó escolhida geração do bom eterno Pai!\n{O grande autor da salvação, com glória coroai!} (Bis)"}, {"label": "Estrofe 3", "text": "Ó perdoados por Jesus, alegres adorai!\n{O Deus de paz, o Deus de luz, com glória coroai!} (Bis)."}, {"label": "Estrofe 4", "text": "Ó raças, tribos e nações, ao Rei divino honrai!\n{A quem quebrou os vis grilhões, com glória coroai!} (Bis)."}], "reviewed": false}, {"number": 54, "title": "VÁ COM DEUS", "page": 11, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh! Sem Deus, a vida é em vão;\nPois sem Deus, que vale a petição?\nMas há de ser, com ele andará,\nE no viver, consigo ficará."}, {"label": "Coro", "text": "Coro: Vá com Deus, vá com Deus,\nVá com Deus, hoje em tal poder.\nVá com Deus, vá com Deus,\nVá com Deus vencer!"}, {"label": "Estrofe 2", "text": "Ao partir às terras além-mar;\nA seguir, da lida o que será?\nNos temporais, ali não há temor,\nAlém do mais, consigo está o Senhor."}, {"label": "Estrofe 3", "text": "Vá com Deus àqueles lares mil;\nVá com Deus por toda a terra vil.\n“Ide e pregai” - Porque não confiar?\nPois é seu Pai, que enfim há de guiar."}], "reviewed": false}, {"number": 55, "title": "SIM, HÁ UM DEUS", "page": 11, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Existe, além do céu anil, um Deus oculto do meu ver.\nCriou o céu de estrelas mil. O mundo fez com Seu poder."}, {"label": "Coro", "text": "Coro: (H) Sim há um Deus, (M) Sim, há um Deus\nQue vivo é, Que vivo é,\nNEle vivemos, NEle vivemos,\nE temos fé! E temos fé!"}, {"label": "Estrofe 2", "text": "(\nM\n) Do pó, meu Deus, (H) Do pó, meu Deus\nHomem criou; Homem criou;\nEle é meu Deus; Ele é meu Deus;\nO grande “Eu Sou”. O grande “Eu Sou”."}, {"label": "Estrofe 3", "text": "Aquele Deus que nos amou, a vida de Seu Filho deu.\nA graça, então nos perdoou. Teremos vida lá no céu!"}, {"label": "Estrofe 4", "text": "“Não, há um Deus”. Alguém me diz; “Não passa de superstição!”.\nMas crendo nEle sou feliz , e me tudo vejo a Sua mão."}], "reviewed": false}, {"number": 56, "title": "PERTINHO DO REI", "page": 12, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que alegria invade o meu ser!\nQuero a todos dizer por que.\nO meu Jesus minh’alma salvou, por Sua graça e Seu poder.\nPor meus pecados na cruz expirou.\nTambém a mim esta promessa deu:"}, {"label": "Coro", "text": "Coro: {Se eu for fiel, então eu subirei, e pra sempre estarei\nBem pertinho do meu Rei.} (Bis)"}, {"label": "Estrofe 2", "text": "Que alegria transborda o meu ser!\nSempre cantando quero viver.\nCom gratidão ao meu bom Salvador; a minha vida consagrarei.\nEle é a razão de todo meu viver,\nTambém a mim esta promessa deu:"}], "reviewed": false}, {"number": 57, "title": "ALVO MAIS QUE A NEVE (Sl 51.7)", "page": 12, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Bendito seja o Cordeiro, que na cruz por nós padeceu.\nBendito seja o Seu sangue,\nQue por nós, ali Ele verteu.\nEis nesse sangue lavados, com roupas que tão alvas são,\nOs pecadores remidos,\nQue perante seu Deus já estão."}, {"label": "Coro", "text": "Coro: Alvo mais que a neve. Alvo mais que a neve.\nSim, nesse sangue lavado, mais alvo que a neve serei."}, {"label": "Estrofe 2", "text": "Quão espinhosa coroa, que Jesus por nós suportou.\nOh! Quão profundas as chagas,\nQue nos provam quanto Ele amou!\nEis nessas chagas pureza, para o maior pecador.\nPois que mais alvo que a neve,\nO Teu sangue nos torna, Senhor!"}, {"label": "Estrofe 3", "text": "Se nós a ti confessarmos, e seguirmos na Tua luz,\nTu não somente perdoas,\nPurificas também, ó Jesus.\nSim, e de todo pecado! Que maravilha de amor!\nPois que mais alvo que a neve,\nO Teu sangue nos torna, Senhor!"}], "reviewed": false}, {"number": 58, "title": "COMO AS ÁGUAS COBREM O MAR (Is 11.9)", "page": 13, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Como as águas cobrem o mar,\nToda a terra se há de encher,\nDo amor de Deus, e da glória do Senhor,\nComo as águas cobrem o mar."}], "reviewed": false}, {"number": 59, "title": "VEM! INFLAMA!", "page": 13, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Meu pecado, resgatado, foi na cruz por Teu amor,\nE da morte, triste sorte, me livraste Tu, Senhor!"}, {"label": "Coro", "text": "Coro: Vem! Inflama, viva chama\nEm meu peito, bem sem fim!\nEu Te adoro, sempre imploro:\nÓ Jesus, habita em mim!"}, {"label": "Estrofe 2", "text": "Se hesitante, vacilante, ouço a voz do tentador,\nTu me guias, me auxilias, e me tornas vencedor."}, {"label": "Estrofe 3", "text": "Redimida, só tem vida, a minh’alma em Teu amor;\nCom apreço, reconheço, quanto devo a Ti, Senhor!"}], "reviewed": false}, {"number": 60, "title": "SOLDADOS DE CRISTO", "page": 13, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Somos soldados de Cristo.\nAvante cantando louvores.\n{Nosso Rei é Mestre dos Mestres,\nGeneral e Senhor dos Senhores.} (Bis)"}, {"label": "Coro", "text": "Coro: Damos glória, aleluia, para sempre, sem cessar.\n{Nosso Rei é Mestre dos Mestres,\nGeneral e Senhor dos Senhores.} (Bis)"}, {"label": "Estrofe 2", "text": "Nas batalhas não temos derrotas.\nAs vitórias não são multicores.\n{Nosso Rei é Mestre dos Mestres,\nGeneral e Senhor dos Senhores.} (Bis)"}], "reviewed": false}, {"number": 61, "title": "TOMADO PELA MÃO", "page": 13, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Coro", "text": "Coro: {Tomado pela mão de Jesus, eu vou!} (3 vezes)\n(H) Por onde for (M) Por onde for!\n{Tomado pela mão de Jesus, eu vou!} (3 vezes)\nEm Seu amor!"}, {"label": "Estrofe 1", "text": "Se Jesus te disse:\n“Amigo, deixa tudo e vem comigo”,\nToma a Cristo com mãos limpas,\n(H) e nEle vai! (M) e nEle vai!\n“Eu te levo”, disse o Amigo,\n“A um lugar, a um reino comigo,\nOnde tudo é mais alegre e mais feliz!”"}], "reviewed": false}, {"number": 62, "title": "O GRANDE AMIGO", "page": 14, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Em Jesus, Amigo temos, mais chegado que um irmão.\nEle manda que levemos, tudo a Deus em oração.\nOh! que paz perdemos sempre, oh! que dor no coração.\nSó porque nós não levamos, tudo a Deus em oração."}, {"label": "Estrofe 2", "text": "Temos lidas e pesares, e na vida tentação.\nNão ficamos sem conforto, indo a Cristo em oração.\nHaverá um outro amigo, de tão grande compaixão?\nOs contritos Jesus Cristo, sempre atende em oração."}, {"label": "Estrofe 3", "text": "E se nós desfalecemos, Cristo estende-nos a mão.\nPois é sempre a nossa força, e refúgio em oração.\nSe este mundo nos despreza, Cristo é nosso em oração.\nEm Seus braços nos acolhe, e nos dá consolação."}], "reviewed": false}, {"number": 63, "title": "UM SÓ REBANHO", "page": 14, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Um só rebanho, um só Pastor.\nUma só fé, e um só Salvador.\nÉ Teu amor que nos une aqui,\n{E num só Espírito adoramos a Ti.} (Bis)"}, {"label": "Estrofe 2", "text": "Um só rebanho, um só Pastor.\nFruto, ó Senhor, desse Teu grande amor\nSó nos gloriamos na Tua cruz,\n{Louvado sejas, bendito Jesus.} (Bis)"}, {"label": "Estrofe 3", "text": "Um só rebanho, um só Pastor.\nÓ Cristo, és digno de nosso louvor.\nTu és o imã que nos atrai,\n{É só por Ti que adoramos ao Pai} (Bis)"}, {"label": "Estrofe 4", "text": "Um só rebanho, um só Pastor.\nEis que esperamos por Ti, ó Senhor\nÉ face a face que vamos ver,\n{Quem nos amou e por nós quis morrer.) (Bis)"}], "reviewed": false}, {"number": 64, "title": "ADORO UM CRISTO VIVO", "page": 15, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Adoro um Cristo vivo, na terra Ele está.\nEu sei que Ele vive e Ele salvará.\nEu vejo a Sua graça, eu ouço a Sua voz,\nÉ Ele quem me livra da morte atroz."}, {"label": "Coro", "text": "Coro: Jesus, meu Rei, sim, vive em meu coração.\nConsola-me, conforta-me na minha tentação.\nJesus, meu Rei, eterno Salvador,\nQuereis saber quem Ele é - Jesus, meu Salvador!"}, {"label": "Estrofe 2", "text": "Jesus, Senhor e Mestre, por mim morreu na cruz\nRessuscitou dos mortos e dá-nos paz e luz.\nEternamente vive, pra sempre viverá.\nEu sei que Ele vive e viverá."}, {"label": "Estrofe 3", "text": "Alegro-me em Cristo, por isto cantarei\nEternas aleluias ao glorioso Rei.\nA única esperança que sempre manterei,\nÉ minha confiança Jesus, meu Rei."}], "reviewed": false}, {"number": 65, "title": "ESTOU SEGUINDO JESUS, O CRISTO", "page": 15, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Estou seguindo Jesus, o Cristo.\nDeste caminho eu não desisto.\nEstou seguindo Jesus, o Cristo,\nAtrás não volto, não volto não."}, {"label": "Estrofe 2", "text": "Atrás o mundo, Jesus na frente,\nJesus o Guia Onipotente.\nAtrás o mundo, Jesus na frente,\nAtrás não volto, não volto não!."}, {"label": "Estrofe 3", "text": "Depois da luta, vem a coroa.\nA recompensa é certa e boa.\nDepois da luta, vem a coroa,\nAtrás não volto, não volto não."}], "reviewed": false}, {"number": 66, "title": "O MEU TESOURO", "page": 15, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu tenho um tesouro, eu tenho sim.\nEu tenho um tesouro. É dentro de mim.\nEste meu tesouro tem muito valor.\nEste meu tesouro é Jesus Cristo, meu Salvador."}, {"label": "Estrofe 2", "text": "(H) Vale mais que o céu. (M) Vale mais que o céu.\nVale mais que o mar. Vale mais que o mar.\nVale mais que tu. Vale mais que tu.\nVale mais que eu. Vale mais que eu."}, {"label": "Estrofe 3", "text": "Este meu tesouro tem muito valor.\nEste meu tesouro é Jesus Cristo, meu Salvador."}], "reviewed": false}, {"number": 67, "title": "VIVO É JESUS", "page": 16, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Montanhas e vales, e vistas imensas.\nSão obras da mão do eterno Senhor."}, {"label": "Coro", "text": "Coro: Vivo é Jesus, hoje vive, sim,\nHabita sempre em mim.\nNunca mais ficarei sem Jesus desde que,\nEle entrou no meu coração."}, {"label": "Estrofe 2", "text": "As flores, as aves, o céu todo azul,\nSão provas do Mestre que hoje se vê."}, {"label": "Estrofe 3", "text": "O sol e a lua, o belo arco-íris,\nSinais do carinho de Deus, Criador."}], "reviewed": false}, {"number": 68, "title": "SUA VIDA MAIS CLARA", "page": 16, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sua vida mais clara se levantará,\nQuando Cristo Jesus voltar."}, {"label": "Coro", "text": "Coro: Ainda que haja trevas, será como a manhã,\n{Será como amanhecer.} (Bis - depois da última estrofe)"}, {"label": "Estrofe 2", "text": "Ruas de ouro e cristal, nossos pés vão pisar,\nE o rosto de Cristo Jesus vou contemplar."}], "reviewed": false}, {"number": 69, "title": "BRILHAR POR JESUS", "page": 16, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "(Brilha, brilha em teu lugar.} (Bis)\nA noite escura chegará,\nA luz porém mais brilhará.\nBrilha por Jesus em teu lugar."}], "reviewed": false}, {"number": 70, "title": "O REI ESTÁ VOLTANDO", "page": 16, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O mercado está vazio, o seu trabalho já parou.\nOs martelos dos obreiros, seu barulho já cessou.\nOs ceifeiros lá no campo, terminaram seu labor.\nToda terra está em suspense. É a volta do Senhor."}, {"label": "Coro", "text": "Coro: O Rei está voltando. O Rei está voltando.\nA trombeta está soando, o meu nome a chamar.\nO Rei está voltando. O Rei está voltando.\n{Aleluia! Ele vem me buscar.} (Bis – depois da última estrofe)"}, {"label": "Estrofe 2", "text": "Vejo a multidão subindo, ouço um coro angelical.\nTodo o céu está se abrindo num bem vindo sem igual.\nComo o som de muitas águas, nós ouvimos ecoar,\n“Aleluias ao Cordeiro! Nós chegamos para o lar.”"}], "reviewed": false}, {"number": 71, "title": "A TUA PAZ", "page": 16, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A Tua paz é como rio, que corre suavemente\nAo encontro do mar, Senhor Jesus.\nA Tua paz é como os campos, onde tem belas flores\nE há pássaros a cantar."}, {"label": "Estrofe 2", "text": "{Pássaros a cantar, (H) cantar\nRios a correr, (H) correr\nQuem tem Jesus tem motivos pra viver.} (Bis)"}], "reviewed": false}, {"number": 72, "title": "SEU NOME (Is 9.6)", "page": 17, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Seu nome é Maravilhoso.} (3 vezes)\nPai da Eternidade, Príncipe da Paz."}, {"label": "Estrofe 2", "text": "{Seu nome é Conselheiro.} (3 vezes)\nPai da Eternidade, Príncipe da Paz."}, {"label": "Estrofe 3", "text": "{Seu nome é Deus Forte.} (3 vezes)\nPai da Eternidade, Príncipe da Paz."}, {"label": "Estrofe 4", "text": "Seu nome é Maravilhoso.\nSeu nome é Conselheiro.\nSeu nome é Deus Forte,\nPai da Eternidade, Príncipe da Paz."}], "reviewed": false}, {"number": 73, "title": "SATISFAÇÃO", "page": 17, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Satisfação é ter a Cristo. Não há maior prazer já visto.\nSou de Jesus, e agora eu sinto,\nSatisfação sem fim."}, {"label": "Estrofe 2", "text": "Satisfação é nova vida, eu com Jesus em alegria,\nSempre cantando a melodia,\nSatisfação sem fim."}, {"label": "Estrofe 3", "text": "Sim, paz real; sim gozo na aflição.\nAchei o segredo.\nÉ Cristo no coração, aleluia!"}, {"label": "Estrofe 4", "text": "Satisfação é não ter medo, pois meu Jesus virá bem cedo,\nLogo em glória eu hei de vê-Lo,\n{Satisfação sem fim!} (3 vezes)"}], "reviewed": false}, {"number": 74, "title": "A CEIA", "page": 17, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mesa preparada, ceia ensinada,\nCristo instruindo, morte aproximada."}, {"label": "Coro", "text": "Coro: Isto é a ceia, a ceia do Senhor,\nDada em memória do Seu grande amor."}, {"label": "Estrofe 2", "text": "Este pão, Meu corpo, que por vós foi dado,\nSacrifício eterno para ser lembrado."}, {"label": "Estrofe 3", "text": "Sangue derramado, suco abençoado.\nCristo entristecendo para ser levado."}], "reviewed": false}, {"number": 75, "title": "OUVE Ó DEUS", "page": 17, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ouve, ó Deus, atende ao meu clamor.\nNos confins da terra, eu clamarei a Ti."}, {"label": "Estrofe 2", "text": "(T) Quando eu abatido for, (M) Lá, lá, lá\n(T) Leva-me para uma rocha\n(H) Mais alta que eu. (M) Mais alta que eu. (Bis)"}, {"label": "Estrofe 3", "text": "Porque Tu tens sido, o meu refúgio e\nUma torre forte, contra todo mal."}, {"label": "Estrofe 4", "text": "(T) Quando eu abatido for, (M) Lá, lá, lá\n(T) Leva-me para uma rocha\n(H) Mais alta que eu. (M) Mais alta que eu. (Bis)"}], "reviewed": false}, {"number": 76, "title": "MEU SENHOR DESCEU DOS CÉUS", "page": 18, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Meu senhor desceu dos Céus e deu a salvação.\nGlória, glória cantam lá nos Céus!\nO Senhor valeu, que satisfação! Aleluia, glória a Deus!"}, {"label": "Coro", "text": "Coro: {Aleluia, aleluia, aleluia, glória a Deus!} (Bis)"}, {"label": "Estrofe 2", "text": "(H) Meu Senhor desceu dos Céus; (M – repetem o coro)\nE deu a salvação.\nGlória, glória, cantam lá nos Céus!\nO Senhor valeu, que satisfação! Aleluia, glória a Deus!\nMeu Senhor desceu dos Céus."}], "reviewed": false}, {"number": 77, "title": "CANTE", "page": 18, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Cante, amém, amém. Alegre-se, amém, amém.\nGlória a Deus, amém, amém.} (Bis)"}, {"label": "Estrofe 2", "text": "(H) Quando o Senhor voltar outra vez.\n(T) Que o povo cante, amém, amém.} (Bis)"}, {"label": "Estrofe 3", "text": "{Cante, amém, amém. Cante, amém, amém.\nQue o povo cante, amém, amém.} (Bis)"}], "reviewed": false}, {"number": 78, "title": "FAZ UM SERVO DE MIM", "page": 18, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Senhor poderoso eu rogo a Ti.\nComo Tu és um servo, faz um servo de mim.\nSeguir Teu exemplo é meu querer.\nComo Tu és um servo, também quero ser."}], "reviewed": false}, {"number": 79, "title": "VAMOS BATALHAR", "page": 18, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vamos batalhar, juntos pelejar, todos guerrear, vamos já.\nO inimigo que, com a sorte vem, tão feroz, irmãos, não vencerá!"}, {"label": "Coro", "text": "Coro: Vamos crentes, vamos já avante,\nFirmes sempre, contra Satanás.\nCristo forte, nosso Comandante\n{Está conosco, General capaz.} (Bis – no final)"}, {"label": "Estrofe 2", "text": "Ó glorioso Pai, o fiel não cai, sempre avante vai, vencedor.\nQuando o fim chegar, fim do batalhar.\nVem nos coroar, por Teu amor."}], "reviewed": false}, {"number": 80, "title": "MEU REDENTOR", "page": 18, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Para o Calvário foi meu Jesus. Dia sombrio, quase sem luz;\nSem ser forçado, vai entre dor, levando a cruz só por amor."}, {"label": "Coro", "text": "Coro: Vejo o Senhor, meu Redentor,\nPor meus pecados sofrendo na cruz.\nDependurado, ensangüentado,\nDesamparado, Cristo Jesus."}, {"label": "Estrofe 2", "text": "“Pai os perdoa.” Ora Jesus, enquanto sangue jorra da cruz.\nSofrendo dores até o fim, ninguém no mundo nos ama assim."}, {"label": "Estrofe 3", "text": "Eu amo a Cristo, meu Salvador,\nPrecioso Amigo, Mestre, Senhor.\nEm minha vida O exaltarei. Na eternidade O louvarei."}], "reviewed": false}, {"number": 81, "title": "EU VENHO A DIZER", "page": 19, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu venho a dizer, eu venho a dizer ao meu Salvador,\nQue eu amo a Ti, que eu amo a Ti, no meu coração."}, {"label": "Coro", "text": "Coro: Eu venho a dizer, eu venho a dizer, honrar a verdade\nTi amo Senhor, Ti quero Senhor, no meu coração."}, {"label": "Estrofe 2", "text": "Eu quero cantar, eu quero cantar, de gozo e de paz.\nEu quero chorar, eu quero chorar de felicidade."}], "reviewed": false}, {"number": 82, "title": "MEU FARDO ELE LEVOU", "page": 19, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu canto sempre alegre e vou dizer porque,\nMeu fardo Ele levou.\nSe alguém me perguntar como foi que aliviei,\nMeu fardo Ele levou."}, {"label": "Estrofe 2", "text": "Seu santo, eterno amor, o meu coração lavou,\nOs meus pecados todos carregou.\nNo mar do esquecimento, pra sempre os quis deixar.\nMeu fardo Ele levou."}], "reviewed": false}, {"number": 83, "title": "NÃO TENHO MEDO (Sl 3.6-7)", "page": 19, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Não tenho medo de milhares do povo\nQue tomam posição contra mim.} (Bis)"}, {"label": "Estrofe 2", "text": "{Levanta-Te, levanta-Te!\nSalva-me, Deus meu!} (Bis)"}], "reviewed": false}, {"number": 84, "title": "SEMPRE CAMINHANDO", "page": 19, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quer nas lutas, quer nas provas, a igreja sempre caminhando.\nQuer nas lutas, quer nas provas, a igreja sempre caminhando,\nSempre caminhando, sempre caminhando."}, {"label": "Estrofe 2", "text": "Ò glória, aleluia, a igreja sempre caminhando.\nÒ glória, aleluia, a igreja sempre caminhando,\nSempre caminhando, sempre caminhando."}], "reviewed": false}, {"number": 85, "title": "SANTO É O SENHOR (Ap. 4.8-11)", "page": 19, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Santo, Santo, Santo é o Senhor,\nSanto é o Senhor Deus Poderoso.} (Bis)\nQue era, que é, e que há de vir,\nSanto, Santo, Santo é o Senhor."}, {"label": "Estrofe 2", "text": "{Glória, Glória, Glória ao Senhor,\nGlória ao Senhor, Deus Poderoso.} (Bis)\nQue era, que é, e que há de vir,\nGlória, Glória, Glória ao Senhor."}, {"label": "Estrofe 3", "text": "{Honra, Honra, Honra ao Senhor,\nHonra ao Senhor, Deus Poderoso.} (Bis)\nQue era, que é, e que há de vir,\nHonra, Honra, Honra ao Senhor."}, {"label": "Estrofe 4", "text": "{Digno, Digno, Digno é o Senhor.\nPara receber a glória e honra.} (Bis)\nQue era, que é, e que há de vir,\nSanto, Santo, Santo é o Senhor."}], "reviewed": false}, {"number": 86, "title": "VAMOS DAR LOUVOR", "page": 19, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Vamos dar louvor, ao Senhor\nLevantemo-nos nossas vozes em Seu louvor!} (Bis)"}], "reviewed": false}, {"number": 87, "title": "AMIGO LEAL", "page": 20, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Toma o meu coração, o meu ser, minhas mãos.\nA Ti dou, ó Jesus, o que sou.\nO meu mundo negar, Tua vontade aceitar,\nO meu ser quero a Ti consagrar."}, {"label": "Coro", "text": "Coro: Faz-me, Amigo Leal, a servir-Te, Senhor;\nTeu amor transmitir com fervor.\nNada sei. Nada sou. Mas Tu és meu Pastor.\nJunto a Ti, já não tenho temor."}, {"label": "Estrofe 2", "text": "Dá-me a voz, dá-me a luz, dá-me o dom de falar,\nPra mensagem de fé propagar.\nDá que possa sentir, o calor das Tuas mãos,\nTransbordando em meu coração."}], "reviewed": false}, {"number": 88, "title": "SEM DEUS", "page": 20, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sem Deus nada somos neste mundo.\nSem Deus não podíamos viver.\n{Nem as folhas das árvores se movem,\nSe não for pelo Seu poder.} (Bis)"}, {"label": "Estrofe 2", "text": "O maior milagre deste mundo, foi Jesus que na cruz realizou.\n{A minh´alma manchada do pecado\nJesus com Seu sangue lavou.} (Bis)"}, {"label": "Estrofe 3", "text": "Na noite que Ele foi traído, em memória a ceia nos deixou.\n{O pão simboliza o Seu corpo,\nO suco, o sangue do Senhor.} (Bis)"}, {"label": "Estrofe 4", "text": "Na ceia nós temos esperança. O Cordeiro logo vai voltar.\n{Vai enxugar pra sempre nossas lágrimas,\nE levar-nos ao Eterno Lar. } (Bis)"}], "reviewed": false}, {"number": 89, "title": "CRUCIFICADO COM CRISTO (Gl 2.19-20)", "page": 20, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Estou crucificado com Cristo, logo, já não sou eu quem vive,\nMas Cristo vive em mim."}, {"label": "Estrofe 2", "text": "E esse viver que agora tenho na carne,\nVivo pela fé no Filho de Deus,\nQue me amou e se entregou a si mesmo por mim!"}, {"label": "Estrofe 3", "text": "Estou crucificado com Cristo;\nLogo, já não sou eu quem vive,\n(H) Mas Cristo vive em mim.\n(M) Mas Cristo vive em mim.\n(T) Mas Cristo vive - - em mim!"}], "reviewed": false}, {"number": 90, "title": "NA PRESENÇA DO SENHOR", "page": 20, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Há prazer, há prazer, há prazer na presença do Senhor.\nHá prazer real, há prazer sem fim,\nHá prazer na presença do Senhor."}, {"label": "Estrofe 2", "text": "Tenho paz, tenho paz, tenho paz na presença do Senhor.\nConfiando nEle há perfeita paz,\nTenho paz na presença do Senhor."}, {"label": "Estrofe 3", "text": "Sinto amor, sinto amor, sinto amor na presença do Senhor.\nSinto amor maior que qualquer outro amor,\nSinto amor na presença do Senhor."}, {"label": "Estrofe 4", "text": "Há prazer, tenho paz, sinto amor na presença do Senhor.\nCristo tudo supre ao que nEle crê.\nHá prazer, tenho paz, sinto amor na presença do Senhor."}], "reviewed": false}, {"number": 91, "title": "SANTO ESPÍRITO", "page": 21, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Santo Espírito enche a minha vida,\nPois com Cristo eu quero brilhar.\nSanto Espírito enche a minha vida.\nUsa-me as almas a salvar."}, {"label": "Coro", "text": "Coro: (H) Aleluia, Aleluia (M) A-- , A--\n(T) Aleluia, dou a Cristo Rei.\n(H) Aleluia, Aleluia (M) A-- , A --\n(T) Aleluia dou ao Rei."}, {"label": "Estrofe 2", "text": "Faz-me, Deus, uma luz fulgurante,\nQue jamais venha escurecer,\nFaz, ó Deus, que meu facho brilhante,\nBrilhe sempre até o amanhecer."}], "reviewed": false}, {"number": 92, "title": "HOSANA!", "page": 21, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mantos e palmas espalhando vai,\nO povo alegre de Jerusalém.\nLá bem ao longe se começa ver,\nO Filho do Homem que montado vem."}, {"label": "Coro", "text": "Coro: Enquanto mil vozes ressoam por aí,\n“Hosana ao que vem em nome do Senhor”\nComo um alento de grande exclamação\nProrrompem com voz triunfal,\n{“Hosana, Hosana ao Rei”} (Bis)"}, {"label": "Estrofe 2", "text": "Como na estrada de Jerusalém,\nUm dia também poderemos cantar,\nA Jesus Cristo que virá outra vez,\nPara levar-nos ao eterno lar."}], "reviewed": false}, {"number": 93, "title": "GRANDE É O SENHOR", "page": 21, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Grande é o Senhor, Rei do Universo.} (Bis)\nPois tão grande é, pois tão grande é!"}, {"label": "Coro", "text": "Coro: {Ho-o-o-sana nas alturas!} (3 vezes)\nPois tão grande é, pois tão grande é!"}, {"label": "Estrofe 2", "text": "{Seja bem vindo, bendito o que vem.} (3 vezes)\nEm nome do Senhor, em nome do Senhor!"}], "reviewed": false}, {"number": 94, "title": "CRISTO, NOME DOS NOMES", "page": 21, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo, nome dos nomes, meu Salvador, glorioso Senhor,\nEmanuel, Deus conosco, o Rei, meu Redentor, Verbo Vivo."}, {"label": "Estrofe 2", "text": "{Ele é príncipe, e Conselheiro,\nDeus Poderoso, Pai Eterno.\nO Seu governo, Ele vai sustentar,\nE o Seu reino não terminará.} (Bis)"}], "reviewed": false}, {"number": 95, "title": "HUMILHAI-VOS (Tg 4.10)", "page": 21, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Coro", "text": "Coro: (H) Humilhai-nos diante de Deus\n(M) Humilhai-vos diante de Deus. (Bis)\n(H) E vos exal – tará\n(M) E vos exal - tará. (Bis)"}, {"label": "Estrofe 1", "text": "(H) Jesus Cristo é o Filho de Deus.\n(M) Jesus Cristo é o Filho de Deus. (Bis)\n(H) Morreu na cruz por mim.\n(M) Morreu na cruz por mim. (Bis)"}], "reviewed": false}, {"number": 96, "title": "MEU CORAÇÃO TRANSBORDA DE AMOR", "page": 22, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "(H) Meu coração transborda de amor,\n(M) Transborda de amor.\n(H) Porque meu Deus (M) Porque meu Deus,\n(H) É um Deus de amor. (M) É um Deus de amor."}, {"label": "Estrofe 2", "text": "(H) Minh´alma está repleta de paz, (M) Repleta de paz.\n(H) Porque Jesus (M) Porque Jesus,\n(H) É a minha paz (M) É a minha paz."}, {"label": "Estrofe 3", "text": "(H) Eu digo aleluia, aleluia, aleluia, aleluia, aleluia,\n(M) Eu digo alelu-u-ia, alelu-u-ia, aleluia,\n(H) E eu digo porque. (M) E eu digo porque."}, {"label": "Estrofe 4", "text": "(H) Eu digo aleluia, aleluia, aleluia, aleluia, aleluia,\n(M) Eu digo alelu-u-ia, alelu-u-ia, aleluia,\n(H) Aleluia amém. (T) Aleluia amém."}], "reviewed": false}, {"number": 97, "title": "OLHAR SOMENTE A TI SENHOR", "page": 22, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "1. {Olhar somente a Ti, Senhor.} (3 vezes)\nE não olhar atrás.\nSeguir teu caminhar, Senhor. Seguir-Te sem parar, Senhor.\nMeu ser Te entregar, Senhor, e não voltar atrás."}, {"label": "Estrofe 2", "text": "2. Amar - - Voltar 3. Seguir - - Voltar"}], "reviewed": false}, {"number": 98, "title": "MEU NOME ESCRITO ESTÁ", "page": 22, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Com pena de ouro escrito está, escrito está, escrito está,\nCom pena de ouro escrito está meu nome lá no céu,\n{Lá no céu, meu nome escrito está.) (Bis)"}], "reviewed": false}, {"number": 99, "title": "AGINDO EU (Is 43)", "page": 22, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Coro", "text": "Coro: {“Agindo Eu, quem O impedirá?”} (4 vezes)"}, {"label": "Estrofe 1", "text": "“Eu sou teu Deus, Eu sou teu Senhor,\nE fora de Mim, não há Salvador.\nAntes de Mim, nenhum Deus se formou.\nDepois de Mim, nenhum Deus haverá.”"}, {"label": "Estrofe 2", "text": "“Eu te criei”, assim diz o Senhor.\n“Eu te amei, sou Deus de amor.\nEu te chamei, sou teu Salvador.\nContigo irei, seja onde for.”"}], "reviewed": false}, {"number": 100, "title": "SHALOM, MEU AMIGO", "page": 22, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Shalom, meu amigo,\nDeus é contigo\nAté o fim."}, {"label": "Coro", "text": "Coro: Para o céu eu irei\nEncontrar com meu Rei\n(H) Shalom, Sha-a-a-lom\n(M) Shalom, Shalom. (Bis)"}, {"label": "Estrofe 2", "text": "Jesus prometeu\nQue vai voltar\nPra me levar."}], "reviewed": false}, {"number": 101, "title": "HÁ MOMENTOS", "page": 23, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Há momentos, em que as palavras não resolvem,\nMas o gesto de Jesus, demonstra amor por nós.} (Bis)"}, {"label": "Coro", "text": "Coro: {Foi no calvário, que Ele sem falar,\nMostrou ao mundo inteiro, o que é o amar.} (Bis)"}, {"label": "Estrofe 2", "text": "{Aqui no mundo, as desilusões são tantas,\nMas existe a esperança, que Ele vai voltar.} (Bis )"}], "reviewed": false}, {"number": 102, "title": "SHALOM", "page": 23, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Shaiá-lá-lá-lá-lá-lá meu irmão Shalom!.} (Bis)"}, {"label": "Coro", "text": "Coro: (Shalom, Shalom, Shalom, Shalom.} (Bis)"}, {"label": "Estrofe 2", "text": "Eu vou para a terra prometida onde o futuro é meu.\nEu vou caminhando na avenida que me leva a Deus."}, {"label": "Estrofe 3", "text": "Eu canto a alegria de viver que o amor me traz.\nOutra coisa não sei fazer que buscar a paz."}, {"label": "Estrofe 4", "text": "Eu vou com sorriso de criança pela multidão.\nEu levo comigo a esperança no coração."}, {"label": "Estrofe 5", "text": "(Shaiá-lá-lá-lá-lá-lá meu irmão Shalom.} (Bis)"}], "reviewed": false}, {"number": 103, "title": "MINH´ALMA CANTA ALEGRE", "page": 23, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Minh´alma canta alegre, Jesus me libertou.\nO Deus de paz, meu Amigo, meu pecados apagou.\nBondade eterna conheci, a justificação.\nJesus está no meu coração."}], "reviewed": false}, {"number": 104, "title": "VAMOS ADORAR A DEUS (Ap 4.10-11)", "page": 23, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Coro", "text": "Coro: {Vamos adorar a Deus. Vamos adorar a Deus.\nVamos invocar Seu nome. Vamos adorar a Deus.} (Bis)"}, {"label": "Estrofe 1", "text": "Ao que está assentado, no trono, e ao Cordeiro,\nSeja o louvor, e a honra, e a glória, e o domínio,\nPelos séculos, dos séculos, amém!"}], "reviewed": false}, {"number": 105, "title": "BUSCAI O REINO DE DEUS", "page": 23, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Buscai primeiro o Reino de Deus, e a Sua justiça,\nE todas as coisas vos serão acrescentadas.\nAlelu-Aleluia!} (Bis – somente os homens)"}, {"label": "Estrofe 2", "text": "(M) Aleluia, Aleluia, Aleluia, Alelu-Aleluia!"}, {"label": "Estrofe 3", "text": "{Não só de pão o homem viverá, mas de toda a palavra,\nQue se procede da boca de Deus.\nAlelu-Aleluia (Bis – somente os homens)"}, {"label": "Estrofe 4", "text": "{Se vos perseguem por causa de mim, não estranheis o porquê.\nNão é o servo maior que o Senhor.\nAlelu-Aleluia!} (Bis – somente os homens)"}, {"label": "Estrofe 5", "text": "(M) Aleluia, Aleluia, Aleluia, Alelu-Aleluia!"}], "reviewed": false}, {"number": 106, "title": "SOMOS UM NO ESPÍRITO", "page": 24, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Somos um no espírito e um no Senhor.} (Bis)\nE rogamos que sempre haja esta união,\nE o mundo verá o nosso amor, nosso amor,\nSim, o mundo verá o nosso –"}, {"label": "Estrofe 2", "text": "(H) A-mor, a-mor, (Mulheres ecoando)\nNuma palavra o Evangelho é amor.\nConte aos outros de Jesus, pois Ele é amor!"}, {"label": "Estrofe 3", "text": "(H) Paz, paz, paz, paz (Mulheres ecoando)\nNuma palavra o Evangelho é paz.\nPaz que excede o conhecimento, paz, paz, paz,"}, {"label": "Estrofe 4", "text": "(H) Cristo, Cristo, (Mulheres ecoando)\nNuma palavra o Evangelho é Jesus.\nEle morreu e ressurgiu. Vivo é Jesus. Vivo é Jesus."}], "reviewed": false}, {"number": 107, "title": "VENHA CRISTO", "page": 24, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "(Homens começam com as Mulheres ecoando)\nJesus Cristo, meu Amigo, Ele me ama, eu O amo.\nRessurgido, Ele volta. Venha Cristo, Aleluia!"}, {"label": "Coro", "text": "Coro: (Homens cantam “Aleluia” 6 vezes)\n(M) Ele viveu para morrer na cruz. Resgatar a humanidade.\nVencendo a morte, Ele ressuscitou! Agora reina para sempre!"}, {"label": "Estrofe 2", "text": "(Homens começam com as Mulheres ecoando)\nEm Jesus, Amigo temos, mais chegado que um irmão.\nEle manda que levemos, tudo a Deus em oração."}], "reviewed": false}, {"number": 108, "title": "EU INVOCO MEU SENHOR (Sl 18)", "page": 24, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "(Homens começam com as Mulheres ecoando)\nEu invoco meu Senhor.\nDigno é de ser louvado.\nSerei salvo dos inimigos."}, {"label": "Coro", "text": "Coro: {O Senhor vive. Bendita seja a Rocha\nE exaltado seja o nome do meu Salvador!} (Bis)"}, {"label": "Estrofe 2", "text": "(Homens começam com as Mulheres ecoando)\nQuem é Deus senão o Senhor?\nQuem é a Rocha senão o Deus?\nRevestir-me-á de força."}], "reviewed": false}, {"number": 109, "title": "MARAVILHOSO É CRISTO SENHOR", "page": 24, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Maravilhoso é! Maravilhoso é!\nMaravilhoso é, Cristo Senhor!\nEle é o grande Rei, Mestre de tudo, eu sei.\nMaravilhoso é, Cristo Senhor!"}, {"label": "Estrofe 2", "text": "Ele é o bom Pastor, a Rocha Eterna,\nTodo Poderoso Deus!\nProstrai, ó povos. Louvai de novo.\nMaravilhoso é, Cristo Senhor!"}], "reviewed": false}, {"number": 110, "title": "LOUVE AO SENHOR", "page": 25, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Louve o Senhor com todo o ser.\nLouve, pois é Ele o Rei dos Reis.} (Bis)"}, {"label": "Estrofe 2", "text": "Louve com a vida, que Ele mesmo colocou em ti,\nPara que entendessem o porquê de existir."}, {"label": "Coro", "text": "Coro: Por isso eu, falo, canto e grito,\nA este Deus, Rei do infinito,\n“Não é um homem que me negará\nA liberdade de eu poder cantar.”\nEu quero é transbordar\nEm amor e graças dar."}, {"label": "Estrofe 3", "text": "{Louve ao Senhor da criação.\nLouve por tão grande salvação.} (Bis)"}, {"label": "Estrofe 4", "text": "Como posso me calar? Os mortos fazem isto bem.\nEu só quero exaltar, a Deus e mais ninguém!"}], "reviewed": false}, {"number": 111, "title": "CANTE ALELUIA AO SENHOR", "page": 25, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "1.\n(H) Cante Aleluia ao Senhor. (M) Cante Aleluia ao Senhor.\n(H) Cante Aleluia ao Senhor. (M) Cante Aleluia ao Senhor.\n(H) Cante Aleluia, cante aleluia. (M) A-le-lu-ia\n(H) Cante Aleluia ao Senhor. (M) Cante Aleluia ao Senhor"}, {"label": "Estrofe 2", "text": "2. Cristo morreu na crua por nós.\n3. Cristo Jesus ressuscitou.\n4. Vive na igreja entre nós.\n5 . Cristo em breve voltará\n6 . Cante aleluia ao Senhor."}], "reviewed": false}, {"number": 112, "title": "CERTEZA", "page": 25, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se andas a procurar, a paz tão desejada\nNão deves desiludir, embora mil problemas\nTenhas que enfrentar. A dor é passageira. Logo chega ao fim."}, {"label": "Estrofe 2", "text": "Então porque temer? Se um novo dia surge\nPode ser bem melhor. Esquece o que passou\nE olha sempre em frente. Encontrarás prazer e paz."}, {"label": "Estrofe 3", "text": "{Talvez em teu viver, não encontraste amor.\nPorém, existe alguém que te ama, te quer bem.\nPodes certeza ter, que tudo há de mudar.\nSempre serás feliz. Jesus em teu viver\nTransformação fará, e então com Ele vais morar.} (Bis)"}], "reviewed": false}, {"number": 113, "title": "QUERO LOUVAR-TE", "page": 25, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "(T) {Glória a Deus, glória a Deus!} (Bis)"}, {"label": "Estrofe 2", "text": "(H) Quero louvar-Te, sempre mais e mais.\nQuero louvar-Te, sempre mais e mais.\nBuscar o Teu querer, Tua graça conhecer,\nQuero louvar-Te (Senhor – só no final)"}, {"label": "Estrofe 3", "text": "1. (M) As aves do céu, cantam para Ti.\nAs flores do campo, refletem Teu poder .\nQuero cantar, quero entregar.\nMeu coração a Ti. (Senhor – só no final)"}, {"label": "Estrofe 4", "text": "2. (H) Amar-te (M) As aves...\n3. (H) Servir-Te (M) As aves...\n4. (H) Buscar-Te (M) As aves..."}], "reviewed": false}, {"number": 114, "title": "EXULTAÇÃO", "page": 26, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A Deus demos glória com grande fervor!\nSeu Filho bendito por nós todos deu.\nA graça concede ao mais vil pecador,\nAbrindo-lhe a porta de entrada no céu."}, {"label": "Coro", "text": "Coro: Exultai! Exultai! Vinde todos louvar.\nA Jesus Salvador, a Jesus Redentor!\nA Deus demos glória porquanto do céu\nSeu Filho, bendito por nós todos deu."}, {"label": "Estrofe 2", "text": "Oh! Graça real foi assim que Jesus,\nMorrendo Seu sangue por nós derramou!\nHerança nos céus com os santos em luz,\nComprou-nos Jesus, pois o preço pagou."}, {"label": "Estrofe 3", "text": "A crer nos convida tal rasgo de amor,\nNos merecimentos do Filho de Deus.\nE quem pois confia no seu Salvador.\nVai vê-lo sentado na glória dos céus."}], "reviewed": false}, {"number": 115, "title": "FICA COMIGO", "page": 26, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Fica comigo, Deus meu Salvador.\nViver sem Ti não posso, meu Senhor!\nSem teu poder, o peso desta vida,\nNão mais eu poderia suportar."}, {"label": "Estrofe 2", "text": "Fica comigo, Deus ó benção minha!\nQual outro dom teria mais valor\nDo que a Tua presença preciosa,\nDia a dia, ó meu Redentor?"}, {"label": "Estrofe 3", "text": "Fica comigo quando tempestades\nCaem sobre mim ó Deus meu Protetor!\nSe ao meu lado estrondam altos mares,\nNão fazem me jamais sentir temor."}, {"label": "Estrofe 4", "text": "Fica comigo quando a solidão\nVence e eu não posso agüentar.\nChamas de dor e a morte já chegando,\nÓ Deus Senhor comigo vem ficar!"}], "reviewed": false}, {"number": 116, "title": "DEUS É TÃO BOM", "page": 26, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Deus é tão bom, aleluia} (Bis)\nDeus é tão bom, é tão bom pra mim."}, {"label": "Estrofe 2", "text": "{Cristo é real, aleluia} (Bis)\nCristo é real, é real pra mim."}, {"label": "Estrofe 3", "text": "(Ele voltará, aleluia} (Bis)\nEle voltará, voltará pra mim."}, {"label": "Estrofe 4", "text": "Deus é tão bom, aleluia. Cristo é real, aleluia,\nEle voltará, voltará pra mim."}], "reviewed": false}, {"number": 117, "title": "RAZÃO DE VIVER", "page": 27, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Andam procurando a razão de viver\nNeste mundo mau querem paz receber.\nFazem seus caminhos pensando em achar\nAlgo que pra vida valor possa dar."}, {"label": "Coro", "text": "Coro: Mas só Jesus pode dar a razão de viver.\nAlegria e paz só Jesus pode dar,\nE assim você será bem feliz, em Jesus."}, {"label": "Estrofe 2", "text": "Como todo mundo eu também procurei\nE agora digo que a paz encontrei.\nCristo me salvou e eu quero falar\nQue uma nova vida Ele pode lhe dar."}], "reviewed": false}, {"number": 118, "title": "SÊ FIEL (AP. 2.10)", "page": 27, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sê fiel até a morte, e Eu te darei\nA coroa da vida.\nSê fiel! Sê fiel!"}], "reviewed": false}, {"number": 119, "title": "ABRE MEUS OLHOS", "page": 27, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Coro", "text": "Coro: (H) Abre meus olhos, eu quero ver Cristo.\nEu quero segui-Lo, dizer que O amo.\n(M) Abre os ouvidos, eu quero ouvir Cristo.\nNas folhas do Livro, eu quero buscá-lo."}, {"label": "Estrofe 1", "text": "Vou contar, vou contar, das belezas que Ele fez, vou contar.\nO Senhor veio me mostrar, cada dia do meu viver,\nO caminho a seguir, rumo ao lar."}, {"label": "Estrofe 2", "text": "Vou cantar, vou cantar, das belezas de Ele fez, vou cantar.\nDemonstrar meu grande amor através do meu viver,\nE a Ele sempre dar meu louvor."}], "reviewed": false}, {"number": 120, "title": "O BARQUINHO", "page": 27, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vede cautelosamente vai, um barquinho a vagar,\nE o vento que é o seu motor, não o deixa parar.\nMinha vida é assim, também.\nNão vivo no mar, mas vivo a vagar.\n{Sou como um barquinho cruzador,\nMas quem me conduz é o Senhor.} (Bis)"}], "reviewed": false}, {"number": 121, "title": "O SENHOR É A MINHA LUZ (Sl 27.1)", "page": 27, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{O Senhor é a minha luz, e a minha salvação.\nA quem temerei, a quem temerei?} (Bis)"}, {"label": "Estrofe 2", "text": "O Senhor é meu refúgio e paz,\nA quem então eu preciso temer?\nO Senhor é a minha luz, e a minha salvação.\nA quem temerei, a quem temerei?"}], "reviewed": false}, {"number": 122, "title": "CREPÚSCULO", "page": 28, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Põe-se o sol e a noite cai, brilham já estrelas mil.\nNesta paz suave, ó Pai, faze ouvir a voz gentil,\nA voz gentil!"}, {"label": "Coro", "text": "Coro: Santo, Santo, Santo és nosso Deus!\nTerra e mar e os altos céus, dão louvor a Ti, Senhor,\nA Ti, Senhor!"}, {"label": "Estrofe 2", "text": "Foge a luz, e as sombras vêm. Calma e paz repousa então.\nDesce, ó Pai, do lar de além. Dá-nos, pois, o Teu perdão,\nO Teu perdão."}, {"label": "Estrofe 3", "text": "Quando enfim reinar a paz, glória, luz e eterno amor,\nTu, que lá no céu estás, lembra-te de nós, Senhor,\nDe nós, Senhor!"}], "reviewed": false}, {"number": 123, "title": "LOUVAI", "page": 28, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Louvai ao Senhor pra sempre,\nDigo outra vez, louvai!\nLouvai o Senhor pra sempre,\nDigo outra vez, louvai!"}, {"label": "Estrofe 2", "text": "Louvai, louvai!\nDigo outra vez, louvai!\nLouvai, louvai!\nDigo outra vez, louvai!"}], "reviewed": false}, {"number": 124, "title": "MAIS PERTO", "page": 28, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mais perto quero estar, meu Deus, de Ti.\nAinda que seja a dor, que me una a Ti.\nSempre hei de suplicar,\nMais perto quero estar,\nMais perto quero estar,\nMeu Deus, de Ti."}, {"label": "Estrofe 2", "text": "Andando triste aqui, na solidão,\nPaz e descanso a mim, Teus braços dão.\nSempre hei de suplicar,\nMais perto quero estar,\nMais perto quero estar,\nMeu Deus, de Ti."}, {"label": "Estrofe 3", "text": "Minh´alma cantará a Ti, Senhor,\nCheia de gratidão, por Teu amor.\nSempre hei de suplicar,\nMais perto quero estar,\nMais perto quero estar,\nMeu Deus, de Ti."}, {"label": "Estrofe 4", "text": "E quando a morte, enfim, me vier chamar,\nCom serafins nos céus, irei morar.\nEntão me alegrarei,\nPerto de Ti, meu Rei,\nPerto de Ti, meu Rei,\nMeu Deus, de Ti."}], "reviewed": false}, {"number": 125, "title": "MAIS DE CRISTO", "page": 29, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mais de Cristo eu quero ver,\nMais do Seu amor obter,\nMais da Sua compaixão,\nMais da Sua mansidão."}, {"label": "Coro", "text": "Coro: {Mais, mais de Cristo.} (Bis)\nMais do Seu puro e santo amor,\nMais de Ti mesmo, ó Salvador!"}, {"label": "Estrofe 2", "text": "Mais de Cristo compreender,\nQuero a Cristo obedecer,\nSempre perto dEle andar,\nSeu amor manifestar."}], "reviewed": false}, {"number": 126, "title": "SENHOR E PAI", "page": 29, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Senhor e Pai de todos nós,\nPerdão por todo mal.\nÓ vem, com Tua doce voz,\nFalarmos mais assim a sós,\nDe paz celestial."}, {"label": "Estrofe 2", "text": "Ó Pai, possamos, hoje aqui,\nO Teu chamado ouvir,\nTal qual fizeste lá no mar,\nPossamos nós contigo andar\nAté ao fim seguir!"}, {"label": "Estrofe 3", "text": "A Ti queremos vir, Senhor,\nO mal deixando atrás!\nAssim possamos sempre ter\nA plenitude no viver\nDe luz, descanso e paz."}], "reviewed": false}, {"number": 127, "title": "A LINDA HISTÓRIA", "page": 29, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cantarei a linda história\nDe Jesus, o Salvador,\nQue deixou Seu lar na glória,\nPra salvar o pecador."}, {"label": "Coro", "text": "Coro: (M) Cantarei - - - - - - a linda história\n(H) Cantarei - - - - - - a linda história\n(M) De Jesus, - - - - - - meu Salvador\n(H) De Jesus, - - - - - - meu Salvador\n(M) Cantarei - - - - - - na Sua glória\n(H) Cantarei - - - - - - na Sua glória\n(M) Com os santos, - - - - - - com fervor.\n(H) Com os santos, - - - - - - com fervor."}, {"label": "Estrofe 2", "text": "Eu perdi-me e Ele achou-me,\nLonge, longe, do meu lar.\nAbraçou-me então, tomou-me\nPra com Ele eu ir morar."}, {"label": "Estrofe 3", "text": "Jesus Cristo deparou-me,\nQuando fraco, pra morrer,\nAs feridas Ele untou-me\nE livrou-me com poder."}, {"label": "Estrofe 4", "text": "Dias negros ainda tenho,\nSofrimento e dissabor,\nMas a Ele eu tudo exponho\nE me livra com amor."}], "reviewed": false}, {"number": 128, "title": "AMOR FRATERNAL", "page": 30, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus, Pastor amado, contempla-nos aqui;\nConcede que sejamos um corpo só em Ti.\nContendas e malícias que longe de nós vão;\nNenhum desgosto impeça a nossa comunhão!"}, {"label": "Estrofe 2", "text": "Pois sendo resgatados por um só Salvador,\nDevemos ser unidos por um mais forte amor.\nOlhar com simpatia os erros de um irmão,\nE todos ajudá-lo com branda compaixão."}, {"label": "Estrofe 3", "text": "Jesus, suave e meigo, ensina-nos a mar,\nE, como Tu, sejamos também no perdoar!\nAh! Quanto carecemos de auxilio do Senhor!\nUnidos, supliquemos a Deus por esse amor!"}, {"label": "Estrofe 4", "text": "Se Tua igreja toda andar em santa união,\nEntão será bendito o nome de cristão.\nAssim o que pediste em nós se cumprirá,\nE todo o mundo inteiro a Ti conhecerá!"}], "reviewed": false}, {"number": 129, "title": "SEGURANÇA", "page": 30, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que segurança sou de Jesus. Eu já desfruto o gozo da luz.\nSou por Jesus, herdeiro de Deus.\nEle me leva à glória dos céus."}, {"label": "Coro", "text": "Coro: {Canta, minh´alma! Canta ao Senhor!\nRende-Lhe sempre ardente louvor.} (Bis)"}, {"label": "Estrofe 2", "text": "Ao seu amor, eu me submeti, e extasiado então me senti,\nAnjos descendo, trazem dos céus\nEcos da excelsa graça de Deus."}, {"label": "Estrofe 3", "text": "Sempre vivendo em Seu grande amor.\nMe regozijo em meu Salvador.\nEsperançoso, vivo na luz, pela bondade do meu Jesus."}], "reviewed": false}, {"number": 130, "title": "FIRMEZA", "page": 30, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Em nada ponho a minha fé, senão na graça de Jesus;\nNo sacrifício remidor, no sangue do bom Redentor."}, {"label": "Coro", "text": "Coro: A minha fé e o meu amor, estão firmados no Senhor.\nEstão firmados no Senhor."}, {"label": "Estrofe 2", "text": "Se Lhe não posso a face ver, na Sua graça vou viver;\nEm cada transe, sem falhar, sempre hei de nEle confiar."}, {"label": "Estrofe 3", "text": "Seu juramento é mui leal, abriga-me no temporal;\nAo vir cercar-me a tentação, é Cristo a minha salvação."}, {"label": "Estrofe 4", "text": "Assim que o Seu clarim soar, irei com Ele me encontrar;\nE gozarei da redenção, com todos que no céu estão."}], "reviewed": false}, {"number": 131, "title": "CRISTO! CRISTO!", "page": 30, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que delícia crer em Cristo, em seu nome confiar;\nAceitar os Seus ensinos, e as promessas desfrutar."}, {"label": "Coro", "text": "Coro: Cristo! Cristo! Já confio, em Teu nome, em Teu poder!\nCristo! Cristo! Bem-amado, faz a minha fé crescer!"}, {"label": "Estrofe 2", "text": "Oh! Que gozo crer em Cristo, ter certeza de perdão!\nReceber amor de Cristo, vida, paz e salvação."}, {"label": "Estrofe 3", "text": "Bem feliz eu sou em Cristo. Sempre dEle quero ser.\nQuero agora mui submisso, só a Ele obedecer."}], "reviewed": false}, {"number": 132, "title": "SOU PEQUENO", "page": 31, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Meu Jesus, no céu está, preparando um lar, eu sei.\nFaz tempo, sim, que Ele foi, preparar um lindo lugar."}, {"label": "Estrofe 2", "text": "Cristo um dia vai voltar, vem pra me levar,\nE no lar que preparou, vou pra sempre morar."}, {"label": "Estrofe 3", "text": "{Sou pequeno, mas Jesus está em meu coração,\ne por isso digo vou ao céu.} (Bis)"}], "reviewed": false}, {"number": 133, "title": "CALMO, SERENO E TRANQUILO.", "page": 31, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Calmo, sereno e tranqüilo, sinto descanso neste viver.\nIsto devo a um Amigo, que só por Ele eu pude obter."}, {"label": "Coro", "text": "Coro: É Jesus, meu Amigo, meu Senhor, o Salvador.\nSó por Ele ganhei a vida eterna com Deus.\n(com Deus, com Deus somente no final)"}, {"label": "Estrofe 2", "text": "Triste foi sua história, levado a cruz sem pecado algum.\nSó porque me amou, morreu por mim e não hesitou."}], "reviewed": false}, {"number": 134, "title": "SOB A SOMBRA DO ALTÍSSIMO (Sl 91)", "page": 31, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Aquele que habita no esconderijo do Altíssimo,\nA sombra do Senhor, Onipotente descansará} (bis)"}, {"label": "Estrofe 2", "text": "(H) Direi do Senhor, (M) Direi do Senhor,\n(T) Ele é meu Deus. (3 vezes)"}, {"label": "Estrofe 3", "text": "Amém, Amém."}], "reviewed": false}, {"number": 135, "title": "O SENHOR TEU DEUS (Sf 3.17)", "page": 31, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{O Senhor, Teu Deus, está no meio de ti,\nPoderoso para salvar-te.\nEle Se deleitará em ti com alegria.\nRenovar-te-á no Seu amor.\nRegozijar-Se-á em ti com júbilo.} (Bis)"}, {"label": "Estrofe 2", "text": "O Senhor, Teu Deus, está no meio de ti,\nPoderoso, poderoso, poderoso."}], "reviewed": false}, {"number": 136, "title": "SANTO", "page": 31, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Santo! Santo! Santo! Deus Onipotente!\nCedo, de manhã, cantaremos Teu louvor.\nSanto! Santo! Santo! Deus Jeová triuno,\nÉs um só Deus, excelso Criador!"}, {"label": "Estrofe 2", "text": "Santo! Santo! Santo! Todos os remidos.\nJunto com os anjos, proclamam Teu louvor.\nAntes de formar-se o firmamento e a terra,\nEras, e sempre és e hás de ser, Senhor."}, {"label": "Estrofe 3", "text": "Santo! Santo! Santo! Nós os pecadores.\nNão podemos ver Tua glória sem tremor.\nTu somente és Santo. Não há nenhum outro.\nPuro e perfeito, excelso Benfeitor."}, {"label": "Estrofe 4", "text": "Santo! Santo! Santo! Deus Onipotente!\nTuas obras louvam Teu nome com fervor.\nSanto! Santo! Santo! Justo e compassivo,\nÉs um só Deus, supremo Criador!"}], "reviewed": false}, {"number": 137, "title": "QUE A BELEZA DE CRISTO", "page": 32, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que a beleza de Cristo se veja em mim.\nToda a Sua bondade e amor sem fim.\nOh! Que todo o meu ser, possa se converter,\nQue a beleza de Cristo se veja em mim."}], "reviewed": false}, {"number": 138, "title": "JESUS ME TRANSFORMOU", "page": 32, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu perdido pecador, longe do meu Jesus.\nAbatido e sem vigor, a perecer sem luz.\nMeu estado Cristo viu, dando-me Sua mão,\nE salvar-me conseguiu da perdição."}, {"label": "Coro", "text": "Coro: Cristo me amou, e me livrou.\nO Seu imenso amor, me transformou.\nFoi Seu poder, o Seu querer.\nSim, Cristo o Salvador, me transformou."}, {"label": "Estrofe 2", "text": "Minha vida, todo o ser, quero-lhe consagrar.\nAo Seu lado vou viver, o Seu amor cantar.\nA mensagem transmitir aos que perdidos são,\nVenham todos já fruir a salvação."}], "reviewed": false}, {"number": 139, "title": "SEGURA NA MÃO DE DEUS", "page": 32, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se as águas do mar da vida quiserem te afogar,\nSegura na mão de Deus e vai.\nSe as tristezas desta vida quiserem te sufocar,\nSegura na mão de Deus e vai."}, {"label": "Coro", "text": "Coro: Segura na mão de Deus, segura na mão de Deus,\nPois ela, ela te sustentará.\nNão temas, segue adiante, e não olhes para trás,\nMas segura na mão de Deus e vai."}, {"label": "Estrofe 2", "text": "Se a jornada é pesada e te cansa a caminhada,\nSegura na mão de Deus e vai.\nOrando, jejuando, confiando e confessando,\nSegura na mão de Deus e vai."}, {"label": "Estrofe 3", "text": "O Espírito do Senhor sempre te revestirá,\nSegura na mão de Deus e vai.\nJesus Cristo prometeu que jamais te deixará,\nSegura na mão de Deus e vai."}], "reviewed": false}, {"number": 140, "title": "GLÓRIA PRA SEMPRE", "page": 33, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Glória pra sempre ao Cordeiro de Deus.\nA Jesus, o Senhor, ao Leão de Judá.\nA raiz de Davi, que venceu e o livro abrirá."}, {"label": "Estrofe 2", "text": "Os céus, a terra e o mar, e tudo o que neles há,\nO adorarão e confessarão, “Jesus Cristo é o Senhor!”"}, {"label": "Estrofe 3", "text": "(H) Ele é o Senhor (M) Aleluia\n(H) Ele é o Senhor (M) Aleluia\n(H) Ressurecto dentre os mortos, Ele é o Senhor. (M) Aleluia\n(T) Todo joelho se dobrará, toda língua confessará.\nQue Jesus Cristo é o Senhor. (Bis)"}], "reviewed": false}, {"number": 141, "title": "TOMA-ME A MÃO", "page": 33, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vem, Senhor, me guiar, minha fé sustentar.\nFraco estou, débil sou, sem vigor.\nQuero as trevas deixar, quero a luz alcançar.\nPela mão, vem guiar-me, Senhor!"}, {"label": "Estrofe 2", "text": "Se o meu jornadear exigir batalhar,\nLaços mil Satanás me armar,\nSocorrer-me ó vem, meu Senhor, Salvador.\nPela mão, vem guiar-me ao lar."}], "reviewed": false}, {"number": 142, "title": "PAI EU TE ADORO", "page": 33, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Pai, eu Te adoro. Minha vida te entrego.\nComo eu Te amo."}, {"label": "Estrofe 2", "text": "Jesus, eu Te adoro. Minha vida Te entrego.\nComo eu Te amo."}, {"label": "Estrofe 3", "text": "Espírito, eu Te adoro. Minha vida Te entrego.\nComo eu Te amo."}], "reviewed": false}, {"number": 143, "title": "ALELUIA", "page": 33, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A, la-la-la, la-la-la, le-lú-ia,\nA, la-la-la, la-la-la, le-lú,\nA, la-la-la, la-la-la, le-lú, ia.\nA, la-la-la, la-la-la, a-le-lu-ia (homens seguram o “ia” )"}, {"label": "Coro", "text": "Coro: (M) A, la-la-la, la-la-la, le-lú-ia,\nA, la-la-la, la-la-la, le-lú,\n(T) A, la-la-la, la-la-la, le-lú, ia.\nA, la-la-la, la-la-la, a-le-lú-ia (Bis)"}, {"label": "Estrofe 2", "text": "Deus apresentou sinais, milagres, Deus apresentou Jesus, meu rei.\nDeus apresentou sinais, milagres, Deus apresentou Jesus, Jesus, meu rei."}, {"label": "Estrofe 3", "text": "Eu crucifiquei o Nazareno. Eu crucifiquei Jesus, meu rei.\nEu crucifiquei o Nazareno, Eu crucifiquei, Jesus, Jesus, meu Rei."}, {"label": "Estrofe 4", "text": "Deus ressuscitou meu Senhor e Cristo, Deus ressuscitou Jesus, meu Rei.\nDeus ressuscitou meu Senhor e Cristo, Deus ressuscitou Jesus, Jesus, meu Rei."}, {"label": "Estrofe 5", "text": "Eu exaltarei Jesus pra sempre, Eu exaltarei Jesus, meu Rei.\nEu exaltarei Jesus pra sempre, Eu exaltarei Jesus, Jesus, meu Rei."}], "reviewed": false}, {"number": 144, "title": "TRANSFORMAÇÃO", "page": 34, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Como a chuva que cai de novo, depois que tudo secou;\nComo a flor que eu vi se abrindo, depois que alguém a regou;\nAssim foi o meu amor, depois que minh´alma te encontrou."}, {"label": "Coro", "text": "Coro: E não vou deixar meu Deus.\nE não vou mais repousar.\nE não vou mais me enganar.\nSem meu Deus não sei viver."}, {"label": "Estrofe 2", "text": "Como a terra que não gerava, e o milagre a transformou;\nEncontrei a mão de Deus, e do chão me levantou.\nAssim foi o meu amor, depois que meu Deus me cativou."}], "reviewed": false}, {"number": 145, "title": "DEUS FORTE, COMO JEOVÁ", "page": 34, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Deus forte, como Jeová,\nNão há outro que eu conheça.} (Bis)"}, {"label": "Estrofe 2", "text": "{Deus da Vitória, Varão de Guerra,\nDeus Soberano. Ele é o Senhor.} (Bis)"}, {"label": "Coro", "text": "Coro: (M) Onde? (H) Onde?\n(T) Onde está seu Deus?\n(M) Onde? (H) Onde?\n(T) Onde ele está?"}, {"label": "Estrofe 3", "text": "{Meu Deus, Ele está no céu,\nTambém no meu coração.\nOs do mundo estão mortos,\nMas o Meu ressuscitou.} (Bis)"}], "reviewed": false}, {"number": 146, "title": "A NOVA JERUSALÉM", "page": 34, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Em um novo caminho estou. Graças ao grande Rei que vou\nCaminhando pra chegar e com o Salvador estar.\nRuas de ouro eu pisarei, e do sol não precisarei,\nPois a glória do meu Deus, a cidade iluminou."}, {"label": "Coro", "text": "Coro: (H) Pra nova Jerusalém (M) Nova Jerusalém\n(H) Pra nova Jerusalém (M) Nova Jerusalém\n(H) Pra nova Jerusalém eu caminhando vou.\n(M) Jerusalém (Bis)\n(T) Eu vou!"}, {"label": "Estrofe 2", "text": "Lá no céu dor não haverá.. Toda lágrima cessará.\nPois o reino de Jesus, só existe amor e paz.\nE qual é tua condição? Do Senhor já tens o perdão\nE a certeza de viver, para sempre com o Rei?"}], "reviewed": false}, {"number": 147, "title": "EXALTAR-TE-EI (Sl 145)", "page": 34, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Coro", "text": "Coro: { Exaltar-Te-ei, ó Deus meu, e Rei.\nBendirei o Teu nome.} (Bis)\nPara todo o sempre. Todos os dias Te bendirei,\nE louvarei o Teu nome, para todo o sempre.\n(“YAHULH” – somente no final o nome em hebraico de Deus)"}, {"label": "Estrofe 1", "text": "Grande é o Senhor, e mui digno de ser louvado.\nA sua grandeza é insondável."}, {"label": "Estrofe 2", "text": "O Senhor é bom para todos, misericordioso.\nO Senhor é fiel em todas as Suas palavras."}, {"label": "Estrofe 3", "text": "Perto está o Senhor de todos os que O invocam,\nDe todos os que O invocam em verdade."}], "reviewed": false}, {"number": 148, "title": "VAMOS CANTAR, ORAR E CONFIAR", "page": 35, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Coro", "text": "Coro: (H) Vamos cantar, (M) Cantar louvores ao nosso Deus (Bis)\n(H) Quem nos criou (M) Quem nos criou,\n(H) E nos salvou. (M) E nos salvou\n(T) Vamos cantar, sem cessar, ao nosso grande Deus !"}, {"label": "Estrofe 1", "text": "(H) Vamos orar, (M) Para descer o poder de Deus (Bis)\n(H) Quem nos criou (M) Quem nos criou,\n(H) E nos salvou. (M) E nos salvou\n(T) Vamos orar, sem cessar, ao nosso grande Deus !"}, {"label": "Estrofe 2", "text": "(H) E confiar, (M) Pois o sustento só vem de Deus. (Bis)\n(H) Quem nos criou (M) Quem nos criou,\n(H) E nos salvou. (M) E nos salvou\n(T) Sim confiar, sem cessar, ao nosso grande Deus !"}], "reviewed": false}, {"number": 149, "title": "ALIANÇA", "page": 35, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Como é precioso, irmão, estar bem junto a ti,\nE juntos, lado a lado, andarmos com Jesus,\nE expressarmos o amor, que um dia Ele nos deu,\nPelo sangue do calvário, sua vida trouxe a nós."}, {"label": "Estrofe 2", "text": "{Aliança no Senhor eu tenho com você.\nNão existem mais barreiras em meu ser.\nEu sou livre pra te amar, pra te aceitar,\nE para te pedir. “Perdoa-me irmão”."}, {"label": "Estrofe 3", "text": "Eu sou um, com você, no amor, do nosso Pai.\nSomos um, no amor de Jesus.\nEu sou um, com você, no amor do nosso Pai.\nSomos um, no amor, de Jesus.} (Bis)"}, {"label": "Estrofe 4", "text": "{Somos um no amor de Jesus.} (Bis)"}], "reviewed": false}, {"number": 150, "title": "CONTINUAR", "page": 35, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Bem sei que tudo podes, meu Amado.\nNenhum dos teus planos é frustrado.\nAinda que com perdas e com dor,\nEu sempre seguirei a Ti, Senhor."}, {"label": "Estrofe 2", "text": "{Os Teus caminhos posso não entender, Senhor,\nmas sei que tudo é visando o meu crescer.\nSe lutas e tribulações eu tenho que passar,\nTe peço forças pra continuar."}, {"label": "Estrofe 3", "text": "Continuar a crer e a confiar,\nNo grande amor que tens, meu Pai, por mim.\nO meu desejo eterno é Te adorar,\nE aos Teus pés me derramar sem fim.} (Bis)"}, {"label": "Estrofe 4", "text": "Sim, e aos Teus pés me derramar sem fim."}], "reviewed": false}, {"number": 151, "title": "O MAIOR AMOR", "page": 35, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Jesus, és a razão da minha vida.\nTu és o meu Deus, a minha força,\nO meu descanso, o início e o fim,\nAmanhecer, entardecer.} (Bis)"}, {"label": "Estrofe 2", "text": "{Jesus, Tu és o meu maior amor,\nMeu Deus, a quem eu tanto amo,\nJesus maravilhoso,\nEterno e vitorioso.} (Bis)"}], "reviewed": false}, {"number": 152, "title": "TU ÉS MEU SALVADOR", "page": 36, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "(T) Deus, eu Te amo, meu Senhor. Tu és o meu libertador.\nTu és meu Salvado-o-o-or\nQuando clamei em oração, me estendeste a Tua mão.\nTu és meu Salvador."}, {"label": "Estrofe 2", "text": "(Mulheres o coro Homens o verso)\nMi-ser-i-cor-di-o-so és. Me per-do-as-te, Rei dos Reis.\nTu és meu Salvador-o-o-or.\nLivre da morte, perdição; Graças Te dou, de coração.\nTu és meu Salvador"}, {"label": "Estrofe 3", "text": "(Homens o coro Mulheres o verso)\nDeus, eu Te amo, meu Senhor. Tu és o meu libertador.\nTu és meu Salvado-o-o-or.\nQuando clamei em oração, me estendeste a Tua mão.\nTu és meu Salvador."}, {"label": "Coro", "text": "Coro: {Cris- to, Sal-va-dor. Graças ao Senhor!\nCris-to, Sal-va-dor. Graças ao Senhor!} (Bis)"}, {"label": "Estrofe 4", "text": "Graças ao Senho-o-o-o-or!\nGraças ao Senho-o-o-o-or!\nGraças ao Senho-o-o-o-or!"}], "reviewed": false}, {"number": 153, "title": "AO ÚNICO", "page": 36, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Ao único que é digno de receber,\nA honra e a glória, a força e o poder,\nAo Rei eterno, imortal, invisível, mas real,\nA Ele ministramos o louvor.} (Bis)"}, {"label": "Estrofe 2", "text": "{Coroamos a Ti, ó Rei Jesus. Coroamos a Ti, ó Rei Jesus.\nAdoramos o Teu nome Nos rendemos a Teus pés.\nConsagramos todo nosso ser a Ti.\nConsagramos todo nosso ser a Ti.} (Bis)\nConsagramos todo nosso ser – a Ti."}], "reviewed": false}, {"number": 154, "title": "AMIZADE", "page": 36, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se uma boa amizade você tem,\nLouve a Deus, pois a amizade é um bem.\nToda a boa amizade você deve conservar,\nComo é bom quando se sabe amar.\nA amizade vem de Deus, e a Deus deve levar,\nComo é bom quando se sabe amar."}, {"label": "Estrofe 2", "text": "Uma boa amizade, é mais forte do que a morte.\nMesmo longe, na saudade,\nA amizade vai ficando até mais forte."}, {"label": "Estrofe 3", "text": "A amizade faz da vida uma canção.\nA amizade faz bater o coração.\nSer amigo é fazer ao amigo todo o bem,\nComo é bom saber amar alguém.\nA amizade vem de Deus, e a Deus deve levar,\nComo é bom quando se sabe amar."}], "reviewed": false}, {"number": 155, "title": "PARA SER FELIZ", "page": 37, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Para ser feliz é preciso sentir,\nEste céu azul, esta imensidão,\nÉ fazer de tristezas estrelas a mais,\nE do pranto uma canção."}, {"label": "Estrofe 2", "text": "Há um mundo bem melhor, todo feito pra você.\nÉ um mundo pequenino que Cristo fez."}], "reviewed": false}, {"number": 156, "title": "CREIO EM TI", "page": 37, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Creio em Ti, ao ver que a chuva cai e faz,\nA flor nascer.\nCreio em Ti, pois sei que enquanto é noite aqui,\nÉ dia ali.\nCreio em Ti, porque me deste o riso e a dor,\nMe deste amor, do Teu amor.\nCreio em Ti! Creio em Ti!"}, {"label": "Estrofe 2", "text": "Se a paz sobre nós seu branco véu descer,\nEu creio em Ti.\nSe a tempestade a terra abalar,\nEu creio em Ti.\nCada vez que neste mundo eu escutar,\nAlguém cantar, alguém chorar.\nDirei então, “Creio em Ti!”"}], "reviewed": false}, {"number": 157, "title": "O LEÃO DA TRIBO DE JUDÁ", "page": 37, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Ele é o Leão da Tribo de Judá.\nJesus rompeu nossas cadeias e nos libertou.\nEle é a Rocha da nossa vitória,\nA nossa força em tempo de fraqueza,\nUma torre em tempo de guerra,\nA Esperança de Israel.} (Bis)"}, {"label": "Estrofe 2", "text": "{A Esperança de Israel.} (Bis)"}], "reviewed": false}, {"number": 158, "title": "LAR FELIZ", "page": 37, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Nesses dias de tanta incerteza,\nNossos lares a fé precisam ter.\nUns aos outros mostrando confiança;\nSendo assim, lar feliz nós vamos ser.\nCom amor, lar feliz nós vamos ser."}, {"label": "Estrofe 2", "text": "Nesses dias de tanta ansiedade,\nNossos lares paciência devem ter.\nUns aos outros mostrando esperança;\nSendo assim, lar feliz nós vamos ser.\nCom amor, lar feliz nós vamos ser."}, {"label": "Estrofe 3", "text": "Nesses dias de tanta insegurança,\nNossos lares firmeza devem ter .\nPais e filhos buscando harmonia;\nEm Jesus, lar feliz nós vamos ser.\nCom amor, lar feliz nós vamos ser."}], "reviewed": false}, {"number": 159, "title": "EM AMOR, POR MIM", "page": 38, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Este é o Meu corpo partido por ti;\nTraz salvação e dá a paz.\nToma e come, e quando fizeres,\nFaze-o em amor, por Mim."}, {"label": "Estrofe 2", "text": "Este é o Meu sangue vertido por ti;\nTraz o perdão e liberdade.\nToma e bebe, e quando fizeres,\nFaze-o em amor por Mim."}], "reviewed": false}, {"number": 160, "title": "AO SENTIR", "page": 38, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "(M) Ao sentir o mundo ao meu redor (H) Ao sentir\nNada vi que pudesse ser real Nada vi\nPercebi que todos buscam paz,\nPorém em vão. Porém em vão\nPois naquilo que procuram\nNão há solução. Não há solução.\nNão há solução. É só Jesus\n(T) Só em Jesus, a paz real eu pude encontrar;\no Seu amor pude experimentar.\nMe entreguei a Cristo, e a vida eterna vou gozar."}, {"label": "Estrofe 2", "text": "(M) Posso ver que você não é feliz (H) Posso ver\nVou dizer que não pode ser feliz Vou dizer\nSe continuar a procurar em vão, Procurar em vão\nEm caminhos que\nNão trazem solução Não trazem solução\nPois naquilo que procuram\nNão há solução. Não há solução.\nSolução. É só Jesus\n(T) Só em Jesus, a paz real você vai encontrar,\nO Seu amor vai experimentar\n{Vem a Jesus Cristo, e a vida eterna vai gozar.} (Bis)"}], "reviewed": false}, {"number": 161, "title": "DIAS VÃO E DIAS VÊM", "page": 38, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Dias vão e dias vêm, e mudança é tão comum.\nSó o Senhor dá-me confiança, e eu quero Te louvar."}, {"label": "Coro", "text": "Coro: Quando a vida apertar\nPra Ti a alma quer voar.\n{Só o Senhor dá-me confiança.\nE eu quero Te louvar.} (Bis - no final)"}, {"label": "Estrofe 2", "text": "Dono da luz, vida e esperança, só o Senhor pode conhecer.\nO vazio de todo homem, só o Senhor pode preencher."}], "reviewed": false}, {"number": 162, "title": "CREIO EM TI", "page": 38, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Perdido foi que Ele me encontrou, neste mundo vil.\nTomou-me no Seu sangue e me lavou. Hoje sou feliz!"}, {"label": "Coro", "text": "Coro: (H) Hoje sou feliz, (M) Ho- Hoje sou feliz,\nFoi-se o meu temor, Foi-se o meu temor,\nVou permanecer, Vou, vou permanecer,\nJunto ao Salvador. Junto ao Salvador."}, {"label": "Estrofe 2", "text": "Foi-se a escuridão. Foi- foi-se a escuridão.\nRaia a luz do sol, Raia a luz do sol.\nPois eu sei que, Pois eu sei que,\nSou do meu Senhor, Sou do meu Senhor,\nE Ele é meu! E Ele é meu!"}, {"label": "Estrofe 3", "text": "Se muitas tentações me sobrevêm, para Ele vou.\nRecebo forças que a mim convém, do meu Salvador."}, {"label": "Estrofe 4", "text": "Se a negra noite assustar-me vem, ouço a Tua voz\nAs trevas tornam-se a luz do sol, se com Ele estou."}], "reviewed": false}, {"number": 163, "title": "É O MEU PRAZER LOUVAR-TE", "page": 39, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quando o Pai enviou Seu Filho, para todos nos salvar.\nSeu amor no altar se derramou, para nova vida dar."}, {"label": "Coro", "text": "Coro: É o meu prazer louvá-lo. È o meu prazer orar.\nÉ o meu prazer erguer a voz e adorar."}, {"label": "Estrofe 2", "text": "Esta vida que me deste, meu caminho encheu de luz.\nQue me leva até o calvário, pois vitória vem da cruz."}, {"label": "Estrofe 3", "text": "Cristo, eu quero a Tua benção, pois me encontro aos Teus pés.\nEste mundo não me moverá do Teu altar."}], "reviewed": false}, {"number": 164, "title": "ELE É JEOVÁ", "page": 39, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ele é Jeová. O Deus da Criação!\nEle é Jeová, Deus Poderoso!\nEle é Deus forte, a Rocha Eterna.\nEle é Jeová-á-á, teu Deus, teu Salvador."}, {"label": "Coro", "text": "Coro: Canta Aleluia , canta aleluia.\nCanta aleluia, can-ta aleluia!\nEle é Jeová-á-á, Deus poderoso.\n{Ele é Jeová-á-á, teu Deus, teu Salvador.} (Bis - no final)"}, {"label": "Estrofe 2", "text": "ele é o “Grande Eu Sou”. È Deus de Abraão,\nJeová Shalom., o Deus de Paz, “ Eu Sou”,\nO Deus de Israel, teu Rei Eterno.\nEle é Jeová-á-á, teu Deus, teu Salvador."}, {"label": "Estrofe 3", "text": "Ele é teu provedor, Jeová Forte.\nÉ Deus da Salvação, o Deus Messias,\nQue em nosso meio, deu testemunho.\nEle é Jeová, teu Deus, teu Salvador."}], "reviewed": false}, {"number": 165, "title": "REUNIMO-NOS AQUI", "page": 39, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Reunimo-nos aqui, só pra glorificar o Rei Jesus.} (2 vezes)\nReunimo-nos aqui, só pra glorificar o Rei Jesus, Senhor.\nAdorar o Rei Jesus, Senhor.\nLevantemos nossas mãos só pra glorificar o Rei Jesus (2 vezes)\nLevantemos nossas mãos só pra glorificar o Rei Jesus, Senhor.\nAdorar o Rei Jesus Senhor.\nDe si mesmo se esquecer e só lembrar de Cristo Rei Jesus. (2 vezes)\nDe si mesmo se esquecer e só lembrar de Cristo Rei Jesus, Senhor.\nAdorar o Rei Jesus Senhor."}], "reviewed": false}, {"number": 166, "title": "A BARCA", "page": 39, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tu te abeiraste da praia.\nNão buscaste nem sábios, nem ricos,\nSomente queres que eu Te siga."}, {"label": "Coro", "text": "Coro: Senhor, Tu me olhaste nos olhos.\nA sorrir, pronunciaste meu nome.\nLá na praia, eu deixei o meu barco.\nJunto a Ti, buscarei outro mar."}, {"label": "Estrofe 2", "text": "Tu sabes bem que em meu barco,\nEu não tenho espadas, nem ouro,\nSomente redes e o meu trabalho."}, {"label": "Estrofe 3", "text": "Tu, minhas mãos solicitas,\nMeu cansaço, que a outros descansem,\nAmor que almeja seguir amando."}, {"label": "Estrofe 4", "text": "Tu, pescador de outros lagos,\nÂnsia eterna, de almas que esperam,\nBondoso amigo - e assim me chamas."}], "reviewed": false}, {"number": 167, "title": "DEUS ESTÁ AQUI", "page": 40, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Deus está aqui, aleluia,\nTão certo como o ar que eu respiro,\nTão certo como amanhã que se levanta,\nTão certo como eu te falo e podes me ouvir."}, {"label": "Estrofe 2", "text": "Deus está em ti ..."}, {"label": "Estrofe 3", "text": "Deus está em nós ..."}], "reviewed": false}, {"number": 168, "title": "A COMEÇAR EM MIM", "page": 40, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "(H) {A começar em mim, quebra corações,\nPra que sejamos todos um, como Tu és em nós.} (M – Bis)"}, {"label": "Estrofe 2", "text": "(M) A começar em mim, quebra corações,\n(H) A começar em mi-im, corações,\n(T) Pra que sejamos todos um, como Tu és em nós.\n(M) Onde há frieza que haja amor.\n(H) Onde há ódio o perdão.\n(T) Pra que teu corpo cresça, sim, rumo a perfeição. (Bis)"}, {"label": "Estrofe 3", "text": "(M) A começar em mim, quebra corações,\n(H) A começar em mi-im, corações,\n(T) Pra que sejamos todos um--como Tu és--em nós (Bis)"}], "reviewed": false}, {"number": 169, "title": "PORQUE RECEBO TANTO,", "page": 40, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "MUITO DEVO DAR"}, {"label": "Estrofe 2", "text": "Porque recebo tanto, muito devo dar;\nPois a prova cada dia Teu amor, sem par.\nCom meu irmão vou repartir. O que me dás vou dividir,\nTeu amor a todos transmitir."}, {"label": "Coro", "text": "Coro: Porque me amas com tão grande amor Senhor,\nMeus bens e minha vida estão ao seu dispor.\nVou repartir amor com todos por palavra e por ação,\nDemonstrando eterna gratidão."}, {"label": "Estrofe 3", "text": "Porque me ajudas e me dás meu pão, meu lar;\nNão posso ver o aflito sem compartilhar.\nVou repartir com meu irmão, o meu abrigo e o meu pão,\nE confortarei seu coração."}], "reviewed": false}, {"number": 170, "title": "NUNCA ESTOU SÓ", "page": 41, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mágoas, pesares, a mim sobrevêm,\nMas firme é o meu andar.\nPor que falharia, se tenho um abrigo,\nQue é Cristo, e quer me guiar?"}, {"label": "Coro", "text": "Coro: (H) Nunca estou (M) Nunca estou só\nPois meu Jesus Pois meu Jesus\nComigo está. Sim, Ele está.\nNunca estou só Nunca estou só\nE minha mão E minha mão\n(T) Sustem"}, {"label": "Estrofe 2", "text": "(T) Foi a promessa, de Jesus, me guiar."}, {"label": "Estrofe 3", "text": "{ (H) Nunca estou só (M) Nunca estou só\nCristo se deu Cristo se deu\n(T) Por mim} (Bis – no final)"}, {"label": "Estrofe 4", "text": "Vem meu amigo, estende sua mão.\nSegura na mão de Deus.\nPois Ele almeja guiar-te, livrar-te\nPor isso o meu Cristo morreu."}], "reviewed": false}, {"number": 171, "title": "A MENSAGEM", "page": 41, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vamos todos cantar e ao Senhor louvar,\nE esta mensagem levar.\nOuça bem meu irmão o que eu vou lhe dizer,\nJesus quer amar através de você."}, {"label": "Estrofe 2", "text": "Agora (H) vou, (M) vou, (H) vou, (M) vou,\n(T) Vou lhe dizer, “ Meu irmão, eu amo você!”."}], "reviewed": false}, {"number": 172, "title": "EU QUERO TE AMAR", "page": 41, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu quero te amar mais e mais, meu irmão,\nEu quero te amar mais e mais.\nVocê faz parte do corpo de Cristo.\nEu quero te amar mais e mais."}, {"label": "Estrofe 2", "text": "Eu quero te compreender, meu irmão,\nEu quero te compreender.\nVocê faz parte do corpo de Cristo.\nEu quero te compreender."}, {"label": "Estrofe 3", "text": "Não posso viver sem você, meu irmão,\nNão posso viver sem você.\nVocê faz parte do corpo de Cristo.\nNão posso viver sem você."}], "reviewed": false}, {"number": 173, "title": "TE AMO COM O AMOR DO SENHOR", "page": 42, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Te amo com o amor do Senhor.} (Bis)\nEu vejo em ti, a glória do meu Rei.\nSim, Te amo com o amor do Senhor."}, {"label": "Estrofe 2", "text": "{Amamos com o amor do Senhor.} (Bis)\nJesus em nós é a glória do meu Rei.\nSim, amamos com o amor do Senhor."}], "reviewed": false}, {"number": 174, "title": "O MESMO ESPÍRITO", "page": 42, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "{Sim, o mesmo Espírito que levantou Jesus\nHabita em nós, habita em nós!} (Bis)"}, {"label": "Estrofe 2", "text": "{Vivifica os nossos corpos,\nO mesmo Espírito que habita em nós.} (Bis)"}], "reviewed": false}, {"number": 175, "title": "MORRI NA CRUZ POR TI", "page": 42, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Morri na cruz por ti, morri pra te livrar.\nMeu sangue, sim, verti, e posso te salvar."}, {"label": "Coro", "text": "Coro: Morri, morri na cruz por ti;\nQue fazes tu por mim?\nMorri, morri na cruz por ti:\nQue fazes tu por mim?"}, {"label": "Estrofe 2", "text": "Aqui vivi por ti, sofri desprezo e dor.\nEu tudo fiz aqui pra ser teu salvador."}, {"label": "Estrofe 3", "text": "Sofri na cruz por ti, a fim de te remir;\nA vida consegui, que tu irás fruir."}, {"label": "Estrofe 4", "text": "Eu trouxe salvação, dos altos céus favor;\nÉ livre meu perdão, sincero meu amor."}], "reviewed": false}, {"number": 176, "title": "RUDE CRUZ", "page": 42, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Rude cruz se erigiu, dela o dia fugiu,\nRevelando vergonha e pavor.\nMas eu amo a Jesus, que morreu nessa cruz,\nDando a vida por mim, pecador."}, {"label": "Coro", "text": "Coro: Sim, eu amo a mensagem da cruz;\nSuas bênçãos eu vou proclamar.\nLevarei eu também minha cruz,\nAté por uma coroa trocar."}, {"label": "Estrofe 2", "text": "Lá da glória dos céus, o Cordeiro de Deus\nAo calvário humilhante baixou;\nE essa cruz tem pra mim, atrativos sem fim,\nPorque nela Ele me resgatou."}, {"label": "Estrofe 3", "text": "Eu, aqui, com Jesus, a vergonha da cruz,\nQuero sempre levar e sofrer.\nEle vem me buscar, e com Ele no lar,\nSua glória pra sempre vou ter."}], "reviewed": false}, {"number": 177, "title": "QUERO VER", "page": 42, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "(H) Quero ver (M) Quero ver\n(H) Cristo lá, (M) Cristo lá,\nQuero ver Cristo lá, glória a Deus!\nLá no Céu eu vou ficar,\nMeu Jesus vou avistar.\nQuero ver Cristo lá, glória a Deus!\n{Quero ver (nome de alguém), Todos, Cristo lá.}"}], "reviewed": false}, {"number": 178, "title": "LEVANTA E PROCLAMA", "page": 43, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Levanta, proclama teu amor a Cristo,\nLevanta, proclama teu amor a Deus,\nMostra, com alegria e fervor, teu amor a Deus."}, {"label": "Estrofe 2", "text": "Assenta, murmura teu amor a Cristo,\nAssenta, murmura teu amor a Deus,\nMostra, com alegria e fervor, teu amor a Deus."}, {"label": "Estrofe 3", "text": "Ele é Rocha e Espada minha, o melhor Amigo meu,\nO mais caro dos milhões é Jesus.\nOutros podem duvidar, ao Senhor eu vou amar.\nEle é Rocha e Espada minha, glória a Deus!"}, {"label": "Estrofe 4", "text": "Levanta, proclama teu amor a Cristo.\nAssenta, murmura teu amor a Deus.\nMostra, com alegria e fervor, teu amor a Deus."}], "reviewed": false}, {"number": 179, "title": "LÁ NO CÉU", "page": 43, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Há um lar mui feliz lá no Céu,\nOnde não há tristeza nem dor. Onde os salvos irão habitar,\nNa presença do seu Salvador.\n{Lá no Céu, lá no Céu, há um lar mui feliz lá no céu!.} (Bis)"}, {"label": "Estrofe 2", "text": "Eu também vou viver lá no Céu,\nE hei de ver quem me deu salvação.\nNão demora o momento de eu ir, e morar lá naquela mansão.\n{Lá no Céu, lá no Céu, há um lar mui feliz lá no Céu!.} (Bis)\nNesse lar tão feliz lá no Céu.\nNunca o mal poderá penetrar. Só há glória, pureza e prazer,\nOnde os salvos por Cristo hão de entrar.\n{Lá no Céu, lá no Céu, há um lar mui feliz lá no Céu.} (Bis)"}], "reviewed": false}, {"number": 180, "title": "SOU FELIZ", "page": 43, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se paz a mais doce me deres gozar,\nSe dor a mais forte sofrer,\nOh! Seja o que for, Tu me fazes saber\nQue feliz com Jesus sempre sou!"}, {"label": "Coro", "text": "Coro: (M) Sou feliz (H) Sou feliz\n(M) Com Jesus (H) Com Jesus\n(T) Sou feliz com Jesus, meu Senhor!"}, {"label": "Estrofe 2", "text": "Meu triste pecado, por meu Salvador,\nFoi pago de um modo cabal;\nValeu-me o Senhor, oh! Mercê sem igual!\nSou feliz! Graças dou a Jesus!"}, {"label": "Estrofe 3", "text": "A vinda eu anseio do meu Salvador;\nEm breve virá me levar\nAo céu, onde vou para sempre morar,\nCom remidos na luz do Senhor!\nO Maior Amor 151\nTu ès Meu Salvador 152"}, {"label": "Estrofe 4", "text": "Amor A Mensagem 171\n(Fraternal) Aliança 149\nAmor Fraternal 128\nEu Quero Te Amar 172\nSe uma Boa Amizade Você Tem 154\nTe Amo Com o Amor do Senhor 173\nUm Só Rebanho 63"}, {"label": "Estrofe 5", "text": "Cantar Cantai ao Senhor 1\nCante, Amém, Amém 77\nVamos Cantar, Orar e Confiar 148"}, {"label": "Estrofe 6", "text": "Ceia A Ceia 74\nAlvo Mais Que a Neve 57\nEm Amor, Por mim 159\nHá Momentos 101\nMeu Redentor 80\nMorri na Cruz por Ti 175\nO Renovo 25\nPor Mim Morreu Jesus 52\nRude Cruz 176\nSem Deus 88"}, {"label": "Estrofe 7", "text": "Céu Lá no Céu 179\nMeu Nome Escrito Está 98\nNova Jerusalém 146\nO Céu 45\nQuero Ver 177\nSua Vida Mais Clara 68"}], "reviewed": false}]}, "cantor": {"name": "Cantor Cristão", "hymns": [{"number": 1, "title": "Antífona", "page": 1, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "- A Ti, ó Deus, fiel e bom Senhor.\nEterno Pai, Supremo Benfeitor,\nNós, os teus servos, vimos dar louvor,\nAleluia! Aleluia!"}, {"label": "Estrofe 2", "text": "A Ti, Deus Filho, Salvador Jesus,\nDa graça a fonte, da verdade a luz,\nPor teu amor, medido pela cruz,\nAleluia! Aleluia!"}, {"label": "Estrofe 3", "text": "A Ti, ó Deus, real Consolador,\nDivino fogo, santificador,\nQue nos anima e nos acende o amor,\nAleluia! Aleluia!"}, {"label": "Estrofe 4", "text": "A Ti, Deus trino, Poderoso Deus,\nQue estás presente sempre junto aos teus,\nA ministrar as bênçãos lá dos céus,\nAleluia! Aleluia!"}], "reviewed": false}, {"number": 2, "title": "Justo És, Senhor", "page": 1, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Justo és, Senhor, nos teus santos caminhos;\nÉs digno em todas as tuas obras;\nEis perto estás dos que te invocam,\nDe todos que te invocam em verdade!\nAleluia! Aleluia!"}], "reviewed": false}, {"number": 3, "title": "Louvor Ao Senhor", "page": 1, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó gratos ao Senhor,\nAo vosso Rei louvai;\nCom alegria e com fervor, (bis)\nSeu culto celebrai!(bis)"}, {"label": "Estrofe 2", "text": "A Ele pertencem\nBênção e sabedoria,\nSim, glória e soberania,\nAgora e pra sempre, sem fim."}], "reviewed": false}, {"number": 4, "title": "Ao Deus Santo", "page": 1, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Santo, Santo, Santo,\nÉs Tu, Senhor!\nLouvem-Te nos altos céus,\nE na terra os filhos teus,\nÓ Deus de amor."}], "reviewed": false}, {"number": 5, "title": "Presença Divina", "page": 2, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Onipotente Rei, aqui presente sê\nNo teu poder;\nEm teu excelso amor inspira-nos louvor;\nQueremos-te, Senhor, engrandecer."}, {"label": "Estrofe 2", "text": "Ó poderoso Deus, nos ouve lá dos céus\nA petição.\nVem-nos abençoar, e vem fazer brotar\nO que se semear no coração."}, {"label": "Estrofe 3", "text": "Vem Tu, Consolador, sê testificador\nDa redenção.\nNo templo vem entrar, a obra completar.\nDas manchas vem limpar o coração."}, {"label": "Estrofe 4", "text": "Ó grande, trino Deus, sim, Te adoramos nós.\nE só a Ti!\nSantificar-nos-ás, ao céu nos levarás,\nA glória nos darás Contigo aí."}], "reviewed": false}, {"number": 6, "title": "Glória Ao Senhor", "page": 2, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A nosso Pai do céu tributa, lábio meu,\nGlória e louvor!\nA quem seu Filho deu, o qual por nós morreu,\nA quem me prostro eu; glória ao Senhor!"}, {"label": "Estrofe 2", "text": "Louvemos ao Senhor, o Santo Redentor,\nO Rei Jesus!\nSua morte me remiu, a mim, tão pecador,\nE assim o céu me abriu; glória a Jesus!"}, {"label": "Estrofe 3", "text": "Espírito de Deus, mandado por Jesus,\nLouvor a ti!\nDe Cristo o grande amor revela, Instruidor!\nSê meu renovador! Louvor a ti!"}, {"label": "Estrofe 4", "text": "Louvemos com ardor, com gozo e com fervor\nO trino Deus!\nEternamente ali, em canto abrasador,\nTrindade santa, a ti louvor nos céus!"}], "reviewed": false}, {"number": 7, "title": "Maravilhas Divinas", "page": 3, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ao Deus de amor e de imensa bondade,\nCom voz de júbilo vinde e aclamai;\nCom coração transbordante de graças,\nSeu grande amor, todos, vinde e louvai."}, {"label": "Estrofe 2", "text": "No céu, na terra, que maravilhas\nVai operando o poder do Senhor!\nMas seu amor aos homens perdidos\nDas maravilhas és sempre a maior!"}, {"label": "Estrofe 3", "text": "Já nossos pais nos contaram a glória\nDe Deus, falando com muito prazer,\nQue nas tristezas, nos grandes perigos,\nEle os salvou por seu grande poder."}, {"label": "Estrofe 4", "text": "Hoje, também nós bem alto cantamos\nQue as orações Ele nos atendeu;\nSeu forte braço, que é tão compassivo,\nEm nosso auxílio, Ele sempre estendeu."}, {"label": "Estrofe 5", "text": "Como até hoje e daqui para sempre,\nEle será nosso eterno poder,\nNosso castelo bem forte e seguro,\nE a nossa fonte de excelso prazer."}], "reviewed": false}, {"number": 8, "title": "Adoração", "page": 3, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A Deus, supremo Benfeitor,\nVós anjos e homens dai louvor;\nA Deus o Filho, a Deus o Pai,\nA Deus Espírito, glória dai."}], "reviewed": false}, {"number": 9, "title": "Santo", "page": 3, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Santo! Santo! Santo! Deus Onipotente!\nCedo de manhã cantaremos teu louvor.\nSanto! Santo! Santo! Deus Jeová triúno,\nÉs um só Deus, excelso Criador.\nSanto! Santo! Santo! Todos os remidos,\nJuntos com os anjos, proclamam teu louvor.\nAntes de formar-se o firmamento e a terra.\nEras, e sempre és e hás de ser, Senhor."}, {"label": "Estrofe 2", "text": "Santo! Santo! Santo! Nós, os pecadores,\nNão podemos ver tua glória sem tremor.\nTu somente és Santo; não há nenhum outro,\nPuro e perfeito, excelso Benfeitor."}, {"label": "Estrofe 3", "text": "Santo! Santo! Santo! Deus Onipotente!\nTuas obras louvam teu nome com fervor.\nSanto! Santo! Santo! Justo e compassivo,\nÉs um só Deus, supremo Criador."}], "reviewed": false}, {"number": 10, "title": "Auxílio Divino", "page": 4, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Santo Deus, vem inflamar\nNossos débeis corações;\nVem as trevas dissipar,\nLivra-nos de imperfeições."}, {"label": "Estrofe 2", "text": "Sim, ó Deus, vem dirigir\nEste culto a celebrar;\nVem, oh, vem-nos revestir\nDe fervor pra Te louvar!"}], "reviewed": false}, {"number": 11, "title": "Ao Deus Trino", "page": 4, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó Deus, bom Pai e Benfeitor,\nA Ti rendemos, com ardor,\nLouvor leal sem fim, Senhor,\nDe todos nós Sustentador."}, {"label": "Estrofe 2", "text": "E Tu, Deus Filho, ó bom Jesus,\nPor nós sofreste numa cruz;\nDe Ti nos vem a clara luz,\nQue nossos pés aos céus conduz."}, {"label": "Estrofe 3", "text": "Tu, Deus, Espírito veraz,\nOh! Nossas almas satisfaz\nCom gozo, com divina paz,\nE as nossas aflições desfaz."}, {"label": "Estrofe 4", "text": "Ó infinito e excelso Deus,\nAmpara-nos, embora réus,\nCom bênçãos, lá dos altos céus,\nA todos nós, os filhos teus."}], "reviewed": false}, {"number": 12, "title": "Louvamos", "page": 5, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Louvamos, louvamos, Senhor e adoramos\nA ti, ó Deus-Homem, no céu assentado;\nQue em tempo devido, na terra humilhado,\nPor nossos pecados morreste na cruz. (bis)"}, {"label": "Estrofe 2", "text": "Louvamos, louvamos, Senhor, e adoramos\nA ti, que a justiça de Deus sustentaste,\nA pena sofrendo por nós merecida,\nA vida depondo pra assim nos remir. (bis)"}, {"label": "Estrofe 3", "text": "Louvamos, louvamos, Senhor, e adoramos\nA glória divina por ti revelada,\nQue para nós brilha na luz esplendente,\nFazendo-nos ver a real perfeição. (bis)"}, {"label": "Estrofe 4", "text": "Em ti concilia-se a santa justiça,\nQue não pode a culpa deixar sem castigo.\nCom a compaixão que por graça recebe\nE exime de culpas o réu pecador. (bis)"}], "reviewed": false}, {"number": 13, "title": "Adoração a Deus", "page": 5, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Bendigam a Deus, glorioso Senhor,\nE com gratidão lhe rendam louvor:\nAmigo dos homens, fiel defensor,\nQue os guarda seguros no seu amplo amor."}], "reviewed": false}, {"number": 14, "title": "O Deus de Abraão", "page": 5, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ao Deus de Abraão louvai,\nDo vasto céu Senhor,\nEterno e poderoso Pai,\nE Deus de amor,\nAugusto Deus Jeová,\nQue terra e céu criou,\nMinha alma o Nome abençoará\nDo grande Eu-Sou."}, {"label": "Estrofe 2", "text": "Ao Deus de Abraão louvai;\nEis, por mandado seu,\nMinha alma deixa a terra e vai\nGozar no céu.\nO mundo desprezei,\nSeu lucro e seu louvor,\nE Deus por meu quinhão tomei\nE protetor."}, {"label": "Estrofe 3", "text": "Meu guia Deus será;\nSeu infinito amor\nFeliz em tudo me fará\nPor onde eu for.\nTomou-me pela mão,\nEm trevas deu-me luz,\nE dá-me eterna salvação\nPor meu Jesus."}, {"label": "Estrofe 4", "text": "Meu Deus por si jurou,\nE nEle confiei,\nE para o céu que preparou\nEu subirei.\nSeu rosto irei eu ver,\nFiado em seu amor,\nE eu hei de sempre engrandecer\nMeu Redentor."}], "reviewed": false}, {"number": 15, "title": "Exultação", "page": 6, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A Deus demos glória, com grande fervor;\nSeu Filho bendito por nós todos deu;\nA graça concede ao mais vil pecador,\nAbrindo-lhe a porta de entrada no céu."}, {"label": "Estrofe 2", "text": "Exultai! Exultai! Vinde todos louvar\nA Jesus, Salvador, a Jesus, Redentor;\nA Deus demos glória, porquanto do céu\nSeu Filho bendito por nós todos deu."}, {"label": "Estrofe 3", "text": "Oh! Graça real, foi assim que Jesus,\nMorrendo, seu sangue por nós derramou!\nHerança nos céus, com os santos em luz,\nComprou-nos Jesus, pois o preço pagou."}, {"label": "Estrofe 4", "text": "A crer nos convida tal rasgo de amor,\nNos merecimentos do Filho de Deus;\nE quem, pois, confia no seu Salvador,\nVai vê-Lo sentado na glória dos céus."}], "reviewed": false}, {"number": 16, "title": "Vinde Adorar", "page": 6, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh! Vinde adorar o excelso e bom Deus,\nEterno Senhor da terra e dos céus,\nQue reina, supremo, envolto na luz,\nE que se revela em Cristo Jesus!"}, {"label": "Estrofe 2", "text": "Seu grande poder deveis contemplar\nNo brilho do céu, na terra e no mar;\nAs gotas de orvalho, sim, toda flor,\nProclamam constantes seu grande Autor."}], "reviewed": false}, {"number": 17, "title": "O Amor de Deus", "page": 7, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Decorridas eras são,\nDesde que os juDeus\nCristo fez proclamação\nDo grande amor de Deus."}, {"label": "Estrofe 2", "text": "Veio aos cegos vista dar,\nLuz nas trevas ser;\nPecadores quis salvar,\nPerdidos recolher."}, {"label": "Estrofe 3", "text": "Nunca os pobres desprezou,\nSempre os recebeu;\nPaga sempre recusou;\nDe graça tudo deu."}, {"label": "Estrofe 4", "text": "Tempos já passados são,\nCristo o mesmo é;\nVida, vista, salvação,\nObtêm-se pela fé."}, {"label": "Estrofe 5", "text": "Que profundo amor se via\nQuando aqui andou!\nTerna, santa simpatia\nEle nos mostrou!"}], "reviewed": false}, {"number": 18, "title": "Amor Sem Igual", "page": 7, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh! Não tens ouvido do amor sem igual,\nDo amor que teu Deus tem por ti?!\nDo amor que o levou a seu Filho entregar,\nPra os salvos levar para si?!"}, {"label": "Estrofe 2", "text": "Oh, crê! Oh, crê!\nA graça de Deus te chama dos céus.\nOh, crê nesse amor sem igual!\nNão foram os grandes que Cristo chamou,\nNem justos veio Ele salvar;\nMas pobres e fracos, culpados e maus\nMandou pelos servos chamar."}, {"label": "Estrofe 3", "text": "O homem, porém, não podia chegar\nÀ santa presença de Deus;\nPorque seus pecados, qual grande montão,\nVendavam-lhe a entrada nos céus."}, {"label": "Estrofe 4", "text": "Mas pelo seu sangue Jesus expiou\nA culpa dos crentes na cruz;\nTirando o pecado, caminho mostrou,\nO qual para o céu nos conduz."}, {"label": "Estrofe 5", "text": "E tu, pecador, não desejas, então,\nO amor do teu Deus conhecer?\nPor fé no Senhor, como teu Salvador,\nIrás alcançar tal prazer."}], "reviewed": false}, {"number": 19, "title": "Boa - Nova", "page": 8, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Alegre nova nos chegou:\nO grande Deus assim amou\nA todo o mundo pecador,\nQue deu seu Filho benfeitor\nEm sua redenção."}, {"label": "Estrofe 2", "text": "Aquele, pois, que em Cristo crer,\nA vida eterna passa a ter;\nJamais a morte vai provar;\nNo céu, porém, irá gozar\nA plena salvação."}, {"label": "Estrofe 3", "text": "Mister é Cristo conhecer,\nE dele em tudo depender,\nGuardar a sua santa lei,\nE coroá-lo nosso Rei\nDe todo o coração."}, {"label": "Estrofe 4", "text": "Ó mundo todo, a Cristo vem,\nAo que concede todo o bem,\nQue poderá tornar feliz\nA cada povo e seu país,\nCom sua provação!"}], "reviewed": false}, {"number": 20, "title": "Amor Perene", "page": 9, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Amavas-me, Senhor, não tendo a luz ainda\nSurgindo lá nos céus, ao mando Criador;\nNem mesmo o sol, na aurora esplendorosa e linda,\nÀ terra dava força fecundante, infinda.\nMeu Deus, que amou!\nMeu Deus, que antigo amor!"}, {"label": "Estrofe 2", "text": "Amavas-me, Senhor, no tempo em que imolado\nFoi numa cruz sangrenta o meigo Salvador,\nLevando sobre Si, sim, todo o meu pecado,\nO Santo de Israel, o teu Cordeiro amado.\nMeu Deus, que amor!\nMeu Deus, que imenso amor!"}, {"label": "Estrofe 3", "text": "Amavas-me, Senhor! No fundo de meu peito\nBrilhou a doce luz do meu Consolador,\nE com promessas mil de teu amor perfeito,\nNasceu em mim a fé em que hoje me deleito.\nMeu Deus, que amor!\nMeu Deus, és todo amor!"}, {"label": "Estrofe 4", "text": "A mim sempre hás de amar! Pois que jamais o inferno\nE o mundo poderão ao teu querer se opor,\nAo teu decreto, ó Rei, ao teu decreto eterno,\nAo teu amor, ó Pai, ao teu amor superno!\nMeu Deus, que amor!\nÉs sempre, sempre amor!"}], "reviewed": false}, {"number": 21, "title": "Louvor Ao Pai e Ao Filho", "page": 9, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Do mundo Deus se condoeu\nDe tal maneira que lhe deu\nPor Salvador o Filho seu.\nLouvor ao Pai e ao Filho dai!"}, {"label": "Estrofe 2", "text": "Jesus sofreu, sim, como réu,\nA fim de nos levar ao céu,\nFoi quem rasgou da morte o véu.\nLouvor ao Pai e ao Filho dai!"}, {"label": "Estrofe 3", "text": "E Cristo, por morrer na cruz,\nOutorga vida, gozo e luz;\nSim, tudo temos em Jesus.\nLouvor ao Pai e ao Filho dai!"}, {"label": "Estrofe 4", "text": "Morreu Jesus e nos remiu,\nFoi sepultado e ressurgiu,\nE para Deus depois subiu.\nLouvor ao Pai e ao Filho dai!"}], "reviewed": false}, {"number": 22, "title": "Amor Sublime", "page": 10, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Qual ave que, buscando os céus,\nO mundo deixa e seus troféus,\nMinha alma vem a Ti, Senhor,\nPra conhecer teu terno amor."}, {"label": "Estrofe 2", "text": "Divino amor, sublime amor,\nDos grandes temas o maior!\nMinha alma quer fruir, gozar\nDe Cristo o tão sublime e amor."}, {"label": "Estrofe 3", "text": "Amor sublime, amor real,\nAmor eterno e sem igual,\nSobre uma cruz por mim morrer\nE me salvar por seu poder!"}, {"label": "Estrofe 4", "text": "Teu Nome, ó Deus, publicarei,\nA tua graça, a tua lei,\nO teu poder e o teu amor!\nMinha alma adora-te, Senhor!"}], "reviewed": false}, {"number": 23, "title": "Deus, Fonte da Vida", "page": 10, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó Deus do céu, da terra e mar,\nHumildes vimos-te adorar;\nO teu amor, sim, celebrar,\nQue tudo dás."}, {"label": "Estrofe 2", "text": "A luz benigna, luz solar,\nE a brisa branda e salutar,\nQue vem a tudo renovar,\nSim, tudo dás."}, {"label": "Estrofe 3", "text": "A verde relva, a linda flor,\nDe ricos frutos o penhor,\nProclamam teu constante amor.\nSim, tudo dás."}, {"label": "Estrofe 4", "text": "Tu, por um mundo pecador\nTeu Filho deste, o Salvador;\nCom ele tudo dás, Senhor.\nSim, tudo dás.\nDás vida aos mortos e perdão,\nDás aos perdidos salvação,\nDe paz enchendo o coração.\nSim, tudo dás."}, {"label": "Estrofe 5", "text": "Pureza dás e dás poder,\nA graça que nos é mister,\nPor ti viver, por ti morrer.\nSim, tudo dás,"}, {"label": "Estrofe 6", "text": "Ensina-nos, Senhor, a amar;\nEnsina-nos, Senhor, a dar,\nE a Ti a vida consagrar,\nPois tudo dás."}], "reviewed": false}, {"number": 24, "title": "Deus É Amor", "page": 11, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Deus é amor. A sua graça\nConquistou meu coração;\nConcedeu-me vida eterna,\nPaz e luz e salvação."}, {"label": "Estrofe 2", "text": "Deus é amor. Eis tudo acaba\nNeste mundo de amargor;\nSó perdura inalterável\nSeu infindo e eterno amor."}, {"label": "Estrofe 3", "text": "Deus é amor. Pois cuida sempre\nDo seu filho bom, fiel.\nEle inspira, guia e livra,\nComo ao povo de Israel."}, {"label": "Estrofe 4", "text": "Deus é amor. Vem, auxilia\nA este pobre pecador;\nPerdoado, agora almeja\nProclamar o teu amor!"}, {"label": "Estrofe 5", "text": "Deus é amor, sim, Deus é amor.\nDeus é amor, sim, Deus é amor."}], "reviewed": false}, {"number": 25, "title": "Amor", "page": 11, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que grande amor, excelso amor,\nQue Cristo nos mostrou!\nPra se tornar o Salvador\nA vida não negou.\nLouvemos tão grande amor,\nSim, tão grande amor\nQue Cristo assim nos manifesta;\nQue maravilha de amor,\nQue nos trouxe para Deus!"}, {"label": "Estrofe 2", "text": "Ninguém, pois, deve duvidar\nDo seu tão grande amor,\nMas todos devem aceitar\nO amor do Salvador."}, {"label": "Estrofe 3", "text": "O que esse amor de nós fará\nÉ-nos vedado ver;\nMas Cristo em breve voltará,\nE nos fará saber."}], "reviewed": false}, {"number": 26, "title": "Rei Excelso", "page": 12, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cantai, que o Salvador chegou!\nAcolha a terra o Rei!\nLeais nações, a ele só\nContentes vos rendei; (bis)\nOh, sim, contentes vos rendei!"}, {"label": "Estrofe 2", "text": "Ao mundo o gozo proclamai\nDo reino de Jesus!\nÓ terra e mar e céus, cantai\nA resplendente luz! (bis)\nA grande e resplendente luz!"}, {"label": "Estrofe 3", "text": "Pecados, dores, morte já\nVencidos dele são;\nA paz Jesus concederá\nEm régia profusão; (bis)\nOh, sim, em régia profusão!"}, {"label": "Estrofe 4", "text": "Verdade e amor são sua lei;\nOs povos acharão\nQue é justo e bom o excelso Rei,\nE lhe obedecerão, (bis)\nSim, todos lhe obedecerão."}], "reviewed": false}, {"number": 27, "title": "Natal", "page": 12, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis dos anjos a harmonia,\nCantam glória ao novo Rei;\nPaz aos homens e alegria,\nPaz com Deus e suave lei.\nOuçam povos exultantes,\nErgam salmos triunfantes,\nAclamando o seu Senhor;\nNasce Cristo, o Redentor."}, {"label": "Estrofe 2", "text": "Cante o povo resgatado:\n\"Glória ao Príncipe da paz.\"\nDeus, em Cristo revelado,\nVida e luz ao mundo traz.\nNasce pra que renasçamos;\nVive para que vivamos;\nRei, Profeta e Salvador!\nLouvem todos ao Senhor!"}, {"label": "Estrofe 3", "text": "Toda a terra e altos céus\nCantem glória ao Homem-Deus!"}], "reviewed": false}, {"number": 28, "title": "Nasceu o Redentor", "page": 13, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Alerta, ó terra, entoa o canto que ressoa:\nO mundo pecador tem pecador sorte e boa.\nA nova se vos dá, e quão alegre soa:\nNasceu o Redentor!"}, {"label": "Estrofe 2", "text": "Nasceu o Redentor! Nasceu o Redentor!\nO eterno Pai do céu seu Filho ao mundo deu.\nAlerta, ó terra, entoa a nova alegre e boa:\nNasceu o Redentor!"}, {"label": "Estrofe 3", "text": "A noite já passou, a aurora já raiou;\nO negro e denso véu de todo se rasgou.\nDos montes através o brado ressoou:\nNasceu o Redentor!"}, {"label": "Estrofe 4", "text": "Nasceu o Rei da paz, num berço humilde jaz;\nNas asas desse amor conforto a todos traz.\nDizei em alta voz que Cristo satisfaz:\nNasceu o Redentor!"}, {"label": "Estrofe 5", "text": "Ó gozo divinal, amor celestial,\nQuem pode Te sondar ou ter um outro igual?\nPosso eu, da morte réu, gozar ventura tal?\nNasceu o Redentor!"}, {"label": "Estrofe 6", "text": "Ó povos, exultai! Nações, oh, jubilai!\nEis finda toda a dor, jamais se dá um ai;\nA virgem deu à luz; a Deus glorificai!\nNasceu o Redentor!"}], "reviewed": false}, {"number": 29, "title": "Nasce Jesus", "page": 14, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O povo, sim, coberto\nDe densas trevas, perto\nDo abismo e não desperto,\nVê, surpreso, um grande e\ndivinal clarão!"}, {"label": "Estrofe 2", "text": "Cumprindo as profecias\nNos nasce o Rei Messias;\nEm horas tão sombrias\nCada povo em trevas vê o seu clarão!"}, {"label": "Estrofe 3", "text": "Jesus, o Rei da glória,\nHumilde em sua história,\nA todos dá vitória;\nVinde ver o Cristo em sua humilhação!"}, {"label": "Estrofe 4", "text": "Ó nova alegre e boa!\nNo céu azul ressoa\nQue Cristo nos perdoa.\nAceitai-o, ó povos; dai-Lhe o coração!"}, {"label": "Estrofe 5", "text": "É Jesus que nasce, Autor da salvação!\nCristo amado a todos traz a redenção!\nO coro angelical, num hino triunfal,\nProclama o Cristo, com adoração!"}], "reviewed": false}, {"number": 30, "title": "Noite de Paz", "page": 14, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Dormem todos em redor;\nEm Belém Jesus nasceu,\nRei da paz, da terra e céu;\nNosso Salvador\nÉ Jesus, Senhor."}, {"label": "Estrofe 2", "text": "\"Glória a Deus! Glória a Deus!\"\nCantam anjos lá nos céus;\nBoas-novas de perdão,\nGraça excelsa, salvação;\nProva deste amor\nDá o Redentor.\nRei da paz, Rei de amor,\nDeste mundo Criador;\nVinde todos lhe pedir\nQue nos venha conduzir.\nDeste mundo a luz\nÉ o Senhor Jesus."}], "reviewed": false}, {"number": 31, "title": "Lugar para Cristo", "page": 15, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tu deixaste, Jesus, o teu reino de luz,\nE baixaste a este mundo tão vil;\nUm presépio, em Belém, Tu, Jesus, Sumo-bem,\nEscolheste por berço infantil."}, {"label": "Estrofe 2", "text": "Vem, Jesus, habitar comigo,\nEm minha alma há lugar; oh, vem já. (bis)"}, {"label": "Estrofe 3", "text": "Alegraram-se os céus, com os santos de Deus,\nSim, por teres nascido, Jesus,\nVindo os filhos de Adão conceder salvação\nPela morte, em resgate, na cruz."}, {"label": "Estrofe 4", "text": "Tu vieste, Senhor, revelar-nos amor,\nE te aprouve do mal nos salvar;\nMas provaste do fel, do motejo cruel,\nMorte, enfim, te fizeram provar."}, {"label": "Estrofe 5", "text": "Outra vez tu virás, e por mim chamarás,\nRodeado dos anjos de Deus;\nOh! Que gozo pra mim, se disseres assim:\n\"Um lugar te darei eu nos céus.\""}], "reviewed": false}, {"number": 32, "title": "Cristo Em Belém", "page": 15, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Alta noite estão pastores\nDe Belém no derredor;\nE os cercou de resplendores\nLuz celeste do Senhor."}, {"label": "Estrofe 2", "text": "Glória a Deus e paz bendita,\nEis o canto angelical\nPara toda a gente aflita!\nTão glorioso e triunfal!"}, {"label": "Estrofe 3", "text": "Ver Jesus na manjedoura,\nOnde veio repousar,\nQuerem eles sem demora,\nPara a nova confirmar."}, {"label": "Estrofe 4", "text": "O Senhor de quanto existe\nQuis pastores procurar,\nPara deste berço triste\nSuas novas proclamar."}, {"label": "Estrofe 5", "text": "\"Novas tenho... dar-vos venho\",\nDisse um anjo com dulçor;\n\"Eis que é nado o Bem-Amado,\nJesus Cristo, o Salvador.\""}], "reviewed": false}, {"number": 33, "title": "Nasceu Jesus", "page": 16, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Nasce Jesus, fonte de luz!\nDescem os anjos cantando;\nNasce Jesus, é nossa luz;\nTrevas vem, pois, dissipando.\nNasce Jesus, fonte de luz!\nRompe as cadeias do forte,\nRaia o dia da salvação, triunfante vem!\nSalve Jesus! Oh, firma teu justo império!\nGrato louvor os homens e os anjos dêem!"}, {"label": "Estrofe 2", "text": "Nasce Jesus, fonte de luz!\nOh! Glória a Deus nas alturas!\nPaz na terra aos homens,\nA quem quer ele bem!"}, {"label": "Estrofe 3", "text": "Deus nos amou e nos mandou\nCristo, seu Filho querido.\nDeus nos amou, Deus encarnou!\nVede o menino nascido!\nDeus nos amou! Deus nos amou!\nDigam-no todos os povos;\nGozam paz e salvação todos os que crêem.\nReino bendito! Reino de amor divino!\nEis que as nações resgate por Cristo têm!"}], "reviewed": false}, {"number": 34, "title": "Plena Graça", "page": 16, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Plena graça para me salvar,\nSangue puro para me lavar\nE poder pra sempre me guardar\nTem meu Senhor."}], "reviewed": false}, {"number": 35, "title": "Incomparável", "page": 17, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O grande amor do meu Jesus,\nPor mim morrendo sobre a cruz,\nDa perdição pra me salvar,\nQuem poderá contar?"}, {"label": "Estrofe 2", "text": "O cálix que Jesus bebeu,\nA maldição que padeceu\nNa cruz por mim, pra me salvar,\nQuem poderá contar?"}, {"label": "Estrofe 3", "text": "A zombaria tão cruel,\nA cruz sangrenta, o amargo fel\nQue ali sofreu pra me salvar,\nQuem poderá contar?"}, {"label": "Estrofe 4", "text": "Incomparável Salvador,\nQuão inefável teu amor!\nQuão impossível de sondar!\nImensidão sem par!"}, {"label": "Estrofe 5", "text": "Quem pode o seu amor contar?\nQuem pode o seu amor contar?\nO grande amor do Salvador\nQuem poderá contar?"}], "reviewed": false}, {"number": 36, "title": "O Amor de Jesus", "page": 17, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó maravilha do amor de Jesus,\nDesse admirável amor sem igual!\nCristo penou e morreu numa cruz,\nPara salvar-me da morte eternal."}, {"label": "Estrofe 2", "text": "Cristo, meu Mestre, veio por mim,\nVeio por mim, veio por mim;\nCristo, meu Mestre, veio por mim,\nVeio pra me salvar."}, {"label": "Estrofe 3", "text": "Oh, duvidar poderei eu jamais\nDesse insondável amor de Jesus!\nEle me veio trazer sua paz,\nDando-me entrada no reino de luz."}, {"label": "Estrofe 4", "text": "Cristo, meu Mestre Divino, meu Deus,\nQuis-me remir e me dar seu favor;\nEle me abriu o caminho dos céus,\nE me adotou como filho de amor.\nVou-me entregar a Jesus, e, fiel,\nQuero fazer conhecido esse amor\nQue me salvou de uma morte cruel;\nQuero viver para meu Salvador."}], "reviewed": false}, {"number": 37, "title": "Amor Glorioso", "page": 18, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Buscou-me com ternura\nJesus, o bom Pastor;\nAchou-me na miséria,\nSalvou-me com amor;\nNo céu cantaram de alegria\nOs anjos, sim, em harmonia."}, {"label": "Estrofe 2", "text": "Oh, que amor glorioso!\nPreço tão grandioso\nQue Jesus por mim na cruz pagou;\nInaudita graça me mostrou!"}, {"label": "Estrofe 3", "text": "Ferido e abandonado,\nJesus me socorreu;\nE segredou-me: \"Achei-te;\nDe agora em diante és meu.\"\nTão meiga voz jamais ouvi;\nPrazer maior jamais senti."}, {"label": "Estrofe 4", "text": "Jesus mostrou-me as chagas\nQue em meu lugar sofreu;\nCoroa, mas de espinhos;\nA cruz que padeceu.\nQue poderia em mim achar,\nPra tais afrontas suportar?"}, {"label": "Estrofe 5", "text": "Minha alma embevecida,\nSeu rosto a contemplar,\nRecorda as muitas bênçãos\nDo seu amor sem-par;\nLouvor e glória e adoração\nTributa-lhe meu coração!"}, {"label": "Estrofe 6", "text": "Enquanto as horas passam,\nEu tenho gozo e paz,\nE aguardo o meu bom Mestre,\nQue tão feliz me faz;\nJesus a mim virá buscar,\nE então pra sempre irei gozar."}], "reviewed": false}, {"number": 38, "title": "Divino Amor", "page": 19, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quem pode o teu imenso amor contar,\nO Salvador Jesus, e esquadrinhar\nSeus alicerces no divino Ser,\nSua extensão ou sua altura ver?\nAmor sem fim!"}, {"label": "Estrofe 2", "text": "Quem pode amor tão vasto compreender?\nPois nem o céu o pôde, enfim, conter.\nFoi neste mundo que se revelou:\nJesus sofrendo sobre a cruz mostrou\nDivino amor."}, {"label": "Estrofe 3", "text": "Quem pode dar adoração capaz\nA ti, que, sem limite, amor nos dás?\nA par do qual o parcial louvor\nQue temos dado ao nosso Salvador\nParece vão."}, {"label": "Estrofe 4", "text": "Mas sempre nos ensina o teu amor\nQue, embora fracos, temos no Senhor\nA fonte inesgotável de afeição,\nQue sabe a voz do nosso coração\nApreciar."}], "reviewed": false}, {"number": 39, "title": "A Ovelha Perdida", "page": 19, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Noventa e nove ovelhas vão\nSeguras ao curral;\nMas uma delas se afastou\nDo aprisco pastoral,\nA errar nos montes de terror,\nDistante do fiel pastor. (bis)"}, {"label": "Estrofe 2", "text": "\"Com a grei submissa, ó bom Pastor,\nNão te contentarás?\"\n\"A errante é minha\", replicou,\n\"Pertence-me a fugaz.\nVou ao deserto procurar\nA ovelha que ouço em dor gritar.\" (bis)"}, {"label": "Estrofe 3", "text": "Nenhum remido imaginou\nQuão negra escuridão,\nQuão fundas águas que passou,\nTrazendo-a à salvação;\nE quando foi pra socorrer,\nA errante estava a perecer. (bis)\n\"Por toda a estrada donde vem,\nQue sangue enxergo ali?\"\n\"Busquei a ovelha com amor,\nO sangue meu verti.\"\n\"Ferida vejo a tua mão...\nA angústia encheu-me o coração.\" (bis)"}, {"label": "Estrofe 4", "text": "Vêm da montanha aclamações!\nÉ a voz do bom Pastor!\nRessoa em notas triunfais\nO salmo vencedor!\nE os anjos cantam lá nos céus:\n\"A errante já voltou a Deus.\" (bis)"}], "reviewed": false}, {"number": 40, "title": "Amor de Cristo", "page": 20, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Qual grande vaga\nDe um imenso mar,\nVem o amor de Cristo\nMinha alma transbordar."}], "reviewed": false}, {"number": 41, "title": "Reconhecimento", "page": 20, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Até a cruz o meu Jesus foi por mim,\nFoi por mim, foi por mim;\nAté a cruz o meu Jesus foi por mim,\nMinha alma pra salvar!"}], "reviewed": false}, {"number": 42, "title": "Realização", "page": 20, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus, agora, sim, eu sei,\nQuão grande é teu amor,\nPois salvação em ti achei!\nAceita o meu louvor."}, {"label": "Estrofe 2", "text": "Jamais descanso conheci,\nInútil sempre sou;\nMas Cristo se lembrou de mim,\nDe graça me salvou.\nComigo, crentes, exaltai\nO grande Salvador;\nPois tudo Cristo me supriu,\nEmbora pecador."}, {"label": "Estrofe 3", "text": "Louvor, louvor a ti darei,\nÓ Cristo, meu Senhor;\nProfeta, Sacerdote e Rei,\nDo mundo o Salvador."}, {"label": "Estrofe 4", "text": "És tu, Jesus, meu Salvador,\nPor ti eu tenho paz;\nJesus, a ti louvor darei,\nPois tudo tu me dás."}], "reviewed": false}, {"number": 43, "title": "Palavras Preciosas", "page": 21, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Preciosas as palavras de Jesus,\nSupremo Rei:\n\"A mim aquele que vier,\nEu não desprezarei.\" (3x) (bis)"}, {"label": "Estrofe 2", "text": "Preciosas as palavras de Jesus,\nSupremo Rei:\n\"A porta sou, por mim entrai;\nDescanso vos darei.\" (3x) (bis)"}, {"label": "Estrofe 3", "text": "Preciosas as palavras de Jesus,\nSupremo Rei:\n\"Oh, vinde, vós, cansados, já;\nÉ suave a minha lei!\" (3x) (bis)"}, {"label": "Estrofe 4", "text": "Preciosas as palavras de Jesus,\nSupremo Rei:\n\"Por vós o mundo já venci;\nPor vós a vida dei\" (3x) (bis)"}], "reviewed": false}, {"number": 44, "title": "A Linda História", "page": 21, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cantarei a linda história\nDe Jesus, o Salvador,\nQue deixou seu lar na glória\nPra salvar o pecador."}, {"label": "Estrofe 2", "text": "Eu perdi-me e ele achou-me,\nLonge, longe do meu lar;\nAbraçou-me então, tomou-me\nPra com ele eu ir morar."}, {"label": "Estrofe 3", "text": "Jesus Cristo deparou-me\nQuando fraco, pra morrer;\nAs feridas ele untou-me\nE livrou-me com poder."}, {"label": "Estrofe 4", "text": "Dias negros inda tenho,\nSofrimento e dissabor;\nMas a Ele eu tudo exponho,\nE me livra com amor."}, {"label": "Estrofe 5", "text": "Cantarei a linda história\nDe Jesus, meu Salvador;\nCantarei a sua glória\nCom os santos, com fervor."}], "reviewed": false}, {"number": 45, "title": "Por Amor de Nós", "page": 22, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Senhor, quão admirável\nÉ teu divino amor!\nEterno e perdurável,\nMotivo de louvor.\nAmando-nos, baixaste\nA este mundo aqui;\nQuerendo, assim, remir-nos\nE nos chamar a ti."}, {"label": "Estrofe 2", "text": "Tu, por amor, provaste\nA nossa condição,\nE, por amor, levaste\nA nossa punição.\nSofreste o desamparo,\nA ira e o dissabor,\nDevidos ao pecado,\nÓ grande Sofredor!"}, {"label": "Estrofe 3", "text": "Por nós Tu deste a vida,\nMorrendo sobre a cruz;\nQual nosso substituto,\nSofreste Tu, Jesus.\nPor isso, Te cercamos\nCom grata adoração;\nPerante ti prostramos\nCorpo, alma e coração."}, {"label": "Estrofe 4", "text": "E não julgamos pouco,\nEm prova desse amor,\nO ser-nos premitido\nServir-te aqui, Senhor.\nOu seja em culto alegre,\nOu seja no sofrer,\nOu seja nos trabalhos,\nSegundo o teu querer."}], "reviewed": false}, {"number": 46, "title": "Jesus me Transformou", "page": 23, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu, perdido pecador,\nLonge do meu Jesus,\nJá me achava sem vigor,\nA perecer sem luz;\nMeu estado Cristo viu,\nDando-me sua mão,\nE salvar-me conseguiu,\nDa perdição."}, {"label": "Estrofe 2", "text": "Minha vida, todo o ser,\nQuero-Lhe consagrar;\nA seu lado vou viver,\nO seu amor sem cantar,\nA mensagem transmitir\nAos que perdidos são.\nVenham todos já fruir\nA salvação."}, {"label": "Estrofe 3", "text": "Cristo me amou, e me livrou;\nO seu imenso amor\nMe transformou\nFoi seu poder, o seu querer,\nSim Cristo, o Salvador,\nMe transformou."}], "reviewed": false}, {"number": 47, "title": "Alegria Perene", "page": 23, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Desperta e canta com fervor,\nSim, ó minha alma, a teu Senhor;\nPois muitos e preciosos bens\nA ti tem dado com amor."}, {"label": "Estrofe 2", "text": "Oh, que grande amor!\nOh, que imenso amor\nDe Cristo pelo pecador!"}, {"label": "Estrofe 3", "text": "Perdido, Cristo me encontrou,\nE dispensou-me compaixão;\nPor seu tão grande amor de pai\nTirou-me desta condição."}, {"label": "Estrofe 4", "text": "Eu sei que é mau meu coração;\nPropende sempre para o mal,\nMas ele em paz me guardará\nCom o seu amor, que é perenal."}], "reviewed": false}, {"number": 48, "title": "Salvação", "page": 24, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cantai a Cristo, Salvador,\nQue tanto nos amou;\nE, para nossa salvação,\nSeu sangue derramou."}, {"label": "Estrofe 2", "text": "Salvação! Salvação!\nQue dimana do Filho de Deus!\nSalvação! Salvação!\nAleluia a Jesus, nosso Deus!"}, {"label": "Estrofe 3", "text": "Mirai o amor que é perenal,\nO amor do grande Deus;\nTão vasto, puro, tão veraz,\nPerdoa os erros meus."}, {"label": "Estrofe 4", "text": "Louvor a Cristo, Redentor,\nDevemos entoar,\nE dar a todos conhecer\nQue Cristo os quer salvar."}], "reviewed": false}, {"number": 49, "title": "Tudo Fez Jesus", "page": 24, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo tudo fez completo,\nNada por fazer deixou;\nVida do mais doce afeto,\nEle para nós comprou."}, {"label": "Estrofe 2", "text": "Seu, o feito; nosso, o gozo;\nNossa, a vida; sua, a cruz;\nSeu, o cálice amargoso;\nNossa, a dita que produz."}], "reviewed": false}, {"number": 50, "title": "A Velha História", "page": 24, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Contai-me a velha história\nDo grande Salvador;\nDe Cristo e sua glória,\nDe Cristo e seu amor.\nCom calma e com paciência,\nPois quero penetrar\nÀ altura do ministério:\nQue Deus nos pode amar."}, {"label": "Estrofe 2", "text": "Contai-me a velha história,\nContai-me a velha história,\nContai-me a velha história\nDe Cristo e seu amor."}, {"label": "Estrofe 3", "text": "Falai-me com doçura\nDo amante Redentor;\nFalai com sentimento,\nPois sou um pecador!\nQuerendo consolar-me\nEm tempos de aflição,\nSempre essa velha história\nDizei do coração."}, {"label": "Estrofe 4", "text": "Se o brilho deste mundo\nToldar do céu a luz,\nNarrai a mesma história\nDa graça de Jesus!\nE quando, enfim, a glória\nDo mundo além raiar,\nContai-me a velha história,\nQue veio aqui salvar."}], "reviewed": false}, {"number": 51, "title": "Vida Na Graça", "page": 25, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jamais houve alguém feliz como o cristão,\nO qual alcançou de Deus bênçãos de amor;\nE tem verdadeira paz com seu Senhor,\nFruindo prazer do céu, graça e perdão."}, {"label": "Estrofe 2", "text": "Prazer, alegria, amor,\nTudo lhe dá Jesus!\nPaz e perdão, favor\nGoza na luz!"}, {"label": "Estrofe 3", "text": "Terror já não tem de Deus; foge do mal;\nNa santa presença está; vive na luz,\nGozando da redenção feita na cruz;\nDeseja crescer na fé, firme e leal.\nJesus é seu Mediador; crê no porvir;\nDa santa Palavra tem força e poder.\nPor Cristo deseja, então, tudo fazer;\nA luz da verdade quer sempre expandir."}], "reviewed": false}, {"number": 52, "title": "Jesus Glorioso", "page": 26, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, sim, Jesus é tão maravilhoso\nQue Deus lhe deu o Nome: o Santo de Israel!\nE o chamou de Todo-Poderoso,\nE Deus da Paz, Senhor, Emanuel.\nO Cristo Rei, que a santa lei\ncumpriu com gozo.\nÉ Sol divino e Salvador fiel!"}, {"label": "Estrofe 2", "text": "Só Cristo, Salvador, em tudo é vencedor;\nPois padeceu, na cruz sofreu humilhação!\nÓ vinde desfrutar o seu amor;\nBuscai, com grande ardor, com devoção,\nO seu favor.\nAmai, irmãos, a quem nos deu perdão!"}, {"label": "Estrofe 3", "text": "Jesus, Senhor assim glorificado,\nDo céu notando o povo entregue a todo o mal,\nQuis vir aqui salvá-lo do pecado.\nE o fez, porém, com grande dor moral.\nCumpriu a lei, salvou a grei\nDo triste estado\nE encheu-a de favor celestial."}, {"label": "Estrofe 4", "text": "Notai, irmãos, e vede que bondade!\nJamais se ouviu de alguém, que assim provasse amar,\nDeveis ouvir Jesus com lealdade,\nDizer que Deus por Cristo pode dar\nReal perdão, a salvação\nE liberdade!\nOh! vinde a Cristo a vida consagrar!"}], "reviewed": false}, {"number": 53, "title": "Os Filhos de Sião", "page": 26, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó filhos de Sião,\nHonrai o Rei dos reis;\nLouvores altos Lhe cantai, (bis)\nGuardai as santas leis. (bis)"}, {"label": "Estrofe 2", "text": "Os que do mundo são\nA Deus não dão louvor;\nMas, filhos do celeste Rei, (bis)\nLouvai ao Salvador! (bis)"}, {"label": "Estrofe 3", "text": "Sião é a nossa santa e gloriosa cidade,\nTambém perene morada\nDos crentes em nosso Jesus."}, {"label": "Estrofe 4", "text": "Dos montes de Sião\nProvêm delícias tais,\nQue de prazer nos enchem mais (bis)\nQue gozos terreais. (bis)"}, {"label": "Estrofe 5", "text": "Oh, venham-no louvar\nOs que seus filhos são,\nE se ergam já a demandar (bis)\nÀs plagas de Sião! (bis)"}], "reviewed": false}, {"number": 54, "title": "Glória e Honra", "page": 27, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Glória, honra e poderio\nSempre sejam ao Cordeiro,\nJesus Cristo, nosso Mestre!\nAleluia! Aleluia!\nVinde todos o adorar!"}], "reviewed": false}, {"number": 55, "title": "Hosana Nas Alturas", "page": 27, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Bendito o Rei que vem em nome do Senhor,\nA quem nós esperamos,\nAo qual nós adoramos!\nBendito o Rei que vem em nome do Senhor!\nHosana! Hosana! Hosana nas alturas! (bis)\nOs seus gloriosos feitos celebrai com fervor!\nEm todo o vale soa\nNova pra nós tão boa!\nBendito o Rei que vem em nome do Senhor!"}, {"label": "Estrofe 2", "text": "Bendito o Rei que vem em nome do Senhor!\nOh, rendam-lhe louvores,\nA Cristo em seus fulgores!\nBendito o Rei que vem em nome do Senhor!\nHosana! Hosana! Hosana nas alturas! (bis)\nOh, vinde todos a Jesus, o Rei, Salvador!\nTodos com alegria,\nVozes em harmonia!\nBendito o Rei que vem em nome do Senhor!\nBendito o Rei que vem em nome do Senhor!\nSim, vem tão majestoso,\nJesus, o Rei bondoso!\nBendito o Rei que vem em nome do Senhor!\nHosana! Hosana! Hosana nas alturas! (bis)\nO Salvador seu povo chama a Si com amor!\nVenham os pequeninos!\nVenham já os meninos!\nBendito o Rei que vem em nome do Senhor!"}], "reviewed": false}, {"number": 56, "title": "Rei da Glória", "page": 28, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A Jesus, o Rei da glória,\nHinos de louvor cantai;\nAos seus pés, humildemente,\nSeu poder, pois, exaltai.\nPerdoados, resgatados,\nSua glória proclamai!"}, {"label": "Estrofe 2", "text": "Seu perdão e sua graça\nAos perdidos dispensou;\nTão paciente e mui bondoso\nAos rebeldes se mostrou;\nLibertou-os, transformou-os,\nDos castigos os salvou!"}, {"label": "Estrofe 3", "text": "Nossas tentações conhece,\nPois satã o quis vencer;\nTriunfante, Cristo agora\nAos tentados quer valer.\nPoderoso e tão bondoso,\nEle pode socorrer!"}, {"label": "Estrofe 4", "text": "Contemplando sua face,\nÓ remidos, o adorai!\nDedicados, consagrados,\nSua fama publicai.\nOh, louvai-o, exaltai-o,\nSeu amor anunciai!"}], "reviewed": false}, {"number": 57, "title": "Bendito o Rei", "page": 28, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "No mundo paz, louvor nos céus!\nCantava a multidão;\nCom o clamor dos fariseus\nErguiam mais o som."}, {"label": "Estrofe 2", "text": "Como em Jerusalém,\nHei de clamar, hei de clamar:\nBendito o Rei, que do alto vem,\nQue vem do céu as trevas dissipar!"}, {"label": "Estrofe 3", "text": "Do grande Rei Jesus, Senhor.\nSim, tais palavras são:\n\"Se algum dos crentes se calar,\nAs pedras clamarão.\""}, {"label": "Estrofe 4", "text": "Bendito Rei, nós, servos teus,\nComo em Jerusalém,\nSem atender aos fariseus,\nLouvamos-Te também."}], "reviewed": false}, {"number": 58, "title": "O Nome de Jesus", "page": 29, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Do Salvador o nome traz\nRecordação que a mim me apraz;\nDos vis grilhões me libertou,\nE deu-me fé que me salvou."}, {"label": "Estrofe 2", "text": "Do Salvador o nome traz\nRecordação que a mim me apraz;\nA ti, Senhor, a ti, louvor\nSem fim eu ergo com fervor."}, {"label": "Estrofe 3", "text": "Em ti, Senhor, eu gozo paz\nE tudo mais que satisfaz;\nDe bênçãos mil sou alvo, sim,\nQue tu, Jesus, dás sempre a mim."}, {"label": "Estrofe 4", "text": "Desprezo, pois, o que é falaz,\nE ponho a fé no Deus veraz;\nFoi ele quem, por grande amor,\nNos deu Jesus, o Redentor."}], "reviewed": false}, {"number": 59, "title": "Saudai Emanuel", "page": 29, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Saudamos-te, ó Emanuel!\nA ti louvores damos;\nDe coração, sim, todos nós\nA ti nos entregamos;\nEm honra a ti, Senhor e Rei,\nOs anjos cantam lá no céu,\nE lá ressoa teu louvor;\nSaudai! Saudai!\nSaudai, saudai Emanuel!"}, {"label": "Estrofe 2", "text": "Rei, Emanuel, Emanuel! (bis)\nSabedoria, poder sem fim,\nHonras e glória as nações te dêem\nHoje e para sempre!\nRei, Emanuel, Emanuel! (bis)\nRei dos reis e Salvador!\nSaudai Emanuel!"}, {"label": "Estrofe 3", "text": "Saudamos-te, ó Emanuel!\nOs santos te rodeiam;\nOs reis da terra se erguerão\nA proclamar teu reino,\nEnquanto os filhos já com Deus,\nCercando o trono lá nos céus,\nEntoam hinos imortais;\nSaudai! Saudai!\nSaudai, saudai Emanuel!"}, {"label": "Estrofe 4", "text": "Saudamos-te, ó Emanuel!\nÓ Rei dos reis eterno!\nVenceste as hostes infernais;\nTu és onipotente!\nJamais a morte reinará.\nEterna glória seja a ti.\nSaudai! Saudai!\nSaudai, saudai Emanuel!"}], "reviewed": false}, {"number": 60, "title": "Coroai", "page": 30, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Saudai o Nome de Jesus!\nArcanjos, vos prostrai!\nO Filho do glorioso Deus\nCom glória coroai!"}, {"label": "Estrofe 2", "text": "Ó escolhida geração\nDo bom, eterno Pai:\nO grande Autor da salvação,\nCom glória coroai!"}, {"label": "Estrofe 3", "text": "Ó perdoados por Jesus,\nAlegres adorai!\nO Deus de paz, o Deus de luz\nCom glória coroai!"}, {"label": "Estrofe 4", "text": "Ó raças, tribos e nações,\nO Rei divino honrai;\nA quem quebrou os vis grilhões\nCom glória coroai!"}], "reviewed": false}, {"number": 61, "title": "Glória a Jesus", "page": 31, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Glória, glória, aleluia!\nGlória, glória ao nosso Salvador!\nGlória a Jesus, glória a Jesus,\nNosso grande Redentor!"}], "reviewed": false}, {"number": 62, "title": "Nome Precioso", "page": 31, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Leva tu contigo o Nome\nDe Jesus, o Salvador;\nEste Nome dá consolo,\nSeja no lugar que for."}, {"label": "Estrofe 2", "text": "Este Nome leva sempre,\nPara bem te defender;\nEle é arma ao teu alcance,\nQuando o mal te aparecer."}, {"label": "Estrofe 3", "text": "Oh, que Nome tão precioso!\nGozo traz ao coração;\nSendo por Jesus aceito,\nTu terás o seu perdão."}, {"label": "Estrofe 4", "text": "Nome santo e venerável\nÉ Jesus, o amado teu;\nRei dos reis, Senhor Eterno,\nTu o aclamarás no céu."}, {"label": "Estrofe 5", "text": "Nome bom, doce à fé,\nA esperança do porvir. (bis)"}], "reviewed": false}, {"number": 63, "title": "Jesus, o Senhor", "page": 31, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus, santo nome do Cristo de Deus,\nPor Deus posto acima de todos, nos céus!\nJesus, o bendito e divino Senhor;\nJesus, o bondoso, fiel Redentor!"}, {"label": "Estrofe 2", "text": "Jesus Nazareno, sem honras aqui;\nJesus, Deus excelso, com glória ali;\nJesus, que saudamos, real Salvador;\nJesus, que aclamamos, do mundo o Senhor!"}], "reviewed": false}, {"number": 64, "title": "Jubiloso", "page": 32, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Desperta já, meu coração,\nFaz tua voz soar;\nLouvores ao teu Rendentor\nNão cesses de cantar,\nPois te remiu, em uma cruz,\nDos vis pecados teus,\nE com seu sangue te comprou\nA doce paz dos céus."}, {"label": "Estrofe 2", "text": "Desperta já, meu coração,\nDesperta, sim, para entoar\nCanções sem fim à redenção,\nDe Deus o amor cantar!"}, {"label": "Estrofe 3", "text": "Remido estou; meu Deus, meu Rei,\nMe deu a salvação\nE me livrou do vil poder\nDa negra tentação.\nTão grande amor não pagarei,\nNão pagarei jamais;\nPois nessa graça ainda vou\nTer gozos divinais!"}, {"label": "Estrofe 4", "text": "Ó! Santo amor, sublime amor,\nQue os anjos lá nos céus\nNão têm poder de aquilatar,\nO eterno amor de Deus!\nTudo Ele faz resplandecer,\nA tudo dá vigor;\nÓ céus, ó mar, ó vastidão,\nLouvai o Deus de amor!"}], "reviewed": false}, {"number": 65, "title": "Jesus, o Bem-amado", "page": 32, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus, teu Nome satisfaz;\nPor todo o orbe espalha a paz;\nPerfeito gozo e vida traz,\nJesus, meu bem-amado!"}, {"label": "Estrofe 2", "text": "Pois, à minha alma, ó Salvador,\nA coração tão sofredor\nConcedes forças e vigor,\nJesus, meu bem-amado!"}, {"label": "Estrofe 3", "text": "Aflito pela tentação,\nMe fortalece a tua mão;\nProstrado, invoco, em oração,\nJesus, meu bem-amado!"}, {"label": "Estrofe 4", "text": "Jesus, teu Nome é sem igual,\nTão carinhoso, tão leal;\nÉs bom Pastor, celestial,\nJesus, meu bem-amado!"}, {"label": "Estrofe 5", "text": "Cristo, Nome de valor!\nCristo, forte Redentor!\nCristo, sumo e bom Pastor,\nSou teu eternamente!"}], "reviewed": false}, {"number": 66, "title": "Rei dos Céus", "page": 33, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis que chefe tão glorioso\nÉ Jesus, o bom Senhor!\nQue lutou mui vitorioso\nPara ser o Salvador."}, {"label": "Estrofe 2", "text": "Vinde todos coroá-lo,\nQue troféus bons ele traz!\nNo poder entronizá-lo,\nPríncipe da nossa paz."}, {"label": "Estrofe 3", "text": "Os juDeus o rejeitaram,\nEscolhendo um outro rei;\nAnjos, santos, potestades,\nObedecem sua lei."}, {"label": "Estrofe 4", "text": "Escutai o grande aplauso:\nTriunfou o bom Jesus;\nEle toma, pois, seu reino,\nCoroado Rei dos céus!"}, {"label": "Estrofe 5", "text": "Coroai-o, ó remidos;\nCoroai-o Rei dos reis! (bis)"}], "reviewed": false}, {"number": 67, "title": "Cristo Exaltado", "page": 34, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis entronizado, à destra do bom Deus,\nComo Rei eterno, Cristo, lá nos céus;\nEle é Rei da glória, que a Satã venceu;\nFeita tal vitória, Deus o recebeu."}, {"label": "Estrofe 2", "text": "Pela sua graça, pelo seu amor,\nSeja dado a Cristo cordial louvor!"}, {"label": "Estrofe 3", "text": "Veio resgatar-nos pela sua cruz;\nQuer apresentar-nos em celeste luz.\nPela sua morte, pelo seu sofrer,\nO inimigo nunca poderá vencer."}, {"label": "Estrofe 4", "text": "Mas o seu serviço continua ali;\nPoderá valer-nos, entretrando, aqui;\nPor nós advogando o Pai está;\nEle nos ajuda e sempre ajudará."}], "reviewed": false}, {"number": 68, "title": "Bem-aventurados", "page": 34, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Glória seja dada a Cristo,\nFilho eterno do bom Deus,\nPois remiu-nos pela graça\nE nos fez herdeiros seus."}, {"label": "Estrofe 2", "text": "Salvos pela fé em Cristo,\nSalvos, sim, no sangue seu;\nTendo nele segurança,\nCaminhemos para o céu."}, {"label": "Estrofe 3", "text": "Já se foi o tempo triste\nEm que procuramos luz!\nEis que longe de nós fica,\nCristo agora nos conduz.\nSim, guardados nós por Ele,\nViveremos em amor;\nBem-aventurados somos;\nEntoemos-lhe louvor."}], "reviewed": false}, {"number": 69, "title": "Aleluia", "page": 35, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Aleluia! Aleluia!\nGratos hinos entoai!\nJubilosos e contentes\nHinos a Jesus cantai!\nPra livrar-nos do pecado\nTriste morte padeceu,\nE da morte triunfando,\nEle vida eterna deu."}, {"label": "Estrofe 2", "text": "Jesus Cristo, o Rei da glória,\nO pecado aniquilou!\nE alcançou a mesma bênção\nPara os que Ele resgatou.\nEis milhares de milhares\nA prestar-lhe adoração,\nDescobrindo, na sua obra,\nVida, luz e salvação."}, {"label": "Estrofe 3", "text": "Aleluia! Aleluia!\nA Jesus todo o louvor!\nAleluia eternamente,\nAo bendito Redentor!\nAleluia ao Espírito Santo,\nQue nos dá consolo e paz;\nAleluia ao Pai eterno,\nDeus da graça, Deus da paz!"}], "reviewed": false}, {"number": 70, "title": "Nome Adorável", "page": 35, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mui doce soa ao coração\nDo pobre pecador\nO Nome que lhe dá perdão -\nJesus, o Salvador."}, {"label": "Estrofe 2", "text": "Jesus, meu Rei, meu Salvador,\nMeu terno e bom Pastor,\nMeu Advogado, meu Senhor,\nMeu forte Redentor.\nBendito o Nome de Jesus,\nEm Ti esperarei;\nTu, que morreste sobre a cruz,\nEm Ti confiarei."}, {"label": "Estrofe 3", "text": "Jesus, é só pensar em Ti\nMinha aflição desfaz;\nE o ver-te bem melhor será;\nÉ descansar em paz."}], "reviewed": false}, {"number": 71, "title": "Amigo Eterno", "page": 36, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Irmãos, todos juntos louvemos\nA Cristo Jesus, nosso Deus,\nPois muitos têm sido os favores\nQue dele tiveram os seus.\nSim, muito nós temos sofrido\nDe incrédulos e fariseus.\nAlegres, irmãos, prossigamos\nNa senda que vai para os céus!"}, {"label": "Estrofe 2", "text": "Oh! Sim, prossigamos, irmãos,\nNa senda que vai para os céus!\nAlegres, irmãos! Alegres, irmãos!\nNa senda que vai para os céus!"}, {"label": "Estrofe 3", "text": "E, crentes, lembrai-vos, portanto,\nDe todos que estão ao redor,\nOs quais inda jazem nas trevas,\nNão crendo em Jesus, Salvador.\nAlerta, pois, crentes, alerta!\nFirmeza no bom Redentor;\nE, gratos, a cada momento\nFalai, pois, do seu grande amor."}, {"label": "Estrofe 4", "text": "Cuidai bem de vossos deveres;\nDe Deus não se deve zombar;\nOuví sempre, sempre, a seu Filho\nE assim nunca haveis de falhar.\nJesus é amigo mui terno,\nÉ firme, fiel e sem-par;\nO seu grande amor e seu braço\nDe tudo vos podem livrar."}], "reviewed": false}, {"number": 72, "title": "Amigo Sem Igual", "page": 36, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Amigo sem igual! Amigo sem igual!\nO meu Jesus em meu lugar\nMorreu pra me salvar!\nAmigo sem igual! Amigo sem igual!\nSeu grande amor não mudará,\nE nunca falhará!"}, {"label": "Estrofe 2", "text": "Amigo sem igual! Amigo sem igual!\nPerto Ele está e quer salvar\nQuem nEle confiar.\nAmigo sem igual! Amigo sem igual!\nConvida com imenso amor\nA todo pecador!"}], "reviewed": false}, {"number": 73, "title": "Um Grande Amigo", "page": 37, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Achei um grande amigo,\nJesus, o Salvador,\nQue com amor me guarda cada dia;\nFiel é seu cuidado,\nConstante o seu amor\nE sem limite a sua simpatia.\nE ainda o mais notável\nÉ que por mim morreu\nE meus pecados todos expiou;\nAssim me regozijo\nNas bênçãos que me deu;\nSim, sei que Jesus Cristo me salvou."}, {"label": "Estrofe 2", "text": "Jesus é meu amigo,\nMeu guia, meu Senhor,\nMeu protetor, sem outro haver igual.\nPor mim sofreu a morte,\nPor mim, um pecador,\nE agora, vivo, guarda-me do mal."}, {"label": "Estrofe 3", "text": "Por este grande amigo\nDesejo aqui viver,\nCom ele ter constante comunhão,\nServí-lo fielmente,\nE assim lhe dar prazer,\nFicando sempre a Ele em sujeição.\nNos seus caminhos santos\nEspero aqui seguir\nE seu amor a todos demonstrar,\nPorque ele do pecado\nMe veio redimir\nE por amor morreu em meu lugar."}, {"label": "Estrofe 4", "text": "A hora vem chegando,\nA Bíblia no-lo diz,\nEm que Jesus ao mundo voltará.\nOh, que momento alegre,\nQue dia tão feliz,\nO dia em que voltar aqui será!\nEntão com ele sempre,\nNos céus, eu ficarei,\nJá livre do pecado, mágoa e dor;\nO seu amado rosto\nNa glória ali verei,\nE gozarei das bênçãos do Senhor."}], "reviewed": false}, {"number": 74, "title": "Graças a Jesus", "page": 38, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Graças ao bom Salvador,\nQue me livra do furor\nDo feroz destruidor!\nGraças, graças a Jesus!"}, {"label": "Estrofe 2", "text": "Graças ao fiel Pastor,\nQue morreu por grande amor\nDeste pobre pecador!\nGraças, graças a Jesus!"}], "reviewed": false}, {"number": 75, "title": "Que Grande Amigo", "page": 38, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que grande amigo é meu Jesus,\nTão santo, bom e terno!\nSem outro igual, o seu poder,\nE o seu amor, superno.\nPara esta ovelha sem vigor\nOlhou com simpatia,\nE sua tão bondosa mão\nServiu-me, então, de guia."}, {"label": "Estrofe 2", "text": "Que grande amigo é meu Jesus,\nDe longe quis buscar-me!\nDesceu, chegou, sofreu, penou,\nMorreu pra resgatar-me!\nAs glórias do seu santo lar\nRenovam meu alento,\nPois em breve espero receber\nO seu acolhimento."}, {"label": "Estrofe 3", "text": "Que grande amigo é meu Jesus,\nMeu guia tão prudente,\nMeu protetor tão ideal,\nE capitão valente!\nSou de Jesus, Jesus é meu,\nPor tempos sempiternos,\nE gozarei de Deus no céu\nFavores seus paternos."}], "reviewed": false}, {"number": 76, "title": "Amigo Verdadeiro", "page": 39, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Há um amigo verdadeiro,\nCristo, o Senhor,\nQue sofreu sobre o madeiro\nA nossa dor.\nEste amigo moribundo,\nPadecendo pelo mundo,\nPatenteia amor profundo.\nQue grande amor!"}, {"label": "Estrofe 2", "text": "Vida eterna é conhecê-lo,\nCristo, o Senhor.\nQuem quiser, depressa venha\nAo Redentor.\nPor nós outros derramava\nO seu sangue, pois amava\nOs perdidos que chamava.\nQue grande amor!"}, {"label": "Estrofe 3", "text": "Ontem, hoje e para sempre\nCristo, o Senhor,\nÉ o mesmo bom amigo\nDo pecador.\nÉ maná para o deserto,\nGuia no maior aperto;\nSeu socorro sempre é certo.\nQue grande amor!"}], "reviewed": false}, {"number": 77, "title": "O Melhor Amigo", "page": 39, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sei que o amigo melhor é Cristo;\nQuando a tempestade assalta a fé,\nPronto estende a sua mão,\nTranquiliza o coração.\nSim, o amigo melhor é Cristo."}, {"label": "Estrofe 2", "text": "Jesus é o melhor amigo.\nJesus é o melhor amigo.\nSim, repreende com dulçor,\nE me anima com vigor.\nSim, o amigo melhor é Cristo."}, {"label": "Estrofe 3", "text": "Oh, que amigo precioso é Cristo!\nNele encontro amor, consolo e paz.\nEm seu braço esperarei;\nNenhum golpe temerei.\nSim, o amigo melhor é Cristo."}, {"label": "Estrofe 4", "text": "Ao passar pelo vale escuro,\nE chegando às águas do Jordão,\nNão receio, pois Jesus,\nSalvo, à pátria me conduz.\nSim, o amigo melhor é Cristo."}, {"label": "Estrofe 5", "text": "Na mansão eternal eu junto\nCom os santos, transformados já,\nEste canto de louvor\nEntoaremos ao Senhor;\nSempre o amigo melhor é Cristo!"}, {"label": "Estrofe 6", "text": "Jesus é o melhor amigo,\nJesus é o melhor amigo.\nDo pecado me salvou,\nPara os céus me preparou.\nSim, o amigo melhor é Cristo."}], "reviewed": false}, {"number": 78, "title": "Tudo de Graça", "page": 40, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sim, de graça, Cristo dá-me paz e perdão,\nInefável alegria, plena salvação."}], "reviewed": false}, {"number": 79, "title": "Um Bom Amigo", "page": 40, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Um bom amigo, e fiel, achei:\nJesus, meu Salvador;\nContar aquilo que fez por mim,\nEu quero, sim, e com fervor."}, {"label": "Estrofe 2", "text": "Do mal não deixa de defender,\nSeguro bem estou;\nCom forte braço, com seu poder\nAmpara-me; contente vou."}, {"label": "Estrofe 3", "text": "Graça real, sem fim,\nMostra Jesus por mim;\nGozo me dá, alegria sem par!\nQue prazer, prazer!\nE quando necessitado sou,\nEu posso recorrer\nAo seu tesouro celestial\nE bênçãos ricas recolher."}, {"label": "Estrofe 4", "text": "Em Cristo todos encontrarão\nAmigo sem igual,\nAmigo que lhes concederá\nFelicidade perenal."}], "reviewed": false}, {"number": 80, "title": "Coração Purificado", "page": 41, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A Jesus com fé chegando,\nAcho plena salvação,\nE seu sangue me levando,\nTorna puro o coração."}], "reviewed": false}, {"number": 81, "title": "Amor Incomparável", "page": 41, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Nenhum amigo há igual a Cristo!\nNão nenhum! Não nenhum!\nOutro não há que minha alma salve!\nNão, nenhum! Não, nenhum!"}, {"label": "Estrofe 2", "text": "Cristo sabe das nossas lutas;\nGuiará até o fim chegar;\nNenhum amigo há igual a Cristo,\nNão nenhum! Não, nenhum!"}, {"label": "Estrofe 3", "text": "Nenhum momento ele me abandona!\nNão, nenhum! Não, nenhum!\nNão há desgosto que não suavize!\nNão, nenhum! Não, nenhum!"}, {"label": "Estrofe 4", "text": "Nenhum amigo há tão nobre e santo!\nNão, nenhum! Não, nenhum!\nTambém não há tão humilde e manso!\nNão, nenhum! Não, nenhum!"}, {"label": "Estrofe 5", "text": "Crente nenhum é desamparado!\nNão, nenhum! Não, nenhum!\nNenhum ansioso há que é rejeitado!\nNão, nenhum! Não, nenhum!"}], "reviewed": false}, {"number": 82, "title": "O Gólgota", "page": 42, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mui longe o monte verde está,\nAo norte de Sião,\nNo qual o bom Jesus, na cruz,\nNos deu a salvação."}, {"label": "Estrofe 2", "text": "Quem sondará, quem contará\nA dor que padeceu?\nMas crer podemos, foi por nós\nO que na cruz sofreu."}, {"label": "Estrofe 3", "text": "Morreu pra dar-nos o perdão,\nMorreu pra sermos bons,\nPra entrarmos na mansão de Deus,\nCom limpos corações."}, {"label": "Estrofe 4", "text": "Ninguém podia, aqui, pagar\nA pena universal;\nSó Cristo pôde nos remir,\nAo preço divinal."}, {"label": "Estrofe 5", "text": "Oh, quanto, quanto nos amou!\nAmemo-lo também;\nE confiando em seu amor,\nFaçamos todo o bem!"}], "reviewed": false}, {"number": 83, "title": "A Cruz de Cristo", "page": 42, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Pendurado foste, ó Senhor Jesus,\nNuma cruz, exposto ao desprezo, assim,\nCena que a pensar muita gente induz;\nSofreste tanto, creio, foi por mim!"}, {"label": "Estrofe 2", "text": "Tu, Jesus, vieste me salvar.\nTu, Jesus, vieste me salvar.\nEu confio em ti,\nTeu amor senti,\nSofreste tanto, creio, foi por mim!"}, {"label": "Estrofe 3", "text": "Sangue tu verteste pra me salvar,\nDeste tua vida, meu Redentor.\nCerto estou, foi tudo em me resgatar;\nSofreste tanto, creio, meu Senhor!"}, {"label": "Estrofe 4", "text": "Tua morte veio me libertar;\nGrande foi o peso de tal paixão.\nTeu amor, oh, quem poderá sondar?!\nSofreste, creio, em tua compaixão!"}, {"label": "Estrofe 5", "text": "Toda a maldição do pecado meu\nTu levaste, pois, sobre Ti, Senhor.\nGozo paz, tornei-me um herdeiro teu,\nSofreste tudo, creio, pelo amor!"}], "reviewed": false}, {"number": 84, "title": "A Cruz", "page": 43, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo, em tua cruz há glória,\nDominando o caos maior;\nToda a luz da sacra história\nSe concentra ao seu redor."}, {"label": "Estrofe 2", "text": "Se me abatem vis temores,\nE a esperança se desfaz,\nÉ na cruz que encontro flores;\nDela vem prazer e paz."}, {"label": "Estrofe 3", "text": "Se o sol brilha da ventura,\nAlegrando o meu viver,\nLá da cruz a luz fulgura\nE me traz maior prazer."}, {"label": "Estrofe 4", "text": "Por igual, já são benditas\nA ventura e a dor, na cruz;\nAlegrias inauditas\nNela trouxe o bom Jesus."}], "reviewed": false}, {"number": 85, "title": "Cantai Louvores", "page": 43, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, vinde, crentes, e entoai\nLouvores a Jesus,\nQue, para a nossa salvação,\nFoi morto numa cruz;\nSeu sangue derramou, de tudo me lavou,\nMais alvo do que a neve me tornou!"}, {"label": "Estrofe 2", "text": "O sangue de Jesus me lavou, me lavou;\nO sangue de Jesus me lavou, me lavou;\nAlegre cantarei louvores a meu Rei,\nA meu Senhor Jesus que me salvou."}, {"label": "Estrofe 3", "text": "Conosco vinde vos unir\nNa guerra contra o mal,\nE, com o nosso Salvador,\nEm marcha triunfal,\nA todos proclamar a graça e seu poder;\nSeu sangue derramou pra nos salvar!"}, {"label": "Estrofe 4", "text": "O capitão da salvação\nÉ Cristo, o Salvador;\nO Rei dos reis, o Redentor,\nJesus, o bom Senhor;\nPois tudo vencerá; vitória nos dará;\nÀ glória, salvos, nos conduzirá."}], "reviewed": false}, {"number": 86, "title": "Sangue Precioso", "page": 44, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, que tão precioso sangue\nMeu Senhor verteu,\nQuando, para resgatar-nos,\nPadeceu!"}, {"label": "Estrofe 2", "text": "Oh, que tão precioso sangue!\nFala-nos de paz;\nTudo quanto a lei exige\nSatisfaz!"}, {"label": "Estrofe 3", "text": "Oh, que tão precioso sangue!\nTraz-nos salvação;\nDeus por ele dá aos crentes\nO perdão!"}, {"label": "Estrofe 4", "text": "Oh, que tão precioso sangue\nDo meu Salvador!\nPois que a todos a manifesta\nSeu amor!"}, {"label": "Estrofe 5", "text": "Oh, que tão precioso sangue,\nQue liberta os réus!\nPodem ter pode por ele entrada\nLá nos céus!"}], "reviewed": false}, {"number": 87, "title": "Calvário", "page": 44, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, como foi que meu Jesus\nAssim sofreu na triste cruz?!\nNão só na cruz, mas no jardim\nAgonizou, e foi por mim!"}, {"label": "Estrofe 2", "text": "Ali na cruz, ali na cruz,\nOh, sim, Jesus por mim sofreu!\nAli na cruz, ali na cruz,\nOh, sim, Jesus por mim morreu!"}, {"label": "Estrofe 3", "text": "O grande horror da escuridão\nApavarou a multidão;\nRasgado o véu lhes fez saber\nQue terminou o seu sofrer."}, {"label": "Estrofe 4", "text": "Que dor cruel na cruz sofreu!\nSeu sangue ali Jesus verteu;\nSim, foi por mim, pra me salvar,\nPara eu, enfim, no céu morar."}], "reviewed": false}, {"number": 88, "title": "Que Fazes Por Mim", "page": 45, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Das glórias eternais\nAo mundo vil desci;\nA sorte eu assumi\nDos míseros mortais;\nE tudo foi por ti,\nQue fazes tu por mim?"}, {"label": "Estrofe 2", "text": "Meu sangue derramei,\nE, no sofrer cruel,\nBebi vinagre e fel;\nNa cruz eu expirei;\nE tudo foi por ti,\nQue sofres tu por mim?"}, {"label": "Estrofe 3", "text": "Pra dar-te a salvação\nSofri, penei, morri;\nTeu substituto fui\nEm dura escravidão;\nE tudo foi por ti,\nQue deste tu por Mim?"}, {"label": "Estrofe 4", "text": "Do Pai celestial\nCompleta redenção,\nA eterna salvação,\nA dita perenal\nTe dou de graça a ti;\nNão temas, vem a mim."}], "reviewed": false}, {"number": 89, "title": "O Poder do Sangue", "page": 46, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Seu sangue tem poder, sim tem poder.\nAlmejas tu do maligno escapar?\nSeu sangue tem este poder."}, {"label": "Estrofe 2", "text": "Há poder, sim, força sem igual,\nSó no sangue de Jesus;\nHá poder, sim, prova-o, pecador,\nOh, aceita o dom de Jesus!"}, {"label": "Estrofe 3", "text": "Queres com tua vaidade acabar?\nSeu sangue há poder, sim, tem poder.\nVícios, paixões, queres tu dominar?\nSeu sangue tem este poder."}, {"label": "Estrofe 4", "text": "Teu coração queres purificar?\nSeu sangue tem poder, sim, tem poder.\nTodas as manchas te pode tirar;\nSeu sangue tem este poder."}, {"label": "Estrofe 5", "text": "Queres entrar no serviço real?\nSeu sangue tem poder, sim, tem poder.\nQueres tembém ser um servo leal?\nTerás no seu sangue o poder."}], "reviewed": false}, {"number": 90, "title": "Contemplação", "page": 46, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Olhando o lenho crucial\nEm que morreu da glória o Rei,\nÀs honras, vida mundanal\nDesprezo eterno votarei."}, {"label": "Estrofe 2", "text": "E não permitas, meu Senhor,\nQue me glorie eu senão\nNa morte do meu Redentor,\nQue me salvou da perdição."}, {"label": "Estrofe 3", "text": "Olhai! Da ensangüentada cruz,\nTorrentes de tristeza e amor!\nQue dor, que amor do meu Jesus,\nPor mim, seu vil perseguidor!"}, {"label": "Estrofe 4", "text": "Se o mundo inteiro fosse meu,\nSeria oferta sem valor;\nTudo o que sou, Senhor, é teu -\nMinha alma e todo o meu amor."}], "reviewed": false}, {"number": 91, "title": "Sangue de Jesus", "page": 47, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O sangue tão precioso de Jesus\nDo pecado purifica;\nO sangue de Jesus me purifica;\nMesmo, mesmo a mim."}], "reviewed": false}, {"number": 92, "title": "Substituição", "page": 47, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Morri na cruz por ti,\nMorri pra te livrar;\nMeu sangue, sim, verti,\nE posso te salvar."}, {"label": "Estrofe 2", "text": "Aqui vivi por ti,\nCom muito dissabor;\nSim, tudo fiz aqui,\nPra ser teu Salvador."}, {"label": "Estrofe 3", "text": "Sofri na cruz por ti,\nA fim de te salvar;\nA vida consegui,\nQue tu irás gozar."}, {"label": "Estrofe 4", "text": "Eu trouxe salvação,\nDos altos céus, favor;\nÉ livre meu perdão;\nSincero, meu amor."}, {"label": "Estrofe 5", "text": "Morri, morri na cruz por ti;\nQue fazes tu por Mim? (bis)"}], "reviewed": false}, {"number": 93, "title": "Só No Sangue", "page": 47, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quem me poderá salvar?\nCristo, que verteu seu sangue.\nOnde as manchas vou limpar?\nSó no seu precioso sangue."}, {"label": "Estrofe 2", "text": "Oh, que preciosa paz,\nQue vem da sua cruz!\nA qual me dá Jesus\nPelo seu precioso sangue!\nVejo a minha salvação\nSó no seu precioso sangue.\nDeus concede-me perdão\nSó no seu precioso sangue."}, {"label": "Estrofe 3", "text": "Dele vem perfeita paz\nPelo seu precioso sangue;\nInfalível e eficaz,\nEsse tão precioso sangue."}, {"label": "Estrofe 4", "text": "Minha justificação\nTenho no precioso sangue;\nGozo traz ao coração\nEsse tão precioso sangue."}, {"label": "Estrofe 5", "text": "Entrarei no céu, enfim,\nPelo seu precioso sangue;\nLouvarei, então, sem fim,\nEsse tão precioso sangue."}], "reviewed": false}, {"number": 94, "title": "Jesus Na Cruz", "page": 48, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Só tu, Jesus, levaste a cruz,\nHumilde em teu amor;\nNo teu olhar brilhava a luz\nDe compaixão, Senhor!"}, {"label": "Estrofe 2", "text": "Julgado foste como réu,\nPilatos foi juiz;\nDe enganador foi teu labéu,\nJulgaram-te infeliz!"}, {"label": "Estrofe 3", "text": "Sofreste zombarias mil,\nDesdém e amargo fel;\nferiu-te a rejeição hostil\nDe gente tão cruel!"}, {"label": "Estrofe 4", "text": "Suspenso em um madeiro vil,\nMostraste o teu amor;\nPerdão pra gente tão servil\nRogaste, Salvador!"}, {"label": "Estrofe 5", "text": "Rendeste o Espírito a Jeová,\nCom grande brado teu,\nSim: \"Tudo consumado está.\"\nMissão que o Pai te deu!"}], "reviewed": false}, {"number": 95, "title": "Vitória do Rejeitado", "page": 49, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus é rejeitado,\nO mundo não o quer;\nRecusa, com orgulho,\nSeu rei reconhecer;\nMas eis que vem glorioso\nDo seu celeste lar,\nPara logo com poder aqui reinar!"}, {"label": "Estrofe 2", "text": "Logo vem o dia eterno\nDa sua exaltação!\nVem, sim, para o livramento\nDe toda a criação.\nOh, que canto de vitória\nEntão há de soar,\nQuando Cristo, triunfante, aqui reinar!"}, {"label": "Estrofe 3", "text": "O sol ao meio-dia\nNão tem o resplendor\nQual há de ter a igreja\nNa vinda do Senhor;\nEis que do Esposo as jóias\nA noiva há de ostentar,\nQuando Cristo, triunfante, aqui reinar!"}, {"label": "Estrofe 4", "text": "Já temos privilégio\nDe pela fé prever\nA divinal herança\nQue vamos receber.\nA dor e o sofrimento\nJamais terão lugar,\nQuando Cristo, triunfante, aqui reinar!"}], "reviewed": false}, {"number": 96, "title": "Deslumbrante", "page": 49, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se nos cega o sol ardente,\nQuando visto em seu fulgor,\nQuem contemplará aquele\nQue do sol é Criador?\nPatriarcas, nem profetas\nO chegaram a avistar,\nNem Adão chegou a vê-Lo,\nAntes mesmo de pecar."}, {"label": "Estrofe 2", "text": "Luz, pra a qual o sol é trevas,\nQuem Te pode contemplar?\nNossos olhos nus, humanos,\nNão Te podem encarar.\nFogo em cima da arca santa,\nSarça ardente no Sinai,\nSão figuras só da glória\nDo Senhor, do eterno Pai."}, {"label": "Estrofe 3", "text": "Para termos nós com Ele\nFranca e doce comunhão,\nCristo, o Filho, fez-se carne,\nFez-se nossa redenção.\nPara que na glória eterna\nNós miremo-Lo sem véu,\nCristo padeceu a morte,\nNova entrada abrindo ao céu."}], "reviewed": false}, {"number": 97, "title": "Jesus Veio Aqui", "page": 50, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, como é tão singular Jesus,\nEsbelto e mui gentil!\nNo rosto traz uma rara luz,\nFanal no mundo vil!"}, {"label": "Estrofe 2", "text": "A sua vida gastou aqui\nPerdidos pra salvar;\nNa cruz sangrenta se deu a Si,\nA fim de os resgatar."}, {"label": "Estrofe 3", "text": "O povo, com apatia, viu\nA prova desse amor;\nE sua graça jamais mediu\nUm mundo pecador."}, {"label": "Estrofe 4", "text": "No céu agora Jesus está,\nMas breve há de voltar,\nE à glória os salvos transportará,\nOnde hão de descansar."}, {"label": "Estrofe 5", "text": "Da sua glória celestial\nVeio Jesus aqui;\nA sua graça divinal\nFê-Lo ao mundo vir!"}], "reviewed": false}, {"number": 98, "title": "Jesus Triunfou", "page": 50, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus Cristo está sentado\nNo seu trono de poder;\nTudo já tem consumado\nDo que quis aqui fazer.\nOh, que glória, oh, que glória\nNo Senhor se pode ver!"}, {"label": "Estrofe 2", "text": "Desde o seu primeiro advento\nEm humana encarnação,\nTé o pleno cumprimento\nDessa terreal missão,\nVemos glória, vemos glória\nQue é dos céus admiração."}, {"label": "Estrofe 3", "text": "Na agonia extrema vemos\nQue vitória então ganhou;\nPor morrer, nós compreendemos,\nEle a vida nos legou;\nCom que glória, com que glória\nSobre a morte triunfou!"}], "reviewed": false}, {"number": 99, "title": "Ressurreição", "page": 51, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis morto o Salvador\nNa sepultura!\nMas com poder, vigor,\nRessuscitou."}, {"label": "Estrofe 2", "text": "Da sepultura saiu!\nCom triunfo e glória ressurgiu!\nRessurgiu, vencendo a morte e o seu poder;\nPode agora a todos vida conceder!\nRessurgiu! Ressurgiu!\nAleluia! Ressurgiu!"}, {"label": "Estrofe 3", "text": "Tomaram precaução\nCom seu sepulcro;\nMas tudo foi em vão\nPara o reter."}, {"label": "Estrofe 4", "text": "A morte conquistou\nCom grande glória!\nOh, graças, alcançou\nVida eternal."}], "reviewed": false}, {"number": 100, "title": "Jesus Ressuscitado", "page": 51, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis Jesus ressuscitado!\nEle para o céu subiu.\nAs prisões quebrou da morte,\nGrandes feitos conseguiu.\nEis Jesus ressuscitado!\nVive e reina lá no céu!\nEis Jesus ressuscitado!\nVoltará ao povo seu!"}, {"label": "Estrofe 2", "text": "Eis Jesus ressuscitado,\nPara nosso Mestre ser!\nConseguiu, na cruz morrendo,\nPelo crente interceder.\nEis Jesus ressuscitado,\nPra a vitória nos ganhar!\nEis Jesus ressuscitado,\nPara nos justificar!"}, {"label": "Estrofe 3", "text": "Eis Jesus ressuscitado!\nEle a morte aniquilou,\nPra ressuscitar-nos todos,\nSim, os crentes que salvou.\nEis Jesus ressuscitado!\nEle em breve voltará.\nEis Jesus ressuscitado,\nE Consigo nos terá!"}], "reviewed": false}, {"number": 101, "title": "Ressurgiu", "page": 52, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo já ressuscitou; aleluia!\nSobre a morte triunfou; aleluia!\nTudo consumado está; aleluia!\nSalvação de graça dá; aleluia!"}, {"label": "Estrofe 2", "text": "Uma vez na cruz sofreu; aleluia!\nUma vez por nós morreu; aleluia!\nMas agora vivo está; aleluia!\nE pra sempre reinará; aleluia!"}, {"label": "Estrofe 3", "text": "Gratos hinos entoai; aleluia!\nA Jesus, o grande Rei; aleluia!\nPois à morte quis baixar; aleluia!\nPecadores pra salvar; aleluia!"}], "reviewed": false}, {"number": 102, "title": "Cristo Volta", "page": 52, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo volta brevemente,\nPara aqui no mundo ter,\nEm lugar de sofrimento,\nMajestade com poder.\nEle volta, e em sua glória\nBrilha a refulgente luz\nDesse dia tão querido\nDos remidos de Jesus."}, {"label": "Estrofe 2", "text": "Cristo volta! Cristo volta!\nPara o povo seu buscar;\nCristo volta triunfante,\nPara com poder reinar,\nCristo volta! Cristo volta!\nNosso amado Salvador.\nOh, que regozijo ao vê-Lo\nSobre todos ser Senhor!"}, {"label": "Estrofe 3", "text": "Cristo volta! Nem mais penas,\nNem mais pranto, nem mais dor,\nNem mais sombra de pecado,\nNem mais falta de vigor.\nEle volta para à glória\nSua igreja conduzir,\nPara tê-la, então, Consigo\nNo celestial porvir."}, {"label": "Estrofe 4", "text": "Cristo volta! Não sabemos\nEm que dia tem de ser,\nMas estamos confiados\nQue seu rosto iremos ver.\nA palavra santa o afirma,\nE não poderá falhar,\nE por isso esperaremos\nVer Jesus aqui voltar."}], "reviewed": false}, {"number": 103, "title": "Jesus Vindo", "page": 53, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus desceu, a Bíblia o diz,\nDo seu celeste lar,\nA fim de o grande amor de Deus\nAos homens declarar."}, {"label": "Estrofe 2", "text": "Jesus morreu, a Bíblia o diz,\nE fez expiação\nDo nosso mal, e assim achou\nUm meio de perdão."}, {"label": "Estrofe 3", "text": "A Bíblia diz que ressurgiu,\nDa morte vencedor,\nE desde agora pode ser\nO nosso Salvador."}, {"label": "Estrofe 4", "text": "A Bíblia diz que voltará,\nA fim de nos levar,\nDo mundo e da tristeza aqui,\nAo seu bendito lar."}, {"label": "Estrofe 5", "text": "A Bíblia diz-nos que Jesus\nNo mundo reinará;\nEntão, Senhor universal,\nlouvor sem fim terá."}], "reviewed": false}, {"number": 104, "title": "O Bom Porvir", "page": 54, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O dia alegre chega,\nRadiante em santa luz,\nQuando, afinal, vencido o mal,\nVier reinar Jesus.\nO Salvador domínio\nTerá de mar a mar,\nE sob a sua proteção\nOs seus vem congregar."}, {"label": "Estrofe 2", "text": "Breve o dia vem; breve o dia vem.\nO dia alegre chega,\nBem perto a aurora está;\nBreve o dia vem; breve o dia vem\nEm que essa paz, que Cristo traz,\nSeu povo gozará."}, {"label": "Estrofe 3", "text": "Jamais a voz do engano\nNo mundo se ouvirá;\nJamais o horror do tentador\nO povo afligirá;\nMas todos a verdade\nSomente falarão,\nE ao grande Deus os santos seus\nCom gozo adorarão."}, {"label": "Estrofe 4", "text": "Por esse dia alegre\nSuspira a criação,\nEm dor, aqui, oculta em si,\nSob dura escravidão;\nMas das tristezas, dores,\nEntão se livrará,\nAo refulgir, no bom porvir,\nA luz que bênção dá."}], "reviewed": false}, {"number": 105, "title": "Feliz", "page": 55, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus sendo meu, sou muito feliz!\nEu vou para o céu, meu lindo país;\nEu não mereço, sou vil pecador,\nMas, crendo, conheço meu bom Salvador!"}], "reviewed": false}, {"number": 106, "title": "O Desejado", "page": 55, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vem, ó Cristo desejado!\nVem depressa, Redentor!\nSalve o dia esplendoroso\nDo regresso teu, Senhor!"}, {"label": "Estrofe 2", "text": "Vem, ó Cristo desejado!\nVem o mundo libertar\nDessas dores em que geme!\nTeu poder vem demonstrar!"}, {"label": "Estrofe 3", "text": "Vem ó Cristo desejado!\nVem o mundo dominar,\nDispensando amor, justiça!\nVem teu reino dilatar!"}, {"label": "Estrofe 4", "text": "Vem, ó Cristo desejado,\nTua glória revelar!\nVem, Senhor Jesus, nos ares\nPara nos arrebatar!"}, {"label": "Estrofe 5", "text": "Vem, esperança deste mundo!\nVem o milênio inaugurar!\nVem teus remidos despertar do sono!\nOh, vem teu reino confirmar!"}], "reviewed": false}, {"number": 107, "title": "Esperando", "page": 55, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Bem ansiosos aguardamos\nTua vinda, ó bom Jesus,\nQuando em majestade e glória\nTu voltares lá dos céus!\nRemovida, então, veremos\nToda dor, toda aflição;\nExultando, aplaudiremos\nTua glorificação!"}, {"label": "Estrofe 2", "text": "Bem ansiosos aguardamos\nTua vinda, ó bom Jesus;\nPois, assim como subiste,\nVoltarás do altos céus.\nE nós, tuas testemunhas,\nCom prazer e exaltação,\nExultando, aplaudiremos\nTua glorificação!"}, {"label": "Estrofe 3", "text": "Bem ansiosos aguardamos\nTua vinda, ó bom Jesus;\nCom os nossos bem amados\nGozaremos tua luz.\nQuando Tu, Jesus, voltares,\nDesfarás toda opressão;\nExultando, aplaudiremos\nTua glorificação!"}], "reviewed": false}, {"number": 108, "title": "Chamada Final", "page": 56, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quando Cristo sua trombeta\nLá do céu mandar tocar,\nQuando o dia mui glorioso lá romper,\nE aos remidos desta Terra\nMeu Jesus se incorporar,\nE fizer-se, então, chamada, lá estarei."}, {"label": "Estrofe 2", "text": "Quando se fizer chamada, (4 vezes)\nLá estarei."}, {"label": "Estrofe 3", "text": "Nesse tão glorioso dia,\nQuando o crente ressurgir\nE da glória de Jesus participar,\nQuando os crentes ressurgidos\nO saudarem no porvir,\nE fizer-se, então, chamada, lá estarei."}, {"label": "Estrofe 4", "text": "Lidarei, então, pra Cristo\nTé o dia terminar;\nFalarei do seu amor por nós aqui;\nQuando, pois, findar a vida\nE o labor aqui cessar,\nE fizer-se, então, chamada, lá estarei."}], "reviewed": false}, {"number": 109, "title": "Por Pouco Tempo", "page": 56, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Anseio a paz, que qual um rio corre,\nE no deserto faz brotar a flor;\nAnseio a fé que, neste pouco tempo,\nDescansa no bendito Salvador.\nHá pouco tempo pra velar, orando,\nE contra o inimigo batalhar;\nHá pouco tempo para aqui, chorando,\nLançar semente, pra depois ceifar."}, {"label": "Estrofe 2", "text": "Por pouco tempo, as lâmpadas zelando,\nDevemos, bem despertos, esperar;\nAssim, pois, pressuroso o noivo vindo,\nCom Ele nós iremos pra seu lar."}], "reviewed": false}, {"number": 110, "title": "Quando Cristo Vier", "page": 57, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quando Cristo os crentes vier buscar,\nTodo vale escuro há de se aclarar,\nQuando Cristo os crentes vier buscar,\nPra gozar no eterno lar."}, {"label": "Estrofe 2", "text": "Quando nos vier buscar,\nQuando Cristo regressar,\nTodo vale escuro há de se aclarar;\nPra gozar nos vem buscar."}, {"label": "Estrofe 3", "text": "Quando Cristo os crentes vier buscar,\nTodas as tristezas hão de acabar,\nQuando Cristo os crentes vier buscar,\nPra gozar no eterno lar."}, {"label": "Estrofe 4", "text": "Quando Cristo os crentes vier buscar,\nTodo o seu receio se extinguirá,\nPois a morte não mais existirá,\nQuando nos vier buscar."}, {"label": "Estrofe 5", "text": "Quando Cristo os crentes vier buscar,\nUm bem-vindo alegre há de ressoar;\nEle nunca mais nos irá deixar,\nQuando nos vier buscar."}], "reviewed": false}, {"number": 111, "title": "Não Tardará", "page": 57, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo do céu em breve virá\nEle afirmou-nos, e não tardará;\nOh, que alegria, que glória será,\nQuando Jesus regressar!"}, {"label": "Estrofe 2", "text": "Em breve os montes ressurgirão;\nTodos os crentes, oh, se encontrarão!\nJuntos, alegres, ao céu subirão!\nQuando Jesus regressar!"}, {"label": "Estrofe 3", "text": "Breve esta terra gozará paz;\nPreso, encerrado será satanás!\nTudo o que é vil deixaremos atrás,\nQuando Jesus regressar!"}, {"label": "Estrofe 4", "text": "Cristo não tarda, não tarda em vir,\nQuando será, no glorioso porvir?\nOh, que alegria teremos em ir,\nQuando Jesus regressar!"}, {"label": "Estrofe 5", "text": "Cristo não tarda, não tarda a voltar;\nCristo não tarda a voltar!\nOh, que alegria, que glória será,\nQuando Jesus regressar!"}], "reviewed": false}, {"number": 112, "title": "Vencendo Vem Jesus", "page": 58, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Já refulge a glória eterna\nDe Jesus o Rei dos reis;\nBreve os reinos deste mundo\nSeguirão as suas leis!\nOs sinais da sua vinda\nMais se mostram cada vez.\nVencendo vem Jesus!"}, {"label": "Estrofe 2", "text": "Glória, glória! Aleluia! (3 vezes)\nVencendo vem Jesus!"}, {"label": "Estrofe 3", "text": "O clarim que chama os crentes\nA batalha já soou;\nCristo, à frente do seu povo,\nMultidões já conquistou.\nO inimigo, em retirada,\nSeu furor patenteou.\nVencendo vem Jesus!"}, {"label": "Estrofe 4", "text": "Eis que em glória refulgente\nSobre as nuvens descerá,\nE as nações e os reis da Terra\nCom poder governará.\nSim, em paz e santidade\nToda a Terra regerá\nVencendo vem Jesus!"}, {"label": "Estrofe 5", "text": "E por fim, entronizado,\nAs nações há de julgar;\nTodos, grande e pequenos,\nO Juiz hão de encarar;\nE os remidos, triunfantes,\nEm fulgor hão de cantar:\nVencido tem Jesus!"}, {"label": "Estrofe 6", "text": "Glória, glória! Aleluia! (3 vezes) (CORO)\nVencido tem Jesus!"}], "reviewed": false}, {"number": 113, "title": "O Dia Glorioso", "page": 59, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Regozijai-vos, sim, ó crentes,\nO Senhor não tardará!\nJá vem o dia mui glorioso\nEm que Cristo voltará!"}, {"label": "Estrofe 2", "text": "Ó dia triunfal de Cristo,\nQuando lá do céu descer!\nEstejamos prontos, jubilosos,\nO Senhor a receber!\nRegozijai-vos, sim, ó crentes!\nO Senhor não tardará!\nJá vem o dia mui glorioso\nEm que Cristo voltará!"}, {"label": "Estrofe 3", "text": "Eis, com milhares de milhares,\nSobre as nuvens Ele vem;\nE todos juntos entraremos\nCom Jesus na glória além!"}, {"label": "Estrofe 4", "text": "E então será glorificado\nNos remidos o Senhor;\nE o mundo ficará pasmado,\nVendo a Cristo em seu fulgor!"}], "reviewed": false}, {"number": 114, "title": "A Vinda do Senhor", "page": 59, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Como foi para o céu, Jesus Cristo há de vir\nQuando o som da trombeta ecoar;\nQuando a voz do arcanjo no céu estrugir,\nEu irei com Jesus me encotrar."}, {"label": "Estrofe 2", "text": "Oh, que dia faustoso esse dia há de ser\nQuando o som da trombeta ecoar;\nQuando Cristo, nas nuvens, tiver de descer,\nPara, assim, entre nós habitar!"}, {"label": "Estrofe 3", "text": "Nesse dia de glória meu corpo mortal\nSemelhante ao de Cristo há de ser;\nE já livre da morte, e já livre do mal,\nO milênio de Cristo hei de ver."}, {"label": "Estrofe 4", "text": "Eu aqui, pela cruz, para o mundo morri,\nMuita dor inda aqui sofrerei;\nMinha vida com Cristo em meu Deus escondi,\nE com Cristo eu aqui reinarei."}, {"label": "Estrofe 5", "text": "Vem, Jesus, ó Senhor, vem depressa reinar,\nVem a paz e a justiça trazer;\nCriação, povo teu, tudo almeja o raiar\nDesse dia de glória e poder."}, {"label": "Estrofe 6", "text": "Este império do mal, vem, Senhor, destruir,\nVem, Esposo celeste, reinar!\nVem, ó Sol da Justiça, no mundo luzir;\nÓ meu Rei, vem meu pranto estancar!"}], "reviewed": false}, {"number": 115, "title": "Breve com Jesus", "page": 60, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Em breve, em breve havemos\nDe ver o Salvador;\nE em casa cantaremos\nJesus e seu amor! (3 vezes)"}], "reviewed": false}, {"number": 116, "title": "Desejo da Alma", "page": 60, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vem, Espírito divino,\nGrande ensinador!\nVem! Descobre às nossas almas\nCristo, o Salvador!"}, {"label": "Estrofe 2", "text": "Vem! Demole os alicerces\nDa enganosa paz,\nAos errados concedendo\nSalvação veraz!"}, {"label": "Estrofe 3", "text": "Vem! Reveste a tua igreja\nDe poder e luz!\nVem! Atrai os pecadores\nAo Senhor Jesus!"}, {"label": "Estrofe 4", "text": "Maravilhas soberanas\nOutros povos vêem;\nOh, derrama a mesma bênção\nSobre nós também!"}, {"label": "Estrofe 5", "text": "Cristo, Mestre,\nOuve com favor!\nEm poder e graça insigne\nObre o teu amor!"}], "reviewed": false}, {"number": 117, "title": "Espírito Santo", "page": 61, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó divino Preceptor,\nMostra-nos o Salvador!\nÓ Tu, bom Consolador,\nEnche-nos de santo amor!"}, {"label": "Estrofe 2", "text": "Tu fiel Instruidor,\nCom celestial favor,\nMostra como Te adorar,\nComo culto a Deus prestar!"}, {"label": "Estrofe 3", "text": "Santo Espírito de Deus,\nEnche de fervor os teus,\nPra cantarem o louvor\nDe Jesus, o Salvador!"}, {"label": "Estrofe 4", "text": "Vem, Espírito veraz!\nEsta escuridão desfaz!\nEnche-nos de santa luz,\nGuia todos a Jesus!"}], "reviewed": false}, {"number": 118, "title": "Santo Espírito", "page": 61, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus, ao céu subindo,\nSe penhorou mandar\nSeu bom e santo Espírito,\nA fim de nos guiar;\nE o grande, excelso Guia,\nEm nós agora está,\nO mundo além revela,\nConduz-nos para lá."}], "reviewed": false}, {"number": 119, "title": "Fidelidade", "page": 61, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Por meus delitos expirou\nJesus, a Vida e Luz;\nEle o castigo meu levou\nNa ensanguentada cruz."}, {"label": "Estrofe 2", "text": "Oh, faz-me forte em confessar\nA Ti, Jesus, Senhor!\nOh, faz-me pronto a confiar\nEm teu excelso amor!"}, {"label": "Estrofe 3", "text": "E eu hei de ter não fraca voz,\nQue trema, ao confessar,\nA quem, com morte tão atroz,\nMinha alma quis salvar?"}, {"label": "Estrofe 4", "text": "Pois eu desejo aqui cantar,\nTão grande Salvador;\nE, quando for no céu morar,\nLouvá-Lo-ei melhor."}], "reviewed": false}, {"number": 120, "title": "Louvai Ao Senhor", "page": 62, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Louvai ao Senhor, o Deus Onipotente,\nLouvai, ó remidos, louvai ao Senhor!\nÓ homens, Deus ama-vos eternamente,\nPois provas nos deu por Jesus, Salvador."}, {"label": "Estrofe 2", "text": "Louvai, louvai, louvai nosso Redentor!\nCantai, cantai, cantai sempre em seu louvor.\nJesus sofreu por nós na cruz,\nLouvai, exaltai nosso Senhor!"}, {"label": "Estrofe 3", "text": "Perdão vos concede o Senhor poderoso,\nQue Cristo por nós no madeiro alcançou;\nDeixai vossos vícios e o mundo enganoso,\nFugi para Cristo, que vos libertou!"}, {"label": "Estrofe 4", "text": "Sim, Cristo vos salva de toda a maldade,\nVos livra dos vícios, da carne e do mal,\nVos tira das trevas, vos dá liberdade\nE salva pra sempre! Que amor sem igual!"}], "reviewed": false}, {"number": 121, "title": "Ecos de Louvor", "page": 62, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Aquele que, de amor por nós,\nÀ morte se entregou\nE, pela mão tomando-nos,\nDo mal nos libertou;\nQue nos levou de novo a Deus,\nO Deus de todo o amor,\nA Cristo soem, pelos céus,\nOs ecos de louvor."}, {"label": "Estrofe 2", "text": "Louvado seja quem nos quis\nDe Deus aproximar,\nE em reino e sacerdotes seus\nCom sangue consagrar.\nLouvado seja quem o dom\nDo Espírito nos deu;\nLouvado seja, pois que abriu\nA entrada para o céu."}, {"label": "Estrofe 3", "text": "Aos teus ouvidos, santo Pai,\nEleve-se o louvor,\nQue destes fracos lábios sai,\nA Cristo, Salvador,\nPois muito nos apraz saber\nQue a Ti, no santo lar,\nLouvor a Cristo agrada ouvir\nNa terra celebrar."}], "reviewed": false}, {"number": 122, "title": "Motivos de Louvor", "page": 63, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, vinde ouvir, enquanto\nDe Cristo eu vou cantar,\nMeu Salvador bendito,\nPois veio-me salvar!\nCordeiro imaculado,\nMinha alma resgatou,\nE com seu próprio sangue\nMeu coração lavou."}, {"label": "Estrofe 2", "text": "Quando a seus pés sentado,\nEu, grato, cantarei\nOs tão gloriosos feitos\nDo meu Senhor e Rei.\nSim, mesmo quando os males\nMe queiram submergir,\nEu cantarei de Cristo,\nQue os pode destruir."}, {"label": "Estrofe 3", "text": "Seguindo na vereda\nQue para o céu conduz,\nEu cantarei de Cristo,\nA minha vida e luz!\nQuando eu me achar sem males\nNaquele santo lar,\nEternamente a Cristo\nLouvor hei de cantar."}], "reviewed": false}, {"number": 123, "title": "Bendito Cordeiro", "page": 63, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Seja bendito o Cordeiro\nQue na cruz por nós padeceu!\nSeja bendito o seu sangue\nQue por nós, pecadores, verteu!\nEis nesse sangue lavados,\nCom roupas que tão alvas são,\nOs pecadores remidos,\nQue perante seu Deus hoje estão!"}, {"label": "Estrofe 2", "text": "Alvo mais que a neve!\nAlvo mais que a neve!\nSim, nesse sangue lavado,\nMais alvo que a neve serei!"}, {"label": "Estrofe 3", "text": "Quão espinhosa a coroa\nQue Jesus por nós suportou!\nOh, quão profundas as chagas\nQue nos provam o quanto Ele amou!\nEis, nessas chagas pureza\nPara o mais torpe pecador,\nPois que mais alvos que a neve\nO teu sangue nos torna, Senhor!"}, {"label": "Estrofe 4", "text": "Se nós aTi confessarmos,\nE seguirmos na tua luz,\nTu não somente perdoas,\nPurificas também, ó Jesus,\nSim, e de todo pecado!\nQue maravilha desse amor!\nPois que mais alvos que a neve\nO teu sangue nos torna, Senhor!"}], "reviewed": false}, {"number": 124, "title": "Cantarei", "page": 64, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cantarei do amor de Cristo,\nNunca houve amor igual;\nDeu a vida pra salvar-nos\nDa condenação fatal."}, {"label": "Estrofe 2", "text": "Cantarei das suas palavras,\nTão repletas de poder,\nQue consolam e me inspiram\nA Jesus obedecer."}, {"label": "Estrofe 3", "text": "Cantarei da imensa graça\nDo seu terno coração;\nPela fé que tenho nEle\nMe garante o meu perdão."}, {"label": "Estrofe 4", "text": "O seu Nome tão glorioso\nCom fervor proclamarei;\nJunto com os seus remidos\nEsse Nome exaltarei."}, {"label": "Estrofe 5", "text": "Cantarei de Jesus Cristo,\nPoderoso Salvador;\nPois transforma, regenera\nO perdido, indigno malfeitor."}], "reviewed": false}, {"number": 125, "title": "Redenção", "page": 65, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Minha alma, canta ao Salvador,\nQue te remiu com tanto amor,\nQue te livrou da escravidão,\nSeu sangue dando em redenção!"}, {"label": "Estrofe 2", "text": "Na redenção firmado estou,\nMeu cativeiro já findou,\nContente, cantarei louvor\nA meu glorioso Redentor."}, {"label": "Estrofe 3", "text": "Longe eu andava do meu Deus,\nSeguindo nos caminhos meus;\nO Salvador me descobriu\nE com seu sangue me remiu."}, {"label": "Estrofe 4", "text": "Feliz momento quando vi,\nNa triste cruz, morrer por mim,\nPra libertar-me do opressor,\nMeu santo e justo Redentor."}, {"label": "Estrofe 5", "text": "Pra minha justificação\nO esforço meu foi todo vão;\nPerante Deus só tem valor\nO sangue do meu Remidor."}, {"label": "Estrofe 6", "text": "Vem, alma opressa, descansar\nNa redenção tão singular;\nJesus garante a salvação,\nSeu sangue vale a redenção."}], "reviewed": false}, {"number": 126, "title": "Louvai", "page": 65, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Louvai, louvai Cristo, o bom Mestre divino!\nPor nós na cruz Ele sofreu, morreu;\nPerdão, perdão hoje aos contritos outorga,\nPois precioso sangue na cruz verteu.\nSim, louvai-O; ei-Lo tão exaltado,\nMediador que nunca nos faltará."}, {"label": "Estrofe 2", "text": "Louvai, louvai, falai da sua grandeza,\nDo perdão, da graça que a todos dá."}, {"label": "Estrofe 3", "text": "Louvai, louvai Cristo, o bom Mestre divino!\nConselhos bons dá Ele ao pecador;\nAnunciai as bênçãos maravilhosas,\nConcedidas por esse Salvador.\nIde, todos, servos de Jesus Cristo,\nEle nunca vos abandonará."}, {"label": "Estrofe 4", "text": "Louvai, louvai Cristo, o bom Mestre divino!\nCantai, cantai, seu grande amor cantai;\nFiéis, cantai de coração, bem unidos,\nSeu poder e glória louvai, louvai!\nQual pastor que cuida do seu rebanho,\nCristo assim os crentes protegerá."}], "reviewed": false}, {"number": 127, "title": "Jesus Bondoso", "page": 66, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus, teu Nome é santo,\nAmável teu querer;\nLouvor real, com puro amor,\nQueremos-Te render.\nPoder e honra e glória a Ti\nNós vimos tributar;\nCom gratidão e devoção\nTeu culto celebrar."}, {"label": "Estrofe 2", "text": "Jesus, teu Nome é santo,\nMerece o nosso amor;\nNos altos céus és nosso Deus,\nO nosso Protetor;\nIncomparável sempre és Tu\nEm tua compaixão,\nPois Tu vieste ao mundo vil\nFazer-Te nosso irmão!"}, {"label": "Estrofe 3", "text": "Jesus, teu Nome é santo,\nAmarga foi a cruz:\nO teu sofrer, o teu penar\nA vida nos produz;\nNa glória já sentado estás,\nAtento à adoração\nQue teus fiéis Te vêm prestar\nCom grato coração."}], "reviewed": false}, {"number": 128, "title": "A Redenção", "page": 67, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eterno Deus, queremos nós\nLouvores a Jesus cantar;\nO seu amor, a sua cruz,\nAjuda-nos a celebrar."}, {"label": "Estrofe 2", "text": "A graça vinda do alto céu,\nQue o Salvador nos concedeu,\nDescanso traz ao coração,\nVigor e paz e salvação."}, {"label": "Estrofe 3", "text": "Da vida és o Criador,\nDe Ti provém inspiração;\nAbrasa-nos com mais ardor\nPra divulgar a redenção."}, {"label": "Estrofe 4", "text": "De Cristo a causa defender,\nO reino seu anunciar,\nA fama dEle promover-\nEis nossa glória singular!"}], "reviewed": false}, {"number": 129, "title": "Bendita Luz", "page": 67, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que bendita, que gloriosa luz!\nÉ mais bela que a do dia!\nIlumina as almas a seguir\nCristo, o Mestre, o eterno Guia."}, {"label": "Estrofe 2", "text": "Sempre canta, alegre, seu louvor,\nQuem possui a luz dos céus;\nGoza afável e celeste paz,\nDom gracioso só de Deus."}, {"label": "Estrofe 3", "text": "Vida nova em santa retidão\nTêm os crentes em Jesus;\nQuem de perto ao Salvador seguir\nDEle alcança graça e luz."}, {"label": "Estrofe 4", "text": "Esperança, vida e salvação\nHás de ter, ó pecador,\nAceitando Cristo, nossa luz,\nEste dom do Deus de amor!"}, {"label": "Estrofe 5", "text": "Luz bendita, luz gloriosa,\nConcedida lá dos altos céus\nSó ao crente em Cristo, o Redentor.\nÓ bendita luz de Deus!"}], "reviewed": false}, {"number": 130, "title": "Beneficência", "page": 68, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se já liberto foste, ó pecador,\nPor quem morreu na negra cruz,\nMostra por frutos santos, em amor,\nQue pertences a Jesus."}, {"label": "Estrofe 2", "text": "Quem poderá gozar o seu favor\nE seguidor de Cristo ser,\nSe, desumano, deixa, sem horror,\nSeu irmão a perecer?"}, {"label": "Estrofe 3", "text": "Ter fé que possa montes transportar\nÉ grande dom que vem dos céus;\nMas dos enfermos dores mitigar\nÉ supremo dom de Deus."}, {"label": "Estrofe 4", "text": "Todos tenhamos gozo do dulçor\nDe praticar nosso dever;\nOuçam de longe as gentes seu louvor,\nEscutando assim dizer:"}, {"label": "Estrofe 5", "text": "Vinde, cristãos, louvar;\nVinde, cristãos, cantar\nA Jesus, do mundo grande Redentor.\nVinde render louvor,\nPelo seu grande amor.\nA Jesus, o Redentor."}], "reviewed": false}, {"number": 131, "title": "Bendize", "page": 68, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Bendize, ó tu, meu coração,\nBendize ao Salvador,\nE tudo quanto houver em mim,\nConsagra-Lhe louvor. (bis)"}, {"label": "Estrofe 2", "text": "Bendize, ó tu, meu coração,\nBendize ao Salvador;\nNão fiques esquecido, pois,\nDo seu divino amor. (bis)"}, {"label": "Estrofe 3", "text": "Ele os delitos com amor\nE graça perdoou,\nE com divina compaixão\nJesus te aliviou. (bis)"}, {"label": "Estrofe 4", "text": "O teu desejo satisfaz\nCom verdadeiros bens;\nA vida renovada, assim,\nTu, como as águas, tens. (bis)"}], "reviewed": false}, {"number": 132, "title": "Ebenézer", "page": 69, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Fonte Tu de toda bênção,\nVem o canto me inspirar;\nDons de Deus, que nunca cessam,\nQuero em alto som louvar.\nOh, ensina o novo canto\nDos remidos lá dos céus\nAo teu servo e ao povo santo,\nPra louvarmos-Te, bom Deus!"}, {"label": "Estrofe 2", "text": "Cá meu \"Ebenézer\" ergo,\nPois Jesus me socorreu;\nE, por sua graça, espero\nTransportar-me para o céu.\nEu, perdido, procurou-me,\nLonge do meu Deus, sem luz;\nMaculado e vil, lavou-me\nCom seu sangue o bom Jesus."}, {"label": "Estrofe 3", "text": "Devedor à tua graça\nCada dia e hora sou;\nTeu desvelo sempre faça\nCom que eu ame a Ti, Senhor.\nEis minha alma vacilante:\nToma-a, prende-a com amor,\nPara que ela, a todo instante,\nGlorifique a ti, Senhor."}], "reviewed": false}, {"number": 133, "title": "Exultação", "page": 69, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tributai, ó vós, remidos,\nGratos hinos a Jesus;\nTendes uma herança boa,\nAbrigada em santa luz!\nPois cantai com alegria,\nQue descanso encontrareis;\nE no derradeiro dia\nA Jesus encontrareis."}, {"label": "Estrofe 2", "text": "Nesta vida achais tristezas,\nMorte, dor, separação;\nAchareis no céu riquezas\nQue jamais se acabarão.\nNa cidade mui gloriosa\nReina Cristo com fulgor;\nNão há pranto, nem pecado,\nNa presença do Senhor."}, {"label": "Estrofe 3", "text": "Para as bodas do Cordeiro,\nÓ remidos, entrareis;\nE, de novo, no seu reino,\nVós do cálix bebereis.\nExultai, sim, alegrai-vos,\nQue vereis o bom Jesus!\nLouvareis eternamente\nAo Cordeiro em santa luz!"}], "reviewed": false}, {"number": 134, "title": "Reino Universal", "page": 70, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó línguas, povos e nações,\nLouvor a Cristo celebrai;\nEm alta voz, ó corações,\nO Nome de Jesus cantai!\nMisericórdia divinal,\nJustiça eterna, eterno amor,\nDe litoral a litoral\nApregoai com todo ardor."}, {"label": "Estrofe 2", "text": "Com reverência, com fervor,\nO incenso do louvor levai;\nSinceros, gratos ao Senhor,\nOh, vinde, alegres, e exultai!\nCom todo ardor, oh, exaltai!\nA Cristo, autor da redenção;\nEm toda língua proclamai\nQue reino dEle os povos são."}], "reviewed": false}, {"number": 135, "title": "Louvor", "page": 70, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Louvamos-Te, ó Deus,\nPelo dom de Jesus,\nQue por nós pecadores\nFoi morto na cruz.\nLouvamos-Te, ó Deus,\nE ao teu Filho de amor,\nQue foi morto, mas vive,\nSupremo Senhor."}, {"label": "Estrofe 2", "text": "Louvamos-Te, ó Deus,\nPelo Espírito, luz\nQue nos tira das trevas\nE a Cristo conduz."}, {"label": "Estrofe 3", "text": "Oh, vem nos encher\nDe celeste fervor,\nE fazer-nos fruir\nTeu afável amor!"}, {"label": "Estrofe 4", "text": "Aleluia, toda glória\nTe rendemos, sem fim;\nAleluia, tua graça\nImploramos. Amém!"}], "reviewed": false}, {"number": 136, "title": "Estudo Bíblico", "page": 71, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis Samuel ouviu\nPalavras de favor,\nE muito se admirou,\nOuvindo o Criador!\nQue dita, se Jesus assim\nViesse me ensinar a mim!"}, {"label": "Estrofe 2", "text": "Não poderia estar\nCom falta de atenção,\nPor medo de pecar\nDe língua ou coração;\nMas sempre havia de escutar,\nOuvindo o grande Deus falar."}, {"label": "Estrofe 3", "text": "Pois na divina lei\nEu ouço a voz do Deus,\nO santo, eterno Rei,\nFalando-me dos céus.\nCom reverente amor convém\nSaber o que essa lei contém."}, {"label": "Estrofe 4", "text": "Eu devo, humilde, ouvir\nA amável instrução,\ne ao bom Jesus servir\nDe todo o coração;\nSer servo humilde, mas fiel,\nTal como o infante Samuel.\nSim, Deus agora está\nTão perto, tão real!\nOh, quão feliz será,\nCom alma filial,\nDizer-Lhe, em hino de louvor:\n\"Escuto; fala, pois, Senhor!\""}], "reviewed": false}, {"number": 137, "title": "O Pão da Vida", "page": 72, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Enquanto, ó Salvador, teu livro eu ler,\nMeus olhos vem abrir, pois quero ver\nDa mera letra, além, a Ti, Senhor;\nEu venho a Ti, Jesus, meu Redentor."}, {"label": "Estrofe 2", "text": "À beira-mar, Jesus, partiste o pão,\nSatisfazendo ali a multidão;\nDa vida o pão és Tu; vem, pois, assim,\nSatisfazer, Senhor, a mim, a mim!"}], "reviewed": false}, {"number": 138, "title": "A Lei do Senhor", "page": 72, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sábia, justa, santa e pura\nÉ a lei do meu Senhor,\nQue corrige a vida impura\nDo perdido pecador.\nDo Senhor o ensinamento\nNela tão perfeito está;\nÉ tão cheia de preceitos\ne conselhos santos dá!"}, {"label": "Estrofe 2", "text": "Do Senhor os bons conselhos\nJustos e benignos são;\nNEles vejo, quais espelhos,\nQuanto é mau meu coração.\nMais que o sol, resplandecentes,\nOs preceitos do Senhor\nIluminam nossas mentes\nCom divino resplendor."}], "reviewed": false}, {"number": 139, "title": "Dia do Senhor", "page": 72, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A semana já passou,\nO Senhor guiou-nos bem;\nO seu povo se lembrou\nQue, reunido, bênçãos tem.\nÉ dos sete o dia melhor,\nDe descanso e de louvor."}, {"label": "Estrofe 2", "text": "Vimos Te pedir perdão,\nÓ amado Redentor;\nMostra tua compaixão,\nNossas culpas tira e a dor!\nDá-nos, hoje, a tua paz,\nBênção que nos satisfaz!"}, {"label": "Estrofe 3", "text": "Desejamos Te louvar,\nTua graça aqui sentir;\nNeste culto reforçar\nEsperanças do porvir;\nPaz e glória, lá dos céus,\nManifesta já, ó Deus!"}, {"label": "Estrofe 4", "text": "O evangelho tem poder\nPara o crente consolar,\nPara o vício seu vencer,\nTodo o mal abandonar.\nQue hoje dê a pregação\nGozo e paz ao coração."}], "reviewed": false}, {"number": 140, "title": "Domingo", "page": 73, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Domingo, ó dia de amor,\nTão cheio de prazer!\nAlmejo, ó meu Senhor,\nA graça e teu poder;\nHonrar-Te, sim, glorioso Rei.\nCumprir a tua santa lei."}, {"label": "Estrofe 2", "text": "Encher-me vem, Senhor,\nDe gozo e muita fé\nÓ grande Benfeitor\nConcede-me a mercê\nDe pecadores despertar\nE tua igreja estimular!"}, {"label": "Estrofe 3", "text": "Espírito de luz,\nOh, dá-me o dom do amor,\nQue vejo em meu Jesus,\nO meigo e bom pastor!\nEnsina-me, pois, meu dever;\nDirige todo meu viver."}], "reviewed": false}, {"number": 141, "title": "Descanso Aos Domingos", "page": 74, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Na terra, aos domingos, Jesus, descansamos,\nMas tens lá no céu um descanso melhor;\nSe, aqui reunidos, prazeres gozamos,\nContigo teremos um gozo maior."}, {"label": "Estrofe 2", "text": "Mais paz e alegria no céu gozaremos,\nQue aquelas que temos aqui, com Jesus;\nSem dores, sem prantos, alegres, veremos\nAquele que para a mansão nos conduz."}, {"label": "Estrofe 3", "text": "Sem medo de ataques de vis inimigos,\nE sem os cuidados mundanos daqui,\nSem sombra de noite, sem nuvens de dia,\nContigo seremos ditosos ali."}, {"label": "Estrofe 4", "text": "Jesus, eu bem sei que Tu tens preparado\nA aurora de gozos eternos pra mim;\nExausto, na senda de dor e pecado,\nEu quero descanso Contigo, sem fim."}], "reviewed": false}, {"number": 142, "title": "Pão da Vida", "page": 74, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Pão da vida, pão dos céus,\nPão de Deus é meu Jesus;\nPão que dá ao coração (bis)\nAlegria, paz e luz."}, {"label": "Estrofe 2", "text": "Sangue que Jesus verteu\nÉ divino, é eficaz;\nEste sangue ao coração (bis)\nForça, amor e vida traz."}, {"label": "Estrofe 3", "text": "Vem, Jesus, me abençoar;\nEnche-me de Ti, Senhor,\nPois almejo Te servir\nE Te honrar, meu Salvador. (bis)"}], "reviewed": false}, {"number": 143, "title": "A Ceia do Senhor", "page": 74, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Será possível esquecer\nO teu amor, Senhor?\nA tua graça em conceder\nPerdão ao pecador?"}, {"label": "Estrofe 2", "text": "Será possível esquecer\nO teu sofrer, Senhor?\nA vida que vieste ter,\nVivida em tanta dor?"}, {"label": "Estrofe 3", "text": "Será possível esquecer\nA grande salvação\nQue Tu vieste nos trazer,\nQue muda o coração?"}, {"label": "Estrofe 4", "text": "Nós vamos hoje celebrar,\nEm santa comunhão,\nO teu sofrer, o teu penar,\nSim, nossa redenção."}], "reviewed": false}, {"number": 144, "title": "Vera Páscoa", "page": 75, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó Jesus! Ó vera Páscoa,\nSuspirada dos antigos!\nÓ Cordeiro eterno e meigo,\nDigna-Te assistir aqui!"}, {"label": "Estrofe 2", "text": "Bom Jesus, ó pão divino!\nPela fé Te apropriamos;\nÉs nas almas o alimento\nQue sustenta o nosso amor."}, {"label": "Estrofe 3", "text": "Bom Jesus, ó vinho puro,\nFonte de perene gozo!\nFaze que nossa alma viva\nPara Ti, de Ti, em Ti."}], "reviewed": false}, {"number": 145, "title": "Batismo", "page": 75, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Às águas do Jordão desceu\nJesus, o Redentor,\nO Deus eterno, que morreu\nPor nós em santo amor."}, {"label": "Estrofe 2", "text": "O exemplo seu devemos ter\nPor norma a nos cingir;\nO salvo pelo seu poder\nSeus passos quer seguir."}, {"label": "Estrofe 3", "text": "Por nós morreu Jesus, na cruz,\nE nos remiu do mal;\nAbriu caminho que conduz\nÀ vida divinal."}, {"label": "Estrofe 4", "text": "Morremos ao pecado vil,\nPra nunca mais voltar,\nE os erros deste mundo hostil\nQueremos desprezar."}, {"label": "Estrofe 5", "text": "A vida nova vamos ter,\nAo bem nos dedicar,\nEm santidade e amor viver,\nDo amor de Deus falar."}], "reviewed": false}, {"number": 146, "title": "Alegria Verdadeira", "page": 76, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sei agora o que me alegra,\nSei agora o que me alegra,\nSei agora o que me alegra,\nConfiando no Senhor!"}, {"label": "Estrofe 2", "text": "É Jesus o que me alegra,\nÉ Jesus o que me alegra,\nÉ Jesus o que me alegra,\nConfiando no Senhor!"}], "reviewed": false}, {"number": 147, "title": "Obediência No Batismo", "page": 76, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cercando teu sepulcro,\nEstamos nós, Jesus,\nTeu Nome aqui louvando,\nAlçando tua cruz.\nAlegres Te seguimos,\nNeste ato, em santo amor;\nMister é obedecer-Te\nEm tudo, ó bom Senhor!"}, {"label": "Estrofe 2", "text": "As águas nos encobrem;\nAssim, também, Senhor,\nAs águas Te cobriam\nDe morte e de furor;\nE, como ressurgiste\nPra a vida perenal,\nAssim, Jesus, levanta,\nLevanta-nos do mal."}, {"label": "Estrofe 3", "text": "Sim, Tu ressuscitaste;\nJamais Tu sofrerás;\nMorreste pelo mundo,\nMas sempre viverás;\nA morte já venceste,\nÓ grande Deus, Jesus!\nA vida nova outorgas\nA quem seguir a luz."}, {"label": "Estrofe 4", "text": "Contigo sepultados,\nQueremos nós aqui\nRenunciar o mundo,\nE só viver por Ti;\nRessuscitados vamos,\nJesus, Contigo andar;\nOh, vem, vem ajudar-nos\nA sempre a Ti honrar!"}], "reviewed": false}, {"number": 148, "title": "Hora Bendita", "page": 77, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Bendita a hora de oração,\nPois traz-nos paz ao coração,\nE sobrepuja toda a dor,\nTrazendo auxílio do Senhor.\nEm tempos de perturbação,\nNa dor maior, na tentação,\nProcurarei com mais fervor (bis)\nA comunhão com o Senhor."}, {"label": "Estrofe 2", "text": "Bendita a hora de oração,\nProduto só da devoção,\nQue eleva ao céu o seu odor\nEm doce cheiro a meu Senhor.\nE, finda a hora de aflição,\nOs dias maus, a tentação,\nEntão darei melhor louvor (bis)\nA meu Jesus, a meu Senhor"}, {"label": "Estrofe 3", "text": "Bendita a hora de oração,\nPois liga-nos em comunhão\nE traz-nos fé e mais amor,\nEnchendo o mundo de dulçor.\nDesejo a vida aqui findar\nCom fé, amor, constante orar;\nDepois da morte, do pavor, (bis)\nEntão será, sim, só louvor."}], "reviewed": false}, {"number": 149, "title": "Persistência Em Oração", "page": 77, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis que, ó Pai, prostrados, Te rogamos nós:\nDá-nos a vitória, nesta luta atroz;\nDá-nos fé robusta para resistir -\nÉ o que teus servos vimos Te pedir!\nDá-nos persistência como a de Jacó,\nPra lutar orando, num desejo só,\nSuplicando graça, sem desanimar,\nTé que recebamos teu favor sem par!"}, {"label": "Estrofe 2", "text": "E, se demorares em nos responder,\nFirmes ficaremos, sem desfalecer;\nTu por graça tudo nos darás, Senhor,\nQuando for provada nossa fé e amor!"}, {"label": "Estrofe 3", "text": "De salvar perdidos, pobres socorrer\nE de dar-nos bênçãos tens real prazer.\nQue alcancemos sempre tua compaixão!\nDá-nos fé mais forte, dá-nos tua mão!"}], "reviewed": false}, {"number": 150, "title": "Pai Nosso", "page": 78, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Nosso Pai, que estás nos céus,\nQue és rodeado de esplendor,\nNome teu santificar\nVimos com ardente amor (bis)"}, {"label": "Estrofe 2", "text": "O teu reino venha a nós;\nNele brilha a luz sem véu;\nSeja feito o teu querer\nTanto aqui como é no céu (bis)"}, {"label": "Estrofe 3", "text": "Cada dia o nosso pão,\nQue a nós todos dá vigor,\nDá-nos hoje, nosso Deus,\nPelo teu benigno amor. (bis)"}, {"label": "Estrofe 4", "text": "Vem, Senhor, nos perdoar\nComo nós, com todo amor,\nDesejamos desculpar\nNosso devedor maior."}, {"label": "Estrofe 5", "text": "No furor da tentação,\nQue nos pode ser fatal,\nNão nos deixes, pois, cair.\nLivra-nos de todo mal. (bis)"}], "reviewed": false}, {"number": 151, "title": "Comunhão", "page": 78, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quão preciosas são as horas\nNa presença de Jesus,\nComunhão mui deliciosa\nDe minha alma com a luz!\nOs cuidados deste mundo\nNão me poderão mover,\nPois é Ele meu abrigo\nQuando o tentador vier (bis)"}, {"label": "Estrofe 2", "text": "Ao sentir-me rodeado\nDe cuidados terreais,\nIrritado, enfraquecido,\nEm hesitações fatais,\nA Jesus eu me dirijo,\nNesses tempos de aflição;\nAs palavras que Ele fala\nTrazem-me consolação. (bis)"}, {"label": "Estrofe 3", "text": "Se confesso meus temores,\ntoda a minha imperfeição,\nEle escuta com paciência\nEssa triste confissão;\nCom ternura repreende\nO pecado e todo o mal;\nEle é sempre meu amigo,\nO melhor e mais leal. (bis)"}, {"label": "Estrofe 4", "text": "Se quereis saber quão doce\nÉ com Deus ter comunhão,\nPodereis, então, prová-lo,\nE tereis compensação.\nProcurai estar sozinhos\nEm conversa com Jesus,\nE tereis, na vossa vida,\nPaz perfeita, graça e luz."}], "reviewed": false}, {"number": 152, "title": "Pastor Divino", "page": 79, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ouve-nos, Pastor divino,\nNós, que neste bom lugar,\nTeu rebanho consagrado,\nDesejamos-Te adorar.\nCristo amado, Cristo amado,\nVem teu povo abençoar. (bis)"}, {"label": "Estrofe 2", "text": "Ao perdido no pecado\nSeu perigo faze ver;\nChama os pobres enganados,\nFaze-os tua voz ouvir;\nAos enfermos, aos enfermos,\nMestre, digna-Te acudir. (bis)"}, {"label": "Estrofe 3", "text": "Traze o pobre desgarrado\nAo aprisco teu, Senhor;\nToma o tenro cordeirinho\nNo regaço teu, Pastor;\nDá-lhe os pastos, dá-lhe os pastos\nDe celeste doce amor. (bis)"}, {"label": "Estrofe 4", "text": "Ó Jesus, escuta o rogo,\nNossa humilde petição;\nVem encher o teu rebanho\nDe sincera devoção;\nCantaremos, cantaremos,\nTua afável proteção. (bis)"}], "reviewed": false}, {"number": 153, "title": "Perdão", "page": 80, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se aqui, Senhor, bem poucos\nTe vêm cantar louvor,\nE aos vis prazeres loucos\nPreferem teu amor,\nO que impossível seja\nA Ti, meu Deus, não há:\nConquiste a tua igreja\nAo meu país, Jeová!"}, {"label": "Estrofe 2", "text": "Jesus, ao Povo inspira,\nTu, que és verdade e luz;\nQuebranta-lhe a mentira,\nDas trevas o conduz.\nDa cega idolatria,\nOh, salva-o, meu Senhor!\nTransforma em claro dia\nA noite de temor."}, {"label": "Estrofe 3", "text": "Senhor, Tu dás sustento\nAo mundo, com poder,\nE dás-lhes mandamento\nPra Te conhecer.\nPorém aos que rejeitam\nA salvação e a cruz,\nE a graça não aceitam,\nOh, dá perdão, Jesus!"}], "reviewed": false}, {"number": 154, "title": "Firme Nas Promessas", "page": 80, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Firme nas promessas do meu Salvador,\nCantarei louvores ao meu Criador.\nFico, pelos séculos do seu amor,\nFirme nas promessas de Jesus."}, {"label": "Estrofe 2", "text": "Firme, firme,\nFirme nas promessas de Jesus, meu Mestre.\nFirme, firme,\nSim firme nas promessas de Jesus."}, {"label": "Estrofe 3", "text": "Firme nas promessas, sempre vejo assim\nPurificação no sangue para mim;\nPlena liberdade gozarei, sem fim,\nFirme nas promessas de Jesus."}, {"label": "Estrofe 4", "text": "Firme nas promessas do Senhor Jesus,\nEm amor ligado com a sua cruz,\nCada dia mais alegro-me na luz,\nFirme nas promessas de Jesus."}], "reviewed": false}, {"number": 155, "title": "O Grande Amigo", "page": 81, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Em Jesus amigo temos,\nMais chegado que um irmão;\nEle manda que levemos\nTudo a Deus em oração!\nOh, que paz perdemos sempre,\nOh, que dor no coração,\nSó porque nós não levamos\nTudo a Deus em oração!"}, {"label": "Estrofe 2", "text": "Temos lidas e pesares\nE na vida tentação;\nNão ficamos sem conforto,\nIndo a Cristo em oração.\nHaverá um outro amigo\nDe tão grande compaixão?\nOs contritos Jesus Cristo\nSempre atende em oração."}, {"label": "Estrofe 3", "text": "E se nós desfalecemos,\nCristo estende-nos a mão,\nPois é sempre a nossa força\nE refúgio em oração.\nSe este mundo em oração.\nSe este mundo nos depreza,\nCristo é nosso em oração;\nEm seus braços nos acolhe\nE nos dá consolação."}], "reviewed": false}, {"number": 156, "title": "Orando Sempre", "page": 81, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó Deus bendito, atende o nosso rogo\nE dá-nos graça e vida de poder;\nNa tentação, que inflama como fogo,\nSó Tu outorgas força de vencer.\nNossa oração responde, ó Pai de amor,\nE, neste mundo, dá-nos teu favor! (bis)"}, {"label": "Estrofe 2", "text": "Perdoa as nossas culpas e pecados,\nQue muitos são, pois débeis somos nós;\nDe Ti, às vezes, vamos afastados,\nRebeldes, não ouvindo tua voz.\nA Ti clamamos, certos do perdão;\nA arrependidos, mostra compaixão! (bis)"}, {"label": "Estrofe 3", "text": "Que privilégio santo e doce temos\nDe ter a paz de Cristo, o Salvador;\nE, em seu bendito Nome, a Deus louvemos,\nAlegres, fortes, cheios de fervor!\nOh, que prazer glorioso, a Deus orar,\nPois é queimar incenso sobre o altar! (bis)"}, {"label": "Estrofe 4", "text": "Orai, nos diz Jesus, teu Filho amado;\nSim, tudo a Ti levamos na oração;\nAqui estamos firmes ao mandado,\nCom fé fazendo a nossa petição!\nOh, vem, Senhor, agora transmitir\nPoder e graça, vem nos assistir! (bis)"}], "reviewed": false}, {"number": 157, "title": "Vivifica-nos, Senhor", "page": 82, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Manda, oh, manda as ricas chuvas,\nTua bênção, Salvador!\nImploramos, esperamos,\nVivifica-nos, Senhor!"}], "reviewed": false}, {"number": 158, "title": "Em Oração", "page": 82, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Nosso Deus e Pai bondoso,\nOuve a nossa petição,\nQue com verdadeiro gozo\nE em humilde adoração\nTe fazemos, neste ansioso\nSuplicar do coração;\nLivra-nos, ó Pai bondoso,\nEm temível tentação."}, {"label": "Estrofe 2", "text": "Ouve, ó Deus, a nossa prece,\nFeita em Nome de Jesus;\nTeu amor nos enaltece,\nDá-nos fé, vigor e luz."}, {"label": "Estrofe 3", "text": "Hoje temos este ensejo\nDe pedir a Ti, Senhor,\nQue nos guardes no desejo\nDe servir ao Salvador,\nNosso Mestre Benfazejo,\nQue nos livra, com amor,\nDo maligno e vil cortejo\nDo infernal enganador."}, {"label": "Estrofe 4", "text": "Livra-nos, Senhor, de tudo\nQue perturba a nossa paz\ne reveste-nos do escudo\nDe uma fé real, veraz,\nPara, em todo transe agudo,\nDerrotarmos Satanás,\nPois da tua lei o estudo\nForças novas sempre traz."}], "reviewed": false}, {"number": 159, "title": "Minha Oração", "page": 83, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Dirijo a Ti, Jesus, minha oração,\nA Ti que tudo vês no coração.\nEu venho Te adorar, tua graça suplicar;\nOh, vem me abençoar; vem já, meu Deus!"}, {"label": "Estrofe 2", "text": "Dirijo a Ti, Jesus, minha oração;\nDo mal que pratiquei, a confissão.\nSê Tu, ó meu Senhor, propício ao pecador;\nConcede, em teu amor, pleno perdão!"}, {"label": "Estrofe 3", "text": "Dirijo a Ti, Jesus, minha oração,\nA Ti que amparo és em aflição;\nOh, vem me consolar, minha alma confortar,\nPra nunca me afastar de Ti, Senhor!"}, {"label": "Estrofe 4", "text": "Escuta, meu Jesus, esta oração,\nQue humilde faço a Ti com gratidão.\nTu és meu Mediador, meu Rei e Salvador;\nPossa eu em teu amor sempre viver!"}], "reviewed": false}, {"number": 160, "title": "A Fé Contemplada", "page": 83, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Deus promete grandes coisas conceder\nA qualquer que peça, crendo que há de obter\nA resposta, sem na fé enfraquecer.\nSua fé Jesus contemplará."}, {"label": "Estrofe 2", "text": "Sua fé Jesus contemplará;\nSim, o que Jesus promete, dá.\nEle vê o coração\nE responde a petição;\nSua fé Jesus contemplará."}, {"label": "Estrofe 3", "text": "Deus tem prometido a quem não duvidar\nDar-lhe tudo quanto a Ele suplicar;\nEle o prometeu e não irá negar!\nSua fé Jesus contemplará."}, {"label": "Estrofe 4", "text": "Deus já grandes maravilhas operou\nPor alguém que, firme, nEle confiou,\nE que da promessa em nada duvidou!\nJesus Cristo a fé contemplará."}, {"label": "Estrofe 5", "text": "Sim, creiamos no que Deus nos prometeu,\nPois jamais desonrará o Nome seu;\nEle cumprirá promessas que nos deu!\nJesus Cristo a fé contemplará."}], "reviewed": false}, {"number": 161, "title": "Poder Espiritual", "page": 84, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Senhor Jesus, oh, vem me conceder\nA plenitude do Consolador;\nDos altos céus me outorga teu poder,\nPoder do Espírito renovador."}, {"label": "Estrofe 2", "text": "Senhor, aviva minha tênue fé;\nAteia em mim o ardor celestial;\nO coração meu guia por mercê,\nExtirpa, expulsa tudo o que é carnal."}, {"label": "Estrofe 3", "text": "Vem Tu fazer em mim habitação,\nEm templo teu transforma-me, Senhor;\nAqui me entrego em tua santa mão, (CORO)\nA teu Espírito renovador."}, {"label": "Estrofe 4", "text": "Outorga força pra testemunhar\nNo meu viver, falar e proceder;\nCorreta vida, santa, modelar,\nTambém repleta de fervor, poder."}], "reviewed": false}, {"number": 162, "title": "Vigiar e Orar", "page": 84, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Bem de manhã, embora o céu sereno\nPareça um dia calmo anunciar,\nVigia e ora; o coração pequeno\num temporal pode abrigar."}, {"label": "Estrofe 2", "text": "Bem de manhã, e sem cessar,\nVigiar, sim, e orar!"}, {"label": "Estrofe 3", "text": "Ao meio-dia, e quando os sons da terra\nAbafam mais de Deus a voz de amor,\nRecorre à oração, evita a guerra\nE goza paz com o Senhor."}, {"label": "Estrofe 4", "text": "Do dia ao fim, após os teus lidares,\nRelembra as bênçãos do celeste amor,\nE conta a Deus prazeres e pesares,\nDeixando em suas mãos a dor."}, {"label": "Estrofe 5", "text": "E sem cessar, vigia a cada instante,\nQue o inimigo ataca sem parar;\nSó com Jesus em comunhão constante\nÉ que o fiel vai triunfar."}], "reviewed": false}, {"number": 163, "title": "Desejos", "page": 85, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu conhecer desejo\nO amor do meu Jesus,\nA glória sempiterna\nDo reino do meu Deus.\nEu aprender desejo\nA santa e boa lei,\nCumprir o seu mandato,\nCom toda a sua grei."}, {"label": "Estrofe 2", "text": "Reproduzir almejo\nA vida de Jesus;\nSer manso, ser humilde,\nTambém servir a Deus;\nEu aprender almejo\nCom Jesus Cristo a orar,\nSozinho na montanha\nCom o Senhor falar."}, {"label": "Estrofe 3", "text": "Amar eternamente\nDesejo a Ti, Jesus;\nPois Tu por mim sofreste\nA maldição da cruz.\nÓ Salvador, concede\nQue alcance teu amor;\nA mim, ovelha tua,\nContempla com favor!"}], "reviewed": false}, {"number": 164, "title": "Revivificação", "page": 86, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tu, que sobre a amarga cruz\nRevelaste teu amor,\nTu, que vives, ó Jesus,\nVivifica-nos, Senhor!"}, {"label": "Estrofe 2", "text": "Eis o mundo tentador\nProcurando nos trair!\nSem teu fogo abrasador\nPresto estamos a cair."}, {"label": "Estrofe 3", "text": "Quantos que corriam bem\nJá não mais Contigo vão!\nOutros seguem, mas também\nfrios, sem amor estão."}, {"label": "Estrofe 4", "text": "Vem agora consumir\nTudo quanto, ó Salvador,\nQuer, altivo, resistir\nAo teu brando e doce amor!"}, {"label": "Estrofe 5", "text": "Vem, oh, vem, Jesus, Senhor,\nNossas almas despertar!\nCom teu puro e santo amor,\nVem, oh, vem nos inflamar,\nOh, vem, oh,vem\nNossas almas inflamar!"}], "reviewed": false}, {"number": 165, "title": "Oração", "page": 86, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Pai celeste, Deus bendito,\nManisfesta teu amor!\nA teus pés eis-nos prostrados,\nImplorando teu favor!\nAos que jazem no pecado,\nMostra a luz da salvação.\nVem brilhar em nossas almas,\nTu, ó Sol da retidão!"}, {"label": "Estrofe 2", "text": "Nesta vida tão penosa,\nVem, Senhor, nos consolar;\nAos aflitos e cansados,\nMostra seu amor sem par!\nNas fraquezas dá conforto,\nAumentando nossa fé,\nE firmando, com bondade,\nSobre a rocha nosso pé!"}, {"label": "Estrofe 3", "text": "Nossas culpas e delitos\nTu nos podes perdoar!\nVem guiar-nos no caminho\nQue conduz ao santo lar!\nPor Jesus, teu Filho amado,\nNosso eterno Sumo bem,\nTudo nós Te suplicamos,\nGlória a Ti, Senhor, Amém!"}], "reviewed": false}, {"number": 166, "title": "As Promessas de Deus", "page": 87, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Acaso podíamos nós conseguir\nMaior segurança do que possuir\nAs lindas promessas do nosso bom Deus,\nFirmadas na Bíblia pra todos os seus?"}, {"label": "Estrofe 2", "text": "Oh, nunca temais! Ele assim nos falou;\nSim, todos os dias convosco Eu estou;\nO vosso sustento serei, e deveis\nEm Mim confiar; sempre sede fiéis."}, {"label": "Estrofe 3", "text": "Por dificuldades tereis de passar,\nNenhum embaraço vos deve espantar;\nConvosco Eu estou para vos proteger\nE o mal Eu farei para o bem concorrer."}, {"label": "Estrofe 4", "text": "Sim, a alma que em Cristo se refugiou,\nOh, todos os dias com ela Eu estou!\nPor mais que o inferno a procure perder,\nJamais poderá, pois Eu vou socorrer."}], "reviewed": false}, {"number": 167, "title": "Vem, Inflama", "page": 87, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Meu pecado resgatado\nFoi na cruz por teu amor,\nE da morte, triste sorte,\nMe livraste, Tu, Senhor."}, {"label": "Estrofe 2", "text": "Vem, inflama a viva chama\nEm meu peito, Bem sem fim!\nEu Te adoro, sempre imploro:\nÓ Jesus, habita em mim!"}, {"label": "Estrofe 3", "text": "Se hesitante, vacilante,\nOuço a voz do tentador,\nTu me guias, me auxilias\nE me tornas vencedor."}, {"label": "Estrofe 4", "text": "Redimida, só tem vida\nA minha alma em teu amor;\nCom apreço reconheço\nQuanto devo a Ti, Senhor!"}], "reviewed": false}, {"number": 168, "title": "Chuvas de Bênçãos", "page": 88, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Chuvas de bênçãos teremos,\nÉ a promessa de Deus.\nTempos benditos veremos,\nChuvas de bênçãos dos céus."}, {"label": "Estrofe 2", "text": "Chuvas de bênçãos teremos,\nVida de paz e perdão.\nOs pecadores indignos,\nGraça dos céus obterão."}, {"label": "Estrofe 3", "text": "Chuvas de bênçãos teremos,\nManda-nos já, ó Senhor!\nDá-nos agora o bom fruto\nDesta palavra de amor."}, {"label": "Estrofe 4", "text": "Chuvas de bênçãos teremos,\nChuvas mandadas dos céus,\nBênçãos a todos os crentes,\nBênçãos do nosso bom Deus."}, {"label": "Estrofe 5", "text": "Chuvas de bênçãos,\nChuvas de bênçãos dos céus;\nGotas somente nós temos;\nChuvas rogamos a Deus."}], "reviewed": false}, {"number": 169, "title": "Mais de Cristo", "page": 88, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mais de Cristo eu quero ver,\nMais do seu amor obter,\nMais da sua compaixão,\nMais da sua mansidão."}, {"label": "Estrofe 2", "text": "Mais, mais de Cristo!\nMais, mais de Cristo!\nMais do seu puro e santo amor,\nMais de Ti mesmo, ó Salvador!\nMais de Cristo compreender,\nQuero a Cristo obedecer,\nSempre perto dEle andar,\nSeu amor manisfestar."}], "reviewed": false}, {"number": 170, "title": "Oração de Consagração", "page": 89, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, mais detestável, sim, seja-me o mal!\nMais calma em pesares, mais alto ideal,\nMais fé no meu Mestre, mais consagração,\nMais gozo em servi-Lo, mais grata oração."}, {"label": "Estrofe 2", "text": "Mais justo me faze, mais sábio, Senhor,\nMais firme na causa, com muito fervor,\nMais reto na vida, mais triste ao pecar,\nUm filho submisso, mais pronto em amar."}, {"label": "Estrofe 3", "text": "Mais puro me faze, mais santo em Jesus,\nMais do teu domínio, mais paz nessa cruz,\nMais rica esperança, mais obras aqui,\nDo céu mais ansioso, mais vida por Ti."}], "reviewed": false}, {"number": 171, "title": "Avivamento", "page": 89, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Aviva-nos, Senhor!\nOh, dá-nos teu poder!\nDe santidade, fé e amor\nReveste o nosso ser!"}, {"label": "Estrofe 2", "text": "Aviva-nos, Senhor!\nEis nossa petição.\nAteia o fogo do alto céu\nEm cada coração!"}, {"label": "Estrofe 3", "text": "Desperta-nos, Senhor!\nOh, faze-nos fruir\nAs ricas bênçãos divinais,\nPrimícias do porvir!"}, {"label": "Estrofe 4", "text": "Renova-me, Senhor,\nInspira mais amor,\nMais zelo, graça e abnegação,\nA bem do pecador!"}], "reviewed": false}, {"number": 172, "title": "Cada Dia", "page": 89, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cada dia tinham pão,\nDado pela eterna mão\nDo Sustentador fiel\nDa família de Israel."}, {"label": "Estrofe 2", "text": "Tu, Jesus, também assim,\nPaz e gozo dá-me a mim;\nCada dia em profusão\nEnche Tu meu coração."}, {"label": "Estrofe 3", "text": "Sempre Tu meu guia sê,\nCada dia dá-me fé;\nCada dia, ó bom Senhor,\nTudo supre com amor."}], "reviewed": false}, {"number": 173, "title": "Mais Amor", "page": 90, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó meu Deus, Te peço: Dá-me mais amor,\nPois no teu serviço quero ter fervor!\nEm teu Filho creio, nEle esperarei;\nCumpre o que Te rogo, meu bendito Rei."}, {"label": "Estrofe 2", "text": "Em Jesus confio, pois que me salvou;\nDerramou seu sangue, seu amor mostrou,\nE das densas trevas para a sua luz\nMe tirou, e agora sempre me conduz."}, {"label": "Estrofe 3", "text": "Sempre hei de segui-Lo, sim, de coração,\nPois que me protege sua forte mão;\nEle é poderoso para me guiar\nSempre no caminho em que convém andar."}], "reviewed": false}, {"number": 174, "title": "Faça-se a Luz", "page": 90, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tu que mandaste, ó Deus,\nDando ordem com poder;\n\"Faça-se a luz!\"\nOuve-nos com favor,\nOnde teu sumo amor\nNão brilha com fulgor,\nFaça-se a luz!"}, {"label": "Estrofe 2", "text": "Fonte de luz dos céus,\nTemos em nosso Deus,\nNosso Jesus.\nCegos, há claridão!\nImpios, eis o perdão!\nDentro do coração\nFaça-se a luz!"}, {"label": "Estrofe 3", "text": "Mestre consolador,\nÂnimo abrasador\nEm nós produz.\nPaz, zelo, fé, poder\nSempre ansiamos ter!\nCumpra-se teu prazer:\nFaça-se a luz!"}, {"label": "Estrofe 4", "text": "Nunca tiveste igual,\nÚnico és e imortal!\nDá-nos a luz!\nPai, santo é teu amor;\nÉs eternal Senhor,\nTerno Consolador,\nFaça-se a luz!"}], "reviewed": false}, {"number": 175, "title": "Minha Aspiração", "page": 91, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo, bom Mestre, eis meu querer;\nTua vontade sempre fazer;\nFaze-me forte pra resistir\nDuras fraquezas que possam vir."}, {"label": "Estrofe 2", "text": "Cristo, bom Mestre, eis meu querer;\nMais santidade de vida ter;\nFaze-me firme, Cristo, meu Deus,\nPara não deixar a senda dos céus."}, {"label": "Estrofe 3", "text": "Cristo, bom Mestre, eis meu querer;\nTodas as minhas faltas vencer;\nFaze-me rijo para lutar,\nPara a vitória sempre ganhar."}], "reviewed": false}, {"number": 176, "title": "Tempo de Ser Santo", "page": 91, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tempo de ser santo tu deves tomar,\nViver com teu Mestre, seu livro estudar,\nAndar com seu povo, e aos fracos valer,\nAs bênçãos celestes de Deus sempre obter."}, {"label": "Estrofe 2", "text": "Tempo de ser puro tu deves achar,\nA sós, sempre orando, com Cristo ficar,\nTeus olhos bem fitos em Deus sempre ter,\nNa tua conduta provar seu poder\nTempo de ser forte tu deves buscar,\nO Mestre seguindo por onde guiar;\nNo gozo ou tristeza sempre obedecer,\nDa fonte divina jamais te esquecer."}, {"label": "Estrofe 3", "text": "Tempo de ser útil tu deves guardar,\nMui calmo nas lutas, em Deus confiar;\nSocorre os aflitos, repleto de amor,\nOs passos seguindo do teu Salvador."}], "reviewed": false}, {"number": 177, "title": "Alvorada", "page": 92, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Apenas rompe a aurora,\nEm Ti eu penso, ó Deus,\nE a Ti levanto logo\nOs lassos olhos meus;\nMinha alma tão sequiosa\nPor seu Deus suspirou;\nAté meu ser inteiro\nCom ânsia O desejou."}, {"label": "Estrofe 2", "text": "Em terra mui deserta\nE cheia de aridez,\nEm que não há estrada\nE em que nem água vês,\nA tua fortaleza\nDesejo ver aqui,\nE teu poder e glória,\nComo eu no templo vi."}, {"label": "Estrofe 3", "text": "Tu tens misericórida\nQue excede a tudo que há;\nPor isso a minha boca\nTeu Nome louvará.\nDurante a vida inteira\nTe quero engrandecer,\nE ao céu, para invocar-Te,\nHumildes mãos erguer."}], "reviewed": false}, {"number": 178, "title": "O Culto Findou", "page": 92, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O culto sagrado findou,\nNo dia bendito de Deus:\nNosso último canto soou\nE as preces subiram aos céus.\nDas faltas concede perdão,\nAceita em Jesus o louvor;\nE, com a divina sanção,\nDespede-nos, grande Senhor!"}], "reviewed": false}, {"number": 179, "title": "Fim do Culto", "page": 93, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Teu culto findo aqui,\nDespede-nos, Senhor;\nDirigi-nos, até o fim,\nPor teu excelso amor."}, {"label": "Estrofe 2", "text": "Queremos em amor\nDe teu favor viver.\nDe teu Espírito gozar,\nE a graça receber."}], "reviewed": false}, {"number": 180, "title": "Despedida", "page": 93, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Grande Deus, em paz, agora,\nVem, despede-nos, Senhor;\nCertos de fruir as bênçãos,\nQue provêm do teu amor.\nDá-nos forças, neste mundo de amargor!"}, {"label": "Estrofe 2", "text": "Graças, graças Te rendemos\nPela tua redenção;\nE rogamos, fervorosos,\nTua firme proteção;\nTeu Espírito domine o coração."}], "reviewed": false}, {"number": 181, "title": "Bênção", "page": 93, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A graça de nosso Senhor,\nE o amor de Deus,\nE a comunhão do Espírito Santo,\nConosco sejam. Amém! Amém!"}], "reviewed": false}, {"number": 182, "title": "Despedida do Culto", "page": 93, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Despede-nos, ó bom Jesus,\nNo fim do teu serviço aqui;\nGuiar-nos venha a tua luz,\nPra que sirvamos só a Ti.\nDepede-nos, ó Salvador!\nDespede-nos em teu amor;\nPermite que nós outra vez\nNos ajuntemos, ó Senhor."}, {"label": "Estrofe 2", "text": "Protege-nos, ó bom Jesus,\nE não nos largue a tua mão!\nO teu amor só nos induz\nA Te louvar de coração."}, {"label": "Estrofe 3", "text": "Pai nosso, Tu, que estás nos céus,\nAqui abençoar-nos vem;\nÓ Tu, Espírito de Deus,\nDá-nos inspiração também."}], "reviewed": false}, {"number": 183, "title": "A Luz do Mundo", "page": 94, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Pra todo perdido nas trevas do mal,\nJesus é a luz do mundo!\nDo sol no esplendor não encontra rival;\nJesus é a luz do mundo!"}, {"label": "Estrofe 2", "text": "Vem para a luz, pois brilha por ti;\nDentro do peito, alegre, a senti;\nVendo-a, do mal a Deus eu corri;\nJesus é a luz do mundo!"}, {"label": "Estrofe 3", "text": "Do reino das trevas nós vimos Jesus;\nJesus é a luz do mundo!\nAndamos seguros na trilha da cruz;\nJesus é a luz do mundo!"}, {"label": "Estrofe 4", "text": "Ó cegos, que a Terra do mal habitais,\nJesus é a luz do mundo!\nNa Bíblia se encontra essa luz que buscais;\nJesus é a luz do mundo!"}, {"label": "Estrofe 5", "text": "Do brilho do sol não carecem os céus;\nJesus é a luz do mundo!\nPois brilha o Cordeiro no Templo de Deus;\nJesus é a luz do mundo!"}], "reviewed": false}, {"number": 184, "title": "Há Livre Perdão", "page": 95, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Glória a Jesus, pois há livre perdão!\nVem, pecador, aceitar este dom:\nDe Deus um livre perdão!\nVem, sim, agora em Jesus confiar;\nVida perene vais nEle encontrar,\nE pleno e livre perdão!"}, {"label": "Estrofe 2", "text": "Longe de Cristo só podes sofrer,\nMas nos seus braços há sumo prazer.\nEm Deus há livre perdão!\nTrevas te cercam? Oh, vem para a luz;\nPaz, força e vida terás em Jesus\nE pleno e livre perdão!"}, {"label": "Estrofe 3", "text": "Cristo está pronto pra te perdoar!\nÓ pecador, por que não aceitar?\nEm Deus há livre perdão."}, {"label": "Estrofe 4", "text": "Basta pensar só no seu grande amor,\nNo seu sofrer e na morte de horror,\nPra ver que há livre perdão!\nArrependido, te entrega a Jesus,\nQue te concede perdão pela cruz,\nSim, pleno e livre perdão!"}, {"label": "Estrofe 5", "text": "Sim, há perdão para aquele que crer!\nE mesmo agora tu podes obter\nDe Deus um livre perdão!\nCristo te espera, sim, vem como estás;\nOh, vem agora, pois receberás\nUm pleno elivre perdão!"}], "reviewed": false}, {"number": 185, "title": "Somente Cristo", "page": 95, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Somente Cristo é Salvador,\nNem outro conhecemos;\nMorreu por nós, em santo amor,\nE vida nEle temos."}, {"label": "Estrofe 2", "text": "Os homens santos e fiéis\nNós sempre respeitamos;\nMas a Jesus, o Rei dos reis,\nHumildes adoramos.\nJesus, Jesus é o Salvador,\nE nem há outro Mediador;\nFoi Ele que por nós morreu,\nE vivo está por nós no céu."}, {"label": "Estrofe 3", "text": "A Deus fazemos oração;\nSó Ele quer e pode\nValer-nos na tribulação;\nAos seus, Deus sempre acode."}, {"label": "Estrofe 4", "text": "No santo sangue de Jesus\nConfia todo crente;\nO que Ele fez na dura cruz\nPra sempre é suficiente."}], "reviewed": false}, {"number": 186, "title": "É Jesus Quem Salva", "page": 96, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O chorar não salva!\nMesmo o lagrimar sem fim\nJamais mancha carmesim\nPoderá lavar em mim;\nO chorar não salva!"}, {"label": "Estrofe 2", "text": "Obras não me salvam!\nMeus esforços sem cessar\nNão me podem transformar,\nNem meus males expiar;\nObras não me salvam!"}, {"label": "Estrofe 3", "text": "Foi Jesus que padeceu,\nSobre a cruz por mim morreu;\nPor seu sangue que verteu\nPôde assim salvar-me!"}, {"label": "Estrofe 4", "text": "Orações não salvam!\nApesar do seu fervor,\nPetições não têm valor\nPra salvar o pecador;\nOrações não salvam!"}, {"label": "Estrofe 5", "text": "É Jesus quem salva!\nEle a obra consumou,\nMeus pecados expiou,\nCom seu sangue me lavou;\nÉ Jesus quem salva!"}], "reviewed": false}, {"number": 187, "title": "Teus Pecados", "page": 97, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Pecador, teus pecados\nBrancos, brancos se farão; (bis)\nInda que sejam vermelhos,\nComo lã serão;\nInda que seus pecados\nSejam como a escarlata,\nBrancos, brancos se farão,\nComo lã se tornarão!"}, {"label": "Estrofe 2", "text": "Pecador, Deus te chama:\nOuve já a voz dos céus! (bis)\nEle é tão bom quão amável,\nCompassível é,\nCom ardor te convida,\nCom amor, sim, te abriga!\nChega, pois, ao Salvador;\nOuve já a voz de amor!"}, {"label": "Estrofe 3", "text": "Desfará tuas culpas;\nDelas não se lembra mais! (bis)\n\"Oh, vinde a mim, vós cansados!\"\nDiz Jesus, Senhor.\nMau embora tu sejas,\nMau embora tu sejas\nSeu descanso te dará\nE feliz te tornará!"}], "reviewed": false}, {"number": 188, "title": "O Evangelho", "page": 97, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A nova do evangelho\nJá se fez ouvir aqui;\nBoas-novas tão alegres,\nElas são pra quem ouvir:\nAssim Deus nos amor,\nSim, a cada pecador,\nQuem nos deu seu Filho amado\nPra sofrer a nossa dor."}, {"label": "Estrofe 2", "text": "A nova do evangelho\nDá-nos todos a saber\nQue fartura há para todos,\nSim, pra quem com fé comer:\nDa vida o pão eu sou;\nSatisfeito ficarás;\nTeus pecados e tua alma\nLevarei, e paz terás."}, {"label": "Estrofe 3", "text": "Santa paz e perdão\nSão as novas lá dos céus!\nSanta paz e perdão!\nÉ bendito o nosso Deus!"}, {"label": "Estrofe 4", "text": "A nova do evangelho\nOra vem nos avisar\nDo perigo grande e grave\nPara quem se descuidar.\nSalvai-nos desde já;\nNão vos demoreis, então,\nNão vireis os vossos olhos,\nOh, fugi da perdição!"}, {"label": "Estrofe 5", "text": "A nova do evangelho\nJubiloso som nos é,\nPois o amor de Jesus Cristo\nDá perdão mediante a fé.\nAs novas se vos dão\nQue já veio o Salvador,\nTão bondoso e poderoso,\nQue perdoa ao pecador."}], "reviewed": false}, {"number": 189, "title": "Graça Inefável", "page": 98, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A graça do Senhor meu coração venceu,\nPois, para me salvar, seu Filho amado deu."}, {"label": "Estrofe 2", "text": "Oh, sim, qualquer que em Cristo crer\nPerdão eterno vai obter\nE vida nova receber."}, {"label": "Estrofe 3", "text": "Aquele que pecar, a morte sofrerá;\nQuem aceitar Jesus, a vida alcançará."}, {"label": "Estrofe 4", "text": "Seu sangue derramou a fim de nos salvar,\nE da condenação nos veio assim livrar."}, {"label": "Estrofe 5", "text": "Oh, vinde receber a vida e seu perdão,\nE juntos possuir Jesus e a salvação!"}], "reviewed": false}, {"number": 190, "title": "Para Salvar-te", "page": 98, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Veio Jesus a este mundo vil\nPara buscar-te a ti;\nFoi rejeitado por gente hostil\nPara salvar-te a ti.\nGlórias ali no céu deixou,\nIngratidão no mundo achou,\nTudo ele fez porque te amou,\nPara salvar-te a ti."}, {"label": "Estrofe 2", "text": "O teu castigo Jesus levou\nPara salvar-te a ti;\nTudo na cruz ele consumou\nPara remir-te a ti;\nQuem dentre os homens compreendeu\nTodas as dores que sofreu,\nA condição em que morreu\nPara salvar-te a ti?"}, {"label": "Estrofe 3", "text": "Glória, glória demos ao Salvador!\nGlória, glória, por seu tão grande amor!\nGlória, glória, temos a paz com Deus!\nGlória, glória, vamos cantar nos céus!"}, {"label": "Estrofe 4", "text": "Tudo isto Deus fez em teu favor\nPara salvar-te a ti;\nChama-te agora com terno amor\nPara perdoar-te a ti.\nDeves chegar em contrição,\nTendo certeza do perdão;\nCristo te estende a sua mão\nPara salvar-te a ti."}, {"label": "Estrofe 5", "text": "Oh, que alegria, que gozo e paz\nTer salvação de Deus\nE nova vida que satisfaz\nA alma que busca os céus!\nLivre das culpas do pecar,\nLonge da dor e do chorar,\nTendo certeza e de gozar\nA redenção de Deus!"}], "reviewed": false}, {"number": 191, "title": "Eis a Nova", "page": 99, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, que mensagem cheia\nDa compaixão de Deus,\nA do evangelho santo\nQue nos conduz aos céus!\nIncomparável graça,\nCheia de santo amor,\nQue ao pecador perdido\nTrouxe o bom Salvador!"}, {"label": "Estrofe 2", "text": "Eis a nova:\nQuem em Jesus confia,\nDele há de ter verdadeira luz,\nVida, perdão e alegria!"}, {"label": "Estrofe 3", "text": "Pois o pecado avilta,\nEnche de escuridão\nA alma rebelde e errada\nSob sua maldição!"}, {"label": "Estrofe 4", "text": "Temos na cruz de Cristo\nBênção e salvação;\nPorta da vida aberta,\nÚnica redenção!"}], "reviewed": false}, {"number": 192, "title": "Só Por Jesus", "page": 100, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo veio dos santos céus,\nVeio do mal salvar-nos;\nDado foi, pelo amor de Deus,\nEm nossa redenção.\nPor Jesus somente\nSalvo está o crente."}, {"label": "Estrofe 2", "text": "Oh, que graça nos revelou\nQuando ele veio ao mundo!\nCompaixão sem igual mostrou\nA todo pecador.\nSim, por sua morte\nTemos vera sorte."}, {"label": "Estrofe 3", "text": "Nem as lágrimas, nem a dor\nPodem a paz ganhar-nos.\nNossas obras são sem valor\nPara o perdão comprar.\nSem pagarmos nada,\nVida nos é dada."}, {"label": "Estrofe 4", "text": "Confiados em Cristo, já\nPleno perdão nós temos;\nFez-nos, nosso Pai, Deus Jeová,\nFilhos por adoção!\nSalvos nele estamos,\nGlória a Deus rendamos!\nSó por Jesus, só por Jesus,\nÉ que nós somos salvos. (bis)"}], "reviewed": false}, {"number": 193, "title": "Proclamação", "page": 101, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Proclamai a todo o mundo que Jesus é Rei!\nProclamai! Proclamai!\nProclamai que suave e santa é sua magna lei!\nProclamai! Proclamai!\nProclamai que ele é nosso Salvador Jesus,\nPois sofreu por nós, pregando na sangrenta cruz;\nQue ele ao reino eterno os salvou em amor conduz!\nProclamai! Proclamai!"}, {"label": "Estrofe 2", "text": "Proclamai que reina sempre nosso Salvador!\nProclamai! Proclamai!\nQue por cetro de seu reino tem o santo amor!\nProclamai! Proclamai!\nProclamai aos infelizes que ele vive lá,\nE, aos cansados e contritos, que descanso dá;\nProclamai aos pecadores que ele os salvará!\nProclamai! Proclamai!"}, {"label": "Estrofe 3", "text": "Proclamai que em breve sobre as nuvens descerá!\nProclamai! Proclamai!\nE com todos os seus santos em fulgor virá!\nProclamai! Proclamai!\nE quem sem demora venham todos se render,\nE fiéis e dedicados servos dele ser;\nSim, estejam prontos quando o Rei dos reis vier!\nProclamai! Proclamai!"}], "reviewed": false}, {"number": 194, "title": "A Mensagem Celeste", "page": 101, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A mensagem vem de Deus,\nQue Jesus é Salvador!\nOh, clamai, vós, filhos seus;\nÉ Jesus o Salvador!\nProclamai, com grande ardor,\nQue Deus ama ao pecador,\nQue seu Filho ao mundo deu\nPara ser o Salvador!"}, {"label": "Estrofe 2", "text": "Ó vós, povos, eis o dom:\nÉ Jesus o Salvador!\nPor seu sangue dá perdão!\nÉ Jesus o Salvador!\nIlhas todas, exultai,\nSeu amor considerai;\nE vós, anjos, proclamai\nQue Jesus é Salvador!"}, {"label": "Estrofe 3", "text": "Ó vós, santos, já bradai:\nÉ Jesus o Salvador!\nVós, nações, oh, jubilai!\nÉ Jesus o Salvador!\nSalvação de graça dá.\nHoje a todo pecador.\nGlória! Glória a Deus Jeová,\nPois Jesus é Salvador!"}], "reviewed": false}, {"number": 195, "title": "Vida Por Um Olhar", "page": 102, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Terás vida em olhar pra Jesus, Salvador;\nEle diz: Vida eterna eu te dou;\nPois, então, pecador, considera esse amor;\nVê Jesus que na cruz expirou."}, {"label": "Estrofe 2", "text": "Vê, vê, viverás!\nTerás, vida em olhar pra Jesus, Salvador;\nEle diz: Vida em mim acharás!"}, {"label": "Estrofe 3", "text": "Terás vida em olhar pra Jesus, Salvador;\nSangue seu derramado ele tem;\nPaga está nossa falta; não haja temor;\nPor olhar, pecador, vida vem."}, {"label": "Estrofe 4", "text": "Terás vida em olhar pra Jesus, Salvador;\nNão há choro, remorso, nem dor\nQue consiga remir a qualquer pecador;\nSó o sangue do bom Redentor."}, {"label": "Estrofe 5", "text": "Terás vida em olhar pra Jesus, Salvador;\nEle tudo por ti já sofreu.\nDeus estende o convite ao maior transgressor;\nVê Jesus, que por ti padeceu!"}, {"label": "Estrofe 6", "text": "Terás vida em olhar pra Jesus, Salvador;\nEle diz: Vida eterna eu te dou.\nNunca perecerás, crendo em Cristo, o Senhor;\nSegurança em Jesus gozarás."}], "reviewed": false}, {"number": 196, "title": "Conta-me", "page": 102, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Conta-me a história de Cristo,\nGrava-a no meu coração;\nConta-me a história preciosa,\nPois ele dá salvação.\nConta que os anjos em coro\nDeram louvor a Jeová.\nOh! Glória a Deus nas alturas\nPelo perdão que nos dá! (bis)"}, {"label": "Estrofe 2", "text": "Cristo sofreu no deserto,\nDias amargos passou\nPelo maligno tentado,\nMas em poder triunfou.\nConta dos seus sofrimentos\nQue ele por nós padeceu\nQuando, em terrível angústia,\nLá no calvário morreu! (bis)"}, {"label": "Estrofe 3", "text": "Conta do cálix amargo;\nEle sofreu maldição!\nConta do triste sepulcro,\nConta da ressurreição.\nOh! grande amor indivizível!\nGraça e favor divinal!\nSantos louvores cantemos (bis)\nAo Salvador eternal!"}], "reviewed": false}, {"number": 197, "title": "Inabalável", "page": 103, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A cruz ainda firme está. Aleluia!\nAleluia!\nE para sempre ficará. Aleluia! Aleluia!\nPois o inferno trabalhou,\nSatanás rancor mostrou,\nMas ninguém a derribou!\nAleluia pela cruz!"}, {"label": "Estrofe 2", "text": "Aleluia! Aleluia!\nAleluia por Jesus!\nAleluia! Aleluia!\nQuem triunfa é só Jesus!"}, {"label": "Estrofe 3", "text": "É sempre vencedora a cruz. Aleluia!\nAleluia!\nPois testifica de Jesus. Aleluia! Aleluia!\nSua graça ali brilhou,\nSeu amor se nos mostrou,\nPlena paz se efetuou!\nAleluia pela cruz!\nAli rendeu o Salvador, aleluia, aleluia,\nA vida pelo pecador. Aleluia! Aleluia!\nFoi ali que triunfou,\nSalvação nos outorgou,\nSim, o céu nos conquistou!\nAleluia pela cruz!"}], "reviewed": false}, {"number": 198, "title": "Aleluia", "page": 104, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A mensagem do Senhor; aleluia!\nÉ cheia de perdão e amor!\nCristo salva o pecador; aleluia!\nSalva até por meio de um olhar!"}, {"label": "Estrofe 2", "text": "Vossa culpa já levou; aleluia!\nJesus a satisfez na cruz;\nSua vida já entregou, aleluia!\nPara vos apresentar a Deus."}, {"label": "Estrofe 3", "text": "Oh, olhai, pois, e vivei!\nConfiai só em Jesus!\nEle salva o pecador; aleluia!\nSalva até por meio de um olhar!"}, {"label": "Estrofe 4", "text": "Sua graça nos legou; aleluia!\nEterna vida lá nos céus;\nConfiai só em Jesus; aleluia!\nConvertei-vos hoje mesmo a Deus!"}, {"label": "Estrofe 5", "text": "Aceitai a salvação; aleluia!\nSegui os passos do Senhor;\nProclamai o seu perdão; aleluia!\nExaltai o grande Redentor!"}], "reviewed": false}, {"number": 199, "title": "Cordeiro Divino", "page": 104, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sacrifícios imolados\nSobre o sanguinoso altar\nNão tiravam os pecados;\nNão podiam expiar\nNossas culpas, nossas culpas,\nNem remorsos dissipar."}, {"label": "Estrofe 2", "text": "Temos sangue mui precioso\nDe um divino Remidor;\nEficaz e tão glorioso\nÉ o grande Expiador;\nPurifica, purifica\nO mais ímpio pecador."}, {"label": "Estrofe 3", "text": "Triste, choro o meu pecado;\nDe Jesus me vem perdão;\nNo Cordeiro confiado,\nNão há mais condenação!\nO Cordeiro, o Cordeiro\nDá completa remissão."}, {"label": "Estrofe 4", "text": "Todo o peso do castigo,\nPunição que mereci,\nLá na cruz, supremo Amigo,\nFoi lançada sobre ti!\nVou cantando, vou cantando:\nMinha culpa estava ali."}], "reviewed": false}, {"number": 200, "title": "A Vinda de Jesus", "page": 105, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo, meu Salvador, veio a Belém,\nPara sofrer zombaria e desdém;\nVeio por causa do amor que me tem,\nA procurar-me a mim!"}, {"label": "Estrofe 2", "text": "Cristo, meu Salvador, morto na cruz,\nDeu-me a alegria do reino de luz,\nE no caminho do céu me conduz;\nTudo ele faz por mim!"}, {"label": "Estrofe 3", "text": "Cristo, meu Salvador, chama por ti,\nEle te diz: \"Com amor te remi.\"\nVem, pois Jesus já fez tanto por ti.\nNão te demores mais!"}, {"label": "Estrofe 4", "text": "Cristo, meu Salvador, inda virá\nCom os remidos; que glória será!\nEu face a face verei a Jeová,\nQuando me vier buscar!"}], "reviewed": false}, {"number": 201, "title": "O Novo Nascimento", "page": 105, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Um rico, de noite, chegou a Jesus,\nA fim de saber o caminho da luz;\nO Mestre bem claro lhe fez entender;\nImporta renascer!"}, {"label": "Estrofe 2", "text": "Importa renascer!\nImporta renascer!\nCom voz infalível o disse Jesus:\nImporta renascer!"}, {"label": "Estrofe 3", "text": "Vós, filhos do mundo, escutai ao Senhor,\nQue sempre vos chama com mui terno amor;\nOuvi que o Senhor nunca cessa em dizer:\nImporta renascer!"}, {"label": "Estrofe 4", "text": "Ó vós, que no santo descanso de Deus\nQuereis ter entrada e viver com os seus,\nDeveis à palavra de Cristo atender:\nImporta renascer!"}, {"label": "Estrofe 5", "text": "Se amados no céu desejais encontrar,\nDeveis vosssas culpas a Deus confessar\nE a ordem de Cristo com fé acolher;\nImporta renascer!"}], "reviewed": false}, {"number": 202, "title": "Jesus Tem Poder", "page": 106, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus tem o poder\nDe as culpas perdoar\nA quem, arrependido, a Deus,\nCom fé, se confessar.\nJesus tem o poder -\nOh, graças ao Senhor! -\nDe dar completa absolvição\nAo pobre pecador."}, {"label": "Estrofe 2", "text": "Sim, Cristo tem poder!\nOnipotente é!\nPor esse seu poder\nMerece a nossa fé!\nSim, Cristo tem poder!\nSó nele confiai!\nPerante o seu poder,\nHumildes adorai!"}, {"label": "Estrofe 3", "text": "Jesus tem o poder\nReal de converter\nO mais rebelde pecador,\nTornando-o novo ser.\nJesus tem o poder\nDe sempre nos guardar,\nE assim poder arrebatar!"}, {"label": "Estrofe 4", "text": "Jesus tem o poder\nDe dar-nos proteção!\nA atribulados corações\nDará consolação!\nJesus tem o poder\nDe, quando o fim chegar,\nCercar-nos de alegria e paz\nE à glória nos levar!"}], "reviewed": false}, {"number": 203, "title": "Olha para Cristo", "page": 107, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Olha para Cristo, olha, pecador,\nPois por ti tragou o cálix de amargor;\nToda a tua culpa Cristo já pagou,\nTodo o teu pecado sobre si tomou."}, {"label": "Estrofe 2", "text": "Olha para Cristo, que por ti morreu;\nPelos teus pecados ele padeceu.\nEle dor amarga lá na cruz sentiu,\nPor seu sangue puro Cristo te remiu."}, {"label": "Estrofe 3", "text": "O poder das trevas ele conquistou,\nO terror da morte já aniquilou;\nEis o véu rasgado, eis do céu a luz,\nTudo está cumprido; olha pra Jesus."}], "reviewed": false}, {"number": 204, "title": "Reconciliai-vos", "page": 107, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis a ordem dos céus, do nosso Deus e Pai:\nTodo o pecador venha ao Salvador,\nPois não não quer que ninguém se perca! Oh, escutai!"}, {"label": "Estrofe 2", "text": "Eis o mandado que vem dos céus\nAos pecadores perdidos, réus:\nArrependei-vos já!\nReconciliai-vos já\nCom o nosso Deus e Pai! (bis)"}, {"label": "Estrofe 3", "text": "Vinde a Deus sem receio! Cristo já remiu\nTodo pecador por seu grande amor!\nDá perdão aos que crêem; pois ele o garantiu!\nReconciliai-vos já com Deus!"}, {"label": "Estrofe 4", "text": "Deus não dá salvação àqueles que não crêem!\nTodo pecador tem o seu favor\nQuando humilde e contrito a Jesus Cristo vem!\nReconciliai-vos já com Deus!"}], "reviewed": false}, {"number": 205, "title": "Jesus Crucificado", "page": 108, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó minha alma, sem demora\nErgue-te para entoar\nOs louvores do teu Cristo\nE seu nome celebrar!\nPra remir-te,\nSua vida te quis dar! (bis)"}, {"label": "Estrofe 2", "text": "Minha condição tão triste\nConheceu meu Salvador,\nE dos céus desceu à terra\nPara ser meu Redentor.\nOh, quão grande\nÉ o amor do meu Senhor! (bis)"}, {"label": "Estrofe 3", "text": "Condenado justamente,\nQue podia eu fazer\nPra livrar-me dessa pena,\nO perdão pra merecer?\nO seu sangue\nQuis Jesus por mim verter! (bis)"}, {"label": "Estrofe 4", "text": "De meus crimes carregando,\nLá na cruz, em meu lugar,\nFoi Jesus cruscificado\nA minha alma pra salvar!\nVinde todos (bis)\nJá comigo adorar!"}], "reviewed": false}, {"number": 206, "title": "Promessa Gloriosa", "page": 108, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vitória como a de Jesus\nNinguém jamais ouviu;\nMorrendo numa ignóbil cruz\nA paz nos conseguiu!"}, {"label": "Estrofe 2", "text": "Que bênção para o pecador\nPoder achar perdão,\nGozar o dom consolador\nDa eterna salvação!"}, {"label": "Estrofe 3", "text": "Oh, vinde todos de graça obter\nSalvação e paz, trazidas por Jesus;\nOh, vinde já dele receber\nO dom que pela fé nos vem da cruz!"}, {"label": "Estrofe 4", "text": "Ó Deus, precioso é teu favor\nQue por Jesus tu dás\nAo mais indigno pecador\nQue em ti procura paz!"}, {"label": "Estrofe 5", "text": "Ó tu que estás na escuridão,\nSem Deus, sem fé, sem luz,\nEscuta a voz de salvação,\nE rende-te a Jesus!"}], "reviewed": false}, {"number": 207, "title": "Mensagem Real", "page": 109, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sou forasteiro aqui, em terra estranha estou;\nDo reino lá do céu embaixador eu sou.\nMeu Rei e Salvador vos manda em seu amor\nAs boas-novas de perdão."}, {"label": "Estrofe 2", "text": "Eis a mensagem que me deu\nAquele que por nós morreu;\n\"Reconciliai-vos já\", é ordem que ele dá;\n\"Reconciliai-vos já com Deus\"!"}, {"label": "Estrofe 3", "text": "É ordem do meu Rei que todo pecador\nArrependido já confesse ao Salvador\nTodo pecado seu, pois ele prometeu\nDar o perdão por seu amor."}, {"label": "Estrofe 4", "text": "No meu eterno lar não há perturbação;\nEterno gozo e paz os salvos fruirão!\nE quem obedecer a Cristo vai viver\nNo reino eterno do meu Rei."}], "reviewed": false}, {"number": 208, "title": "Justificação", "page": 109, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Das águas da vida quem queira beber,\nBem arrependido no Salvador crer,\nDa pena da morte liberto será,\nPois Cristo a seu povo do mal salvará."}, {"label": "Estrofe 2", "text": "O dom é de graça, e Cristo é capaz\nDe satisfazer com dulcíssima paz\nAo homem que aceite seu pleno perdão,\nSem outra esperança de obter salvação."}, {"label": "Estrofe 3", "text": "Por meio do sangue que Cristo verteu\nFicou consumado o resgate do réu;\nE o Pai lhe oferece, por seu terno amor,\nLugar em seu lar, com o bom Salvador."}, {"label": "Estrofe 4", "text": "É Deus quem afirma que dá salvação;\nDe todo pecado concede perdão;\nE então vos convida a que, assim como estais,\nVós sem mais receios a Cristo venhais."}], "reviewed": false}, {"number": 209, "title": "Venham Escutar", "page": 110, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Desprezado foi o verbo\nPor aqueles que criou;\nNão obstante, as nossas dores\nEle foi quem as levou;\nFoi por esses sofrimentos\nQue alcançamos nós a paz;\nSua morte no Calvário\nPara nós a vida traz."}, {"label": "Estrofe 2", "text": "Ele foi desamparado\nPara termos proteção,\nE por nós se fez pecado\nPara dar-nos retidão;\nSim, do seu querido Filho\nDeus o rosto desviou,\nNessa ocasião solene\nQuando Cristo nos salvou."}, {"label": "Estrofe 3", "text": "Para nós tem começado\nNovo, refulgente dia;\nEm lugar de triste choro,\nDesfrutamos alegria;\nE provamos hoje as bênçãos\nDesse lar além, nos céus,\nOnde moraremos juntos\nCom Jesus e nosso Deus."}, {"label": "Estrofe 4", "text": "Provações de toda sorte\nNão nos devem assustar.\nNem apertos, nem perigos\nNossa fé prejudicar;\nPois que Deus tem prometido\nO seu povo proteger;\nPor aquele que nos ama\nSempre havemos de vencer."}, {"label": "Estrofe 5", "text": "Venham todos escutar:\nSalvação Deus quer-vos dar,\nEntregando o Filho amado,\nDeus mostrou-nos seu amor,\nSeu propósito benigno\nDe salvar o pecador."}], "reviewed": false}, {"number": 210, "title": "Cristo Te Chama", "page": 111, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo te chama com mui terno amor;\nÓ pecador, vem atender!\nDele não fujas com fútil temor;\nVem a Jesus te render!"}, {"label": "Estrofe 2", "text": "Cristo te chama pra vir descansar;\nÓ pecador, vem atender!\nTeu grande peso te quer minorar;\nVem a Jesus te render!"}, {"label": "Estrofe 3", "text": "Cristo deseja, pois, te perdoar;\nÓ pecador, vem atender!\nTudo ele fez para te resgatar;\nVem a Jesus te render!"}, {"label": "Estrofe 4", "text": "Cristo de novo se põe a chamar;\nÓ pecador, vem atender!\nCorre depressa, sim, vem te entregar;\nNada te deve deter!"}, {"label": "Estrofe 5", "text": "Ó pecador, eis o Senhor!\nVem, atende com fé a chamada de amor!"}], "reviewed": false}, {"number": 211, "title": "Vem, Pecador", "page": 111, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis, Cristo te convida: vem, pecador!\nPois dá eterna vida; vem, pecador!\nTudo é tão favorável; vem, pecador!\nCristo é tão admirável; vem, pecador!"}, {"label": "Estrofe 2", "text": "Pois hoje tens o ensejo; vem, pecador!\nE tu não tens desejo? Vem, pecador!\nSe tu não mais duvidas, vem, pecador!\nSim, urge que decidas! Vem, pecador!"}], "reviewed": false}, {"number": 212, "title": "Oh, Vinde Já", "page": 112, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus vos diz: Oh, vinde já\nA mim e descansai!\nEu amo-vos, eu sou Jesus;\nNo Mestre confiai! (3x)"}, {"label": "Estrofe 2", "text": "Quem ouve, diga: Vinde já\nA Cristo confessar!\nOuvi a voz de salvação\nE vinde já gozar! (3x)"}, {"label": "Estrofe 3", "text": "Ó pecadores, vinde já\nÀ fonte de dulçor!\nOh, vinde já pra desfrutar\nO dom do Redentor! (3x)"}, {"label": "Estrofe 4", "text": "O que quiser já pode vir\nA Deus, o Salvador;\nPois ele abriu caminho ao céu,\nPerdão ao pecador! (3x)"}], "reviewed": false}, {"number": 213, "title": "Quem Quiser", "page": 112, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quem ouvir as novas, vá proclamar:\nSalvação de graça vinde desfrutar!\nOh, que o mundo inteiro ouça anunciar:\nTodo que quiser, é vir!"}, {"label": "Estrofe 2", "text": "Todo que quiser, venha receber!\nPossam todos essa boa-nova ouvir!\nÉ o Pai celeste que convida assim:\nTodo que quiser, é vir!"}, {"label": "Estrofe 3", "text": "Quem quiser agora, venha aceitar;\nEis a porta aberta, já podeis entrar;\nÉ Jesus caminho para ao céu chegar;\nTodo que quiser, é vir!"}, {"label": "Estrofe 4", "text": "Que fiel promessa tens, pecador!\nQueres tu a vida? Vem ao Salvador!\nEle a todos fala com mui terno amor:\nTodo que quiser, é vir!"}], "reviewed": false}, {"number": 214, "title": "Cristo Chama Por Ti", "page": 113, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo Jesus, com amor divinal,\nChama por ti; que amor sem igual!\nEle te dá salvação eternal;\nVem, pecador, agora!"}, {"label": "Estrofe 2", "text": "Vem a Jesus, o bom Salvador!\nEle por ti já sofreu grande dor;\nSangue verteu no Cálvario;\nDá-te perdão plenário!"}, {"label": "Estrofe 3", "text": "Oh, não desprezes tal prova de amor!\nVem, oh, vem já a Cristo, o Senhor;\nEle te chama, vem já, pecador!\nComo é propícia a hora!"}, {"label": "Estrofe 4", "text": "Vem, meu amigo, que a morte a ninguém\nMostra-se compassiva, e convém\nQue te despertes, que o mal aí vem.\nVem, oh, vem sem demora!"}, {"label": "Estrofe 5", "text": "Hoje tu tens a melhor ocasião\nDe te entregares de coração;\nVem a Jesus, que te dá salvação.\nVai-se o bom tempo embora!"}], "reviewed": false}, {"number": 215, "title": "Fonte Bendita", "page": 113, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, vinde a fonte de sangue;\nVinde, sim, vinde a Jesus!\nPaz e perdão vos outorga;\nVinde alcançá-los na cruz."}, {"label": "Estrofe 2", "text": "Vinde, pois, vinde depressa!\nCristo vos quer receber!\nOh, vinde à fonte de sangue,\nVinde vos satisfazer!"}, {"label": "Estrofe 3", "text": "Tais como sois, vinde à fonte;\nEle vos receberá;\nTodos os vossos pecados\nCristo Jesus limpará.\nEis a promessa do Mestre,\nFeita ao que queira aceitar;\nVida na glória celeste,\nJunto de Deus vai gozar."}, {"label": "Estrofe 4", "text": "Vinde a Jesus! Vinde a Jesus!\nNão demoreis; vinde já, vinde já!\nPaz e perdão vos outorga;\nVinde alcançá-los na cruz."}], "reviewed": false}, {"number": 216, "title": "Descanso Em Jesus", "page": 114, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "\"Vem, vem a mim, se cansado estás\",\nDiz o Filho do santo Deus;\n\"Com fé vem a mim e desfrutarás\nO descanso que dou aos meus.\""}, {"label": "Estrofe 2", "text": "Deus o proclama, Cristo te chama:\n\"Vem, pecador, vem a mim!\"\nA voz te fala com terno amor:\n\"Com fé hoje vem amim!\""}, {"label": "Estrofe 3", "text": "\"Vem, vem a mim\", diz o Salvador\nAo pior que no mundo houver;\nA graça de Deus chama o pecador\nPara pleno perdão obter."}, {"label": "Estrofe 4", "text": "Não nos podemos jamais gabar\nDe fazer nossa paz com Deus;\nJesus essa paz veio consumar\nSobre a cruz a favor dos seus."}], "reviewed": false}, {"number": 217, "title": "Segue-me", "page": 114, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Escuta a voz do bom Jesus:\n\"Segue-me, vem, segue-me.\nGuiar-te-ei à eterna luz;\nSegue-me, vem, segue-me.\nPor ti eu toda lei cumpri;\nPor ti o amargo fel bebi;\nPor ti a morte já sofri;\nSegue-me, vem, segue-me.\""}, {"label": "Estrofe 2", "text": "\"Liberto dos pecados teus,\nSegue-me, vem, segue-me.\nGuiar-te-ei aos altos céus;\nSegue-me, vem, segue-me.\nOh, quantas vezes te chamei,\nE tu quebraste a minha lei;\nMas fiador teu eu fiquei;\nSegue-me, vem, segue-me.\""}, {"label": "Estrofe 3", "text": "\"Em mim tu podes descansar;\nSegue-me, vem, segue-me.\nVem teus cuidados me entregar;\nSegue-me, vem, segue-me.\nEu sou teu Deus, teu Salvador;\nEu te amo muito, ó pecador;\nOh, deixa todo o teu temor;\nSegue-me, vem, segue-me.\""}, {"label": "Estrofe 4", "text": "\"Sim, meu Jesus, Te seguirei;\nSeguirei, sim, seguirei;\nPor ti eu tudo deixarei;\nDeixarei, sim, deixarei;\nMui débil sou, e sem valor;\nSem ti não posso andar, Senhor;\nMas enche-me do teu vigor!\nSeguirei, sim, seguirei.\""}], "reviewed": false}, {"number": 218, "title": "Vinde a Mim", "page": 115, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, vinde a mim, o vosso Salvador,\nVosso Advogado, vosso Redentor,\nO bom Pastor, e vosso eterno Rei!\nOh, vinde a mim! Descanso vos darei!"}, {"label": "Estrofe 2", "text": "Gozo eternal eu vos farei fruir.\nVinde! Por que razão deixais de vir?\nVinde, fugi do enganador sagaz!\nOh, vinde a mim! Eu vos darei a paz!"}, {"label": "Estrofe 3", "text": "Oh, vinde a mim, gentios e juDeus!\nNão há limite à salvação de Deus.\nOh, vinde a mim! Eu vos darei perdão,\nPois só por mim tereis a salvação!"}, {"label": "Estrofe 4", "text": "Vida de paz, descanso e gozo, além,\nConcederei a todos os que crêem.\nSois convidados ao festim real!\nOh, vinde ao lar, à casa paternal!"}, {"label": "Estrofe 5", "text": "Oh, vinde a mim! (3x)\nDescanso vos darei! (3x)"}], "reviewed": false}, {"number": 219, "title": "Vem Já", "page": 116, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Não te demores, amigo!\nPor que te delongas assim?\nJesus está pronto a salvar-te.\nNão ouves o seu \"vinde a mim\"?"}, {"label": "Estrofe 2", "text": "Que lucrarás, meu amigo,\nDeixando isto para amanhã?\nAs coisas do mundo perecem;\nSem Cristo terás vida vã."}, {"label": "Estrofe 3", "text": "Não te demores, amigo!\nO dia da morte já vem!\nDepois que deixares o mundo,\nTerás de prestar conta além."}, {"label": "Estrofe 4", "text": "Ó meu amigo, decide:\nVem logo a Jesus aceitar!\nDespreza teus muitos pecados;\nJesus dá-te graça sem-par."}, {"label": "Estrofe 5", "text": "Vem já, vem já,\nVem, perdido, a Jesus! (bis)"}], "reviewed": false}, {"number": 220, "title": "Perdão e Salvação", "page": 116, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "\"Vem, vem a mim!\" - o Salvador terno\nDiz ao que sede tem.\nQue venha, e dessa célica fonte\nDesfrutará o bem."}, {"label": "Estrofe 2", "text": "\"Oh, vinde a mim! Se andais em trabalhos\nTereis descanso assim;\nTomai, pois, sobre vós o meu jugo;\nSim, aprendei de mim.\""}, {"label": "Estrofe 3", "text": "Jesus o coração quebrantado\nJamais rejeitará;\nMas, ai de quem não queira aceitá-lo\nPerdido ficará."}, {"label": "Estrofe 4", "text": "Encher-vos quer de bênçãos celestes,\nO grande Salvador.\nPodeis ouvir com indiferença\nContar tão grande amor?"}, {"label": "Estrofe 5", "text": "Jesus, o Mestre, vos chama.\nQuereis a Cristo vir?\nO seu perdão e salvação\nPodeis já possuir."}], "reviewed": false}, {"number": 221, "title": "Convite", "page": 117, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "\"Vinde todos sem demora\"\nDiz o amado Redentor;\nEle salva, e mesmo agora\nVos convida com amor"}, {"label": "Estrofe 2", "text": "Seu convite é admirável,\nVinde a Cristo, o bom Senhor!\nSeu convite é aceitável,\nVinde ao vosso Salvador!"}, {"label": "Estrofe 3", "text": "Ele está vos convidando\nPara o divinal festim;\nVoz eterna vos chamando:\n\"Pecadores, vinde a mim!\""}, {"label": "Estrofe 4", "text": "Aos contritos pecadores\nVestes brancas ele dá;\nAflições, tristezas, dores,\nLá no céu não haverá."}], "reviewed": false}, {"number": 222, "title": "Manso e Suave", "page": 117, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Manso e suave Jesus, convidando,\nChama por ti e por mim.\nEis que ele à porta te espera, velando;\nVela por ti e por mim."}, {"label": "Estrofe 2", "text": "\"Vem já, vem já! Alma cansada, vem já!\"\nManso e suave Jesus, convidando,\nChama: \"O pecador, vem!\"\nPois que esperamos? Jesus, convidando,\nConvida a ti, sim, e a mim.\nOh, não desprezes mercê que está dando,\nSim, dando a ti, dando a mim!"}, {"label": "Estrofe 3", "text": "Correm os dias, as horas se passam,\nPassam por ti e por mim;\nTranses de morte por fim nos esperam,\nVêm tanto a ti quanto a mim."}, {"label": "Estrofe 4", "text": "Oh, grande amor que Jesus nos tem dado,\nTem dado a ti, dado a mim!\nVeio salvar-nos do tão vil pecado,\nVeio por ti e por mim."}], "reviewed": false}, {"number": 223, "title": "Abrigo", "page": 118, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Óh, vinde, vós aflitos, já,\nA Cristo o Redentor!\nAbrigo certo vos dará,\nRefúgio em seu amor."}, {"label": "Estrofe 2", "text": "Seu sangue derramou por nós,\nE assim nos veio abrir\nEstrada reta, que conduz\nAo céu, o bom porvir."}, {"label": "Estrofe 3", "text": "Em Cristo há vida, paz e luz,\nSó nele existe amor;\nDá tudo, enfim, o bom Jesus\nAo pobre pecador."}, {"label": "Estrofe 4", "text": "Oh, vinde, pois, e vinde já\nA Cristo vos unir!\nPerdão Jesus concederá\nÀquele que o seguir."}, {"label": "Estrofe 5", "text": "Cristo salva, Cristo salva,\nSalva o pecador. ( bis )"}], "reviewed": false}, {"number": 224, "title": "Um Passo Só", "page": 118, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Um passo só pra Cristo!\nPor que mais demora?\nEle oferece, agora,\nA paz e bem-estar.\nUm passo só! Um passo só!\nVem, ó pecador,\nCom arrependimento,\nTudo lhe confessando!\nUm passo só pra Cristo!\nOh, vem sem demorar!"}, {"label": "Estrofe 2", "text": "Um passo só pra Cristo!\nDas trevas para a luz;\nPara inefável gozo,\nAo lado de Jesus."}, {"label": "Estrofe 3", "text": "Um passo só pra Cristo!\nÓ vem, decide já!\nCom terno amor te espera,\nPerdão te outorgará."}, {"label": "Estrofe 4", "text": "Um passo só pra Cristo!\nOh, deixa todo o mal,\nAs seduções do mundo,\nE aceita a paz real!"}, {"label": "Estrofe 5", "text": "Um passo só pra Cristo!\nNão queiras hesitar;\nPois corre grande risco\nQuem mais de demorar."}, {"label": "Estrofe 6", "text": "Um passo só pra Cristo!\nMui breve a morte vem;\nComo viver sem ele\nNa eternidade, além?"}, {"label": "Estrofe 7", "text": "Um passo só pra Cristo!\nOh, clama, pecador:\n'Salva-me, que eu pereço,\nSocorre-me, Senhor!'"}, {"label": "Estrofe 8", "text": "Um passo dou, para o Senhor,\nPara o Salvador,\nCom arrependimento\nE nele confiando!\nO passo dou pra Cristo\nSem mais me demorar!"}], "reviewed": false}, {"number": 225, "title": "Voz de Ternura", "page": 119, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A terna voz do Salvador\nA todos nos convida,\nChamando-nos por seu amor,\nQuerendo dar-nos vida."}, {"label": "Estrofe 2", "text": "Quer no presente ou no porvir,\nNunca na terra ou céu de luz\nMais doce nota se há de ouvir\nQue o nome de Jesus."}, {"label": "Estrofe 3", "text": "O cálix cheio de amargor\nJesus tem esgotado,\nA fim de dar ao pecador\nPerdão do seu pecado."}, {"label": "Estrofe 4", "text": "Por essa grande salvação\nDê graças todo crente;\nÉ digna de celebração\nAgora e eternamente."}], "reviewed": false}, {"number": 226, "title": "Dá Teu Coração", "page": 120, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Queres o teu vil pecado vencer?\nDá teu coração a Jesus.\nQueres também seu favor receber?\nDá teu coração a Jesus."}, {"label": "Estrofe 2", "text": "Já chega de hesitação!\nJá chega de oposição!\nOh, busca em Cristo o perdão,\nE dá-lhe teu coração"}, {"label": "Estrofe 3", "text": "Em santidade desejas viver?\nDá teu coração a Jesus.\nQueres do Espírito Santo o poder?\nDá teu coração a Jesus."}, {"label": "Estrofe 4", "text": "A tempestade não quer acalmar?\nDá teu coração a Jesus.\nQueres as tuas paixões refrear?\nDá teu coração a Jesus."}, {"label": "Estrofe 5", "text": "Dos teus amigos alguém te traiu?\nDá teu coração a Jesus.\nBusca a amizade de quem te remiu,\nDá teu coração a Jesus."}, {"label": "Estrofe 6", "text": "Queres no céu a teu Deus exaltar?\nDá teu coração a Jesus.\nQueres a glória divina alcançar?\nDá teu coração a Jesus."}], "reviewed": false}, {"number": 227, "title": "Despertado Coração", "page": 121, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Despertado coração,\nEm Jesus há salvação;\nEis-nos todos a rogar\nPara Cristo te salvar."}, {"label": "Estrofe 2", "text": "Basta já de rebelião,\nDe vexame e perdição;\nCom paciência, com amor,\nJá te espera o Redentor."}, {"label": "Estrofe 3", "text": "Vem amigo, oh, vem já,\nA Jesus te dedicar!\nVem amigo, oh, vem já!\nEle, pois, te quer salvar!"}, {"label": "Estrofe 4", "text": "O que o mundo prometeu\nSabes que não concedeu;\nEm Jesus tu acharás\nSalvação, amor e paz."}, {"label": "Estrofe 5", "text": "Sem demora, amigo, vem;\nDe Jesus aceita o bem,\nNele sempre encontrarás\nVida infinita, gozo e paz."}], "reviewed": false}, {"number": 228, "title": "Ouvi a Chamada", "page": 121, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, escutai! Jesus vos chama;\nSim, escutai a quem vos ama!\nVinde sem hesitar,\nVinde, pois, aceitar.\nEis que está perto a salvação;\nCristo concede-vos perdão."}, {"label": "Estrofe 2", "text": "Cristo vos chama;\nOh, vinde sem mais hesitar!\nSim, vinde agora;\nDeixai de tanto demorar!"}, {"label": "Estrofe 3", "text": "Eis que Jesus vos chama: Vinde.\nAntes que o tempo próprio finde!\nOh, não fiqueis no mal,\nTendo um convite tal!\nOh, não temeis a perdição?\nCristo vos dá a salvação!"}, {"label": "Estrofe 4", "text": "Cristo Jesus é o pão da vida;\nPara aceitá-lo vos convida\nNão desejais gozar\nVida no eterno lar?\nVinde e aceitai a salvação,\nNão obdureis o coração!"}], "reviewed": false}, {"number": 229, "title": "Régio Hóspede", "page": 122, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tendes vós lugar vazio\nPara Cristo, o Salvador?\nEle bate e quer entrada,\nQuer salvar-vos em amor."}, {"label": "Estrofe 2", "text": "Dai lugar a Jesus Cristo!\nIde já o convidar,\nPara que ache em vós morada\nE onde sempre possa estar!"}, {"label": "Estrofe 3", "text": "Vós quereis divertimentos,\nAmizades e prazer,\nMenos esse amigo vero,\nQue por nós ousou morrer?"}, {"label": "Estrofe 4", "text": "Tendes tempo para Cristo?\nLogo o buscarei em vão!\nHoje é tempo favorável\nDe aceitar a salvação!"}], "reviewed": false}, {"number": 230, "title": "Deus Chamando", "page": 122, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Deus sempre insiste em me chamar,\nE eu inda estou a demorar;\nO aviso devo eu atender\nE para o Salvador correr."}, {"label": "Estrofe 2", "text": "Ei-lo a convidar-me!\nEle quer solvar-me!\nE, com persistência, Deus me chama sempre;\nCom ternura chama,\nCom amor me chama,\nO Senhor insiste sempre em me chamar."}, {"label": "Estrofe 3", "text": "Deus sempre insiste em me advertir,\nE eu sempre recusando ouvir;\nAssim não devo proceder,\nMas, sim, ao Salvador correr."}, {"label": "Estrofe 4", "text": "Deus inda continua a instar,\nE eu é que não o deixo entrar;\nPorém não cessa de bater,\nDeseja tanto me valer."}, {"label": "Estrofe 5", "text": "Eu vou, enfim, me decidir;\nQuero a Jesus a porta abrir,\nEu quero ouvir o seu chamar\nE sem demora me entregar."}], "reviewed": false}, {"number": 231, "title": "Vem, Filho, Vem", "page": 123, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Do país distante, onde tu não tens\nPai, nem pão, nem casa, vem, filho, vem!"}, {"label": "Estrofe 2", "text": "Tu serás bem-vindo no celeste lar;\nDeus o beijo de perdão te espera dar."}, {"label": "Estrofe 3", "text": "Oh, se tal convite tratas com desdém,\nTriste a tua sorte! Vem, filho, vem!"}, {"label": "Estrofe 4", "text": "Eis a porta aberta, sabes para quem?\nPara os pecadores! Vem, filho, vem!"}, {"label": "Estrofe 5", "text": "Oh, contempla a mesa, que fartura tem!\nTu estás faminto; vem, filho, vem!"}], "reviewed": false}, {"number": 232, "title": "Cristo À Porta", "page": 123, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "À porta chamo-te, alma triste,\nAnsioso por te consolar;\nSe minha voz enfim ouviste,\nPosso eu entrar? ( bis )"}, {"label": "Estrofe 2", "text": "Por ti foi grande meu castigo.\nSofri sem nunca murmurar.\nPerfeita paz terás comigo -\nPosso eu entrar? ( bis )"}, {"label": "Estrofe 3", "text": "A minha graça poderosa\nO teu pecado vem lavar;\nÓ alma impura, pesarosa,\nPosso eu entrar? ( bis )"}, {"label": "Estrofe 4", "text": "Eu vim pra dar-te vida e gozo,\nQue podes hoje desfrutar;\nCom isso te farei ditoso -\nPosso eu entrar? ( bis )\nÁ porta por amor levado,\nTeu mal procuro debelar\nÓ pecador desalentado,\nPosso eu entrar? ( bis )"}], "reviewed": false}, {"number": 233, "title": "Por Que Não Já", "page": 124, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó corações, considerai\nA voz de amor do vosso Deus!\nAs vossas culpas, Oh, chorai!\nQuereis perdão? Por que não já?"}, {"label": "Estrofe 2", "text": "Por que não já? Por que não já?\nQuereis perdão? Por que não já?"}, {"label": "Estrofe 3", "text": "Pois o amanhã não sei se vem,\nTambém não sei o que trará;\nA vida é incerta a vós também.\nQuereis perdão? Por que não já?"}, {"label": "Estrofe 4", "text": "O bom Senhor ao pecador\nA graça não recusará;\nUni-vos, pois, ao Salvador.\nQuereis perdão? Por que não já?"}], "reviewed": false}, {"number": 234, "title": "Cristo Salva", "page": 124, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo salva o pecador,\nLava o negro coração;\nAo contrito, com amor,\nOferece salvação."}, {"label": "Estrofe 2", "text": "Confiai em seu poder;\nConfiai em seu amor;\nCrede, pois, que Cristo quer\nLibertar o pecador."}, {"label": "Estrofe 3", "text": "Cristo salva o pecador\nE concede-lhe perdão.\nAceitai o bom Senhor,\nAceitai de coração."}, {"label": "Estrofe 4", "text": "Vinde todos, e achareis\nPaz e luz no Redentor;\nVinde, e então recebereis\nVida eterna do Senhor."}], "reviewed": false}, {"number": 235, "title": "Chamada", "page": 125, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo te chama, chama, chama\nDas densas trevas, ó pecador!\nEle te salva, salva, salva;\nVem sem demora a Jesus, Redentor."}, {"label": "Estrofe 2", "text": "Cristo te salva! Cristo te salva!\nJá, sem demora, vem, vem, pecador!\nChega-te agora, dize a teu Mestre:\nTu me salvaste, meu Redentor!"}, {"label": "Estrofe 3", "text": "Inda te espera, espera, espera -\nTão compassível é o Salvador!\nÉ Cristo mesmo, mesmo, mesmo,\nQuem te convida com tão grande amor."}, {"label": "Estrofe 4", "text": "Com amor grande, grande, grande,\nJá veio ao mundo teu Salvador!\nVem tu a Cristo, Cristo, Cristo;\nHá salvação para o vil pecador!"}], "reviewed": false}, {"number": 236, "title": "Atribulado Coração", "page": 125, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Atribulado coração,\nEm Cristo alívio encontrarás;\nConsolo, paz e seu perdão,\nSim, dele tu receberás."}, {"label": "Estrofe 2", "text": "Dilacerado pela dor\nDas tuas culpas, do pecar,\nVem sem demora ao Salvador,\nE vida nova hás de gozar."}, {"label": "Estrofe 3", "text": "Se, para vir ao Salvador,\nTu tens fraquezas e vencer,\nOh, vem, pois ele, em seu amor\nE em graça, te dará poder!"}, {"label": "Estrofe 4", "text": "A Cristo sem demora vem,\nPois ele almeja te valer;\nE sempre quer buscar teu bem;\nConfia nele em teu viver!"}, {"label": "Estrofe 5", "text": "Oh, vem sem demora ao Salvador!\nPor que vacilar e ter temor?\nOh, vem! Vem já!\nDescanso te dará!"}], "reviewed": false}, {"number": 237, "title": "Tão Perto", "page": 126, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tão perto do reino, mas sem salvação!\nTão perto, porém sem Jesus, sem perdão!\nDeixai os pecados e o vosso temor!\nChegai-vos agora a Jesus, Salvador!"}, {"label": "Estrofe 2", "text": "Oh, vinde a Jesus! Chegai-vos,\nChegai-vos ao bom Salvador!"}, {"label": "Estrofe 3", "text": "Tão perto que ouvis os remidos cantar\nDa graça de Cristo, que os veio salvar!\nE ainda quereis no pecado viver,\nEnquanto o perdão Deus vos quer conceder?"}, {"label": "Estrofe 4", "text": "Morrer sem ser salvo, sem paz, sem Jesus,\nPerdidos pra sempre, em tormentos, sem luz!\nOh, considerai! Ao convite atendei,\nE sem mais demora a Jesus vos rendei!"}], "reviewed": false}, {"number": 238, "title": "A Água da Vida", "page": 126, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A água da vida Jesus nos dá\nFranca e livremente!\nQuem beber dela não morrerá,\nNunca, nunca, nunca!\nÓ pecadores, sem exceção,\nVinde, vinde, vinde!\nCristo oferece-vos salvação,\nGrátis, a todos que a buscam!"}, {"label": "Estrofe 2", "text": "O Espírito e a esposa dizem: 'Vem!\nVem, bebe dessa água da vida!'\nResponda, pois, quem sede tem:\n'À fonte de Cristo já vou.'\nSim, a água da vida corre\nSempre, sempre, sempre!\nSim, a água da vida corre,\nOh, sim, corre ao nosso dispor!"}, {"label": "Estrofe 3", "text": "Cristo prepara a mansão nos céus\nFranca e livremente,\nOnde estaremos com nosso Deus\nSempre, sempre, sempre!\nLá não há morte, pecado ou dor -\nNunca, nunca, nunca!\nSó há riquezas de real valor:\nCristo as promete aos que o amam."}, {"label": "Estrofe 4", "text": "Cristo vos dá veste nupcial\nFranca e livremente!\nEle vos chama ao festim real,\nCedo, cedo, cedo!\nÉ para aqueles que nele crêem\nHoje, hoje, hoje!\nTodas as glórias do mundo além,\nCristo as revela aos que o amam."}], "reviewed": false}, {"number": 239, "title": "A Luz do Céu", "page": 127, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tu anseias hoje mesmo a salvação?\nTens desejo de banir a escuridão?\nAbre, então, de par em par teu coração!\nDeixa a luz do céu entrar!"}, {"label": "Estrofe 2", "text": "Deixa a luz do céu entrar! ( bis )\nAbre bem a porta do teu coração!\nDeixa a luz do céu entrar!"}, {"label": "Estrofe 3", "text": "Cristo, a luz do céu, em ti quer habitar,\nPara as trevas do pecado dissipar,\nTeu caminho e coração iluminar!\nDeixa a luz do céu entrar!"}, {"label": "Estrofe 4", "text": "Que alegria andar ao brilho dessa luz!\nVida eterna e paz no coração produz!\nOh, aceita agora o Salvador Jesus!\nDeixa a luz do céu entrar!"}], "reviewed": false}, {"number": 241, "title": "Palavra Abençoada", "page": 127, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Palavra abençoada,\nConvite que contém\nPromessa e cumprimento,\nCom infinito bem.\nEis, cheio de ternura,\nJesus vos chama a si,\nEscravos do pecado,\nE diz-vos: 'Vinde a mim!'"}, {"label": "Estrofe 2", "text": "Por que viver tão longe\nDos braços de Jesus?\nPor que vagar nas trevas,\nPodendo andar na luz?\nDa vida sem proveito,\nDa culpa e da aflição,\nCorramos para a senda\nDa eterna salvação."}, {"label": "Estrofe 3", "text": "Vinde, vinde a mim! ( bis )\nTristes, carregados,\nVinde, vinde a mim!\nVinde, vinde a mim! ( bis )\nFracos e cansados,\nVinde, vinde a mim!"}, {"label": "Estrofe 4", "text": "Em tempos de amargura,\nDe desalento e dor,\nOu quando nos persegue\nDoloso tentador,\nJesus, com voz maviosa,\nNos dá abrigo em si,\nE, dissipando o medo,\nSegreda: 'Vinde a mim!'"}, {"label": "Estrofe 5", "text": "Em tudo e para sempre\nOuçamos ao Senhor,\nAchando doce alívio\nNo seu profundo amor.\nAssim conheceremos\nO gozo que produz,\nNo coração submisso,\nO 'vinde' de Jesus."}], "reviewed": false}, {"number": 242, "title": "Vinde Já", "page": 128, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vinde já, vinde já,\nAo bendito Salvador;\nConfiai, pois ele vos salvará,\nE a todo pecador."}, {"label": "Estrofe 2", "text": "Oh, não crês? Oh, não crês\nNeste grande, imenso bem?\nO Senhor Jesus te dará perdão;\nAceita, pois, e vem!"}, {"label": "Estrofe 3", "text": "Meu Jesus, meu Jesus,\nQuero em ti só confiar;\nEu te peço só teu amor e luz;\nDesejo me salvar!\nCreio em ti, creio em ti,\nPois tu és meu Redentor!\nEu a minha grande miséria vi,\nOh, vale-me, Senhor!"}, {"label": "Estrofe 4", "text": "Meu Senhor, meu Senhor,\nJá conheço o teu amor;\nGraças eu te dou, ó meu Benfeitor,\nPor todo o teu favor!"}], "reviewed": false}, {"number": 243, "title": "Vida Eterna", "page": 129, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, vinde ver Jesus, o Salvador!\nDa morte eterna salva o pecador;\nA todo que confia em seu amor,\nSim, vida eterna dá!"}, {"label": "Estrofe 2", "text": "Necessitado fui ter com Jesus,\nMinhas fraquezas todas eu lhe expus;\nEle apontou-me para os altos céus,\nPois vida eterna dá."}, {"label": "Estrofe 3", "text": "Das minhas culpas ele me livrou,\nPois que na cruz resgate consumou;\nTodo o pecado meu me perdoou,\nE vida eterna dá."}, {"label": "Estrofe 4", "text": "Bem sei que nada posso merecer;\nCumpri tão poucas vezes meu dever;\nA Cristo, pois, eu vou me submeter,\nPois vida eterna dá."}, {"label": "Estrofe 5", "text": "Gozo, paz, salvação, vida eterna dá!\nLuz, amor e perdão, vida eterna dá!\nA todo que confia em seu amor,\nSim, vida eterna dá!"}], "reviewed": false}, {"number": 244, "title": "Graça Admirável", "page": 129, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vinde, aflitos pecadores,\nCheios de tristezas e dor,\nA Jesus, que vos convida\nCom instante e terno amor.\nEle é forte, ele é forte,\nConfiai em seu favor. ( bis )"}, {"label": "Estrofe 2", "text": "Vinde, pobres e famintos,\nE o favor de Deus buscai;\nFé bendita, toda a graça,\nSó em Cristo procurai.\nSem dinheiro, sem dinheiro, ( bis )\nVinde a Cristo e já comprai."}, {"label": "Estrofe 3", "text": "A consciência diz bem claro:\nÉs indigno de favor.\nDiz Jesus: Eu pelo indigno\nJá morri, sou fiador.\nVinde logo, vinde logo, ( bis )\nAceitai seu rico amor."}, {"label": "Estrofe 4", "text": "Eis Jesus, Deus humanado,\nSobre o trono de esplendor;\nEis ferida a fronte e o lado,\nMostra o sangue Redentor.\nIsso basta, isso basta, ( bis )\nVinde, vinde sem temor."}], "reviewed": false}, {"number": 245, "title": "Cristo Vai Passar", "page": 130, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Há hoje alguém esperando\nPara Jesus encontrar?\nVenha, sem mais demorar-se,\nCristo vai hoje passar!\nEi-lo de mãos estendidas,\nCheio de graça sem-par;\nOh, que ventura inaudita -\nCristo vai hoje passar!"}, {"label": "Estrofe 2", "text": "Cristo vai hoje passar, passar, passar!\nPassa de amor transbordando,\nTodos a si convidando.\nO Mestre vai hoje passar,\nSim, hoje ele vai passar."}, {"label": "Estrofe 3", "text": "Há inda alguém duvidando\nDo seu poder de salvar?\nPois venha experimentá-lo,\nCristo vai hoje passar!\nO seu poder é divino,\nO seu amor é sem-par.\nÓ coração quebrantado!\nCristo vai hoje passar!"}, {"label": "Estrofe 4", "text": "Há inda alguém demorando\nPara Jesus aceitar?\nEis que o Senhor está perto,\nEle vai hoje passar!\nÓ pecador desditoso,\nNão cesses, pois, de clamar!\nVem tuas culpas chorando;\nCristo vai hoje passar!"}], "reviewed": false}, {"number": 246, "title": "Vem Agora", "page": 131, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vem a Cristo, vem agora."}, {"label": "Estrofe 2", "text": "Vem, oh, vem, pecador!\nVem, vem, confiadamente,\nA Jesus, o Senhor!"}, {"label": "Estrofe 3", "text": "Crendo nele ficas salvo."}, {"label": "Estrofe 4", "text": "Deus não quer que tu te percas."}, {"label": "Estrofe 5", "text": "Cristo pode, sim, salvar-te."}, {"label": "Estrofe 6", "text": "O Senhor não te rejeita."}, {"label": "Estrofe 7", "text": "Ele almeja perdoar-te."}], "reviewed": false}, {"number": 247, "title": "Vem, Filho Perdido", "page": 131, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vem, filho perdido,\nÓ pródigo, vem!\nRuína te espera\nNas trevas além.\nTu, de medo tremendo,\nE de fome gemendo."}, {"label": "Estrofe 2", "text": "Vem, filho perdido,\nÓ pródigo, vem!\nTeu pai te convida,\nQuerendo-te bem!\nVestes há para ornar-te,\nRicos dons, vem fartar-te!"}, {"label": "Estrofe 3", "text": "Vem, filho perdido,\nSim, volta a Jesus!\nBondade infinita\nSe avista na cruz.\nEm miséria vagando,\nTuas culpas chorando!"}, {"label": "Estrofe 4", "text": "Ó pródigo, escuta\nAs vozes de amor!\nOh, rompe as ciladas\nDo vil tentador,\nPois em casa há bastante,\nE tu andas errante!"}, {"label": "Estrofe 5", "text": "Ó filho perdido,\nVem, pródigo, vem!\nVem! Vem! Pródigo, vem!"}], "reviewed": false}, {"number": 248, "title": "O Filho Pródigo", "page": 132, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ide meu filho procurar,\nJá prestes a perecer\nNo meio dos males, no pecar,\nSua alma a se corromper."}, {"label": "Estrofe 2", "text": "Oh, ide buscá-lo já! ( bis )\nOh, com amor, com intenso fervor,\nOh, ide buscá-lo já!"}, {"label": "Estrofe 3", "text": "Oh, quem me dera contemplar\nAgora esse filho meu!\nOh, como desejo-vê-lo entrar\nNa senda que vai ao céu!"}, {"label": "Estrofe 4", "text": "Ide buscar meu filho já,\nTão vil é o seu viver;\nTrazei-me meu filho como está,\nPois tanto o desejo ter!"}], "reviewed": false}, {"number": 249, "title": "Banquete de Belsazar", "page": 132, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Numa orgia nefanda,\nO rebelde Belsazar,\nCom os grandes do seu reino,\nTodos eles a folgar,\nCom espanto pararam\nQuando o rei estremeceu:\nNa parede a mão divina,\nEscrevendo, apareceu."}, {"label": "Estrofe 2", "text": "No palácio, os festivos\nNobres não souberam ler\nTal escrita na perede;\nLogo o rei, todo a tremer,\nVir mandou bem depressa\nO cativo Daniel,\nQue, do escrito na perede,\nDeu a tradução fiel.\nA sentença foi grave\nAo monarca dos calDeus,\nQue vivia no pecado;\nSem temor nenhum de Deus:\n'O teu reino passou-se;\nNa parede escrito está;\nNa balança da justiça\nA tua alma em falta está.'"}, {"label": "Estrofe 3", "text": "Tua vida, ó amigo,\nNesta hora escrita está;\nO registro dos teus atos\nDeus, no céu, escreve já;\nQue Jesus, pois, te faça\nTal escrita compreender,\nQue, em havendo tempo, possas\nSua graça receber."}, {"label": "Estrofe 4", "text": "Lá no céu, a mão de Deus!\nLá no céu, a mão de Deus!\nVê qual seja a tua sorte,\nA tua vida ou morte;\nLá no céu, escreve a mão de Deus."}], "reviewed": false}, {"number": 250, "title": "Quase Induzido", "page": 133, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quase induzido a crer em Jesus,\nQuase induzido a andar na luz!\nNão queiras replicar:\n'Quando tiver vagar,\nEspero então chegar para Jesus!'"}, {"label": "Estrofe 2", "text": "Quase induzido! Ó coração!\nQuase induzido! Faz decisão!\nHoje, o bom Salvador,\nCom voz de terno amor,\nConvida o pecador: 'Escuta e vem!'"}, {"label": "Estrofe 3", "text": "Quase induzido! Decide Já!\nQuase induzido! Tarde será!\nQuase te enganará,\nQuase não servirá,\nQuase te lançará na perdição!"}], "reviewed": false}, {"number": 251, "title": "Quase Achegado", "page": 133, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quase achegado ao bom Salvador?\nChega mais perto, sim, pecador!\nNão penses em dizer:\n'Hoje, não pode ser;\nVou amanhã fazer a decisão.'"}, {"label": "Estrofe 2", "text": "Se resolveste a Cristo seguir,\nHoje é o tempo de decidir\nOuve essa voz de amor\nQue diz, ó pecador:\n'Tempo não há melhor pra salvação.'"}, {"label": "Estrofe 3", "text": "Quase não basta; faz perigar\nTua esperança de ao céu chegar.\nQuase não valerá,\nNunca te salvará,\nMas, sim, te levará à perdição."}], "reviewed": false}, {"number": 252, "title": "A Porta Franca", "page": 134, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Franqueada a porta a nós está\nDa perenal morada,\nE Cristo nos concederá\nA triunfal entrada."}, {"label": "Estrofe 2", "text": "Oh, quanto amor Jesus sentiu!\nPois ele a porta já me abriu\nA mim, a mim;\nA porta já me abriu."}, {"label": "Estrofe 3", "text": "Se queres, pecador, entrar,\nA porta está aberta!\nAli no céu terás lugar\nQue Cristo a ti oferta."}, {"label": "Estrofe 4", "text": "Oh, vinde, pecadores, já,\nSim, vinde sem demora!\nO tempo próprio passará,\nOh, vinde entrar agora!"}], "reviewed": false}, {"number": 253, "title": "Não Havia Lugar", "page": 134, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Não teve um palácio no mundo o Senhor,\nNem honras lhe deram de Rei Salvador;\nMas a manjedoura só pôde encontrar,\nPorque não havia mais outro lugar."}, {"label": "Estrofe 2", "text": "Não há lugar pra Cristo\nEm tua vida e lar?\nTerás, então, de ouvir dizer:\n'No céu não tens lugar.'"}, {"label": "Estrofe 3", "text": "Aqui, nos prazeres, tu queres viver,\nGastando os talentos e todo o teu ser?\nPor que continuas no triste pecar?\nPor que não concedes a Cristo lugar?"}, {"label": "Estrofe 4", "text": "Oh, quão infelizes as almas sem luz,\nIngratas, perdidas, sem paz, sem Jesus!\nSim, Cristo hoje mesmo deseja habitar\nEm ti, meu amigo. Oh, dá-lhe lugar!"}], "reviewed": false}, {"number": 254, "title": "Não Venhas Tarde", "page": 135, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Depressa vem, amigo,\nPois é bem tarde já;\nNas bodas preparadas\nLugar pra todos há.\nTalvez tu, demorando,\nO esposo vá chegar,\nE quando então bateres\nNão poderás entrar."}, {"label": "Estrofe 2", "text": "Então com que tristeza,\nÓ alma, hás de chorar,\nOuvindo a voz de Cristo:\nÉ tarde para entrar."}, {"label": "Estrofe 3", "text": "Se só se despertares\nNa vinda de Jesus,\nTu não terás entrada,\nPor te falhar a luz.\nOh, considera a mágoa\nQue tu terás então!\nA porta já fechada\nE tu batendo em vão!"}, {"label": "Estrofe 4", "text": "Prepara-te, ó amigo,\nPra a vinda do Senhor,\nSe crente, pois, tu fores,\nTerás o seu favor;\nNo céu, então, cantando,\nIrás decerto entrar;\nMas se te descuidares\nNão hás de ali chegar."}], "reviewed": false}, {"number": 255, "title": "Qual É Teu Refúgio", "page": 136, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Amigo, qual é teu refúgio\nE qual teu destino real?\nPor que trabalhar por tesouros\nQue tens de deixar afinal?\nOh, cuida do bem da tua alma\nQue eterna permanecerá,\nE tem mais valor que este mundo.\nSó Cristo a salvar poderá."}, {"label": "Estrofe 2", "text": "De nada aproveita este mundo ganhar,\nSe em troca tua alma tu tens de entregar.\nSe em troca tua alma tu tens de entregar."}, {"label": "Estrofe 3", "text": "Amigo, teu Mestre te chama.\nCom grande paciência e amor;\nOh, vem aceitar sua graça,\nOferta do teu Benfeitor!\nMedita na cruz do Calvário;\nOh, pensa no que ele sofreu!\nSim, vem com arrependimento,\nE aceita essa oferta do céu!"}, {"label": "Estrofe 4", "text": "Amigo, eis que o tempo se passa;\nAceita de Deus o perdão;\nA graça da misericórdia\nOpera real salvação.\nDepressa, depressa decide,\nDespreza este mundo falaz,\nContente, submisso, te entrega\nA quem te dá vida de paz!"}], "reviewed": false}, {"number": 256, "title": "Inda Há Lugar", "page": 136, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Inda há lugar; o régio Salvador\nChama ao banquete o pobre pecador."}, {"label": "Estrofe 2", "text": "Vem, vem; oh, vem!\nNo céu inda há lugar!"}, {"label": "Estrofe 3", "text": "Eis o convite, escuta a voz de Deus!\nOh, vinde a Cristo, vinde para os céus!"}, {"label": "Estrofe 4", "text": "Ávido vem, e cheio de fervor\nOuve o bem-vindo de celeste amor."}, {"label": "Estrofe 5", "text": "Hoje há lugar; desperta, meu irmão,\nPois quem demora arrisca a salvação."}, {"label": "Estrofe 6", "text": "Bem cedo a porta tem de se fechar,\nE se dirá então: 'Não há lugar.'"}], "reviewed": false}, {"number": 257, "title": "Quem É Que Vai", "page": 137, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quem é que vai com Jesus estar\nLá no céu? Lá no céu?\nQuem dessa graça vai desfrutar?\nVais tu? Vou eu? Vais tu? Vou eu?\nQuem vai provar esse santo amor,\nLonge de toda a tristeza e dor,\nJunto com Cristo, seu Salvador?\nVais tu? Vou eu? Vais tu? Vou eu?"}, {"label": "Estrofe 2", "text": "Logo o cristão vai deixar a cruz\nLá no céu, lá no céu,\nTer a coroa de glória e luz -\nVais tu? Vou eu? Vais tu? Vou eu?\nVai, sim, de Cristo o semblante ver,\nSuas palavras ouvir, e ter\nGozo de celestial prazer?\nVais tu? Vou eu? Vais tu? Vou eu?"}, {"label": "Estrofe 3", "text": "Quem vai ainda querer entrar\nLá no céu? Lá no céu?\nPois se dirá: 'Não há mais lugar.'\nVais tu? Vou eu? Vais tu? Vou eu?\nQuem vai parar na miséria atroz,\nSem mais ouvir a celeste voz?\nVai, por desgraça, qualquer de nós?\nVais Tu? Vou eu? Vais tu? Vou eu?"}, {"label": "Estrofe 4", "text": "Quem vai ter parte na adoração,\nLá no céu? Lá no céu?\nQue os redimidos a Deus darão?\nVais tu? Vou eu? Vais tu? Vou eu?\nQuem, com o coro celestial,\nParte terá no louvor real,\nLivre de todo o poder do mal?\nVais tu? Vou eu? Vais tu? Vou eu?"}], "reviewed": false}, {"number": 258, "title": "Chora Agora", "page": 137, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Pecador, confessa a chora\nTeus pecados sem tardar;\nOlha bem que o tempo foge,\nÉ perigo demorar.\nLouco estás se não te emendas,\nSabes que te há de julgar\nEm Deus reto e justiceiro,\nQue te pode condenar."}, {"label": "Estrofe 2", "text": "Chora agora as tuas culpas,\nVai a Deus as confessar;\nE se não, sem mais remédio,\nTarde, então hás de chorar.\nAh, se a dor aqui te aflige,\nComo então hás de sofrer\nNo tormento, sem alívio,\nPara sempre a padecer?"}, {"label": "Estrofe 3", "text": "Com remorso e pranto tarde\nTu dirés: 'Eu infeliz!\nEu perverso e desgraçado!\nDeus chamou-me e não quis.'\nOuve a Deus, escuta agora,\nSim, enquanto a vida der;\nPois naquele grande dia\nJusticeiro ele há de ser."}], "reviewed": false}, {"number": 259, "title": "A Última Hora", "page": 138, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ao findar o labor desta vida,\nQuando a morte a teu lado chegar,\nQue destino há de ter a tua alma?\nQual será no futuro o teu lar?"}, {"label": "Estrofe 2", "text": "Meu amigo, hoje tu tens a escolha:\nVida ou morte, qual vais aceitar?\nAmanhã pode ser muito tarde,\nHoje Cristo te quer libertar."}, {"label": "Estrofe 3", "text": "Tu procuras a paz neste mundo,\nEm prazeres que passam em vão,\nMas na última hora da vida\nEles já não te satisfarão."}, {"label": "Estrofe 4", "text": "Por acaso tu riste, ó amigo,\nQuando ouviste falar em Jesus?\nMas é só ele o único meio\nDe salvar pela morte na cruz."}, {"label": "Estrofe 5", "text": "Tens manchada tua alma e não podes,\nNunca, ver o semblante de Deus;\nSó os crentes com corações limpos\nPoderão ter o gozo nos céus."}, {"label": "Estrofe 6", "text": "Se decides deixar teus pecados,\nE entregar tua vida a Jesus,\nTrilharás, sim, na última hora,\nUm caminho brilhante de luz."}], "reviewed": false}, {"number": 260, "title": "Agora", "page": 139, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, quantos enganados,\nFiados no porvir!\nE quantos condenados,\nPor sempre repelir\nA salvação de graça\nQue Deus tem para dar!\nÀ noite eterna descem,\nEm trevas vão penar!"}, {"label": "Estrofe 2", "text": "Deixai entrar a graça\nEm vossos corações;\nDeixai que Deus desfaça\nOs vossos vis grilhões.\nCom vossa resistência\nMais duros vos tornais;\nTomai, pois, consciência\nDo quanto perigais."}, {"label": "Estrofe 3", "text": "Ainda que tivésseis\nO mundo e seu favor,\nQue galardão teríeis\nSem ter o Salvador?\nPois cedo chega a hora\nDe contas dar a Deus;\nTornai-vos desde agora\nAmados filhos seus!"}], "reviewed": false}, {"number": 261, "title": "Alma Ansiosa", "page": 139, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Só vejo trevas e furor,\nDa tempestade o furação;\nSó vejo, cheio de pavor,\nPerigo, morte, assolação."}, {"label": "Estrofe 2", "text": "Aflito, estou a procurar,\nPara minha alma um Salvador;\nCorrido tenho terra e mar,\nNenhum achei eu de valor."}, {"label": "Estrofe 3", "text": "Meus olhos elevei ao céu,\nClamei aos anjos com ardor;\nDa lei eu, um maldito réu,\nPedi perdão pra o pecador."}, {"label": "Estrofe 4", "text": "Resposta em coro pude ouvir:\n'Perdão pra ti aqui não há;\nSó Cristo pode te remir,\nE salvação só ele dá.'"}, {"label": "Estrofe 5", "text": "Ao pé da cruz estou, Senhor!\nContrito, rogo a ti perdão;\nE, por teu sangue remidor,\nEu peço minha salvação."}], "reviewed": false}, {"number": 262, "title": "Contrição", "page": 140, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A teus pés prostrados\nEis-nos, Salvador!\nVem agora mesmo encher-nos\nDo teu grande amor!"}], "reviewed": false}, {"number": 263, "title": "Luz Divina", "page": 140, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, vem, divina luz,\nAs trevas dissipar!\nOh, vem-me alumiar!\nOh, vem, divina luz!"}, {"label": "Estrofe 2", "text": "Oh, vem, divina luz,\nConverte o coração,\nE dá-me a salvação!\nOh, vem, divina luz!"}, {"label": "Estrofe 3", "text": "Amor celeste, vem,\nVem inundar meu ser,\nE o ódio desfazer.\nAmor celeste, vem!"}, {"label": "Estrofe 4", "text": "Oh, vem tu, meu Senhor,\nHabita no meu lar!\nErige o teu altar\nEm mim, ó Salvador!\nSem luz, nas trevas vivo;\nNa alma que se humilha,\nÓ luz divina, brilha;\nBrilhar agora vem!"}], "reviewed": false}, {"number": 264, "title": "Das Trevas", "page": 141, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Envolvido em densas trevas,\nAlmejava a luz do céu,\nBem sentindo meus pecados,\nMinha condição de réu."}, {"label": "Estrofe 2", "text": "Ó meu Mestre poderoso,\nForte e terno Salvador,\nRompe os laços que arruínam\nMinha vida, ó meu Senhor!"}, {"label": "Estrofe 3", "text": "Meus talentos tenho gasto,\nTuas leis eu desprezei;\nMas se tu comigo fores,\nTeu prazer eu cumprirei."}, {"label": "Estrofe 4", "text": "Nos teus braços, bem seguro,\nGuarda-me, meu bom Jesus,\nNa verdade justa e santa\nQue me leva ao céu de luz."}], "reviewed": false}, {"number": 265, "title": "Resgate", "page": 141, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Pendurado no madeiro,\nÓ Jesus, quiseste assim\nAbolir meu cativeiro\nPelo teu amor sem fim!\nO teu sangue foi vertido;\nExpiraste, ó meu Jesus,\nE ficou por ti cumprido\nMeu resgate sobre a cruz."}, {"label": "Estrofe 2", "text": "Neste sangue que verteste\nPurifica-me, Senhor;\nFoi por mim que tu morreste.\nSê propício ao pecador!\nSê propício ao desgraçado,\nSob a dor da maldição;\nDesse abismo do pecado\nSalva-me com tua mão.\n'Vinde a mim', Jesus convida,\nCom seu manso coração;\nJá da fé na chama brilha\nO penhor da salvação.\nEi-lo ali na cruz pregado;\nChama a todo pecador\nA limpar o seu pecado,\nNesse sangue expiador."}], "reviewed": false}, {"number": 266, "title": "Tal Qual Estou", "page": 142, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tal qual estou, eis-me, Senhor,\nPois o teu sangue remidor\nVerteste pelo pecador;\nÓ Salvador, me achego a ti!"}, {"label": "Estrofe 2", "text": "Tal qual estou, sem esperar\nQue possa a vida melhorar;\nEm ti só quero confiar;\nÓ Salvador, me achego a ti!"}, {"label": "Estrofe 3", "text": "Tal qual estou, e sem poder,\nAs faltas podes preencher\nE tudo quanto me é mister;\nÓ Salvador, me achego a ti!"}, {"label": "Estrofe 4", "text": "Tal qual estou me aceitarás,\nE tu minha alma limparás,\nCom teu amor me cobrirás;\nÓ Salvador, me achego a ti!"}], "reviewed": false}, {"number": 267, "title": "Salvação Pela Fé", "page": 142, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Qualquer que crer, Jesus o diz,\nCerto, tem a salvação,\nEu creio em ti, ó meu Senhor,\nE, crendo, tenho a salvação!"}], "reviewed": false}, {"number": 268, "title": "Como Estou", "page": 142, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ouço meu Senhor dizer:\n'Teus esforços são em vão,\nNada podes merecer,\nEu te dou a salvação.'\nAti, Jesus, Senhor,\nVenho como sou;\nBem nenhum mereço eu,\nTeu sangue me salvou."}, {"label": "Estrofe 2", "text": "Sim, eu venho a ti, Jesus,\nTua graça receber;\nInfinito é teu amor,\nSem limites teu poder."}, {"label": "Estrofe 3", "text": "Ai, me falta a retidão\nSou indigno pecador,\nMas pureza alcançarei\nNo teu sangue redentor."}, {"label": "Estrofe 4", "text": "Pela fé em ti, Senhor,\nRecebi o teu perdão;\nDe pecado e de temor\nLivre está meu coração."}, {"label": "Estrofe 5", "text": "Lá no céu eu cantarei\nTua eterna redenção;\nSempre ali te renderei\nMeu louvor e gratidão."}], "reviewed": false}, {"number": 269, "title": "Confissão", "page": 143, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu aos teus pés, Jesus,\nCom contrição,\nProcuro a tua luz;\nDá-me perdão!\nSim, vem me perdoar,\nVem teu favor mostrar!\nOh, queiras me escutar\nEm oração!"}, {"label": "Estrofe 2", "text": "Cansado e triste estou,\nMeu Redentor.\nUm pecador eu sou,\nCristo, Senhor!\nPortanto, venho a ti;\nOh, dá-me alívio aqui,\nPois já me arrependi,\nMeu Salvador!"}, {"label": "Estrofe 3", "text": "Eis do meu Deus a voz,\nVem me chamar;\nJesus comigo a sós\nQuer me falar!\nJá creio, Salvador,\nNo teu perdão e amor,\nE quero a ti, Senhor,\nMe consagrar!"}, {"label": "Estrofe 4", "text": "Estou inda aos teus pés\nCom gratidão!\nMeu Salvador tu és!\nDeste o perdão!\nEu creio em ti, meu Deus,\nSou um dos servos teus,\nConduze os passos meus,\nÓ tu, Jeová!"}], "reviewed": false}, {"number": 270, "title": "Resolução", "page": 144, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus, Senhor, me chego a ti;\nOh, dá-me alívio mesmo aqui!\nO teu favor estende a mim;\nAceita um pecador!"}, {"label": "Estrofe 2", "text": "As minhas culpas grandes são;\nMas tu, que não morreste em vão,\nMe podes conceder perdão;\nAceita um pecador!"}, {"label": "Estrofe 3", "text": "Eu nada posso merecer,\nTu vês-me prestes a morrer;\nJesus, a ti me vou render;\nAceita um pecador!"}, {"label": "Estrofe 4", "text": "Sim, venho agora, Redentor;\nSó tu, Jesus, és meu Senhor;\nOh, vem salvar-me em teu amor;\nAceita um pecador!"}, {"label": "Estrofe 5", "text": "Eu venho como estou;\nEu venho como estou;\nPorque Jesus por mim morreu,\nEu venho como estou."}], "reviewed": false}, {"number": 271, "title": "Substituição", "page": 144, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Todo o meu tão vil pecado\nLanço, Cristo, sobre ti;\nÓ Cordeiro imaculado,\nPadeceste tu por mim!\nSou indigno, estou manchado,\nVenho, pois, Jesus, a ti;\nO teu sangue derramado\nPode bem lavar-me a mim."}, {"label": "Estrofe 2", "text": "Pobre e já desesperado,\nÓ Jesus, confio em ti;\nSó por ti abençoado,\nTudo encontro para mim."}, {"label": "Estrofe 3", "text": "Triste estou, mui carregado,\nQuero descansar em ti;\nDeste modo aliviado,\nMe consolas tu a mim."}], "reviewed": false}, {"number": 272, "title": "Só Um Passo", "page": 145, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mui terna e mui doce do Mestre é a voz,\nChamando-me com amor;\nDe braços abertos te espero, vem já;\nOh, vem ao teu Redentor!"}, {"label": "Estrofe 2", "text": "Cristo me chama, me quer salvar,\nÉ só um passo que tenho de dar;\nQuero achegar-me, Senhor, a ti,\nPara nunca te abandonar."}, {"label": "Estrofe 3", "text": "'Tens muitos pecados e vives sem fé',\nSugere-me o tentador.\n'Eu tudo já fiz', me segreda outra voz,\n'Confia em teu Salvador'."}, {"label": "Estrofe 4", "text": "'Mui frágil me sinto, receio cair!'\nCom medo ainda aleguei:\n'Ó alma, não temas, pois Cristo te diz:\nEu não te abandonarei.'"}, {"label": "Estrofe 5", "text": "O mundo perdido nas trevas está,\nSeu gozo é só ilusão,\nAmor, vida e paz me concede Jesus,\nSou dele de coração."}], "reviewed": false}, {"number": 273, "title": "Salvador Benigno", "page": 145, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Salvador benigno, atende,\nPois me queres bem!\nVais abençoando a outros,\nSalva-me também."}, {"label": "Estrofe 2", "text": "A teus pés estou prostrado,\nSim, em contrição;\nPeço-te que me consoles\nEste coração."}, {"label": "Estrofe 3", "text": "Já confio no teu sangue,\nBusco teu favor;\nQue minha alma atribulada\nGoze teu amor."}, {"label": "Estrofe 4", "text": "És a fonte de conforto,\nDe onde a vida vem;\nDá-me alívio mesmo agora,\nE perdão também."}, {"label": "Estrofe 5", "text": "Cristo! Cristo!\nQue me queres bem!\nVais abençoando a outros,\nSalva-me também."}], "reviewed": false}, {"number": 274, "title": "Coro Santo", "page": 146, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, que belos hinos cantam lá nos céus,\nPois do mundo o filho mau voltou!\nVede no caminho o bom Pai abraçar,\nEsse filho que ele tanto amou."}, {"label": "Estrofe 2", "text": "Glória, glória os anjos cantam lá!\nGlória, glória as harpas tocam já!\nÉ o santo coro, dando glória a Deus,\nPor mais um remido entrar nos céus."}, {"label": "Estrofe 3", "text": "Oh, que belos hinos cantam lá nos céus!\nÉ que já se reconciliou\nA alma revoltosa, que, submissa a Deus,\nConvertida, o mundo abandonou!"}, {"label": "Estrofe 4", "text": "Ó arrependidos, hoje festejai,\nComo os anjos fazem com fervor!\nIde, pressurosos, vós, e anunciai\nQue se resgatou um pecador!"}], "reviewed": false}, {"number": 275, "title": "Contentamento", "page": 146, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu já contente estou; tenho Jesus!\nCom alegria vou; tenho Jesus!\nGozo que o mundo traz\nBem cedo se desfaz;\nTenho perfeita paz, paz em Jesus."}, {"label": "Estrofe 2", "text": "Eu posso envelhecer, nunca Jesus!\nEu posso empobrecer, nunca Jesus!\nTudo me suprirá,\nSempre me valerá,\nNada me faltará, tenho Jesus."}, {"label": "Estrofe 3", "text": "Vai tudo aqui findar, menos Jesus!\nQuando o Juiz chegar, é meu Jesus!\nBem grato me há de ser\nQuando meu Rei descer;\nCerto, ele irá dizer: 'Sou teu Jesus.'"}], "reviewed": false}, {"number": 276, "title": "Coro Celeste", "page": 147, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Celeste, estranho coro,\nJamais ouvido aqui,\nCom seu poder excelso,\nAgora, alegre, ouvi;\nÉ o canto dos arcanjos,\nLouvando o Salvador,\nDizendo que na terra\nFoi salvo um pecador."}, {"label": "Estrofe 2", "text": "Tão lenta e branda soa,\nAo peito dando paz,\nA voz de Deus, aquela\nQue as ânsias vâs desfaz!\nEscuta, irmão, escuta,\nO doce canto seu,\nQue vibra pelo espaço,\nE ecoa lá no céu."}, {"label": "Estrofe 3", "text": "Da vaga o som bravio,\nDa brisa a ciciar\nNa mata o passaredo,\nCantando ao despertar,\nA mãe em doce canto,\nAo pé do filho seu,\nNão tem aquele encanto\nDa linda voz do céu."}, {"label": "Estrofe 4", "text": "Ao meu ouvido chega\nO canto sem igual;\nTão belo em sonho ouvira\nJamais qualquer mortal.\nMeu canto extasiado,\nEspera, sem cessar,\nUnir-se à voz dos anjos\nAli no eterno lar."}, {"label": "Estrofe 5", "text": "Sublime e doce canto\nDa nossa pátria além\nSó ouve o que, contrito,\nA Deus por Cristo vem."}], "reviewed": false}, {"number": 277, "title": "Convencido", "page": 148, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Já convencido, eis-me, Senhor,\nQue fui remido por teu amor;\nEu quero obedecer e graças tributar\nA quem na cruz sofreu pra me salvar."}, {"label": "Estrofe 2", "text": "Já convencido do meu perdão,\nQue fui remido da escravidão,\nCorro, Senhor, a ti, cheio de ardente amor,\nVem habitar em mim, meu Salvador."}, {"label": "Estrofe 3", "text": "Já convencido que livre estou,\nJá persuadido que ao céu eu vou,\nGuiado por Jesus, com ele habitarei,\nRepouso lá no céu encontrarei."}, {"label": "Estrofe 4", "text": "Já convencido que Cristo é meu,\nJá persuadido de que sou seu,\nAmar eu quero, sim, o grande Salvador,\nPorque primeiro amou o pecador."}], "reviewed": false}, {"number": 278, "title": "Cantai", "page": 148, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O meu coração sofredor\nDescanso seguro encontrou,\nSeguido os conselhos de amor\nDo Pai que do mal me chamou."}, {"label": "Estrofe 2", "text": "Nos astros esparsos nos céus,\nDa lua no brando clarão,\nEu leio poemas de Deus\nQue outorga aos contritos perdão."}, {"label": "Estrofe 3", "text": "No livro bendito encontrei\nPalavras de amor e de luz;\nE canto celeste escutei\nDos anjos, saudando Jesus."}, {"label": "Estrofe 4", "text": "Os males do mundo olvidei,\nPor isso me pus a cantar;\nCom Deus para sempre estarei,\nIrei com Jesus ao seu lar."}, {"label": "Estrofe 5", "text": "Cantai, cantai\nNo templo de nosso Senhor!\nCantai, cantai!\nAo mundo mostrai seu amor!"}], "reviewed": false}, {"number": 279, "title": "A Doce Luz", "page": 149, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu nas trevas vagueava\nSem a luz da retidão;\nA minha alma estava morta,\nE eu, sem fé no coração."}, {"label": "Estrofe 2", "text": "Mas um dia a sua graça\nDeus mandou e a doce luz;\nVi então caminho claro,\nSim, ouvi o meu Jesus."}, {"label": "Estrofe 3", "text": "Dentro em mim meu 'homem velho'\nContra a retidão lutou;\nMas Jesus comigo estava,\nSantamente me guiou."}, {"label": "Estrofe 4", "text": "Foi um novo nascimento,\nHonra e glória ao Redentor!\nEle deu-me luz e vida,\nSantidade e seu amor."}, {"label": "Estrofe 5", "text": "Como é triste andar em trevas,\nSem perdão do Salvador!\nBela é a vida, mas a vida\nDominada pelo amor."}], "reviewed": false}, {"number": 280, "title": "Fiquei Curado", "page": 149, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Para Jesus, Senhor, olhando pela fé,\nCurado já fiquei e foi real mercê,\nPois Deus assim o mundo amou,\nQue o próprio Filho lhe mandou."}, {"label": "Estrofe 2", "text": "Oh, de Jesus as chagas comoventes são!\nAfirmam que na cruz existe o meu perdão;\nO meu resgate vejo assim,\nPois que Jesus morreu por mim."}, {"label": "Estrofe 3", "text": "Reconciliado estou, a voz de Deus ouvi;\nSeu filho me tornou, salvou-me para si;\nSeu Santo Espírito me deu,\nPenhor e guia para o céu."}], "reviewed": false}, {"number": 281, "title": "Achei a Fonte Carmesim", "page": 150, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Achei a fonte carmesim\nQue meu Jesus abriu.\nNa cruz morrendo ali por mim,\nMinha alma redimiu."}, {"label": "Estrofe 2", "text": "Eu creio, sim, eu creio, sim,\nJesus por mim morreu;\nE sobre a cruz, pra me salvar,\nCastigo padeceu."}, {"label": "Estrofe 3", "text": "Na cruz meu Cristo já pagou\nO mal que cometi;\nE pela morte que passou\nA vida eu consegui."}, {"label": "Estrofe 4", "text": "Assim, pois, fez-me, com amor,\nAndar no trilho seu;\nConfio sempre com fervor\nEm quem por mim morreu."}], "reviewed": false}, {"number": 282, "title": "Maravilha", "page": 150, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Chegado á cruz do meu Salvador,\nProstrado aos pés do meu Redentor,\nEle atendeu logo a meu clamor;\nGlória ao Salvador!"}, {"label": "Estrofe 2", "text": "Que maravilha, Jesus me amou!\nTudo de graça me perdoou!\nQuebrou meus laços e me livrou!\nGlória ao Salvador!"}, {"label": "Estrofe 3", "text": "Glória ao Salvador! ( bis )\nAgora sei que ele me salvou.\nGlória ao Salvador!"}], "reviewed": false}, {"number": 283, "title": "Mais Perto", "page": 151, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mais perto quero estar, meu Deus, de ti,\nInda que seja a dor que me una a ti!\nSempre hei de suplicar:\nMais perto quero estar, ( bis )\nMeu Deus, de ti!"}, {"label": "Estrofe 2", "text": "Andando triste aqui, na solidão,\nPaz e descanso a mim teus braços dão.\nSempre hei de suplicar:\nMais perto quero estar, ( bis )\nMeu Deus, de ti!"}, {"label": "Estrofe 3", "text": "Minha alma cantará a ti, Senhor,\nCheia de gratidão por teu amor.\nSempre hei de suplicar:\nMais perto quero estar, ( bis )\nMeu Deus, de ti!"}, {"label": "Estrofe 4", "text": "E quando a morte, enfim, me vier chamar,\nCom serafins nos céus irei morar.\nEntão me alegrarei,\nPerto de ti, meu Rei, ( bis )\nMeu Deus, de ti!"}], "reviewed": false}, {"number": 284, "title": "Companhia Divina", "page": 151, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó meu querido Salvador,\nVem conceder-me teu favor;\nNuvem nenhuma terreal\nTire-me a luz celestial."}, {"label": "Estrofe 2", "text": "Quando eu no leito despertar\nTua presença quero achar;\nAo dar começo ao meu labor,\nSê tu meu Guia e Protetor."}, {"label": "Estrofe 3", "text": "Vem conceder-me teu poder;\nSó poderei assim vencer\nAs seduções do tentador;\nFica comigo, Salvador."}], "reviewed": false}, {"number": 285, "title": "O Alvo Supremo", "page": 151, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O mundo vil já desprezei,\nE seu caminho abominei;\nMes te suplico, ó Salvador:\nA ti me eleva, Redentor!"}, {"label": "Estrofe 2", "text": "No mundo não encontro paz,\nPois ele não me satisfaz;\nAqui só tenho que sofrer;\nContigo quero, pois, viver."}, {"label": "Estrofe 3", "text": "Desejo, sim, aqui viver,\nPor tua causa me bater;\nJá pela fé eu avistei\nO lar em que descansarei."}, {"label": "Estrofe 4", "text": "À tua glória, já no fim,\nÓ meu Jesus, me leva, sim,\nE me sustenta até chegar\nÀs portas do celeste lar!"}, {"label": "Estrofe 5", "text": "Mais perto, sim, mais perto, sim,\nOh, junto a ti me eleva a mim,\nAo céu em que, meu Salvador,\nContigo esteja sem temor!"}], "reviewed": false}, {"number": 286, "title": "Junto a Ti", "page": 152, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Minha possessão eterna,\nÉs o meu maior amor;\nBem maior que o bem da vida,\nÉs, meu Deus, meu Salvador."}, {"label": "Estrofe 2", "text": "O prazer ou o descanso\nNão te venho suplicar;\nQuero trabalhar sofrendo,\nMas contigo sempre andar."}, {"label": "Estrofe 3", "text": "Pelo vale tão sombrio\nE também terrível mar\nQueira tua mão divina\nSempre, sempre me guiar."}, {"label": "Estrofe 4", "text": "Quando pelas santas portas\nDa feliz Jerusalém\nEu puder entrar na glória,\nGozarei o eterno bem."}, {"label": "Estrofe 5", "text": "Junto a ti, junto a ti, ( bis )\nQuero andar contigo sempre\nNa jornada minha aqui."}], "reviewed": false}, {"number": 287, "title": "Com Jesus", "page": 153, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Triste e sombrio foi meu viver,\nLonge de ti, meu Salvador;\nPaz e perdão de ti venho obter,\nJunto de ti, Senhor.\nFoi grande a luta da provação,\nTenho sofrido muita aflição;\nPra confortar o meu coração,\nEu venho a ti, Senhor!"}, {"label": "Estrofe 2", "text": "Minhas vaidades atirarei\nLonge de mim, ó Salvador;\nPois teu querer será minha lei,\nServir-te-ei, Senhor.\nO teu amor desejo provar,\nA tua graça quero gozar.\nSempre contigo almejo ficar,\nTeu sempre quero ser."}, {"label": "Estrofe 3", "text": "Medo da morte nunca terei;\nPerto de mim tu sempre estás,\nPois ao teu lar decerto eu irei,\nTu me receberás.\nJunto a ti, pois, quero viver,\nJunto a ti eu vou combater,\nJunto a ti vencer ou morrer,\nCristo, meu Salvador."}], "reviewed": false}, {"number": 288, "title": "Perto do Senhor", "page": 153, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Perto de ti almejo estar,\nPerto, sim, bem perto;\nTua presença desfrutar,\nPerto, sim, bem perto.\nPerto de ti pra compreender\nTeu grande amor e teu querer,\nComo contigo andar, viver,\nPerto, sim, bem perto. ( bis )"}, {"label": "Estrofe 2", "text": "Perto de ti em oração,\nPerto, sim, bem perto,\nSe revigora o coração,\nPerto, sim, bem perto,\nGozo perfeito a transbordar,\nVistas de glória e extasiar,\nDita feliz contigo estar,\nPerto, sim, bem perto. ( bis )"}, {"label": "Estrofe 3", "text": "Em comunhão contigo estar,\nPerto, sim, bem perto;\nSempre contigo conversar,\nPerto, sim, bem perto;\nTua vontade discernir,\nTeus bons ensinos quero ouvir,\nPara melhor te amar, servir,\nPerto, sim, bem perto. ( bis )"}, {"label": "Estrofe 4", "text": "Quero na santa guerra estar,\nperto, sim, bem perto,\nTua divisa sustentar,\nPerto, sim, bem perto;\nManifestar o teu amor,\nO teu poder e teu favor,\nGraça, perdão ao pecador,\nPerto, sim, bem perto."}], "reviewed": false}, {"number": 289, "title": "Ao Pé da Cruz", "page": 154, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quero estar ao pé da cruz,\nDe onde rica fonte\nCorre franca, salutar,\nDo Calvário monte."}, {"label": "Estrofe 2", "text": "A tremer ao pé da cruz,\nGraça eterna achou-me;\nMatutina Estrela ali\nRaios seus mandou-me."}, {"label": "Estrofe 3", "text": "Sempre a cruz, Jesus, meu Deus,\nQueiras recordar-me;\nDela à sombra, Salvador,\nQueiras abrigar-me."}, {"label": "Estrofe 4", "text": "Junto a cruz, ardendo em fé.\nSem temor vigio,\nPois à terra santa irei,\nSalvo, além do rio."}, {"label": "Estrofe 5", "text": "Sim, na cruz, sim, na cruz,\nSempre me glorio,\nE no fim vou descansar,\nSalvo, além do rio."}], "reviewed": false}, {"number": 290, "title": "Cristo, Meu Mestre", "page": 155, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo, meu Mestre, meu amigo sem igual,\nTu dás descanso, salvação real.\nQuando sou provado, e já vou desfalecer,\nTu, meu Cristo amado, vens me socorrer."}, {"label": "Estrofe 2", "text": "Perto, mui perto, eu chegar-me vou a ti:\nPerto, mui perto, vem, Senhor, a mim."}, {"label": "Estrofe 3", "text": "Só tu me amparás: quando perseguido sou,\nEm ti, ó Cristo, socorrer-me vou.\nPois em ti eu posso resistir à tentação,\nSim, em ti obtendo força, paz, perdão."}, {"label": "Estrofe 4", "text": "Cristo, meu Mestre, que mais gozo posso ter\nQue no teu reino tua glória ver?\nEm teu seio quero minha fronte reclinar,\nPara ter descanso desse labutar."}], "reviewed": false}, {"number": 291, "title": "Comunhão Celeste", "page": 155, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Comigo assiste, ó Deus! A noite vem,\nAs trevas crescem, eis, Senhor, convém\nQue me socorra a tua proteção;\nOh, vem fazer comigo habitação!"}, {"label": "Estrofe 2", "text": "Depressa encontrarei o fim mortal;\nDesaparece o gozo terreal;\nMudança vejo em tudo e corrupção;\nComigo faze eterna habitação!"}, {"label": "Estrofe 3", "text": "Vem revelar-me teu querer, Senhor!\nDivino Mestre, Rei, Consolador!\nMeu guia forte, Amparo em tentação!\nVem, vem fazer comigo habitação!"}, {"label": "Estrofe 4", "text": "Presente estás nas trevas e na luz;\nNão há perigo, andando com Jesus;\nA morte e a tumba não aterrarão\nÀquele em quem fizer habitação!"}, {"label": "Estrofe 5", "text": "Ó morte, em Cristo gozo a redenção!\nSepulcro, o pó verá ressureição!\nNo reino além não há pertubação.\nCom Deus eu herdo eterna habitação."}], "reviewed": false}, {"number": 292, "title": "Perto de Jesus", "page": 156, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Meu Senhor, sou teu, tua voz ouvi\nA chamar-me com amor;\nMas a ti mais perto eu almejo estar,\nÓ bendito Salvador!"}, {"label": "Estrofe 2", "text": "Mais perto da tua cruz\nQuero estar, ó Salvador!\nMais perto, para a tua cruz,\nLeva-me, ó meu Senhor!"}, {"label": "Estrofe 3", "text": "A seguir-te só me consagro já,\nConstrangido pelo amor;\nE meu coração bem contente está\nEm servir-te a ti, Senhor!"}, {"label": "Estrofe 4", "text": "Oh, que pura e santa delícia é\nAos teus santos pés me achar,\nE com viva e mui reverencia fé\nCom o Salvador falar."}], "reviewed": false}, {"number": 293, "title": "Desejos Espirituais", "page": 156, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Em mim vem habitar, oh, vem, Jesus,\nEm mim fazer brilhar a tua luz!\nEis a minha ambição: ter e sentir, Senhor,\nMais gratidão e mais amor."}, {"label": "Estrofe 2", "text": "Os passos teus seguir eu quero, sim;\nServir e bendizer até o fim;\nEis o meu anelar, meu ideal maior:\nContigo andar, ó Salvador!"}, {"label": "Estrofe 3", "text": "Em meu interior, vem tu brilhar;\nFaz-me, com mais ardor, da cruz falar.\nReveste o coração de teu excelso amor,\nDe retidão e de fervor!"}, {"label": "Estrofe 4", "text": "Oh, que consolação a Cristo amar,\nPois que com tanto amor me quis salvar!\nnada me alegra mais, gozo não há maior\nQue tua paz, ó Salvador!"}], "reviewed": false}, {"number": 294, "title": "Necessitado", "page": 156, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "De ti, Jesus, Senhor,\nEu tenho precisão;\nSó teu divino amor\nDá paz ao coração."}, {"label": "Estrofe 2", "text": "Ó meu Jesus, comigo\nVem estar agora,\nTé que no céu contigo\nEu vá morar."}, {"label": "Estrofe 3", "text": "Oh, dá-me, meu Jesus,\nFruir teu rico amor,\nE andar em tua luz,\nSubmisso a ti, Senhor!"}, {"label": "Estrofe 4", "text": "Vencendo a tentação,\nContente viverei\nSob tua proteção,\nÓ meu bendito Rei!"}], "reviewed": false}, {"number": 295, "title": "Tudo Entregarei", "page": 157, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tudo, sim, por ti darei!\nResoluto, mas submisso,\nSempre, sempre, seguirei!"}, {"label": "Estrofe 2", "text": "Tudo entregarei!\nTudo entregarei!\nSim, por ti, Jesus bendito,\nTudo deixarei!"}, {"label": "Estrofe 3", "text": "Tudo, ó Cristo, a ti entrego,\nCorpo e alma, eis aqui!\nEste mundo mau renego,\nÓ Jesus, me aceita a mim!"}, {"label": "Estrofe 4", "text": "Tudo, ó Cristo, a ti entrego,\nQuero ser somente teu!\nTão submisso à tua vontade\nComo os anjos lá no céu!"}, {"label": "Estrofe 5", "text": "Tudo, ó Cristo, a ti entrego;\nOh, eu sinto teu amor\nTransformar a minha vida\nE meu coração, Senhor!"}, {"label": "Estrofe 6", "text": "Tudo, ó Cristo, a ti entrego;\nOh, que gozo, meu Senhor!\nPaz perfeita, paz completa!\nGlória, glória ao Salvador!"}], "reviewed": false}, {"number": 296, "title": "Consagração", "page": 158, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A ti seja consagrada\nMinha vida, ó meu Senhor;\nMeus momentos e meus dias\nSejam só em teu louvor."}, {"label": "Estrofe 2", "text": "Sempre minhas mãos se movam\nCom presteza e com amor,\nE meus pés velozes corram\nAo serviço do Senhor."}, {"label": "Estrofe 3", "text": "Minha voz pra sempre toma,\nPara o teu louvor cantar;\nToma os lábios meus, fazendo-os\nA mensagem proclamar."}, {"label": "Estrofe 4", "text": "Minha prata e ouro toma;\nNada quero te esconder;\nMinha inteligência guia\nSó e só por teu saber."}, {"label": "Estrofe 5", "text": "A vontade minha toma,\nSujeitando-a a ti, Senhor,\nDo meu coração fazendo\nO teu trono, ó Salvador."}, {"label": "Estrofe 6", "text": "Meu amor e meu desejo\nSejam só teu nome honrar;\nFaze que meu corpo inteiro\nEu te possa consagrar."}], "reviewed": false}, {"number": 297, "title": "Súplica", "page": 158, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Prometo agora, meu Jesus,\nServir-te com sincero amor;\nConcede, pois, que tua luz\nHabite em mim, ó Salvador,\nE assim os males vencerei;\nNão temerei a luta atroz;\nA estrada reta trilharei,\nAtento sempre à tua voz."}, {"label": "Estrofe 2", "text": "O mundo mau ao meu redor\nAfoga-se em profanações;\nÉ mui sutil o tentador,\nTerríveis surgem vis paixões;\nSê tu, Jesus, refúgio meu,\nAmparo e forte defensor;\nProtege e livra o servo teu\nDa corrução do enganador."}, {"label": "Estrofe 3", "text": "E se eu me enfraquecer na fé,\nOu me afastar de ti, meu Deus,\nConcede-me a real mercê\nDo teu amparo lá dos céus.\nDesperta-me, se adormecer,\nE se fugir, deter-me vem!\nVem repreender-me se eu temer\nDe praticar em tudo o bem."}, {"label": "Estrofe 4", "text": "Tu prometeste, meu Senhor,\nÀquele que em ti confiar,\nCercá-lo de teu grande amor\nE lá no céu lhe dar lugar.\nResponde, pois, ó meu Senhor,\nÀ minha humilde petição;\nDirige-me com teu favor\nAté chegar à redenção."}], "reviewed": false}, {"number": 298, "title": "Estou Pronto", "page": 159, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Nem sempre será pra o lugar que eu quiser\nQue o Mestre me tem de mandar;\nÉ tão grande a seara já a embranquecer,\nA qual eu terei de ceifar!\nSe, pois, a caminho que nunca segui,\nA voz a chamar-me eu ouvir,\nDirei: 'Meu Senhor, dirigido por ti,\nIrei tua ordem cumprir.'"}, {"label": "Estrofe 2", "text": "Eu quero fazer o que queres, Senhor;\nSerei sustentado por ti,\nE quero dizer o que queres, Senhor,\nQue o servo teu deva dizer."}, {"label": "Estrofe 3", "text": "Eu sei que há palavras de amor e perdão\nQue aos outros eu posso levar,\nPorque nas estrelas dos vícios estão\nPerdidos que devo ir buscar.\nSenhor, se com tua presença real\nTu fores pra fortalecer,\nDarei a mensagem de servo leal,\nFarei, meu Senhor, meu dever."}, {"label": "Estrofe 4", "text": "Eu quero encontrar um obscuro lugar\nNa seara do meu bom Senhor;\nEnquanto for vivo, sim, vou trabalhar\nEm prova do meu grato amor.\nDe ti meu sustento só dependerá;\nTu, pois, hás de me proteger;\nA tua vontade, sim, minha será;\nE eu pronto o que queres a ser."}], "reviewed": false}, {"number": 299, "title": "Onde Quer Que Seja", "page": 160, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Onde quer que seja, com Jesus irei;\nEle é meu bendito Salvador e Rei.\nSeja para a guerra, para batalhar,\nSeja pra a campina para semear."}, {"label": "Estrofe 2", "text": "Onde quer, onde quer que Deus me mandar.\nPerto do meu Salvador eu quero andar."}, {"label": "Estrofe 3", "text": "Onde quer que seja, seguirei Jesus,\nDiz o coração que vive em sua luz;\nPerto dele sempre bem seguro vou,\nOnde quer que seja, pois, contente estou."}, {"label": "Estrofe 4", "text": "Seja, pois, para onde quer que me levar,\nAcharei com ele ali meu doce lar.\nOnde quer que seja, sempre cantarei:\n'Tu, Senhor, comigo estás, não temerei.'"}], "reviewed": false}, {"number": 300, "title": "Tudo Por Cristo", "page": 160, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Do Salvador bendito\nSempre desejo ser;\nLivre do mundo iníguo\nQuero também viver."}, {"label": "Estrofe 2", "text": "Quero servir a Cristo,\nDe prontidão estar;\nÚtil na paz, na luta,\nPronto pra trabalhar."}, {"label": "Estrofe 3", "text": "Quero ficar com Cristo,\nSempre com ele andar;\nSeja na vida ou morte,\nSeja no eterno lar."}, {"label": "Estrofe 4", "text": "Queres, pois, aceitar-me\nTal como sou, Senhor?\nVenho entregar-me agora;\nSou teu, meu Redentor."}, {"label": "Estrofe 5", "text": "Quero viver pra Cristo,\nTudo lhe dedicar;\nTudo por Cristo, tudo, tudo\nQuero renunciar."}], "reviewed": false}, {"number": 301, "title": "Crer e Observar", "page": 161, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Em Jesus confiar, sua lei observar,\nOh, que gozo, que bênção, que paz!\nSatisfeitos guardar tudo quando ordenar\nAlegria perene nos traz."}, {"label": "Estrofe 2", "text": "Crer e observar\nTudo quanto ordenar;\nO fiel obedece\nAo que Cristo mandar!"}, {"label": "Estrofe 3", "text": "O inimigo falaz e a calúnia mordaz\nCristo pode desprestigiar;\nNem tristeza, nem dor, nem intriga maior\nPoderão ao fiel abalar."}, {"label": "Estrofe 4", "text": "Que delícia de amor, comunhão com o Senhor\nTem o crente zeloso e leal;\nO seu rosto mirar, seus segredos privar,\nSeu consolo constante e real."}, {"label": "Estrofe 5", "text": "Resolutos, Senhor, e com fé, zelo e ardor,\nOs teus passos queremos seguir;\nTeus preceitos guardar, o teu nome exaltar,\nSempre a tua vontade cumprir."}], "reviewed": false}, {"number": 302, "title": "Como a Neve", "page": 161, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Bom Jesus, és todo meu;\nEu também sou todo teu.\nDá-me graça para ser\nTodo teu até morrer."}, {"label": "Estrofe 2", "text": "Bom Jesus, minha alma quer\nQual a neve branca ser;\nVive no meu coração,\nFaze-o puro, limpo e são."}, {"label": "Estrofe 3", "text": "Salvo estou em teu amor;\nJá não tenho assim temor;\nGozo a mais perfeita paz,\nNem a morte susto traz."}, {"label": "Estrofe 4", "text": "Dia a dia, meu Jesus,\nQuero andar em tua luz,\nTé que enfim eu vá morar\nNo celeste e eterno lar."}], "reviewed": false}, {"number": 303, "title": "Amor a Jesus", "page": 162, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus, sempre te amo porque sei que és meu;\nA ti toda a honra e louvores dou eu.\nMeu Mestre divino, meu amo, meu Rei,\nA ti, ó meu Cristo, me submeterei!"}, {"label": "Estrofe 2", "text": "Eu te amo porque tu morreste por mim;\nEu te amo porque teu amor não tem fim.\nEm ti confiança pra sempre terei;\nA ti, ó meu Cristo, me submeterei!"}, {"label": "Estrofe 3", "text": "Eu te amo na vida, na morte também;\nSempre hei de louvar-te na glória de além.\nAgora e pra sempre por ti viverei;\nA ti, ó meu Cristo, me submeterei!"}], "reviewed": false}, {"number": 304, "title": "Um Vaso de Bênção", "page": 162, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quero ser um vaso de bênção,\nSim, um vaso escolhido de Deus,\nPara as novas levar aos perdidos,\nBoas-novas que vêm lá dos céus."}, {"label": "Estrofe 2", "text": "Quero ser um vaso de bênção\nPara todos os dias fazer\nAos culpados que vivem nas trevas\nO perdão de Jesus conhecer."}, {"label": "Estrofe 3", "text": "Quero ser um vaso de bênção,\nSim, um vaso de bênção sem-par,\nAvisando que crentes em Cristo\nJubilosos no céu hão de entrar."}, {"label": "Estrofe 4", "text": "Para ser um vaso de Bênção,\nÉ mister uma vida real,\nUma vida de fé e pureza,\nRevestida do amor divinal.\nFaze-me vaso de bênção, Senhor,\nVaso que leve a mensagem de amor!\nEis-me submisso pra teu serviço,\nTudo consagro-te agora, Senhor."}], "reviewed": false}, {"number": 305, "title": "Consagrar Tudo", "page": 163, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Teu divinal amor veio me buscar;\nTudo com gratidão quero consagrar.\nAceita, meu Senhor, de um grato pecador\nTributo de louvor, dado com fervor."}, {"label": "Estrofe 2", "text": "Atende, meu Jesus, essa petição;\nTão débil sou, e mau é meu coração.\nTeu nome a exaltar, a nova a publicar,\nTeu reino a dilatar, vem-me habilitar."}, {"label": "Estrofe 3", "text": "Oh, dá-me mais paixão de um amor real,\nPra te servir e ser muito mais leal!\nAs almas a ganhar, sempre na luz a andar,\nE os filhos teus a amar, vem-me habilitar."}, {"label": "Estrofe 4", "text": "Tudo o que sou, Senhor, eu te votarei;\nDo mundo vil e mau nunca mais serei;\nTeu rosto quando vir, amor no céu luzir,\nA glória do porvir vou enfim fruir."}], "reviewed": false}, {"number": 306, "title": "O Caminho da Cruz", "page": 163, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Foi Jesus que abriu o caminho pra o céu;\nNão há outro meio de ir.\nNunca irei entrar no celeste lar\nSe o caminho da cruz errar."}, {"label": "Estrofe 2", "text": "Para o céu por Jesus irei,\nPara o céu por Jesus irei;\nGrande é o meu prazer\nDe certeza ter:\nPara o céu pela cruz irei."}, {"label": "Estrofe 3", "text": "Certamente eu vou no caminho da cruz\nCom resolução andar.\nÉ desejo meu de gozar no céu\nEssa herança que Cristo deu."}, {"label": "Estrofe 4", "text": "Os caminhos ímpios do mundo deixei;\nJamais neles vou seguir;\nSigo, pois, Jesus, com a minha cruz,\nNo caminho que ao céu conduz."}], "reviewed": false}, {"number": 307, "title": "Reconhecimento", "page": 164, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Não sou meu! Por Cristo salvo,\nQue por mim morreu na cruz,\nEu confesso alegremente\nQue pertenço ao bom Jesus."}, {"label": "Estrofe 2", "text": "Não sou meu! Por Cristo salvo,\nPois seu sangue derramou\nE da pena do pecado\nA minha alma resgatou."}, {"label": "Estrofe 3", "text": "Não sou meu! A ti confio\nTudo quanto chamo meu;\nTudo em tuas mãos entrego,\nPois, Senhor, sou todo teu."}, {"label": "Estrofe 4", "text": "Não sou meu! Oh, santifica\nTudo quanto sou, Senhor;\nDa vaidade e da soberba\nLivra-me, meu Salvador"}, {"label": "Estrofe 5", "text": "Não sou meu, oh, não sou meu!\nBom Jesus, sou todo teu!\nHoje mesmo e para sempre,\nBom Jesus, sou todo teu!"}], "reviewed": false}, {"number": 308, "title": "Para Onde For, Irei", "page": 164, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se eu tiver Jesus ao lado,\nE por ele auxiliado,\nSe por ele for mandado,\nA qualquer lugar, irei."}, {"label": "Estrofe 2", "text": "Seja meu caminho duro,\nEspinhoso ou inseguro,\nEm seus braços bem seguro,\nAonde me mandar, irei."}, {"label": "Estrofe 3", "text": "Males poderão cercar-me,\nOu perigos assustar-me,\nMas se Cristo segurar-me,\nAonde me mandar, irei.\nQuando terminar a vida,\nFinda minha triste lida,\nTenho a glória prometida,\nEu pra meu Senhor irei."}, {"label": "Estrofe 4", "text": "Seguirei a meu bom Mestre, ( 3 vezes )\nOnde quer que for, irei."}], "reviewed": false}, {"number": 309, "title": "Consagrando-nos", "page": 165, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Consagrando-nos a ti,\nImplorando tua proteção;\nOh, presente sê aqui,\nConcedendo tua direção!"}, {"label": "Estrofe 2", "text": "Cada vez mais e mais\nMostra-nos o teu favor;\nUne-nos em ti, Senhor,\nPelos laços do divino amor."}, {"label": "Estrofe 3", "text": "Através da provação\nGuia sempre, sempre com amor;\nGuarda-nos o coração,\nRevestindo-o sempre de fervor."}, {"label": "Estrofe 4", "text": "Habilita-nos, Senhor,\nOutorgando sempre mais poder;\nAo teu povo, bom Pastor,\nImploramos bênçãos conceder."}], "reviewed": false}, {"number": 310, "title": "Em Teus Braços", "page": 165, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Em teus braços eu me escondo,\nOnde sempre quero estar;\nAo teu lado, protegido,\nEu desejo caminhar.\nInimigos me perseguem,\nEu sucumbo, ó Salvador!\nMuito aflito te suplico:\nAuxilia-me, Senhor!"}, {"label": "Estrofe 2", "text": "Em teus braços eu me escondo,\nOnde sempre quero estar;\nAo teu lado, protegido,\nEu desejo caminhar."}, {"label": "Estrofe 3", "text": "Em teus braços eu me escondo,\nPois sem ti não posso andar;\nCom o coração aflito\nVenho a ti para implorar:\nOh, escuta, Cristo, os rogos\nQue te faço com fervor!\nDá-me abrigo nos teus braços,\nE protege-me, Senhor!"}, {"label": "Estrofe 4", "text": "Em teus braços eu me escondo,\nOnde possa repousar\nA minha alma tão cansada\nE um abrigo possa achar.\nJá eu creio que me atendes,\nEu confio em ti, Senhor;\nNos teus braços abrigado,\nBem seguro estou, Senhor!"}], "reviewed": false}, {"number": 311, "title": "Confiança", "page": 166, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sobre a cruz, por meus pecados,\nQuis Jesus por mim morrer.\nEm Jesus refugiado,\nNada tenho que temer."}], "reviewed": false}, {"number": 312, "title": "Amparo", "page": 166, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Nas agruras desta vida,\nNo descanso e no labor,\nDá-me força na fadiga\nE protege-me, Senhor!"}, {"label": "Estrofe 2", "text": "Os malvados me detestam\nE me querem destruir;\nMas os anjos me rodeiam,\nNão me deixam secumbir."}, {"label": "Estrofe 3", "text": "Inda que satã me assalte,\nVacilar não poderei;\nInda que o poder me falte,\nPor Jesus eu vencerei."}, {"label": "Estrofe 4", "text": "Quando o mal vier na vida,\nForte e rijo me assaltar,\nMeu Jesus, na minha lida,\nCerto me há de sustentar."}, {"label": "Estrofe 5", "text": "Ó Jesus, vem proteger-me,\nGuarda-me, por compaixão!\nÓ Jesus, vem defender-me,\nSê tu minha salvação!"}], "reviewed": false}, {"number": 313, "title": "Proteção Divina", "page": 167, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ao crente é dada proteção\nDe Deus, seu Benfeitor;\nConforto dá ao coração\nDo triste pecador.\nTambém amparo sempre dá\nA quem com fé pedir;\nSeu braço forte estenderá\nA quem o mal ferir."}, {"label": "Estrofe 2", "text": "Oh, que grandioso amor\nTem o bom Redentor!\nConcede-nos sem cessar\nTão ricos dons gozar."}, {"label": "Estrofe 3", "text": "Jesus, sim, recompensará\nA todo vencedor;\nMas ante os anjos negará\nO indigno traidor.\nAvante, então, ó campeões,\nNa luta, pois, entrai;\nMantendo firmes convicções,\nPor Cristo trabalhai!"}, {"label": "Estrofe 4", "text": "Ele nos guadará,\nSempre nos guiará,\nE vida celestial\nTeremos afinal."}], "reviewed": false}, {"number": 314, "title": "Estou Seguro", "page": 167, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que consolação tem meu coração,\nDescansando no poder de Deus;\nEle tem prazer em me proteger;\nDescansando no poder de Deus."}, {"label": "Estrofe 2", "text": "Descansando\nNos eternos braços do meu Deus,\nVou seguro,\nDescansando no poder de Deus."}, {"label": "Estrofe 3", "text": "Sempre avante vou, bem contente estou,\nDescansando no poder de Deus;\nTudo hei de vencer pelo seu poder,\nDescansando no poder de Deus."}, {"label": "Estrofe 4", "text": "Não recearei, nada temerei,\nDescansando no poder de Deus;\nGozo paz e amor junto a meu Senhor,\nDescansando no poder de Deus."}, {"label": "Estrofe 5", "text": "Lutas sem cessar hei de atravessar,\nDescansando no poder de Deus;\nNão me deixará, mas me susterá,\nDescansando no poder de Deus."}], "reviewed": false}, {"number": 315, "title": "Meu Clamor", "page": 168, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Neste mundo, mar profundo,\nNão me deixes perecer;\nSê comigo, bom Amigo,\nÓ Jesus, eterno Ser!\nDesta vida minha ida\nPouco tardará a chegar;\nE, entretanto, Cristo santo,\nGuarda-me pra não pecar."}, {"label": "Estrofe 2", "text": "Deus clemente, onipotente,\nLivra-me da perdição,\nE que goze eternamente\nDa celeste habitação;\nQue minha alma em doce calma,\nFrua teu imenso amor;\nE, exaltando-te, louvando,\nViva sempre, Redentor."}, {"label": "Estrofe 3", "text": "Meu Jesus, ó meu bom Mestre,\nSê meu Guia e Protetor;\nNesta vida, triste lida,\nDá amparo ao pecador!\nHumilhado, consternado,\nTe dirijo o meu clamor;\nEm tormentos, meus lamentos\nOh, escuta bom Senhor!"}], "reviewed": false}, {"number": 316, "title": "Deus É Por Mim", "page": 168, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "É Deus por mim; não temo\nO mundo e seu furor;\nMinha alma está segura,\nNa graça do Senhor.\nSou pelo Rei amado,\nO meu amigo é Deus.\nE raivem inimigos,\nValido sou dos céus."}, {"label": "Estrofe 2", "text": "Firmado na esperança\nDo Salvador Jesus,\nPor ele assegurado,\nJamais me falta luz;\nNele é que me glorio,\nEu, triste pecador;\nSeu sangue mui precioso\nTem divinal valor."}, {"label": "Estrofe 3", "text": "Se Deus me justifica,\nQuem me condenará?\nDo grande amor de Cristo\nNinguém me apartará;\nA morte, a vida, os homens,\nTristeza e tentação,\nEm vão procuram todos\nRomper esta união."}, {"label": "Estrofe 4", "text": "Celeste luz me inunda\nDe paz e salvação;\nDe santo regozijo\nMe pulsa o coração;\nO sol que me ilumina\nÉ Cristo, o meu Senhor;\nO gozo que me alegra\nÉ seu constante amor."}, {"label": "Estrofe 5", "text": "Aleluia! Aleluia!\nO meu amigo é Deus!\nAleluia! Aleluia!\nValido sou dos céus!"}], "reviewed": false}, {"number": 317, "title": "Abrigo", "page": 169, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Refúgio Cristo sempre dá,\nRefúgio, sim, de todo mal;\nQuem nele crer escapará\nDe tudo quanto é infernal."}, {"label": "Estrofe 2", "text": "Sim, Cristo é nosso abrigo no temporal,\nNo temporal, no temporal,\nSim, Cristo é nosso abrigo no temporal,\nE guarda-nos de todo o mal."}, {"label": "Estrofe 3", "text": "Embora ruja o temporal,\nEu sei que não me alcançará!\nSeguro estou no vendaval;\nAbrigo meu Jesus será."}, {"label": "Estrofe 4", "text": "Enfim o mundo gozará\nBonança após a inquietação;\nPois só Jesus concederá\nSossego e paz ao coração."}], "reviewed": false}, {"number": 318, "title": "Deus me Esconde", "page": 170, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quando a tempestade ruge,\nQuando vem o furacão,\nEm Jesus abrigo tenho\nSob a sua proteção."}, {"label": "Estrofe 2", "text": "Mesmo que sofrer eu venha,\nDeus o permite para o bem.\nEm amor e não em ira,\nO castigo seu nos vem."}, {"label": "Estrofe 3", "text": "Inimigos me perseguem,\nSatanás me quer vencer,\nMas Jesus é poderoso\nPara bem me defender."}, {"label": "Estrofe 4", "text": "Minha cruz vou carregando\nNesta peregrinação;\nNas maiores tempestades\nCristo dá-me proteção."}, {"label": "Estrofe 5", "text": "Jesus Cristo me resguarda\nOnde o mal jamais me atinge;\nJesus Cristo me conserva\nSob sua proteção."}], "reviewed": false}, {"number": 319, "title": "Abrigo Perfeito", "page": 170, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Deus é meu abrigo em todo vendaval;\nNele tenho, pois, toda proteção;\nVivo confiando em seu poder real,\nSem qualquer perturbação."}, {"label": "Estrofe 2", "text": "Deus me guiará, guiará,\nSim, Deus me guiará;\nDeus me guardará,\nO meu Deus me guardará!"}, {"label": "Estrofe 3", "text": "Os perigos que me cercam muitos são,\nFortes tentações assaltar-me vêm;\nHostes infernais formadas sempre estão,\nCombatendo todo bem!"}, {"label": "Estrofe 4", "text": "O meu Deus não me abandonará, porém,\nOnde o mal poder tenha de atacar;\nEle me protege como lhe convém,\nNunca irei desanimar!"}, {"label": "Estrofe 5", "text": "Eu guardado estou, andando em seu amor,\nAbrigado em seu divinal poder;\nSim, prossigo vitorioso, sem pavor,\nPor não ter o que temer!"}], "reviewed": false}, {"number": 320, "title": "Abrigo Feliz", "page": 171, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Abrigado em meu Jesus, há descanso e paz.\nTenho alívio quando aflito,\nPaz dará se estou contrito,\nAbrigado em meu Jesus, há descanso e paz.\nConfiando em seu amor, tenho paz."}, {"label": "Estrofe 2", "text": "Tenho paz e perdão e prazer,\nAbrigado no Senhor;\nTenho paz e perdão e prazer,\nConfiando em seu amor. ( bis )"}, {"label": "Estrofe 3", "text": "Garantido por Jesus, há perdão, perdão;\nHá perdão real, perfeito\nE poder pra andar direito;\nGarantido por Jesus, há perdão, perdão.\nConfiando em seu amor, há perdão."}, {"label": "Estrofe 4", "text": "Trabalhando por Jesus, há prazer, prazer;\nÉ prazer contra a história\nDe Jesus, o Rei da glória;\nTrabalhando por Jesus, há prazer, prazer;\nConfiando em seu amor, há prazer."}], "reviewed": false}, {"number": 321, "title": "Abrigo Seguro", "page": 171, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Confio só em ti, Jesus, meu Salvador;\nEm quem, senão em ti, descansarei, Senhor?\nÉ só no teu excelso amor\nQue tenho abrigo, ó meu Senhor!"}, {"label": "Estrofe 2", "text": "Eu pobre escravo fui, mas tu, ó meu Jesus,\nDo jugo que senti livraste-me na cruz;\nE, preso pelo teu amor,\nAgora sirvo a ti, Senhor!"}, {"label": "Estrofe 3", "text": "O dia alegre vem, o Amado voltará,\nE então a vida além minha alma gozará;\nEu com Jesus descansarei,\nE seu louvor entoarei."}], "reviewed": false}, {"number": 322, "title": "Cristo Valerá", "page": 172, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oscilando minha fé,\nCristo valerá;\nPerseguido, sem mercê,\nEle valerá."}, {"label": "Estrofe 2", "text": "Ele valerá! Ele valerá!\nSeu amor por mim não muda,\nSim, me valerá. ( bis )"}, {"label": "Estrofe 3", "text": "Crente inútil eu serei\nSe me não valer;\nNem serviço prestarei\nSem o seu poder."}, {"label": "Estrofe 4", "text": "Com seu sangue me comprou,\nNão me deixará;\nVida eterna me outorgou,\nSim, me valerá."}], "reviewed": false}, {"number": 323, "title": "Castelo Forte", "page": 172, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Castelo forte é nosso Deus,\nEspada e bom escudo;\nCom seu poder defende os seus\nEm todo transe agudo.\nCom fúria pertinaz\nPersegue Satanás,\nCom artimanhas tais,\nE astúcias tão cruéis,\nQue iguais não há na terra."}, {"label": "Estrofe 2", "text": "A nossa força nada faz;\nEstamos, sim, perdidos;\nMas nosso Deus socorro traz\nE somos protegidos,\nDefende-nos Jesus,\nO que venceu na cruz,\nSenhor dos altos céus;\nE, sendo o próprio Deus,\nTriunfa na batalha."}, {"label": "Estrofe 3", "text": "Se nos quisessem devorar\nDemônios não contados,\nNão nos podiam assustar,\nNem somos derrotados.\nO grande acusador\nDos servos do Senhor\nJá condenado está;\nVencido, cairá\nPor uma só palavra."}, {"label": "Estrofe 4", "text": "Sim, que a palavra ficará,\nSabemos com certeza,\nE nada nos assustará\nCom Cristo por defesa.\nSe temos de perder\nOs filhos, bens, mulher,\nEmbora a vida vá,\nPos nós Jesus está,\nE dar-nos-á seu reino."}], "reviewed": false}, {"number": 324, "title": "Refúgio Verdadeiro", "page": 173, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Seguro estou, não tenho temor do mal;\nSim, guardado pela fé em meu Jesus,\nNão posso duvidar desse amor leal;\nEle em meu caminho sempre me conduz.\nNão me deixará, mas me abrigará,\nDo pecado vil me vem livrar.\nA sua graça não me recusará;\nSim Jesus é quem me pode sustentar."}, {"label": "Estrofe 2", "text": "No poder de Cristo, o Mestre,\nMinha vida salva está!\nDo perigo que cercá-la\nEle poderá livrá-la;\nSeu poder eterno sempre a susterá."}, {"label": "Estrofe 3", "text": "Abrigo eterno tenho no Salvador;\nEle esconde a minha vida em seu poder;\nEu recear não posso do malfeitor\nQue procura pertinaz me enfraquecer.\nConfiando, então, nessa proteção,\nSigo a Cristo e quero ser fiel\nNa minha vida, cheio de gratidão,\nSim, a meu Senhor e Rei Emanuel."}, {"label": "Estrofe 4", "text": "Perigo algum me pode causar temor,\nPois meu Salvador não me abandonará;\nCom sua proteção e com seu amor,\nDirigindo a minha vida ele estará.\nNunca o deixarei, mas fiel serei,\nSempre firme, cheio de fervor;\nA Cristo, Redentor, meu Senhor e Rei,\nEu me entregarei, firmado em seu amor."}], "reviewed": false}, {"number": 325, "title": "Naufrágio", "page": 174, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Uma barca naufragando,\nQuem a valerá?\nAfundando está no abismo,\nQuem a salvará?"}, {"label": "Estrofe 2", "text": "Já desfaleceu o nauta,\nVê-se a perecer,\nE suplica muito ansioso:\n'Venham me valer!'"}, {"label": "Estrofe 3", "text": "É revolto o mar da vida\nPara o viajor;\nAo clamar, porém, socorre-o\nCristo, o Salvador."}, {"label": "Estrofe 4", "text": "Enfrentando a negra morte,\nCheio de pavor,\nFoi que Cristo quis salvar-te,\nPobre pecador."}, {"label": "Estrofe 5", "text": "Naufragante, escuta\nTeu bom Salvador:\n'Eis-me pronto pra salvar-te;\nConfia, e deixa teu temor.'"}], "reviewed": false}, {"number": 326, "title": "Refúgio", "page": 174, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Meu divino Protetor.\nQuero em ti me refugiar;\nPois a ondas de terror\nAmeaçam me tragar!\nQuase estou a perecer!\nDá-me a tua proteção;\nPois guardado em teu poder\nNão receio o furacão."}, {"label": "Estrofe 2", "text": "Outro amparo não achei;\nSem alento venho a ti;\nSe me negas morrerei;\nVoz da morte eu já ouvi.\nEu confio em teu amor\nE na tua compaixão;\nÉs meu forte defensor;\nNão me largue a tua mão."}, {"label": "Estrofe 3", "text": "Tudo o que eu desejo dás,\nCristo meu, e ainda mais;\nDás-me força e tua paz,\nSempre tu comigo vais.\nO teu nome santo é\nE eu injusto e fraco sou;\nPonho em ti a minha fé,\nSei que em ti seguro estou."}, {"label": "Estrofe 4", "text": "Graça imensa em ti se achou\nPara tudo perdoar;\nSangue teu se derramou,\nNele quero me salvar,\nFonte tu de todo bem,\nDá-me sempre de beber!\nConforta minha alma vem;\nQueiras sempre me valer."}], "reviewed": false}, {"number": 327, "title": "O Piloto", "page": 175, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Guia, Cristo, minha nau\nSobre o revoltoso mar;\nTão enfurecido e mau,\nQuer fazê-la naufragar.\nVem, Jesus, oh, vem guiar,\nMinha nau vem pilotar!"}, {"label": "Estrofe 2", "text": "Como sabe serenar\nBoa mãe o filho seu,\nVem, acalma, assim, o mar,\nQue se eleva até o céu.\nVem, Jesus, oh, vem guiar,\nMinha nau vem pilotar!"}, {"label": "Estrofe 3", "text": "Se no porto, quando entrar,\nMais o mar se enfurecer,\nQue me possa deleitar\nEm ouvir Jesus dizer:\n'Entra, pobre viajor,\nNo descanso do Senhor.'"}], "reviewed": false}, {"number": 328, "title": "Sossegai", "page": 176, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó Mestre, o mar se revolta,\nAs ondas não dão pavor;\nO céu se reveste de trevas,\nNão se te dá que morramos?\nPodes assim dormir,\nSe a cada momento nos vemos,\nSim, prestes a submergir?"}, {"label": "Estrofe 2", "text": "Mestre, na minha tristeza\nEstou quase a sucumbir;\nA dor que pertuba minha alma,\nEu peço-te, vem banir!\nDe ondas do mal que me encobrem,\nQuem me fará sair?\nPereço sem ti, ó meu Mestre!\nVem logo, vem me acudir!"}, {"label": "Estrofe 3", "text": "Mestre, chegou a bonança,\nEm paz eis o céu e o mar!\nO meu coração goza calma,\nQue não poderá findar.\nFica comigo, ó meu Mestre,\nDono da terra e céu,\nE assim chegarei bem seguro\nAo porto, destino meu."}, {"label": "Estrofe 4", "text": "As ondas atendem ao meu mandar:\nSossegai!\nSeja o encapelado mar,\nA ira dos homens, o gênio do mal,\nTais águas não podem a nau tragar,\nQue leva o Senhor, Rei do céu e mar,\nPois todos ouvem o meu mandar:\nSossegai! Sossegai!\nConvosco estou para vos salvar;\nSim, sossegai!"}], "reviewed": false}, {"number": 329, "title": "Conta as Bênçãos", "page": 176, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se com desalento julgas tudo vão,\nConta as muitas bênçãos, dize-as de uma vez,\nHás de ver, surpreso, quanto Deus já fez."}, {"label": "Estrofe 2", "text": "Conta as bênçãos, conta quantas são,\nRecebidas da divina mão;\nUma a uma, dize-as de uma vez,\nHás de ver, surpreso, quanto Deus já fez."}, {"label": "Estrofe 3", "text": "Tens, acaso, mágoas, triste é teu lidar?\nÉ a cruz pesada que tens de levar?\nConta as muitas bênçãos, não duvidarás,\nE em canção alegre os dias passarás."}, {"label": "Estrofe 4", "text": "Quando vires outros com seu ouro e bens,\nLembra que tesouro prometidos tens;\nNunca os bens da terra poderão comprar\nA mansão celeste em que tu vais morar."}, {"label": "Estrofe 5", "text": "Seja teu conflito fraco ou forte cá,\nNão te desanimes, Deus por cima está;\nSeu divino auxílio, minorando o mal,\nTe dará consolo e paz celestial."}], "reviewed": false}, {"number": 330, "title": "O Segredo do Viver", "page": 177, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quando nos cercar o mal,\nAo rugir o temporal,\nEm Jesus é confiar,\nNunca poderá falhar."}, {"label": "Estrofe 2", "text": "Quando a dor ou aflição\nVem turbar o coração,\nÉ preciso confiar,\nA Jesus tudo entregar."}, {"label": "Estrofe 3", "text": "Quando fraco me sentir,\nQuando o mundo me oprimir,\nE pesar a minha cruz,\n'Crê somente!' - Diz Jesus."}, {"label": "Estrofe 4", "text": "Quer nas trevas, quer na luz,\nSempre perto está Jesus,\nPerto e pronto pra salvar\nQuem somente confiar."}, {"label": "Estrofe 5", "text": "O segredo do viver,\nO segredo do vencer,\nÉ em Cristo confiar!\nNunca, nunca duvidar!"}], "reviewed": false}, {"number": 331, "title": "Glória No Porvir", "page": 178, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Temos sombras neste vale,\nEm que estamos a passar;\nMas das águas cristalinas\nJá se vê o marulhar.\nEis que o bom Pastor segreda,\nAjudando a prosseguir:\nHá, sim, sombras neste vale,\nMas há glória no porvir."}, {"label": "Estrofe 2", "text": "Glória no porvir!\nGlória eterna no porvir!\nHá, sim, sombras neste vale,\nMas há glória no porvir."}, {"label": "Estrofe 3", "text": "Temos sombras neste vale,\nMas fragrâncias ao derredor;\nPois as rosas da montanha\nNos transmitem sei olor.\nO bom Mestre nos anima\nNa subida a prosseguir:\nHá, sim, sombras neste vale,\nMas há glória no porvir."}, {"label": "Estrofe 4", "text": "Mas as sombras deste vale,\nDe uma vez se desfarão,\nCom a vinda mui gloriosa\nDo Senhor da criação.\nEia, pois, ó vós, remidos,\nEscutai-o a repetir:\nHá, sim, sombras neste vale,\nMas há glória no porvir."}], "reviewed": false}, {"number": 332, "title": "Meu Senhor de Tudo Sabe", "page": 178, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Meu Senhor de tudo sabe,\nCertamente, sim;\nCom cuidados incansáveis\nMe protege a mim.\nTudo quanto Deus permite,\nPra meu bem será,\nE, no dia mais penoso,\nForças Deus dará.\nSei que Deus o meu futuro\nTem na sua mão;\nSeus desvelos compassivos\nIncessantes são.\nInda que eu mais tarde encontre\nProvações e dor,\nPor detrás das negras nuvens\nBrilha seu amor."}, {"label": "Estrofe 2", "text": "Gosto de contar-lhe quanto\nMe sucede aqui;\nSou seu filho e quer que esteja\nSempre junto a si,\nPara que seus bons cuidados\nPossa aqui gozar,\nDando graças por aquilo\nQue me queira dar."}, {"label": "Estrofe 3", "text": "Oh, sim, confiadamente\nQuero prosseguir,\nSem receios, nem cuidados\nQuanto ao meu porvir;\nPois que Deus, meu Pai, me assiste\nCom divino amor,\nSendo aquele que me guia\nCristo, o Salvador."}], "reviewed": false}, {"number": 333, "title": "Deus É Sabedor", "page": 179, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu sei que Deus é sabedor\nDo meu sofrer, da minha dor;\nMas sei também que o meu penar\nEm gozo pode transformar."}, {"label": "Estrofe 2", "text": "Meu Deus, meu Pai,\nMeu Deus de tudo é sabedor.\nSim, Deus, meu Pai,\nVem minorar a minha dor."}, {"label": "Estrofe 3", "text": "Eu sei que Deus é sabedor\nQue fui um grande pecador;\nMas com poder e compaixão\nLivrou-me da destruição."}, {"label": "Estrofe 4", "text": "Eu sei que Deus é sabedor\nDas minhas faltas, meu temor;\nMas pronto está pra me valer,\nDe todo o mal me protege."}], "reviewed": false}, {"number": 334, "title": "Alívio", "page": 180, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vem, alma cansada, tomada de dor,\nEntrega os cuidados na mão do Senhor;\nA Cristo confia teu grande pesar,\nPois nele descanso tu podes achar."}, {"label": "Estrofe 2", "text": "As mágoas, desgostos, revela ao Senhor,\nNão, oh, não receies vir tudo lhe expor;\nDo mal que te oprime te pode curar;\nJesus tem desejo de te confortar."}, {"label": "Estrofe 3", "text": "Se tu provaste tal consolação,\nVai, leva a mensagem de paz e perdão\nÀs almas aflitas, opressas de dor;\nVai, traze os contritos aos pés do Senhor."}], "reviewed": false}, {"number": 335, "title": "O Gozo da Vida", "page": 180, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo amado, sei que na força do mal\nTu, meu Mestre, sempre serás protetor.\nTu me guardas, dando-me paz divinal;\nEu contigo sempre serei vencedor!"}, {"label": "Estrofe 2", "text": "Cristo, Mestre,\nSei que contigo sou vencedor;\nDá-me graça,\nDá-me do teu poder, Redentor."}, {"label": "Estrofe 3", "text": "Que alegria tenho no meu Salvador;\nTenho graça, vida de amor paternal!\nTudo posso, tudo, por ti, meu Senhor;\nDeste mundo sou vencedor afinal!"}, {"label": "Estrofe 4", "text": "Não duvido, Cristo, meu Mestre, de ti;\nCreio em tua rica promessa, Jesus;\nNão me deixes, nem me rejeites aqui,\nQuero sempre ver tua face de luz!"}, {"label": "Estrofe 5", "text": "Oh, que bênção ter a certeza do bem,\nTer na vida paz e perdão do Senhor!\nMui alegre, busco essa pátria de além,\nOnde reina Cristo Jesus, Rei de amor!"}], "reviewed": false}, {"number": 336, "title": "Fonte de Consolação", "page": 181, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Alma, que aflita estás, Deus, Pai bondoso,\nEm compaixão e amor, tem o poder\nDe te livrar do mal e dar-te gozo,\nE sem demora em Jesus te esconder."}, {"label": "Estrofe 2", "text": "Ó meu irmão, se tens grandes tormentos,\nLembra-te, então, de Deus, teu Protetor;\nEle te livrará desses lamentos;\nSó ele pode sarar tua dor."}, {"label": "Estrofe 3", "text": "Se pesaroso estás em tua vida,\nBusca o teu Salvador, Cristo Jesus.\nEle com muito amor já te convida,\nCristo te ajuda a levar tua cruz."}, {"label": "Estrofe 4", "text": "Oh, que consolação temos em Cristo,\nPois da tristeza Deus nos livrará!\nSempre sustenta os seus; somos benquistos,\nEle nos ama e nos protegerá."}], "reviewed": false}, {"number": 337, "title": "Nada de Desânimo", "page": 181, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Queres desanimar-te?\nJá não tens teu fervor?\nDe coração pesado,\nNão crês em teu Senhor?\nPois Cristo é teu Amigo,\nTeu Guia e Protetor;\nDe tudo que cereces\nTe supre seu favor."}, {"label": "Estrofe 2", "text": "Exulta, ó crente, exulta!\nAo Salvador bendiz!\nPor ele protegido,\nÉs livre e és feliz."}, {"label": "Estrofe 3", "text": "Sendo, porém, tentado,\nPrestes a sucumbir,\nTurvo o teu horizonte,\nMui feio o teu porvir,\nProcura já chegar-te\nBem junto ao Salvador,\nPois tudo te garante\nTeu Guia e Protetor.\n\"Nunca se turbe, ó crente,\nTeu triste coração!\"\nEis com ternura exclama\nQuem te deu salvação:\n\"Confia em mim somente,\nSomente em meu poder;\nE nas mansões eternas\nComigo irás viver.\""}], "reviewed": false}, {"number": 338, "title": "Redentor", "page": 182, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sei que vive o Redentor,\nSei que há vida em seu favor,\nQue, se aqui na cruz morreu,\nReina em glória lá no céu."}, {"label": "Estrofe 2", "text": "Vive para interceder\nE nas lutas me valer;\nVive pra me sustentar\nE do mal me resguardar."}, {"label": "Estrofe 3", "text": "Deus me livra de temor,\nMinorando a minha dor;\nA tristeza me desfaz,\nDá-me gozo, vida e paz."}, {"label": "Estrofe 4", "text": "Vive! Hosanas eu lhe dou!\nVive Reina! E salvos eu sou!\nVivo nele, o Redentor,\nSempre firme em seu amor!"}], "reviewed": false}, {"number": 339, "title": "Não Consintas", "page": 182, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, não consintas tristezas\nDentro do teu coração;\nTendo fé firme no Mestre,\nSegue-o sem hesitação."}, {"label": "Estrofe 2", "text": "Não consentir! Não consentir\nQue qualquer dor ou tristeza\nVenha apagar teu amor!\nOh, não temer! Nunca ceder!\nEm teus apertos te lembra\nQue Cristo é teu Protetor."}, {"label": "Estrofe 3", "text": "Se por acaso desgostos\nVierem trazer-te temor,\nNunca te esqueças de Cristo,\nQue é teu maior Protetor."}, {"label": "Estrofe 4", "text": "Deixa, pois, tua tristeza,\nToda incerteza e temor;\nPaz e prazer tu em breve\nReceberás do Senhor."}], "reviewed": false}, {"number": 340, "title": "Importará", "page": 183, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Importará ao Senhor Jesus\nQue eu viva no mundo a ter\nO meu coração cheio de aflição?\nSentirá meu triste viver?"}, {"label": "Estrofe 2", "text": "Oh, sim, eu sei, Jesus bem vê\nO que eu estou a sofrer;\nEm cruel peleja, pavor, inveja\nJesus me quer valer."}, {"label": "Estrofe 3", "text": "Importará ao Senhor Jesus\nQue eu viva com dissabor,\nPor andar sem luz, que me vem da cruz?\nSentirá, pois, meu Salvador?"}, {"label": "Estrofe 4", "text": "Importará ao Senhor Jesus\nQue eu caia na tentação?\nSe Satã puder minha fé vencer,\nMe dará de novo o perdão?"}, {"label": "Estrofe 5", "text": "Importará ao Senhor Jesus\nSe a morte ferir meu lar?\nE que diga aDeus aos queridos meus\nSentirá Jesus? Pessará?"}], "reviewed": false}, {"number": 341, "title": "Socorro Divino", "page": 183, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "No meu viver é ajudador\nMeu Pai dos céus, meu bom Senhor;\nA minha vida toda vê,\nE quer fazer-me bem, eu sei."}, {"label": "Estrofe 2", "text": "As minhas lutas Ele vê,\nE sempre ajuda por mercê;\nDo meu pesar é sabedor,\nE logo vem me dar vigor.\nOh, quer-me bem, sim, quer-me bem!\nEm compaixão valer-me vem;\nNa minha dor e dissabor\nMeu Pai vigia com amor."}, {"label": "Estrofe 3", "text": "As culpas e fraquezas vê,\nOs erros contra sua lei;\nNão tarda a vir com seu perdão\nO grande Deus de compaixão."}, {"label": "Estrofe 4", "text": "Vai, pois, buscar, ó meu irmão,\nDivina paz em aflição;\nDe todo mal te livrará\nO teu Senhor, que perto está."}], "reviewed": false}, {"number": 342, "title": "A Minha Cruz", "page": 184, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A cruz que me deu Jesus Cristo\nFortalece o meu amor;\nAs dores que sempre me ferem\nNão me apartam do Senhor."}, {"label": "Estrofe 2", "text": "A cruz que me deu para eu levar,\nAs dores que a mim vêm assaltar,\nNão escondem meu Jesus,\nPois eu ando em sua luz;\nVou vencendo para os céus."}, {"label": "Estrofe 3", "text": "O mundo a meu Mestre despreza,\nE persegue os de Jesus;\nMas por seu amor, pela graça,\nLevarei a minha cruz."}, {"label": "Estrofe 4", "text": "Fazer a vontade de Cristo\nEu desejo sempre, sim;\nContando eu a tão bela história\nTenho gozo e paz sem fim."}], "reviewed": false}, {"number": 343, "title": "Sempre Firme", "page": 184, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Minha morada, Jesus, assegura,\nPaz e conforto na luta feroz;\nDá-me teu braço, transporta-me à altura\nOnde escutar poderei tua voz."}, {"label": "Estrofe 2", "text": "Vem dar-me paz, ó meu Jesus,\nDá-me teu braço, ó Cristo!\nVou perecendo longe da cruz,\nE eu em clamar insisto!"}, {"label": "Estrofe 3", "text": "Triste, procuro refúgio ao teu lado,\nVolta-me a paz, o descanso me vem;\nQuando na terra me achar desprezado\nGlória terei noutra pátria de além."}, {"label": "Estrofe 4", "text": "Quando da morte cercar-me a tristeza,\nFinda a jornada do mundo cruel,\nCerto terei nesse dia a certeza\nDe ir me alegrar sob imenso docel."}], "reviewed": false}, {"number": 344, "title": "Deus Cuidará de Ti", "page": 185, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Aflito e triste coração,\nDeus cuidará de ti;\nPor ti opera a sua mão,\nQue cuidará de ti."}, {"label": "Estrofe 2", "text": "Deus cuidará de ti,\nEm cada dia proverá;\nSim, cuidará de ti,\nDeus cuidará de ti."}, {"label": "Estrofe 3", "text": "Na dor cruel, na provação,\nDeus cuidará de ti;\nSocorro dá e salvação,\nPois cuidará de ti."}, {"label": "Estrofe 4", "text": "A tua fé Deus quer provar,\nMas cuidará de ti;\nO teu amor quer aumentar,\nE cuidará de ti."}, {"label": "Estrofe 5", "text": "Nos seus tesouros tudo tens,\nDeus cuidará de ti;\nTerrestres e celestes bens,\nE cuidará de ti."}, {"label": "Estrofe 6", "text": "O que é mister te pode dar\nQuem cuidará de ti;\nNos braços seus te sustentar,\nPois cuidará de ti."}], "reviewed": false}, {"number": 345, "title": "Contar a Jesus", "page": 185, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A Jesus Cristo contarei tudo\nQue haja em meu peito a me perturbar;\nOs meus cuidados, meus sofrimentos,\nSó Ele os pode suavizar."}, {"label": "Estrofe 2", "text": "A Jesus Cristo, meu Bem-Amado,\nNarrarei sempre minha aflição;\nAos meus cuidados, aos meus tormentos,\nSó Ele pode dar solução."}, {"label": "Estrofe 3", "text": "A Jesus Cristo contarei tudo;\nEle é Amigo firme e leal.\nBasta pedir-lhe, que, sem demora,\nAos meus pesares dá fim cabal."}, {"label": "Estrofe 4", "text": "Sempre tentado, sei que preciso\nDe um protetor que possa valer;\nSó meu Amado, que é invencível,\nPode, portanto, me proteger."}, {"label": "Estrofe 5", "text": "Deste caminho os maus me desejam,\nPois, desviar e me demover;\nMas Jesus Cristo, forte e zeloso,\nSempre me ajuda a permanecer."}], "reviewed": false}, {"number": 346, "title": "Meu Deus Proverá", "page": 186, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Na forte aflição, nos perigos e dor,\nNa vil traição e no negro terror,\nCom toda a certeza vitória virá;\nÉ firme a promessa: 'Meu Deus proverá.'\n'Meu Deus proverá, meu Deus proverá.'\nÉ firme a promessa: 'Meu Deus proverá.'"}, {"label": "Estrofe 2", "text": "Às aves do céu dá sustento o bom Deus,\nE com mais prazer Ele cuida dos seus,\nPois nada de bom aos fiéis faltará;\nQue grande verdade: 'Meu Deus proverá.'\n'Meu Deus proverá, meu Deus proverá.'\nQue grande verdade: 'Meu Deus proverá.'"}, {"label": "Estrofe 3", "text": "Se vem Satanás e nos quer assustar\nCom medo falaz para a fé nos tirar,\nNão pode; que é nossa e pra sempre será\nA rica promessa: 'Meu Deus proverá.'\n'Meu Deus proverá, meu Deus proverá.'\nA rica promessa: 'Meu Deus proverá.'"}, {"label": "Estrofe 4", "text": "A nossa virtude Ele pode aumentar;\nJesus nos ajuda a vitória a ganhar;\nDo vil inimigo nos esconderá;\nCom grande largueza: 'Meu Deus proverá'.\n'Meu Deus proverá, meu Deus proverá.'\nCom grande largueza: 'Meu Deus proverá.'"}, {"label": "Estrofe 5", "text": "Na hora final, quando a morte chegar,\nA voz do Senhor só nos há de alegrar;\nE mesmo na morte eu hei de cantar\nCom plena certeza: 'Meu Deus proverá.'\n'Meu Deus proverá, meu Deus proverá.'\nCom plena certeza: 'Meu Deus proverá.'"}], "reviewed": false}, {"number": 347, "title": "O Coração Em Paz", "page": 187, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vindo sombras escuras nos caminhos teus,\nOh, não te desanime! Canta um hino a Deus!\nCada nuvem escura um arco-íres traz\nQuando em teu coração reinar perfeita paz."}, {"label": "Estrofe 2", "text": "Se teu coração estiver em paz\nBem contentee alegre sempre te acharás.\nSe teu coração estiver em paz\nVerás que um arco-íres cada nuvem traz."}, {"label": "Estrofe 3", "text": "Se o viver é de lutas, cheio de amargor,\nMostra afeto aos aflitos, age em seu favor,\nE de tudo o que sofres tu te esquecerás;\nFruirás gozo e calma, se tiveres paz."}, {"label": "Estrofe 4", "text": "Vem após negra noite a aurora matinal;\nFica o céu mais brilhante após o temporal!\nA esperança não percas, tudo vencerás!\nFugirão as tristezas, se tiveres paz."}], "reviewed": false}, {"number": 348, "title": "Confiando", "page": 187, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Confiando em meu Jesus,\nDele vêm-me paz e luz;\nQuando vem a provação,\nEle dá-me sua mão."}, {"label": "Estrofe 2", "text": "Dá-nos o Consolador,\nQue nos enche de fervor,\nE não deixa tropeçar\nQuando o tentador chegar."}, {"label": "Estrofe 3", "text": "E se nele eu confiar,\nPoderei, então, cantar,\nQuando o temporal bater,\nVenha, sim, o que vier!"}, {"label": "Estrofe 4", "text": "Oh, enquanto aqui viver.\nConfiança eu hei de ter!\nQuando a vida terminar,\nLá na glória irei cantar."}, {"label": "Estrofe 5", "text": "Confiemos nele já,\nVencedores nos fará;\nAtravés da provação\nDá-nos força e direção."}], "reviewed": false}, {"number": 349, "title": "Rica Promessa", "page": 188, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh. como é grande e doce a promessa\nDo Salvador, Jesus, nosso Rei!\nAo que confia na sua graça\nEle diz: 'Nunca te deixarei.'"}, {"label": "Estrofe 2", "text": "Oh, não temas, oh, não temas,\nPois eu contigo sempre serei!\nOh, não temas, oh, não temas,\nPois eu nunca te deixarei!"}, {"label": "Estrofe 3", "text": "Eu sou teu Deus e, para livrar-te,\nSempre contigo eu estarei;\nNão temas, pois, porque bem seguro\nEu pela mão te conduzirei"}, {"label": "Estrofe 4", "text": "Para remir-te dei o meu sangue,\nPelo teu nome eu te chamei;\nMeu para sempre tu és agora;\nCrê, pois, que nunca te deixarei."}, {"label": "Estrofe 5", "text": "Eras indigno, mas escolhi-te;\nNão temas, pois eu muito te amei;\nQuem do meu braços pode pode arrancar-te?\nSempre seguro te guardarei."}], "reviewed": false}, {"number": 350, "title": "Quero o Salvador", "page": 188, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quero o Salvador comigo;\nSó com ele eu posso andar;\nQuero conhecê-lo perto,\nNo seu braço descançar."}, {"label": "Estrofe 2", "text": "Quero o Salvador comigo,\nPois tão fraca é minha fé;\nSua voz me dá conforto,\nQuando me vacila o pé."}, {"label": "Estrofe 3", "text": "Quero o Salvador comigo,\nDia a dia em meu viver,\nNa tristeza, no trabalho,\nNo conflito e no prazer."}, {"label": "Estrofe 4", "text": "Quero o Salvador comigo,\nSábio guia e Bom Pastor,\nTé passar além da morte,\nLonge do perigo e dor."}, {"label": "Estrofe 5", "text": "Confiado no Senhor,\nConsolado em seu amor,\nSeguirei no meu caminho,\nSem tristeza e sem temor."}], "reviewed": false}, {"number": 351, "title": "Direção Divina", "page": 189, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "As tuas mãos dirigem meu destino.\nÓ Deus de amor, que sempre seja assim!\nTeus são os meus poderes, minha vida;\nEm tudo, eterno Pai, dispõe de mim.\nMeus dias sejam curtos ou compridos,\nPassados em tristezas ou prazer,\nEm sombra ou luz, é tudo como ordenas\nE eu tenho por bem-vindo o teu querer."}, {"label": "Estrofe 2", "text": "As tuas mãos dirigem meu destino,\nCravadas dantes na sangrenta cruz;\nPor meus pecados foram transpassado\nE posso nelas descansar, Jesus!\nNos céus erguidas, sempre intercedeu\nAs santas mãos não pedirão em vão;\nAo seu cuidado, em plena confiança,\nEntrego a minha eterna salvação."}, {"label": "Estrofe 3", "text": "As tuas mãos dirigem meu destino;\nAcasos para mim não haverá.\nO grande Pai vigia o meu caminho\nE sem motivo não me aflingirá.\nEu tenho em seu poder constante amparo,\nForte é seu braço, imenso o seu amor;\nE em breve, entrando na cidade eterna\nEu louvarei meu guia e Salvador."}], "reviewed": false}, {"number": 352, "title": "Seguindo a Cristo", "page": 190, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sempre, sempre seguirei a Cristo;\nSeja por onde for, eu o seguirei.\nSempre, sempre seguirei a Cristo;\nSeja, pois, por onde for eu seguirei."}], "reviewed": false}, {"number": 353, "title": "Sou Pecador", "page": 190, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó Deus, tu me provaste a mim;\nNinguém se esconderá de ti;\nPrevês para onde quero andar,\nConheces como vou falar."}, {"label": "Estrofe 2", "text": "Sou pecador; dá-me perdão!\nSegura minha débil mão!\nConduz meus fracos pés, Senhor,\nE louvarei meu Benfeitor!"}, {"label": "Estrofe 3", "text": "Eu vivo à luz do teu olhar;\nSenhor, quem poderá sondar\nA ciência tua e teu poder,\nSe é insondável teu saber?"}, {"label": "Estrofe 4", "text": "Nas trevas e na clara luz\nA mão divina me conduz;\nE, se fugindo dela vou,\nDe teu poder cercado estou."}, {"label": "Estrofe 5", "text": "Criaste-me; por tua mão\nFormados os meus membros são;\nAs maravilhas do Senhor\nExcedem muito a meu louvor."}, {"label": "Estrofe 6", "text": "Ó Deus da minha salvação,\nPesquisa, pois, meu coração;\nExpurga-me, se houver em mim\nQualquer ofensa contra ti."}], "reviewed": false}, {"number": 354, "title": "Cada Momento", "page": 190, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sendo remido por Cristo na cruz,\nVivo gozando no reino da luz;\nCheio da graça que vem de Jesus,\nCada momento o Senhor me conduz."}, {"label": "Estrofe 2", "text": "Cada momento me guia o Senhor,\nCada momento dispensa favor,\nSua presença me outorga vigor,\nCada momento sou teu, ó Senhor!"}, {"label": "Estrofe 3", "text": "Junto com Cristo na luta moral,\nO erro combato, os pecados e o mal,\nErgo bem alto a bandeira real,\nCada momento mais firme e leal."}, {"label": "Estrofe 4", "text": "Salvo por Cristo da vil perdição,\nPosso sentir que ele dá proteção;\nNunca os contritos o buscam em vão,\nCada momento concede perdão."}, {"label": "Estrofe 5", "text": "Nas minhas lutas me pode amparar,\nE do maligno também me livrar;\nCada momento por onde eu andar,\nCristo, meu Mestre, me pode guardar."}], "reviewed": false}, {"number": 355, "title": "Luz Benigna", "page": 191, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Na escuridão, oh, brilha, meiga Luz!\nGuiar-me vem!\nNa negra noite brilha e me conduz;\nGuiar-me vem!\nNão peço luz a fim de longe ver:\nSomente luz em cada passo ter."}, {"label": "Estrofe 2", "text": "Em outro tempo não queria luz\nPra me guiar;\nNão quis seguir o que me impõe a cruz:\nQuis vacilar.\nSem luz eu não desejo mais andar;\nOh, vem, Senhor, oh, vem meus pés guiar!"}, {"label": "Estrofe 3", "text": "Guardou-me até aqui o teu poder,\nE guardará;\nTeu braço vai-me ainda defender,\nE guiará.\nE, finda minha vida terreal,\nIrei morar no lar celestial."}], "reviewed": false}, {"number": 356, "title": "Jesus Como Guia", "page": 192, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Meu Jesus me guia sempre\nQue mais posso desejar?\nDuvidar do meu Amado?\nDo meu Deus desconfiar?\nPaz perfeita, gozo infindo\nTenho, e sua proteção;\nPois eu sei que por mim vela\nSeu bondoso coração."}, {"label": "Estrofe 2", "text": "Meu Jesus me guia sempre,\nEnsinando-me a viver,\nConcedendo graça e força\nPara me desenvolver.\nPerecer jamais eu posso,\nPois quem pode resistir\nAo Deus forte, Pai eterno,\nQue minha alma quis remir?"}, {"label": "Estrofe 3", "text": "Meu Jesus me guia sempre,\nPelo seu tão terno amor!\nVida santa, glória eterna\nMe garante o Salvador.\nOh, mui breve vem o dia,\nO da grande redenção,\nQuando salva, transformada,\nHá de ser a criação!"}], "reviewed": false}, {"number": 357, "title": "Guia-me", "page": 192, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Guia-me, meu Salvador;\nSempre me conduz, Senhor;\nCerto, firme e forte estou,\nPois contigo andando vou."}, {"label": "Estrofe 2", "text": "Guia, guia,\nSempre guia, Salvador;\nCom ternura, com amor,\nGuia-me, meu Redentor."}, {"label": "Estrofe 3", "text": "Confiando sempre em Ti,\nBom auxílio consegui;\nOh, dirige-me, Senhor,\nNeste mundo enganador!"}, {"label": "Estrofe 4", "text": "Tu me guiarás a mim,\nTé chegar da vida o fim,\nPara a terra do fulgor,\nNa presença do Senhor."}], "reviewed": false}, {"number": 358, "title": "Não Há Perigo", "page": 193, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Muitos falam dos perigos\nDo caminho em que eu estou;\nMas não vêem a luz que brilha\nAo redor, por onde vou."}, {"label": "Estrofe 2", "text": "Meu Jesus me guia os passos,\nE já veio em mim morar;\nNeste mundo perigoso\nSó por mim não posso andar."}, {"label": "Estrofe 3", "text": "Falam mais de desenganos\nE de dura provação;\nMas Jesus me ampara sempre\nE me dá consolação."}, {"label": "Estrofe 4", "text": "Sei que meu amor é fraco\nE propendo pra pecar;\nMas, com seu divino auxílio,\nHei de sempre triunfar."}], "reviewed": false}, {"number": 359, "title": "Jesus Como Guia", "page": 193, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus me guia, que prazer!\nPalavra de consolação!\nEm todo transe em que estiver,\nMe guia sempre a sua mão."}, {"label": "Estrofe 2", "text": "Às vezes, quando em aflições,\nNo meio de perigo e dor,\nPor água mansa ou bravo mar,\nMe guia a mão do meu Senhor."}, {"label": "Estrofe 3", "text": "Ajuda-me a não murmurar,\nQualquer que for a condição;\nContente vou, pois guiarás\nPor tua mui bondosa mão."}, {"label": "Estrofe 4", "text": "E quando a morte a mim vier\nE a minha vida aqui ceifar,\nPor Ti guardado, meu Senhor,\nContigo espero então morar."}, {"label": "Estrofe 5", "text": "Jesus me guia, que prazer!\nÉ sua mão que me conduz.\nEm cada passo me é mister\nQue me dirija meu Jesus."}], "reviewed": false}, {"number": 360, "title": "Companheiro", "page": 194, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "De teu cuidado terno\nMe cerca, ó Salvador;\nPorque se Tu ao longe estás\nEu fico sem vigor!\nAo pé de Ti desejo,\nMeu Deus, meu Pai, viver,\nE Tua forte mão sentir\nA minha mão suster."}, {"label": "Estrofe 2", "text": "Tu és o meu amparo,\nMeu Guia e Protetor;\nA graça, a paz, reside em Ti,\nEm Ti reside o amor.\nNo auge da ventura\nOu das tribulações,\nTeu santo nome bendirei,\nÓ luz dos corações!"}, {"label": "Estrofe 3", "text": "Sem Ti, Jesus benigno,\nDe que me serve andar\nNum chão florido, ou sobre mim\nO belo sol brilhar?\nSem Ti é sempre noite,\nSenhor, é afrontar,\nEm frágil nau, ou num batel,\nEncapelado mar."}, {"label": "Estrofe 4", "text": "Só Tu da morte as sombras\nPoder tens de afastar,\nE as portas da mansão feliz\nAbrir de par em par.\nA Ti, naquele dia,\nNo dia sem igual,\nCom os remidos cantarei\nO hino triunfal."}], "reviewed": false}, {"number": 361, "title": "Por Mim", "page": 194, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Salvação Jesus me dá;\nCom amor me guiará;\nPara o céu me levará!\nTu não queres a Cristo seguir?\nQue poder me dá Jesus\nPara andar em sua luz\nE levar a minha cruz!\nTu não queres a Cristo seguir?"}, {"label": "Estrofe 2", "text": "Cristo já por mim morreu;\nSua graça concedeu;\nE por mim na cruz venceu.\nTu não queres a Cristo seguir?"}, {"label": "Estrofe 3", "text": "Eu no céu irei morar;\nCom os anjos vou cantar;\nA Jesus irei louvar.\nTu não queres a Cristo seguir?"}, {"label": "Estrofe 4", "text": "Cristo Jesus, meu Salvador,\nVela por mim, vela por mim,\nCristo Jesus, meu Salvador,\nTudo o que é bom fará por mim."}], "reviewed": false}, {"number": 362, "title": "Nunca Sozinho", "page": 195, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Neste mundo sozinho\nNão quero nem posso avançar,\nPois eu sou tão fraquinho,\nNunca me posso guardar;\nMas Jesus vai comigo,\nSempre pronto a salvar,\nPois Ele mesmo promete\nQue nunca irá me deixar."}, {"label": "Estrofe 2", "text": "Nunca me deixar!\nNunca me deixar! (bis)\nPois Ele mesmo promete\nNunca me deixar!"}, {"label": "Estrofe 3", "text": "Inimigos mui fortes\nProcuram minha alma perder;\nE se sozinho andasse,\nQue poderia fazer?\nCom Jesus a meu lado,\nPosso alegre avançar,\nPois Ele mesmo promete\nQue nunca irá me deixar."}, {"label": "Estrofe 4", "text": "Nas tristezas da vida,\nNas dores e nas aflições,\nE no lidar do dia,\nVindo quaisquer tentações,\nCristo sempre comigo\nAnda pra me livrar,\nPois Ele mesmo promete\nQue nunca irá me deixar."}], "reviewed": false}, {"number": 363, "title": "Sê Tu Meu Guia", "page": 196, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sê tu meu Guia, ó Cristo; estou medroso\nDe andar sozinho pela solidão;\nSê tu meu Guia, e o ermo pavoroso\nJá não será lugar de escuridão."}, {"label": "Estrofe 2", "text": "Sê tu meu Guia; leva-me a teu lado,\nPois junto a Ti desejo estar, Senhor;\nQue por teu braço estando assim firmado\nNão hei de tropeçar nem ter temor."}, {"label": "Estrofe 3", "text": "Sê tu meu Guia, em tempo radiante,\nOu na bonança, ou mesmo em temporal;\nSê tu meu Guia, que eu prossiga avante\nSem me afastar do rumo divinal."}, {"label": "Estrofe 4", "text": "Sê tu meu Guia, até que tenha entrada\nNa casa paternal, no céu além;\nAli, sem fim, minha alma descansada\nTerá contigo seu eterno bem."}], "reviewed": false}, {"number": 364, "title": "Filhos de Deus", "page": 196, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Do Deus santo somos filhos,\nCo-herdeiros de Jesus!\nEm seu Filho o Pai nos olha\nE nos leva à sua luz."}, {"label": "Estrofe 2", "text": "Amados, filhos somos já de Deus,\nE há de revelar-se o que nós seremos\nQuando o dia de Cristo raiar.\nHavemos de nos transformar\nNa semelhança de nosso Mestre,\nE vê-lo-emos como é."}, {"label": "Estrofe 3", "text": "Que esperança tão gloriosa,\nA de vermos nosso Deus!\nOh, que graça incomparável\nHabitar nos altos-céus!"}, {"label": "Estrofe 4", "text": "Vem, Jesus, querido Mestre,\nVem os teus do mal tirar,\nCompletar a tua obra;\nVem, oh, vem-nos libertar!"}], "reviewed": false}, {"number": 365, "title": "Fé Persistente", "page": 197, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Almejo a fé que forte é\nDiante do terror,\nQue, calma, não recuará\nDo mundo aterrador."}, {"label": "Estrofe 2", "text": "A fé que não me faz queixar\nNa dor da correção;\nMas, quando o fogo mais arder,\nMais firma o coração."}, {"label": "Estrofe 3", "text": "A fé que sempre brilha mais\nNo negro furacão;\nQue no perigo sente paz,\nAudaz na escuridão."}, {"label": "Estrofe 4", "text": "Ó Deus, me dá tamanha fé,\nQue, venha o que vier\nAqui na lide provarei\nCelestial prazer."}], "reviewed": false}, {"number": 366, "title": "Firmeza", "page": 197, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Em nada ponho a minha fé,\nSenão na graça de Jesus;\nNo sacrifício remidor,\nNo sangue do bom Redentor."}, {"label": "Estrofe 2", "text": "Se lhe não posso a face ver,\nNa sua graça vou viver;\nEm cada transe, sem falhar,\nSempre hei de nele confiar."}, {"label": "Estrofe 3", "text": "Seu juramento e mui leal,\nAbriga-me no temporal;\nAo vir cercar-me a tentação,\nÉ Cristo a minha salvação."}, {"label": "Estrofe 4", "text": "Assim que o seu clarim soar,\nIrei com ele me encontrar;\nE gozarei da redenção\nCom todos que no céu estão.\nA minha fé e o meu amor\nEstão firmados no Senhor,\nEstão firmados no Senhor."}], "reviewed": false}, {"number": 367, "title": "Firme Na Rocha", "page": 198, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que alicerce tendes pra construir\nUma casa firme pra resistir\nGrande tempestade que há de chegar\nE a instável casa há de derrubar?"}, {"label": "Estrofe 2", "text": "Nossa morada na Rocha está;\nFirme e segura ela ficará;\nQuando o temporal contra ela der\nHá de resistir todo o seu poder."}, {"label": "Estrofe 3", "text": "Como faz a areia na fundação,\nFazem nossas obras na salvação,\nPois alguém que só em si mesmo crê\nNo Senhor Jesus inda não tem fé."}, {"label": "Estrofe 4", "text": "Os cristãos, porém, que deveras crêem,\nPelas obras mostram a fé que têm;\nSua fé firmada no Salvador,\nNa maior procela, ei-los sem temor!"}], "reviewed": false}, {"number": 368, "title": "Confiança", "page": 198, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Salvador bendito, terno e bom Senhor\nSó em ti confio, grande Salvador!\nSobre a cruz morreste para me salvar;\nTudo padeceste para me livrar."}, {"label": "Estrofe 2", "text": "Ó Jesus bendito, terno e bom Senhor,\nSó em ti confio, grande Salvador!"}, {"label": "Estrofe 3", "text": "Só em ti confio, grande é teu amor;\nNunca desprezaste nenhum pecador;\nTodo o que contrito já te procurou\nPela tua graça salvação achou."}, {"label": "Estrofe 4", "text": "Sim, em ti confio, Salvador fiel,\nNunca abandonaste, pois, teu Israel;\nTua excelsa graça nunca faltará,\nO que em ti confia não perecerá.\nSempre em ti confio, grande é teu poder,\nTu os inimigos podes bem vencer;\nSalvo e bem seguro leva-me, Senhor,\nSempre protegido pelo teu amor."}], "reviewed": false}, {"number": 369, "title": "Só Jesus", "page": 199, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quem tenho eu no céu, Senhor?\nSó Jesus, só Jesus.\nÉ só Jesus meu Salvador,\nSó Jesus, só Jesus.\nEle o lagar por mim pisou,\nDe sofrimento me livrou,\nEle a minha alma fascinou,\nMeu Jesus, meu Jesus."}, {"label": "Estrofe 2", "text": "Eu não almejo mais prazer;\nSó Jesus, só Jesus.\nGozo só nele posso ter,\nEm Jesus, em Jesus.\nPois a Jesus eu vou seguir,\nToda a minha alma vou abrir\nA Jesus, Jesus."}, {"label": "Estrofe 3", "text": "E, se vier perseguição?\nCom Jesus, com Jesus.\nEle será o meu quinhão,\nSó Jesus, só Jesus.\nNada me poderá faltar;\nQuem é que o pode contestar?\nPois prometeu bem me guardar,\nMeu Jesus, meu Jesus."}, {"label": "Estrofe 4", "text": "Quando esta vida terminar,\nSó Jesus, só Jesus.\nVou em seus braços descançar,\nDe Jesus, de Jesus.\nDores me podem retalhar,\nOu meus amigos me deixar,\nEu, não obstante, vou cantar:\nSó Jesus, só Jesus."}], "reviewed": false}, {"number": 370, "title": "Crendo Em Cristo", "page": 199, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mestre divino, ó Jesus, meu Senhor,\nEu creio em ti, sim, creio em ti;\nForça recebo, sustento e vigor,\nQuando, Senhor, creio em ti!"}, {"label": "Estrofe 2", "text": "Quando me cercam as ondas do mar,\nEu creio em ti, sim, creio em ti;\nGozo e prazer tenho e graça sem-par,\nQuando, Senhor, creio em ti!"}, {"label": "Estrofe 3", "text": "Inda que as trevas encubram o céu,\nEu creio em ti, sim, creio em ti;\nPaz, gozo eu tenho através desse véu,\nQuando, Senhor, creio em ti!"}, {"label": "Estrofe 4", "text": "Cristo Jesus, meu Amigo leal,\nEu creio em ti, sim, creio em ti;\nSempre refúgio, defesa real,\nCristo Jesus, creio em ti!"}, {"label": "Estrofe 5", "text": "Creio, creio,\nCristo Jesus, creio em ti!\nGozo concedes-me, força, vigor,\nQuando, Senhor, creio em ti."}], "reviewed": false}, {"number": 371, "title": "Rocha Eterna", "page": 200, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Rocha eterna, foi na cruz\nQue morreste tu, Jesus;\nVem de ti um sangue tal\nQue me limpa todo mal;\nTraz as bênçãos do perdão:\nGozo, paz e salvação."}, {"label": "Estrofe 2", "text": "Nem trabalho, nem penar\nPode o pecador salvar;\nSó tu podes, bom Jesus,\nDar-me vida, paz e luz.\nPeço-te perdão, Senhor,\nPois confio em teu amor."}, {"label": "Estrofe 3", "text": "Eis que vem a morte atrás\nDesta vida tão fugaz;\nQuando eu ao meu lar subir,\nE teu rosto em glória vir,\nRocha eterna que prazer\nEu terei de em ti viver!"}], "reviewed": false}, {"number": 372, "title": "Salvo Estou", "page": 201, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Glória a Jesus, sim, ao Filho de Deus,\nO bom Salvador que nos veio dos céus!\nEstávamos mortos, mas ele chegou\nE do pecado nos ressuscitou."}, {"label": "Estrofe 2", "text": "Salvo! Salvo!\nEu salvo das penas eternas já sou!\nSalvo! Salvo!\nPela graça de Cristo Jesus salvo estou!"}, {"label": "Estrofe 3", "text": "Na corrupção não podia viver,\nA vida era assim um constante sofrer,\nAté que num dia Jesus me encontrou\nE ele minha alma de novo gerou."}, {"label": "Estrofe 4", "text": "Longe de Cristo tão cego eu andei;\nEm trevas vivia, perdido, bem sei,\nMas ele com seu grande amor me buscou,\nLogo minha alma da morte livrou."}, {"label": "Estrofe 5", "text": "Salvo pra sempre eu agora já sou,\nJesus com seu sangue minha alma lavou.\nLouvores pra sempre ao Senhor eu darei.\nAo seu trabalho me consagrarei."}], "reviewed": false}, {"number": 373, "title": "Certeza", "page": 201, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Por mim sofreu o Salvador;\nGlória, glória a meu Jesus!\nLouvai comigo ao Redentor.\nGlória, glória a meu Jesus!"}, {"label": "Estrofe 2", "text": "Jesus, Jesus, o Salvador!\nÉ doce o nome do Senhor.\nAbrasa-me com santo amor;\nGlória, glória a meu Jesus!"}, {"label": "Estrofe 3", "text": "Os meus pecados carregou,\nE sobre a cruz me resgatou."}, {"label": "Estrofe 4", "text": "Eu sei que perdoado estou;\nE com certeza ao céu eu vou."}, {"label": "Estrofe 5", "text": "E, quando a luta aqui findar,\nNo céu de luz eu vou cantar."}], "reviewed": false}, {"number": 375, "title": "Segurança", "page": 202, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vivo feliz, pois sou de Jesus,\nE já desfruto o gozo da luz!\nSou por Jesus herdeiros de Deus,\nEle me leva à glória dos céus."}, {"label": "Estrofe 2", "text": "Canta, minha alma! (bis)\nCanta ao Senhor!\nRende-lhe sempre ardente louvor!"}, {"label": "Estrofe 3", "text": "Ao seu amor eu me submeti,\nE extasiado então me senti.\nAnjos, descendo, trazem dos céus\nEcos da excelsa graça de Deus."}, {"label": "Estrofe 4", "text": "Sempre vivendo em seu grande amor,\nMe regozijo em meu Salvador;\nEsperançoso, vivo na luz,\nPela bondade do meu Jesus!"}], "reviewed": false}, {"number": 376, "title": "Salvação Perfeita", "page": 202, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Livres do medo temos ficado;\nCristo morreu, levando o pecado;\nEis o resgate: o pacto se fez;\nFomos remidos de uma vez!"}, {"label": "Estrofe 2", "text": "Ao malfeitor, que a pena merece,\nVida e perdão Jesus oferece;\nClama por graça, com avidez,\nCristo te acolhe de uma vez!"}, {"label": "Estrofe 3", "text": "Graça real! não há mais castigo!\nTemos a paz sem medo e perigo!\nVeste reais, não triste nudez;\nCristo enriquece de uma vez!"}, {"label": "Estrofe 4", "text": "\"Filhos de Deus!\" favor inaudito!\nDeus nos amou em grau infinito!\nNesta clemência não há dobrez;\nHá segurança de uma vez!"}, {"label": "Estrofe 5", "text": "De uma vez! Oh, sim, acredita!\nÓ pecador, tens sorte bendita!\nTudo Jesus, por nós, satisfez!\nCristo salvou-nos de uma vez!"}], "reviewed": false}, {"number": 377, "title": "Não Sei Por Que", "page": 203, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Não sei por que de Deus o amor\nA mim se revelou,\nPor que razão o Salvador\nPra si me resgatou."}, {"label": "Estrofe 2", "text": "Ignoro como o Espírito\nConvence-nos do mal,\nRevela Cristo, Verbo seu,\nConsolador real."}, {"label": "Estrofe 3", "text": "Não sei o que mal ou bem\nÉ destinado a mim;\nSe maus ou áureos dias vêm,\nAté da vida o fim."}, {"label": "Estrofe 4", "text": "E quando vem Jesus não sei,\nSe breve ou tarde vem;\nMas sei que meu Senhor virá\nNa glória que ele tem."}, {"label": "Estrofe 5", "text": "Mas eu sei em quem tenho crido,\nE estou bem certo que é poderoso\nPra guardar o meu tesouro\nAté o dia final."}], "reviewed": false}, {"number": 378, "title": "Já Certo Estou", "page": 203, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Já certo estou, sim, certo estou\nQue Cristo tem amor por mim.\nJá certo estou, sim, certo estou\nQue Cristo salva a mim."}, {"label": "Estrofe 2", "text": "Já certo estou, sim, certo estou:\nJesus morreu, morreu por mim.\nJá certo estou, sim, certo estou:\nJesus morreu por mim."}, {"label": "Estrofe 3", "text": "Já salvo estou por meu Jesus,\nPois padeceu na cruz por mim;\nJá salvo estou por meu Jesus,\nPois padeceu por mim."}], "reviewed": false}, {"number": 379, "title": "Laços Benditos", "page": 204, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Benditos laços são\nOs do fraterno amor,\nQue nesta santa comunhão\nNos unem ao Senhor."}, {"label": "Estrofe 2", "text": "Ao mesmo trono vão\nAs nossas petições;\nÉ mútuo o gozo, ou a aflição\nDos nossos corações."}, {"label": "Estrofe 3", "text": "Aqui tudo é comum,\nO rir e o prantear;\nEm Cristo somos todos um,\nNo gozo e no lidar."}, {"label": "Estrofe 4", "text": "Se desta santa união\nNos vamos separar,\nNo céu eterna comunhão\nHavemos de gozar."}], "reviewed": false}, {"number": 380, "title": "Amor", "page": 204, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Qual o adorno desta vida? É o amor.\nAlegria é concedida pelo amor.\nÉ benigno, é paciente,\nNão se torna maldizente (bis)\nEste meigo amor."}, {"label": "Estrofe 2", "text": "Com suspeitas não se alcança doce amor.\nOnde houver desconfiança, ai do amor.\nPois mostremos tolerância;\nMuitas vezes a arrogância (bis)\nMurcha e mata o amor."}, {"label": "Estrofe 3", "text": "Inda quando for custoso, nutre amor,\nAo irado e mui furioso mostra amor.\nNão te dês por insultado,\nMas responde com agrado, (bis)\nVence pelo amor."}, {"label": "Estrofe 4", "text": "Não te irrites, mas tolera, com amor.\nTudo sofre, tudo espera pelo amor.\nDesavenças e rancores\nNão convém a pecadores (bis)\nsalvos pelo amor."}, {"label": "Estrofe 5", "text": "Pois, irmão, ao teu vizinho mostra amor.\nO valor não é mesquinho deste amor,\nO supremo Deus nos ama,\nCristo para os céus nos chama, (bis)\nOnde reina o amor."}], "reviewed": false}, {"number": 381, "title": "Amor Fraternal", "page": 205, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus, Pastor amado,\nContempla-nos aqui;\nConcede que sejamos\nUm corpo só em ti.\nContendas e malícias\nQue longe de nós vão!\nNenhum desgosto impeça\nA nossa comunhão."}, {"label": "Estrofe 2", "text": "Pois sendo resgatados\nPor um só Salvador,\nDevemos ser unidos\nPor um mais forte amor;\nOlhar com simpatia\nOs erros de um irmão,\nE todos ajudá-lo\nCom branda compaixão."}, {"label": "Estrofe 3", "text": "Jesus, suave e meigo,\nEnsina-nos a amar,\nE como tu sejamos\nTambém no perdoar!\nAh, quanto carecemos\nDe auxílio do Senhor!\nUnidos supliquemos\nA Deus por esse amor!"}, {"label": "Estrofe 4", "text": "Se tua igreja toda\nAndar em santa união,\nEntão será bendito\nO nome de Cristão;\nAssim o que pediste\nEm nós se cumprirá,\nE todo o mundo inteiro\nA ti conhecerá."}], "reviewed": false}, {"number": 382, "title": "Vamos À Igreja", "page": 206, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tenho gozo e alegria celeste\nQuando vou adorar ao Senhor\nCom os crentes em Cristo, na igreja,\nQuando juntos rendemos louvor."}, {"label": "Estrofe 2", "text": "Vamos, crentes em Cristo, à igreja,\nConversar com o nosso bom Deus;\nEscutar os seus ricos conselhos,\nRecolher ricas bênçãos dos céus."}, {"label": "Estrofe 3", "text": "Com prazer eu aguardo a chegada\nDesse dia do meu Salvador;\nNele, pois, a minha alma, contente,\nSe derrama em ações de louvor."}, {"label": "Estrofe 4", "text": "Ó meu Mestre divino e amado,\nEu contigo desejo viver;\nTua lei, tua causa e teu povo\nQuero sempre abraçar, defender."}, {"label": "Estrofe 5", "text": "Oh, vem, sim, vem à igreja comigo,\nSim, vamos servir ao Senhor,\nPois maior alegria não temos\nDo que ter comunhão em amor."}], "reviewed": false}, {"number": 383, "title": "Satisfação", "page": 206, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Senhor Jesus, eu te amo mais\nQue o mundo e seu prazer;\nPois deste-me perfeita paz,\nQue nunca irei perder."}, {"label": "Estrofe 2", "text": "Senhor, de mim mais perto estás\nQue amigos meus aqui!\nOh, quanto à alma satisfaz\nO só pensar em ti!"}, {"label": "Estrofe 3", "text": "E de prazer meu coração\nEu sinto transbordar;\nSem ti comigo, os dias são\nQuais noites sem luar."}, {"label": "Estrofe 4", "text": "Ó meu precioso Salvador,\nQue gozo é caminhar\nAqui contigo, e sem temor\nTeu rosto contemplar!"}, {"label": "Estrofe 5", "text": "Metade nunca se contou\nDo amor de Deus Jeová!\nMetade nunca se contou\nDa paz que aos salvos dá!"}], "reviewed": false}, {"number": 384, "title": "A Voz de Jesus", "page": 207, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que doce voz tem meu Senhor,\nVoz de amor, tão terna e graciosa,\nQue enche o coração, dá consolação\nQue só o crente goza."}, {"label": "Estrofe 2", "text": "Qual maior prazer que lhe ouvir dizer:\n\"Vem, meu filho, vem escutar\nO que eu fiz por ti, tudo o que sofri\nNa cruz pra te resgatar?\""}, {"label": "Estrofe 3", "text": "Chamou-me não só uma vez -\nTantas té que eu, triste, humilhado,\nPude a voz ouvir, pude então sair\nDas garras do pecado."}, {"label": "Estrofe 4", "text": "Jesus não me deixa sofrer,\nSua voz me ensina o caminho\nDe vencer o mal, com firmeza tal\nQue nunca estou sozinho."}], "reviewed": false}, {"number": 385, "title": "Louvor", "page": 207, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vamos nós louvar a Deus,\nVamos, vamos;\nAo Senhor de toda luz,\nSanto, santo!\nCantem, louvem lá nos céus\nNosso Deus e Rei Jesus!\nExaltado seja Deus,\nSanto, santo!\nDeus, o nosso eterno Pai,\nSanto, santo!\nDeu-nos bênçãos por Jesus,\nVede, vede!\nAo Senhor glorificai,\nVós, os salvos pela cruz,\nSim, conosco glória dai,\nVinde, vinde!"}, {"label": "Estrofe 2", "text": "Exaltemos nosso Deus,\nSanto, santo!\nExaltemos com fervor,\nHoje, hoje!\nTributemos todos nós\nHinos santos de louvor,\nSim, louvor em alta voz,\nHoje, hoje!"}, {"label": "Estrofe 3", "text": "Ao Senhor de todo amor,\nDeus de glória,\nDeus de luz e Deus de paz,\nCantem glória!\nHoje nós também louvor\nVimos dar-te, que te apraz,\nPois nos deste, Salvador,\nMuitas bênçãos!"}, {"label": "Estrofe 4", "text": "Exaltado seja o nosso Deus e Pai!\nExaltado, para sempre, oh, exaltai!\nCantem, louvem lá nos céus\nNosso Deus e Rei Jesus!\nExaltado seja Deus,\nSanto, santo!"}], "reviewed": false}, {"number": 386, "title": "Cristo, Meu Deleite", "page": 208, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ah, se eu tivesse mil vozes\nPara o Brasil encher\nCom os louvores de Cristo,\nQue singular prazer!"}, {"label": "Estrofe 2", "text": "Sua bondade infinita,\nSeu divinal amor,\nDeslumbram-me sobremaneira\nE infundem-me vivo ardor."}, {"label": "Estrofe 3", "text": "Sua presença constante\nFirma-me o coração,\nTira-me toda a incerteza,\nGuarda na provação."}, {"label": "Estrofe 4", "text": "Desta nação brasileira\nSeja Jesus Senhor;\nQue este país tão querido\nRenda-se ao Salvador."}], "reviewed": false}, {"number": 387, "title": "Contentamento", "page": 209, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Minha alma deleita-se em Cristo;\nAfável é ele para mim;\nViver na sua intimidade\nDá gozo real e sem fim."}, {"label": "Estrofe 2", "text": "Muito contente estou,\nPois que Jesus me amou,\nPra si me chamou,\nPor filho tomou,\nFeliz, tão feliz eu sou."}, {"label": "Estrofe 3", "text": "Por sua bondade admirável,\nEu vivo a fruir seu amor;\nA sua presença conserva\nMinha alma na fé, com fervor."}, {"label": "Estrofe 4", "text": "Um dia serei semelhante\nA Cristo, meu reto Senhor;\nCom ele terei eu morada,\nOh, graças a meu Salvador!"}], "reviewed": false}, {"number": 388, "title": "O Homem Feliz", "page": 209, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Feliz é o homem que não vai\nConforme os ímpios vão,\nNem com os pecadores tem\nAlguma comunhão. (bis)"}, {"label": "Estrofe 2", "text": "Porém na lei, na santa lei\nDe Deus se alegra bem;\nE posto sempre o coração\nNa lei divina tem. (bis)"}, {"label": "Estrofe 3", "text": "Tal homem florescendo vai\nQual plantação que está\nAo pé de um rio, e fruto bom\nEm tempo próprio dá. (bis)"}, {"label": "Estrofe 4", "text": "Jamais a sua folha cai,\nNem murcha vem a ser,\nE bem maduro se fará\nO fruto que ele der. (bis)"}, {"label": "Estrofe 5", "text": "Os ímpios não serão assim;\nJamais felizes são;\nPorém parecem com o pó\nQue os ventos levarão. (bis)"}, {"label": "Estrofe 6", "text": "No juízo não subsistirão,\nNo dia do Senhor;\nDos justos longe ficarão,\nCurtindo eterna dor. (bis)"}], "reviewed": false}, {"number": 389, "title": "Ventura", "page": 210, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O amor de meu Cristo é ventura,\nRepleto de graça sem-par;\nE sua ternura percebo\nCada dia por mim aumentar."}, {"label": "Estrofe 2", "text": "Oh, ternura, graça e amor\nMe dispensa o Salvador!\nQue amor sublime do meu Mestre!\nQue ternura, que graça sem-par!"}, {"label": "Estrofe 3", "text": "Contente seguir vou seus passos,\nNos trilhos traçados por Deus;\nE se me provar na fornalha,\nSejam feitos os desígnos seus."}, {"label": "Estrofe 4", "text": "Veloz se aproxima o seu dia;\nEntão seu semblante verei.\nAssim seu amor e ternura\nEu eternamente gozarei."}], "reviewed": false}, {"number": 390, "title": "Nada Falta", "page": 210, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "De Jesus a doce voz\nOuvi eu, pecador;\nAceitei, de coração,\nJesus, meu Salvador."}, {"label": "Estrofe 2", "text": "Meu pecado, sim,\nExpiou na cruz\nE por graças sem igual\nSalvou-me meu Jesus."}, {"label": "Estrofe 3", "text": "Retidão em mim não há;\nPor graça salvo sou.\nDevo tudo a meu Senhor,\nPois já me resgatou."}, {"label": "Estrofe 4", "text": "Por Jesus eu tenho paz,\nE gozo o seu favor;\nNada aqui me faltará,\nCom Cristo, meu Senhor."}], "reviewed": false}, {"number": 391, "title": "Estou Contente", "page": 211, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, como estou contente,\nFeliz, meu coração!\nPorque Jesus, meu Mestre,\nOuviu minha oração;\nE livre já das trevas,\nAgora vejo a luz;\nBendito seja Cristo,\nPor mim levou a cruz!"}, {"label": "Estrofe 2", "text": "Desamparado estive,\nMas Cristo me buscou;\nEstive desviado,\nMas Ele me encontrou;\nSeu sangue tão precioso\nDa morte me remiu;\nEm hora tão radiante\nDa culpa me eximiu!"}, {"label": "Estrofe 3", "text": "Perante o trono branco,\nOh, bem queria eu\nVer todos os remidos\nNa glória lá no céu!\nOh, que inefável gozo\nAo ver meu Salvador,\nE as hostes mui gloriosas\nCantando seu louvor!\nEu viverei pra Cristo\nEnquanto aqui ficar,\nTé quando ao lar celeste\nMeu Mestre me chamar;\nFeliz e sempre alegre\nSerei no eterno lar,\nCantando as aleluias\nAo Redentor sem-par!"}, {"label": "Estrofe 4", "text": "Cantarei na sua glória,\nCantaremos aleluia,\nJubilosos, lá no céu. (bis)"}], "reviewed": false}, {"number": 392, "title": "Extraviado", "page": 212, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Bem longe de Deus eu andava,\nUm pobre perdido fui eu;\nPensava que fosse impossível\nEntrar a minha alma no céu."}, {"label": "Estrofe 2", "text": "Vaguei tão errante nas trevas,\nNem raio de luz vinha a mim,\nE triste, cansada a minha alma,\nNão via perdão para mim."}, {"label": "Estrofe 3", "text": "Estando no meio das trevas,\nBem clara uma voz eu ouvi,\nDizendo-me: \"Sou poderoso\nPra dar salvação hoje a ti.\""}, {"label": "Estrofe 4", "text": "Parei; era a voz do meu Mestre,\nFalando palavras de amor;\nClamei: \"Sou um pobre perdido;\nOh, tem compaixão, Salvador!\""}, {"label": "Estrofe 5", "text": "Então me entreguei a meu Mestre;\nFeliz Jesus Cristo me fez.\nA todos eu vou proclamando:\nFoi ele que me satisfez."}, {"label": "Estrofe 6", "text": "E quando, por graça de Cristo,\nO céu alcançar afinal,\nLouvores darei para sempre\nA quem me deu vida eternal"}], "reviewed": false}, {"number": 393, "title": "Cristo pra Mim", "page": 213, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, que descanso em Jesus encontrei!\nCristo pra mim! Cristo pra mim!\nOh, que tesouros infindos achei!\nCristo pra mim! Cristo pra mim!\nQue outros escolham o mundo pra si,\nQueiram riquezas, delícias, aqui;\nEu buscarei, ó Jesus, sempre a ti.\nCristo pra mim! Cristo pra mim!"}, {"label": "Estrofe 2", "text": "Quer na aflição, na doença ou na dor:\nCristo pra mim! Cristo pra mim!\nQuer na saúde, na força ou vigor:\nCristo pra mim! Cristo pra mim!\nSempre ao meu lado, pra me socorrer\nCom seu amor, sim, e com seu poder;\nEm cada transe pronto a me valer!\nCristo pra mim! Cristo pra mim!"}, {"label": "Estrofe 3", "text": "No dia amargo da perseguição:\nCristo pra mim! Cristo pra mim!\nNas duras provas e na tentação:\nCristo pra mim! Cristo pra mim!\nEle na cruz o pecado venceu,\nQuando por mim no Calvário morreu,\nE da vitória a certeza me deu;\nCristo pra mim! Cristo pra mim!"}, {"label": "Estrofe 4", "text": "Quando no vale da morte eu entrar:\nCristo pra mim! Cristo pra mim!\nQuando perante meu Deus me encontrar:\nCristo pra mim! Cristo pra mim!\nSó no teu sangue confio, Senhor!\nSó no teu sempre imutável amor!\nInda outra vez cantarei, Salvador:\nCristo pra mim! Cristo pra mim!"}], "reviewed": false}, {"number": 394, "title": "Realidade", "page": 213, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ouvi o Salvador dizer:\n\"Vem descansar em mim,\nE nos meus braços podes ter\nConsolação sem fim.\"\nEntão eu vim e lhe entreguei\nMeu triste coração;\nAbrigo, paz e gozo achei,\nAchei consolação."}, {"label": "Estrofe 2", "text": "Ouvi o Salvador dizer:\n\"De graça eu sempre dou\nAs águas vivas. Vem beber:\nDa vida a fonte eu sou.\"\nVim a Jesus e me prostrei\nÀs águas e bebi;\nJamais a sede sentirei,\nEstando sempre aqui."}, {"label": "Estrofe 3", "text": "Ouvi o Salvador dizer:\n\"A luz do mundo sou;\nOh, vinde a mim! A quem vier\nA luz da vida dou.\"\nVim a Jesus e nele achei\nO sol que brilha em mim;\nE nessa luz eu andarei\nAté da vida o fim."}], "reviewed": false}, {"number": 395, "title": "Cristo Satisfaz", "page": 214, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Riquezas não preciso ter,\nMas, sim, celeste bem;\nNem falsa paz ou vão prazer,\nPorquanto o crente tem\nEterno gozo no Senhor,\nPor desfrutar o seu amor."}, {"label": "Estrofe 2", "text": "Com Cristo estou contente,\nEle me satisfaz;\nCom esse amor do Salvador,\nAgora estou contente."}, {"label": "Estrofe 3", "text": "Do mundo as honras para mim\nPerderam seu valor;\nJá tenho a paz divina, enfim,\nServindo ao meu Senhor,\nTerei meu gozo principal\nAo vê-lo em glória triunfal."}, {"label": "Estrofe 4", "text": "Até que esteja lá no céu,\nAonde Cristo entrou,\nE veja a face já sem véu\nDe quem me resgatou,\nDesejo só aqui viver\nDe um modo que lhe dê prazer."}], "reviewed": false}, {"number": 396, "title": "Cegueira e Vista", "page": 215, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, tão cego eu andei, e perdido vaguei,\nLonge, longe do meu Salvador;\nMas da glória desceu e seu sangue verteu\nPra salvar um tão pobre pecador."}, {"label": "Estrofe 2", "text": "Foi na cruz, foi na cruz onde um dia eu vi\nMeu pecado castigado em Jesus;\nFoi ali, pela fé, que meus olhos abri,\nE eu agora me alegro em sua luz."}, {"label": "Estrofe 3", "text": "Eu ouvia falar dessa graça sem-par,\nQue do céu trouxe nosso Jesus;\nMas eu surdo me fiz, converter-me não quis\nAo Senhor que por mim morreu na cruz."}, {"label": "Estrofe 4", "text": "Mas um dia senti meus pecados e vi\nSobre mim o castigo da lei;\nMas depressa fugi, em Jesus me escondi,\nE refúgio seguro nele achei."}, {"label": "Estrofe 5", "text": "Oh, que grande prazer inundou o meu ser,\nConhecendo esse tão grande amor,\nQue levou meu Jesus a sofrer lá na cruz\nPra salvar um tão pobre pecador!"}], "reviewed": false}, {"number": 397, "title": "Achei Descanso", "page": 215, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó Jesus, achei descanso\nEm teu terno coração;\nÉ manancial de gozo\nE consolação!\nJá cheguei a comtemplar-te,\nE minha alma se inundou\nCom a refulgente graça\nQue ela em ti achou."}, {"label": "Estrofe 2", "text": "Com inteira confiança\nTe contemplo pela fé;\nTua mão onipotente\nMeu refúgio é;\nSatisfazes meus anelos\nSupres o que me é mister;\nTu sossegas meus temores\nPelo teu poder."}, {"label": "Estrofe 3", "text": "Sê tu sempre meu consolo,\nMeu constante guardião,\nPois os teus reais favores\nGozo e paz me dão.\nResplendor da eterna glória,\nFonte de perene amor,\nSou feliz com tua glória,\nCristo Salvador!"}], "reviewed": false}, {"number": 398, "title": "Sou Feliz", "page": 216, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se paz a mais doce me deres gozar,\nSe dor a mais forte sofrer,\nOh, seja o que for, tu me fazes saber\nQue feliz com Jesus sempre sou!"}, {"label": "Estrofe 2", "text": "Sou feliz com Jesus!\nSou feliz com Jesus, meu Senhor!"}, {"label": "Estrofe 3", "text": "Embora me assalte o cruel Satanás,\nE ataque com vis tentações,\nOh, certo eu estou, apesar de aflições,\nQue feliz eu serei com Jesus!"}, {"label": "Estrofe 4", "text": "Meu triste pecado por meu Salvador,\nFoi pago de um modo cabal;\nValeu-me o Senhor, oh, mercê sem igual!\nSou feliz! Graças dou a Jesus!"}, {"label": "Estrofe 5", "text": "A vinda eu anseio do meu Salvador;\nEm breve virá me levar\nAo céu, onde vou para sempre morar\nCom remidos na luz do Senhor!"}], "reviewed": false}, {"number": 399, "title": "Cantarei de Cristo", "page": 216, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cantarei de Jesus Cristo,\nQue sofreu pra me salvar;\nEle sobre a cruz foi morto\nPra da pena me livrar."}, {"label": "Estrofe 2", "text": "Cantarei de Jesus Cristo,\nSua graça exaltarei;\nEncontrou-me muito aflito,\nE descanso nele achei."}, {"label": "Estrofe 3", "text": "Cantarei que Jesus Cristo\nCom amor me resgatou;\nEle sobre a cruz foi morto;\nMeus pecados apagou."}, {"label": "Estrofe 4", "text": "Cantarei de sua graça\nQue rebelde me encontrou;\nCom amor e piedade\nEle me regenerou."}, {"label": "Estrofe 5", "text": "Cantarei no céu a Cristo,\nBendirei seu grande amor;\nHumilhou-se pra salvar-me;\nLouvarei com zelo e ardor."}], "reviewed": false}, {"number": 400, "title": "Júbilo", "page": 217, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus, Senhor altíssimo,\nA morte quis sofrer,\nDe pecadores míseros\nIrmãos seus quis fazer."}, {"label": "Estrofe 2", "text": "Por isso canto, canto todo o dia,\nCristo me enche de gozo e alegria!"}, {"label": "Estrofe 3", "text": "Com incessante júbilo,\nProclamo o amor de Deus,\nPorque me enxuga as lágrimas,\nE diz-me: \"Tu és meu.\""}, {"label": "Estrofe 4", "text": "É esta a história única\nDa compaixão de Deus\nO meu alegre cântico\nAqui e lá nos céus."}], "reviewed": false}, {"number": 401, "title": "Eu Sou de Jesus", "page": 217, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mui triste eu andava, sem gozo e sem paz,\nMas eu hoje tenho alegria eficaz,\nE constantemente bendigo a meu Deus,\nE é claro o motivo, pois sou de Jesus!"}, {"label": "Estrofe 2", "text": "Eu sou de Jesus, aleluia!\nDe Cristo Jesus, meu Senhor!\nNão quero falhar, mas quero falar,\nAndar e viver com Jesus!"}, {"label": "Estrofe 3", "text": "Seguro vivia nas garras do mal,\nO mundo atirou-me no abismo fatal;\nAgora, qual ave voando nos céus,\nEu vivo contente pois sou de Jesus!"}, {"label": "Estrofe 4", "text": "Ó alma turbada por que lamentar?\nNo mestre tu achas tesouros sem-par:\nInfinda alegria, poder, salvação!\nOh, vem, vem a Cristo, sem hesitação!"}], "reviewed": false}, {"number": 402, "title": "Escrava Resgatada", "page": 218, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis a escrava resgatada,\nGrande preço Cristo deu,\nNão foi ouro, nem foi prata,\nFoi seu sangue que verteu."}, {"label": "Estrofe 2", "text": "Pois agora que sou tua,\nSem jamais a ti perder,\nQuero, meu Senhor, servir-te,\nGrata, e só por ti viver."}, {"label": "Estrofe 3", "text": "Quero receber teu jugo;\nEm teus passos caminhar;\nSó a ti eu me subjugo,\nVou contigo em paz morar."}, {"label": "Estrofe 4", "text": "Eis que estou aqui na terra,\nEsperando o teu voltar;\nLevarás, então, a escrava\nQue no céu vai habitar."}, {"label": "Estrofe 5", "text": "De maneira tal amaste,\nQue por mim, Senhor, morreste;\nPra remir-me do pecado,\nTu sofreste em meu lugar."}], "reviewed": false}, {"number": 403, "title": "Alegre", "page": 218, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Perdido andei na escuridão,\nMas Cristo me encontrou,\nE com a luz do seu amor\nAs trevas dissipou."}, {"label": "Estrofe 2", "text": "No caso de se escurecer\nDe nuvens todo o céu,\nJesus, bendito Salvador,\nÉ luz que rasga o véu!"}, {"label": "Estrofe 3", "text": "Andando estou na luz de Deus,\nQue doce comunhão!\nProssigo sempre com vigor,\nDeixando o mundo vão."}, {"label": "Estrofe 4", "text": "Lá, face a face, então verei\nJesus, o Salvador,\nO qual a sua vida deu\nPor mim, vil pecador."}, {"label": "Estrofe 5", "text": "Eu alegre vou na sua luz,\nPois Jesus agora me conduz.\nDesde que me achou\nDa morte me livrou;\nAndo sempre alegre,\nCristo me salvou!"}], "reviewed": false}, {"number": 404, "title": "Substituição", "page": 219, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "De pecados carregado,\nAbatido e triste andei,\nEm procura de descanso,\nQue, entretanto, não achei."}, {"label": "Estrofe 2", "text": "De pecados carregado,\nA Jesus, então, clamei:\n\"Triste estou, desesperado.\"\nA seus pés eu me lancei."}, {"label": "Estrofe 3", "text": "De pecados carregado,\nA olhar não me atrevi;\nMas a voz do Bem-amado\nMe falou, sim, e eu ouvi."}, {"label": "Estrofe 4", "text": "\"De pecados carregado,\nEu, na cruz, já padeci;\nSobre o lenho pendurado,\nJá fui morto, e foi por ti.\"\nDe pecados carregado,\nÓ Jesus, meu Salvador,\nFoste em meu lugar cravado,\nComo é grande o teu amor!"}], "reviewed": false}, {"number": 405, "title": "Gozo e Paz", "page": 220, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, eu sou feliz, pois já creio em meu Jesus\nQue por mim morreu, deu-me a vida e deu-me luz!\nSim, eu sou feliz, tenho a paz que Cristo dá\nE eu agora sei que do mal me guardará."}, {"label": "Estrofe 2", "text": "Sim, feliz eu sou só por Cristo;\nE por ele sou benquisto;\nEm Jesus eu gozo esse dom veraz;\nSeu amor me satisfaz."}, {"label": "Estrofe 3", "text": "Que prazer maior posso então ambicionar\nDo que ter Jesus e com ele sempre andar?\nMais prazer não há! Só Jesus me dá perdão,\nSó Jesus concede gloriosa salvação."}, {"label": "Estrofe 4", "text": "Alegreia e paz gozo em meu bom Salvador;\nNeste mundo vil é Jesus meu Protetor.\nGozo infindo achei pela fé no eterno Rei;\nPaz perfeita, paz no Senhor já encontrei."}], "reviewed": false}, {"number": 406, "title": "Confiar Em Cristo", "page": 220, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que delícia é crer em Cristo,\nEm seu nome confiar,\nAceitar os seus ensinos\nE as promessas desfrutar!"}, {"label": "Estrofe 2", "text": "Cristo! Cristo! Já confio\nEm teu nome, em teu poder;\nCristo! Cristo, Bem-amado!\nFaze minha fé crescer."}, {"label": "Estrofe 3", "text": "Oh, que gozo é crer em Cristo,\nTer certeza de perdão!\nReceber de Cristo mesmo\nVida, paz e salvação.\nBem feliz eu sou em Cristo,\nSempre dele quero ser;\nQuero agora, mui submisso,\nSempre a ele obedecer."}], "reviewed": false}, {"number": 407, "title": "Ditoso Dia", "page": 221, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ditoso o dia em que aceitei\nDo meu Senhor a salvação;\nA grande paz que eu alcancei\nPerdura no meu coração."}, {"label": "Estrofe 2", "text": "Que prazer eu senti\nNo dia em que me converti!\nAgora sinto o seu amor,\nE segurança, paz, fervor.\nSou feliz! Tão feliz!\nPois em Jesus me satisfiz!"}, {"label": "Estrofe 3", "text": "Aquilo que eu então votei\nMinha alma, sim, o cumprirá.\nEm cada dia renderei\nLouvor a Deus, que me ouvirá."}, {"label": "Estrofe 4", "text": "Exulta, pois, meu coração,\nNo Filho do supremo Deus;\nPorque te deu a redenção\nE trouxe-te perdão dos céus."}], "reviewed": false}, {"number": 408, "title": "Descanso Verdadeiro", "page": 221, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cada coração procura\nOnde possa descansar,\nMas descanso verdadeiro\nSó Jesus o pode dar."}, {"label": "Estrofe 2", "text": "Pois meu coração te entrego.\nÓ Jesus, meu Salvador!\nSejas tu pra sempre dele,\nO seu Rei e seu Senhor."}, {"label": "Estrofe 3", "text": "Cristo sempre, e tão somente\nCristo, Salvador e Rei;\nMeu abrigo, meu amigo,\nTudo, tudo nele achei."}], "reviewed": false}, {"number": 409, "title": "Plena Paz", "page": 222, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Plena paz gozo eu!\nPlena paz gozo eu!\nE, seguindo a meu Jesus,\nVou andando para o céu."}], "reviewed": false}, {"number": 410, "title": "Felicidade No Serviço", "page": 222, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "No serviço do meu Rei eu sou feliz,\nSatisfeito, abençoado;\nProclamando do meu Rei a salvação,\nNo serviço do meu Rei."}, {"label": "Estrofe 2", "text": "No serviço do meu Rei eu sou feliz,\nObediente e corajoso;\nNa tristeza ou na alegria sei sorrir,\nNo serviço do meu Rei."}, {"label": "Estrofe 3", "text": "No serviço do meu Rei eu sou feliz,\nJubiloso e consagrado;\nAo seu lado desafio a todo mal,\nNo serviço do meu Rei."}, {"label": "Estrofe 4", "text": "No serviço do meu Rei eu sou feliz,\nVenturoso e decidido;\nQuanto tenho no serviço gastarei,\nNo serviço do meu Rei."}, {"label": "Estrofe 5", "text": "No serviço do meu Rei\nMinha vida empregarei;\nGozo, paz, felicidade,\nTem quem serve a meu bom Rei."}], "reviewed": false}, {"number": 411, "title": "Dia Festivo", "page": 222, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Que alegria neste dia\nNós estamos a gozar!\nNeste ensejo bom desejo\nTemos: só a Deus louvar."}, {"label": "Estrofe 2", "text": "Que alegria neste dia\nEnche-nos o coração!\nInimigos e perigos\nJá venceu o Capitão."}, {"label": "Estrofe 3", "text": "Que alegria neste dia\nTêm os crentes em Jesus;\nReunidos os remidos,\nFazem tudo em sua luz!"}, {"label": "Estrofe 4", "text": "Deus glorioso, Deus bondoso,\nAbençoa-nos aqui;\nQue esta igreja sempre seja\nConsagrada só a ti!"}, {"label": "Estrofe 5", "text": "Oh, cantemos, pois, com alegria\nNeste grande e mui festivo dia!\nVê, Vê o que nos fez o Rei dos reis!"}], "reviewed": false}, {"number": 412, "title": "A Música dos Salvos", "page": 223, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ah, que canto que, soando,\nEnche os ares de dulçor!\nSão os salvos, entoando\nHinos ao seu Redentor."}, {"label": "Estrofe 2", "text": "Ele, o Deus excelso, amou-nos,\nDignos nós da perdição;\nCom poder real salvou-nos\nDa perpétua maldição."}, {"label": "Estrofe 3", "text": "Graça excelsa! Deus aceita\nOs rebeldes com favor!\nNunca o Salvador rejeita\nO contrito pecador."}, {"label": "Estrofe 4", "text": "Vinde todos! Sem limite\nÉ a sua compaixão!\nEis o divinal convite!\nAbraçai a salvação.\nOuve as vozes da vitória,\nEm caminho para a glória,\nProclamando a doce história (bis)\nDe Jesus e seu amor!"}], "reviewed": false}, {"number": 413, "title": "Lealdade", "page": 224, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "É ordem do Senhor,\nSelada com amor:\nFiéis, leais, prossegui,\nMesmo até morrer!\nNão fraquejeis, irmãos,\nDeveis ser bons cristãos\nE ser fiéis e leais\nA Cristo, Salvador!"}, {"label": "Estrofe 2", "text": "Seu amor pregai,\nAlmas conquistai!\nManda-nos Jesus, Senhor.\nAvante, avante, irmãos,\nSim, como bons cristãos,\nFiéis e sempre leais\nA Cristo, Salvador!"}, {"label": "Estrofe 3", "text": "Oh, vinde-vos unir,\nDispostos para agir,\nFiéis, leais no labor,\nMesmo até morrer!\nO mal a derrotar,\nA luz fazei brilhar,\nFiéis e sempre leais\nA Cristo, Salvador!"}, {"label": "Estrofe 4", "text": "Eis-nos, Senhor, aqui;\nConsagra-nos a ti;\nQueremos, pois, ser fiéis,\nMesmo até morrer!\nA causa defender,\nTeu reino promover,\nFiéis e sempre leais\nA Cristo, Salvador!"}], "reviewed": false}, {"number": 414, "title": "Acordai", "page": 225, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis que vamos para aquele bom país,\nOnde o crente, sim, é Cristo quem diz,\nCom seu Salvador, pra sempre ali feliz,\nVai gozar e descansar.\nTrabalhemos, pois, com zelo e com vigor,\nConstrangidos pelo seu imenso amor;\nTrabalhemos pelo nosso Salvador;\nEis que a vida vai findar!"}, {"label": "Estrofe 2", "text": "Acordai! Acordai! Despertai! Despertai!\nE cantai! Sim, cantai!\nO Senhor não tardará!\nEis que vamos para aquele bom país,\nOnde o crente, sim, é Cristo quem o diz,\nCom seu Salvador, pra sempre ali feliz,\nVai gozar e descansar."}, {"label": "Estrofe 3", "text": "Eis conosco nosso insigne Capitão\nQue nos assegura a eterna salvação!\nEis da santa fé o invicto pavilhão!\nVamos, vamos trabalhar!\nEia, avante! Nada temos que temer;\nPor Jesus havemos sempre de vencer;\nTrabalhemos juntos sem desfalecer\nPara a obra completar."}, {"label": "Estrofe 4", "text": "Revestidos da couraça de Jesus,\nComo servos seus, e filhos, sim, da luz,\nGloriando-nos em Cristo e sua cruz,\nVamos, vamos trabalhar!\nOs perdidos vamos com amor buscar,\nAos desesperados vamos declarar\nQue Jesus deseja os homens transformar!\nOh, sim, vamos trabalhar!"}], "reviewed": false}, {"number": 415, "title": "Alerta", "page": 225, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Minha alma alerta vai,\nEis inimigos mil;\nDe Satanás a hoste sai,\nCom assombroso ardil."}, {"label": "Estrofe 2", "text": "Velar, orar, lidar\nSem tréguas, sem temor;\nDe dia em dia, e sem cessar,\nProssegue em teu labor."}, {"label": "Estrofe 3", "text": "Na lida, até morrer,\nVai sempre com teu Deus;\nPois ele vai te proteger\nE coroar nos céus."}], "reviewed": false}, {"number": 416, "title": "Filhos da Luz", "page": 226, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Filhos da luz, que desfrutais perdão,\nAmados do Senhor,\nErguei-vos com fervor e retidão,\nVivei pra seu louvor!\nConforme a glória desta herança,\nMarchai com toda confiança, (bis)\nAndando em luz, andando em luz."}, {"label": "Estrofe 2", "text": "Filhos da luz, em santidade e paz\nVós precisais andar,\nPedindo auxílio estável e eficaz,\nPois tendes de lutar\nContra inimigos arrojados;\nDeveis estar bem preparados; (bis)\nVivei na luz, vivei na luz."}, {"label": "Estrofe 3", "text": "Filhos da luz, nascidos sois de Deus,\nFugi de todo o mal;\nCom santo zelo demandai os céus,\nA casa paternal!\nE, vigilantes, não dormindo,\nAs horas com temor remindo, (bis)\nAndai na luz, andai na luz."}, {"label": "Estrofe 4", "text": "Filhos da luz, quando afinal chegar\nO dia do Senhor,\nBendito o servo que ele então achar\nServindo-o com amor!\nPois com prazer no céu entrando,\nOs salvos cantam, exaltando (bis)\nA Deus em luz, a Deus em luz."}], "reviewed": false}, {"number": 417, "title": "Brilha No Viver", "page": 226, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Não somente pra fazer um feito singular\nÉ mister agir com muito ardor,\nMas as coisas mais humildes por executar,\nDeves fazê-las com fervor."}, {"label": "Estrofe 2", "text": "Brilha no meio do teu viver,\nPois talvez algum aflito possas socorrer; (bis)\nBrilha no meio do teu viver."}, {"label": "Estrofe 3", "text": "Oh, talvez alguma vida possas alegrar\nCom palavras doces, em amor;\nOu talvez algumas almas tristes alcançar\nCom a mensagem do Senhor."}, {"label": "Estrofe 4", "text": "Por maior que seja teu esforço a exercer,\nPor mais firme a tua devoção,\nEm redor, oh, quantas almas vivem sem prazer!\nJazem na negra escuridão."}], "reviewed": false}, {"number": 418, "title": "Disposição de Trabalhar", "page": 227, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Bendito Senhor, nosso Rei Jesus,\nDirige-nos pelo teu grande amor,\nContempla-nos, dá-nos divina luz,\nProtege-nos, dando-nos teu favor."}, {"label": "Estrofe 2", "text": "Oh, vem, sim, querido Senhor,\nOuvir-nos em nossa oração,\nE dá-nos da tua presença o penhor,\nE dá-nos também direção."}, {"label": "Estrofe 3", "text": "Nós vimos a ti, Redentor, pedir\nPoder e coragem no labutar;\nJesus, em teus passos queremos ir,\nContigo queremos viver, lutar."}, {"label": "Estrofe 4", "text": "Pois grande é a vinha, Jesus Senhor,\nOs frutos maduros caindo estão.\nOh, vem, pois, encher-nos de fé e amor,\nA fim de colhê-los com prontidão."}, {"label": "Estrofe 5", "text": "Os rogos atende dos servos teus,\nQue invocam teu nome com devoção,\nSustenta-nos, cheios do amor de Deus,\nConcede-nos sempre maior visão."}], "reviewed": false}, {"number": 419, "title": "Mãos Ao Trabalho", "page": 227, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mãos ao trabalho, crentes,\nVai já passando o alvor;\nVamos, enquanto temos\nNossa vida em flor!\nVamos, enquanto é dia,\nCom força trabalhar;\nEia, que em vindo a noite,\nJá não há lidar."}, {"label": "Estrofe 2", "text": "Mãos ao trabalho, crentes,\nJá, ide, enquanto há luz;\nEia, que agora é tempo\nDe servir Jesus!\nIde o vigor da vida\nTodos ao bem votar;\nEia, que em vindo a noite,\nJá não há lidar!"}, {"label": "Estrofe 3", "text": "Mãos ao trabalho, crentes,\nBreve nos chega o fim;\nFirmes, enquanto a morte\nNão tocar clarim!\nVamos, irmãos, à obra,\nPor Cristo trabalhar;\nEia, que em vindo a noite,\nVamos descansar."}], "reviewed": false}, {"number": 420, "title": "Servir Alegremente", "page": 228, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ao Mestre, alegremente,\nIrmãos, deveis servir;\nAo Salvador bendito\nObedecer, seguir.\nOs céus e a terra toda\nProclamam seu poder;\nMilhões alegremente\nObservam seu querer."}, {"label": "Estrofe 2", "text": "Ao Mestre, alegremente\nIrmãos, deveis servir;\nAo salvador bendito\nObedecer, seguir."}, {"label": "Estrofe 3", "text": "Ao Mestre, alegremente,\nHosanas entoai;\nAo Deus do mundo inteiro,\nProstrados, adorai;\nQual rocha inabalável\nO que ordenou nos é,\nEterno, indubitável,\nO autor da nossa fé."}, {"label": "Estrofe 4", "text": "Ao Mestre, alegremente,\nNa vossa vida honrai,\nA fama dele ao mundo\nInteiro anunciai.\nDomínio e majestade,\nCom honra e com poder,\nUm reino sempiterno\nJesus há de exercer."}], "reviewed": false}, {"number": 421, "title": "Conversação Cristã", "page": 229, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sabeis falar de tudo\nQue neste mundo há,\nMas nem sequer palavra\nDe Deus, que tudo dá?!"}, {"label": "Estrofe 2", "text": "Irmãos! Irmãos! Falemos\nDe nosso Salvador;\nOremos ou cantemos\nE demos-lhe louvor!"}, {"label": "Estrofe 3", "text": "Falamos do mau tempo,\nDo frio e do calor;\nOh, bem melhor seria\nFalar do Salvador!"}, {"label": "Estrofe 4", "text": "Falemos da bondade\nDo grande Salvador,\nDe sua excelsa graça,\nDe seu imenso amor!"}, {"label": "Estrofe 5", "text": "Da cruz também falemos,\nOnde ele nos quis dar\nSeu sangue tão precioso,\nE assim nos resgatar."}], "reviewed": false}, {"number": 422, "title": "Trabalho Cristão", "page": 230, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vamos nós trabalhar, somos servos de Deus;\nCom o Mestre seguir no caminho dos céus;\nCom o seu bom conselho o vigor renovar,\nE fazer prontamente o que Cristo mandar!"}, {"label": "Estrofe 2", "text": "No labor, com fervor, a seguir a Jesus,\nCom esperança e fé e com oração,\nAté que volte o Redentor."}, {"label": "Estrofe 3", "text": "Vamos nós trabalhar, os famintos fartar,\nPara a fonte os sedentos depressa levar;\nSó na cruz do Senhor nossa glória será,\nPois Jesus salvação pela graça nos dá!"}, {"label": "Estrofe 4", "text": "Vamos nós trabalhar para Cristo, o Senhor;\nContra o reino das trevas será vencedor;\nEle, então, para sempre exaltado será,\nPois real salvação pela graça nos dá!"}, {"label": "Estrofe 5", "text": "Vamos nós trabalhar, ajudados por Deus,\nQue coroa real nos dará lá nos céus;\nNa mansão dos fiéis o descanso será,\nPois Jesus salvação pela graça nos dá!"}], "reviewed": false}, {"number": 423, "title": "Oh, Buscai", "page": 230, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, buscai, não as riquezas\nDeste mundo de incertezas,\nQue as do céu não dão tristezas!\nOh, buscai-as, sim, buscai!"}, {"label": "Estrofe 2", "text": "Oh, buscai, não as loucuras,\nQue só trazem amarguras,\nMas venturas santas, puras.\nOh, buscai-as, sim, buscai!"}, {"label": "Estrofe 3", "text": "Oh, buscai Jesus primeiro!\nSalvação há no Cordeiro,\nPleno gozo e verdadeiro;\nOh, buscai-o, sim, buscai!"}, {"label": "Estrofe 4", "text": "Oh, buscai a santidade,\nA pureza e a caridade!\nImitai sua humildade;\nImitai-a, imitai!"}, {"label": "Estrofe 5", "text": "Com os seus imitadores,\nSede bons trabalhadores,\nE buscai os pecadores;\nOh, buscai-os, sim, buscai!"}, {"label": "Estrofe 6", "text": "Sim, buscai-os, pra salvá-los,\nIde com amor ganhá-los,\nPois Jesus mandou chamá-los;\nOh, buscai-os, sim, buscai!"}], "reviewed": false}, {"number": 424, "title": "Vamos À Colheita", "page": 231, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ceiferos somos nós fiéis,\nSegando para o Rei dos reis\nOs frutos prontos pra colher,\nQue em derredor se estão a ver.\nAssim, ao nosso Salvador\nRendemos preito de louvor,\nAo nosso Mestre, lá no céu,\nQue sobre a cruz por nós morreu."}, {"label": "Estrofe 2", "text": "Vamos já obedecer,\nVamos à colheita,\nPara, quando anoitecer,\nVer a obra feita.\nPouco tempo ainda há\nBreve, breve, breve acabará."}, {"label": "Estrofe 3", "text": "Nós repigamos por Jesus,\nQue para os campos nos conduz.\nE, se os obreiros poucos são,\nOciosos ficaremos? Não!\nAinda há campo pra ceifar,\nQue muito fruto devem dar.\nNão ouves Cristo perguntar:\nQuem quer por mim ir trabalhar?"}, {"label": "Estrofe 4", "text": "As horas vão passando já\nO dia breve acabará,\nConosco toma o teu lugar\nE por Jesus vem trabalhar!\nPor que ocioso esperas lá?\nA noite logo chegará.\nTu queres fruto ao céu levar,\nOu folhas só apresentar?"}], "reviewed": false}, {"number": 425, "title": "Luz Após Trevas", "page": 232, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Luz após trevas, glória após luz\nGanho após perda, trono após cruz,\nPaz após luta, fruta após flor,\nRiso após pranto, gozo após dor."}, {"label": "Estrofe 2", "text": "Crente após ímpio, justo após réu,\nGraça após ira, vista após véu,\nSol após chuva, mel após sal,\nLar após lida, bem após mal."}, {"label": "Estrofe 3", "text": "Perto após longe, Cristo após eu,\nVida após tumba, terra ante o céu;\nGlória, paz, vida, fé, trono e luz,\nTudo isso eu tenho, crendo em Jesus."}], "reviewed": false}, {"number": 426, "title": "Gratidão Na Luta", "page": 232, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Com gratidão e com fervor\nCantemos já ao bom Senhor,\nPois seu poder nos libertou\nE seu amor nos revelou."}, {"label": "Estrofe 2", "text": "Aceite-nos, Senhor, querido Salvador!\nAqui presente sê, dirige a tua grei,\nA faze prosperar o nosso trabalhar:\nFazer o mundo todo teu nome conhecer!"}, {"label": "Estrofe 3", "text": "Vem conservar-nos em união,\nE encher-nos vem o coração\nDo teu amor tão singular,\nE em tua luz nos faze andar."}, {"label": "Estrofe 4", "text": "Pra bem lutar vem conceder\nO teu favor e teu poder;\nAjuda-nos a prosseguir\nNo bom querer de te servir."}], "reviewed": false}, {"number": 427, "title": "Conquistar o Mundo", "page": 232, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "'O mundo vasto imenso,\nPra Cristo conquistar'-\nEste é o grande lema\nDo nosso labutar.\nHumilde, desprezado,\nPor nós na cruz morreu;\nGlorificado reina\nNa terra e lá no céu."}, {"label": "Estrofe 2", "text": "Sim, conquistar\nO mundo pra Cristo!\nO mundo, sim,\nPra Cristo, o Salvador!"}, {"label": "Estrofe 3", "text": "O mundo vasto, imenso:\nO povo do Brasil,\nNações além dos mares,\nFamílias, tribos mil,\nOs povos da Europa,\nDa China, do Japão,\nA todos proclamemos\nDe Cristo a salvação!"}, {"label": "Estrofe 4", "text": "O mundo vasto, imenso:\nSeus lares, corações,\nImpérios, tronos, reinos,\nAs grandes multidões\nAo Salvador bendito\nTerão de se entregar,\nPois no universo inteiro\nJesus há de imperar!"}], "reviewed": false}, {"number": 428, "title": "Luz Nas Trevas", "page": 233, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Avançai! Avançai! Derramai santa luz\nSobre os povos da terra que não têm Jesus!\nIde, pois, diz o Mestre. De vós, quem irá,\nObservando o preceito que Cristo nos dá?\nConfiai no Senhor; não tenhais mais temor!\nAvançai com Jesus, avançai!"}, {"label": "Estrofe 2", "text": "Avançai! Avançai! Com a Bíblia na mão;\nProclamai às nações que já há remissão!\nEncarai os perigos com fé em Jesus!\nSe sofrermos aqui, reinaremos em luz;\nVinde, crente, lutai; nos trabalhos entrai!\nAvançai sem temor, avançai!"}, {"label": "Estrofe 3", "text": "Avançai! Avançai! A pregar aos milhões\nQue perecem nas trevas e sem salvação!\nFoi por ele tembém que Jesus padeceu,\nQue na terra pobreza e insultos sofreu.\nProclamai redenção! Em Jesus há perdão!\nAvançai com amor, avançai!"}], "reviewed": false}, {"number": 429, "title": "Ceifando", "page": 234, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Espalhemos todos a semente santa,\nDesde a madrugada até o anoitecer,\nCalmos, aguardando o tempo da colheita,\nQuando alegremente havemos de colher."}, {"label": "Estrofe 2", "text": "Havemos de colher! Havemos de colher!\nOh, quão jubilosos havemos de colher!\nHavemos de colher! Havemos de colher!\nMesses abundantes havemos de trazer!"}, {"label": "Estrofe 3", "text": "Semeemos quando seres perniciosos\nA semente boa querem destruir;\nDeus abençoando, alegres, satisfeitos,\nA colheita santa havemos de fruir."}, {"label": "Estrofe 4", "text": "Eia, pois, obreiros, semeai, ousados,\nA semente viva da verdade e luz,\nProclamando Cristo, seu poder e glória,\nSalvação perfeita que alcançou na cruz!"}], "reviewed": false}, {"number": 430, "title": "Em Cada Lugar", "page": 234, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se já estás salvo por Cristo, o Senhor\nDize-o em cada lugar!\nE se ele perdido te achou, pecador\nDize-o em cada lugar!"}, {"label": "Estrofe 2", "text": "Se Cristo expiou tua culpa na cruz,\nDize-o em cada lugar!\nSe sabes que te ama e que ao céu te conduz\nDize-o em cada lugar!"}, {"label": "Estrofe 3", "text": "Se queres servir a Jesus por amor,\nDize-o em cada lugar!\nSe tens boas-novas do teu Salvador,\nDize-o em cada lugar!"}, {"label": "Estrofe 4", "text": "Se tu és herdeiro com Cristo nos céus,\nDize-o em cada lugar!\nAté a presença chegares de Deus,\nDize-o em cada lugar!"}, {"label": "Estrofe 5", "text": "Irmão! Irmão!\nDize-o em cada lugar!\nSe tu os perdidos quiseres salvar,\nDize-o em cada lugar!"}], "reviewed": false}, {"number": 431, "title": "Acode Em Tempo", "page": 235, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Acode em tempo! Depressa, ó irmão!\nVale aos incautos na vil tentação!\nEis como lutam, sem ter mais vigor!\nOh, vem, vem livrá-los de sorte pior!"}, {"label": "Estrofe 2", "text": "Acode em tempo! Acode em tempo!\nDepressa vem socorrer!\nAcode em tempo! Acode em tempo!\nVem, vem depressa valer!"}, {"label": "Estrofe 3", "text": "Acode em tempo! Não vês teu irmão\nAgonizante na vil corrupção\nNosso inimigo o procura lançar\nE sua alma anciosa na mal arrojar."}, {"label": "Estrofe 4", "text": "Acode em tempo! Com dedicação\nLeva a mensagem de Deus - Salvação!\nPor Cristo, o mestre, sim, vamos lutar;\nVai passando o tempo, oh, vem ajudar!"}, {"label": "Estrofe 5", "text": "Em breve o mundo terá de acabar,\nE almas no abismo terão de tombar.\nAcode em tempo! Sim, faze luzir\nA luz salvadora do eterno povir!"}], "reviewed": false}, {"number": 432, "title": "Avante com Deus", "page": 235, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó crentes brasileitos,\nFirmai-vos no Senhor.\nO seu perdão erguendo,\nPendão do seu amor."}, {"label": "Estrofe 2", "text": "'A Pátria para Cristo!'\nBem alto apregoai,\nE a graça do evangelho\nNa vida proclamai.\nOh, quanto infelizes,\nSem Deus, sem salvação,\nNo abismo estão caindo\nDa eterna perdição!\nA salvação perfeita,\nA vida, o gozo e a paz\nDá Cristo, nosso Mestre,\nPois a alma satisfaz."}, {"label": "Estrofe 3", "text": "Tremenda resistência\nHavemos de sofrer;\nSatã e suas hostes\nProcuram nos deter.\nCoragem, pois, ó crentes,\nJesus triunfará!\nNos lares brasileiros\nJesus dominará."}, {"label": "Estrofe 4", "text": "Ó crentes brasileiros,\nO Mestre tem poder\nDe aos nossos conterrâneos\nA vida conceder!\nNa luta prossigamos\nCom zelo e com ardor;\n'A Pátria para Cristo!'\nAvante com fervor!"}], "reviewed": false}, {"number": 433, "title": "A Colheita Além", "page": 236, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cai a semente no bom frescor,\nÉ semeada, sim, no calor,\nÉ semeada na viração,\nÉ semeada na escuridão."}, {"label": "Estrofe 2", "text": "Sobre os rochedos irá murchar,\nOu nas estradas se esperdiçar,\nEntre os espinhos vai se perder,\nOu nas campinas há de crescer."}, {"label": "Estrofe 3", "text": "Há sementeira, pois, de amargor,\nHá de remorso e de negro horror,\nHá de vergonha e de confusão,\nHá de miséria e de perdição."}, {"label": "Estrofe 4", "text": "Vale-me tu, grande Semeador!\nFaz prosperar todo o meu labor:\nQuero servir-te, meu Rei Jesus,\nQuero contigo ceifar em luz.\nOh, qual há de ser, além,\nA ceifa do mal ou bem?\nSempre lançada com força ou langor,\nCom ousadia, com medo e tremor,\nJá, ou nos dias do certo porvir,\nMesse bendita e gloriosa tem de vir!"}], "reviewed": false}, {"number": 434, "title": "Onde os Obreiros", "page": 237, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, onde os obreiros pra trabalhar\nNos campos tão vastos a lourejar?!\nA causa requer prontidão, vigor.\nOh, quem quer ceifar com desvelo e ardor?!"}, {"label": "Estrofe 2", "text": "Onde os obreiros? Oh, quem quer ir\nNos campos tão vastos a escassez suprir?!\nQuem quer decidir, hoje, a se entregar,\nE os frutos benditos arrecadar?"}, {"label": "Estrofe 3", "text": "O joio do mal a proliferar,\nO trigo do Mestre quer sufocar.\nCeifeiros, avante, no campo entrai,\nO dia declina, ceifai, cefai!"}, {"label": "Estrofe 4", "text": "Eis portas abertas à pregação!\nNações suspirando por Salvação!\nOh, onde os obreiros pra anunciar\nDe Deus o perdão de um amor sem-par?!"}], "reviewed": false}, {"number": 435, "title": "Ainda Há Lugar", "page": 237, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, convidai-os, pois há lugar\nNo banquete celestial!\nSim, ide ajuntá-los, e a casa enchei\nDe famintos do pão real."}, {"label": "Estrofe 2", "text": "Pelo caminhos, pelos valados,\nOh, ide, sim, proclamar\nQue tudo, tudo já pronto está:\nNão há de faltar lugar!"}, {"label": "Estrofe 3", "text": "Oh, convidai-os, pois há lugar\nPara todos que queiram vir!\nNão sabem do amor eternal de Deus,\nQue com gozo nos quer ouvir.\nOh, convidai-os, pois há lugar!\nÉ mensagem de um Deus de amor!\nDeveis convidá-los, sem exceção,\nAo banquete do Salvador!"}], "reviewed": false}, {"number": 436, "title": "Dai-nos Luz", "page": 238, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Uma voz ressoa de geral clamor:\nDai-nos luz! Dai-nos luz!\nOs milhões em trevas, cheios de pavor,\nPedem luz, pedem luz!"}, {"label": "Estrofe 2", "text": "Dai-nos luz, a mui gloriosa luz\nDe perdão, de paz e amor!\nDai-nos luz, a tão preciosa luz\nDe Jesus, o Salvador!"}, {"label": "Estrofe 3", "text": "Ansiamos vida, paz, consolação;\nDai-nos luz! Dai-nos luz!\nSe é por Cristo só que Deus nos dá perdão,\nDai-nos luz! Dai-nos luz!"}, {"label": "Estrofe 4", "text": "Sim, por toda parte deve reluzir\nEssa luz de Jesus,\nQue ilumina a estrada que hemos de seguir.\nDai-nos luz! Dai-nos luz!"}, {"label": "Estrofe 5", "text": "Eia, pois, ó crente, todo o mundo enchei\nDessa luz de Jesus!\nAos milhões perdidos sem tardar valei\nCom a luz de Jesus!"}], "reviewed": false}, {"number": 437, "title": "As Boas-novas", "page": 238, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Povo de Deus, cumpri o vosso encargo\nDe proclamar do nosso Deus o amor!\nPois ele, compassivo, não deseja\nA perdição do pobre pecador."}, {"label": "Estrofe 2", "text": "As boas-novas anunciai!\nQue Deus nos ama, contentes, proclamai!"}, {"label": "Estrofe 3", "text": "Oh, contemplai milhares que perecem\nPresos nas garras do pecado e mal,\nSem que haja quem, com pena, lhes indique\nCristo Jesus, Libertador real!\nNão consintais que fiquem desgarradas\nAs almas pelas quais Jesus sofreu;\nHaja cuidado que ninguém se perca\nPor descuidarmos o mandado seu!"}, {"label": "Estrofe 4", "text": "Disseminai entre as nações e tribos\nQue o nosso Deus é o Deus do eterno amor;\nQue ele deixou as glórias infinitas\nPara salvar o mundo pecador."}, {"label": "Estrofe 5", "text": "Oh, consagrai os vossos bens e filhos\nPra difundir de Cristo a santa luz!\nCom orações constantes, fervorosas,\nAuxiliai a causa de Jesus!"}, {"label": "Estrofe 6", "text": "Ei-lo que vem! Mas antes dessa vinda\nApregoai a graça e seu amor!\nQue estejam prontos todos os remidos\nPara aclamá-lo: Cristo! Redentor!"}], "reviewed": false}, {"number": 438, "title": "Ouvindo de Jesus", "page": 239, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Disse Jesus: Ide por todo o mundo\nE pregai o eterno dom\nDa salvação, que com amor profundo,\nDá o Deus gracioso e bom;\nTendo na cruz a afirmação do amor,\nProclamai o dom do redentor.\nOh, conquistai\nAlmas perdidas, buscai\nO pecador enfermo, quase moribundo!"}, {"label": "Estrofe 2", "text": "Vamos, irmãos, levar\nEssa luz ao mundo inteiro!\nVamos, irmãos, contar\nQue esse dom é verdadeiro!\nVamos, irmãos, pregar\nMui confiados no Cordeiro\nQue na cruz já fez\nA nossa redenção!"}, {"label": "Estrofe 3", "text": "Todos unidos neste grande intento,\nProclamemos salvação!\nSem recuar, sempre mostrando alento,\nSim, cumpramos a missão\nQue o Salvador, Cristo Jesus, nos deu!\nEle está também no posto seu.\nDiz-nos o Rei:\n\"Sempre convosco estarei.\"\nVamos, irmãos, por Cristo neste pensamento!"}, {"label": "Estrofe 4", "text": "Firmes, levemos a mensagem santa\nDo evangelho de Jesus!\nEsta mensagem divinal que encanta\nE que o pecador conduz;\nCheia de bênçãos do glorioso Deus,\nQue descobre os escolhidos seus;\nCheia de amor,\nTraz-nos do céu o fragor\nDa compaixão de Deus e dá-nos graça tanta!"}], "reviewed": false}, {"number": 439, "title": "Oração Pela Pátria", "page": 240, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Minha Pátria para Cristo!\nEis a minha petição;\nMinha Pátria tão querida\nEu te dei meu coração,\nLar prezado, lar formoso,\nÉ por ti o meu amor;\nQue o meu Deus de excelsa graça\nTe dispense seu favor."}, {"label": "Estrofe 2", "text": "Quero, pois, com alegria,\nVer feliz a mãe gentil,\nPor vencer o evangelho\nNesta terra do Brasil.\nBrava gente brasileira,\nLonge vá temor servil;\nOu ficar a Pátria salva,\nOu morrer pelo Brasil."}, {"label": "Estrofe 3", "text": "Salve Deus a minha Pátria,\nMinha Pátria varonil!\nSalve Deus a minha terra,\nEsta terra do Brasil."}], "reviewed": false}, {"number": 440, "title": "A Pátria Feliz", "page": 240, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A Pátria para Cristo!\nEsta é minha oração!\nÓ Pátria abençoada,\nÉ teu meu coração!\nQuerido lar paterno,\nÓ Pátria, ó meu amor!\nÓ Deus de excelsa graça,\nDispensa-lhe favor!"}, {"label": "Estrofe 2", "text": "Ó povo brasileiro,\nOh, contemplai Jesus,\nO qual por vós foi morto\nNa ensangüentada cruz!\nA pena do pecado\nCom grande amor sofreu;\nSeu sangue tão precioso\nAli por vós verteu!"}, {"label": "Estrofe 3", "text": "A Pátria para Cristo!\nOh, seja assim, meu Deus,\nQue todo brasileiro\nOuça os apelos teus!\nE quando nós ouvirmos\nA tua voz de além,\nQue todo brasileiro\nAtenda e goze o bem!"}], "reviewed": false}, {"number": 441, "title": "Graça e Salvação", "page": 241, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ide a mensagem ao mundo levar:\nSalvação do Senhor!\nCristo Jesus aos perdidos quer dar\nGraças e salvação!\nVede os aflitos nas trevas do mal,\nEis, como aspiram a paz divinal!\nIde levar-lhes o gozo eternal:\nGraça e salvação!"}, {"label": "Estrofe 2", "text": "Deste convite de perdão\nPor todo o mundo a mensagem levai!\nEste convite de perdão,\nAntes da vinda do Mestre, pregai!"}, {"label": "Estrofe 3", "text": "Forte é o braço daquele que dá\nSalvação do Senhor.\nSua palavra declara que há\nGraça e salvação!\nVós, ó remidos, bem alto cantai!\nIde, aos aflitos a paz proclamai!\nIde por todo lugar e mostrai\nGraça e salvação!\nDeus a mensagem por nós enviou:\nSalvação do Senhor\nSão profundezas que nos revelou:\nGraça e salvação!"}, {"label": "Estrofe 4", "text": "Nós que sabemos da graça e do amor,\nVamos levá-los ao vil pecador!\nTodos cantemos em alto louvor:\nGraça e salvação!"}], "reviewed": false}, {"number": 442, "title": "O Missionário", "page": 242, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Desde um a outro pólo,\nDa China ao Panamá,\nE do africano solo\nAté ao Canadá,\nPor mui longínquas terras,\nNós vamos sem pavor,\nPor vales e por serras,\nPregando o Salvador."}, {"label": "Estrofe 2", "text": "De Deus as maravilhas,\nQue vemos ao passar\nPor terras e por ilhas,\nE pelo argênteo mar,\nSão tantas, são imensas!\nMas, cegos, os pagãos,\nProfessam falsas crenças,\nAdoram Deuses vãos."}, {"label": "Estrofe 3", "text": "Mas nós, que conhecemos\nA forte luz da fé,\nNas trevas deixaremos\nAquele que não crê?\nSem mais demora vamos\nFalar-lhe do perdão\nQue por Jesus gozamos:\nA eterna salvação."}, {"label": "Estrofe 4", "text": "Seu nome proclamando\nA toda geração,\nIremos exaltando\nDe Cristo a salvação;\nQue a alma decidida\nAo lado de Jesus\nTerá a eterna vida\nQue promanou da cruz."}], "reviewed": false}, {"number": 444, "title": "Brasil", "page": 243, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Do vasto Mato Grosso\nÀ costa Ceará,\nPor vilas e cidades,\nDo sul ao Grão-Pará,\nDesse evangelho santo,\nQue nos legou Jesus,\nAo povo brasileiro\nLevemos nós a luz!"}, {"label": "Estrofe 2", "text": "Do sul ao Amazonas,\nDo centro até o mar,\nA doce nova corre\nDo amor que não tem par.\nE muitos foram salvos\nDa morte e perdição,\nPois, crendo, agora, em Cristo,\nJá têm a salvação."}, {"label": "Estrofe 3", "text": "Mas muitos infelizes\nQue devem ser cristãos,\nAdoram Deuses feitos\nPor suas próprias mãos.\nDe tão fatal pecado,\nA idolatria vil,\nUnidos no evangelho,\nSalvemos o Brasil."}], "reviewed": false}, {"number": 445, "title": "Deves Divulgar", "page": 243, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, que bela e doce história\nDo bom Pai celestial,\nQue nos vendo extraviados,\nEm perigo sem igual,\nEnviou seu Filho amado\nPra todos nós salvar!\nTão bela história, crente,\nTu deves divulgar!"}, {"label": "Estrofe 2", "text": "Sim, tu, irmão, tens que contar\nA história de Jesus;\nSeus feitos e palavras\nTu deves divulgar!"}, {"label": "Estrofe 3", "text": "Esta bela história é sempre\nPoderosa pra salvar,\nTransformando e abençoando\nQuem a Cristo quer chegar.\nMas há muitos infelizes\nSem compreender a luz;\nA eles vai e conta\nA história de Jesus!"}, {"label": "Estrofe 4", "text": "Oh, não digas que não podes\nEssa história anunciar!\nFaze tudo ao teu alcance\nPara Cristo sempre honrar!\nVamos, crentes, proclamando\nJesus, o Salvador\nA bela e doce história\nDe Deus e seu amor!"}], "reviewed": false}, {"number": 446, "title": "Avançai", "page": 244, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Confiando no Senhor, avançai, avançai!\nEsperando em seu amor, avançai!\nA Jesus sempre exaltai,\nSeu poder anunciai,\nSua graça proclamai, avançai!"}, {"label": "Estrofe 2", "text": "Se vos chama a trabalhar, avançai, avançai!\nIde as novas proclamar, avançai!\nCom sincera fé e amor,\nCombatendo com fervor,\nE, seguindo ao Salvador, avançai!"}, {"label": "Estrofe 3", "text": "Cristo avisa que virá, avançai, avançai!\nE o seu povo guiará; avançai!\nEle almeja vos levar\nPara o céu, o eterno lar,\nOnde havéis de descansar. Avançai!"}], "reviewed": false}, {"number": 447, "title": "Nunca Ouvir de Cristo", "page": 244, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Não te importa se algum dos amigos morrer\nSem ter conhecimento de Cristo?\nDeixas que no Juízo ele venha a dizer:\n\"A mim nunca falaram de Cristo?\""}, {"label": "Estrofe 2", "text": "\"Não me falaram de Cristo! (bis)\nTantos vi que salvou,\nMas ninguém se importou\nDe falar-me da graça de Cristo!\"\nNão te importa que as almas preciosas a Deus,\nOh, não sejam levadas a Cristo?!\nPois dirão quando Cristo vier outra vez:\n\"A nós nunca falaram de Cristo!\""}, {"label": "Estrofe 3", "text": "Não te importa se entrares sem jóias no céu\nPor não teres trazido alma a Cristo?\nOh, não venhas tu ser acusado de réu\nPor não teres falado de Cristo!"}, {"label": "Estrofe 4", "text": "Não te cales jamais; pede a Deus graça, irmão,\nPara dar testemunho de Cristo;\nPra ninguém no juízo exclamar com razão:\n\"A mim nunca falaram de Cristo!\""}], "reviewed": false}, {"number": 448, "title": "Ide", "page": 245, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo, divino Rei, para os perdidos\nLauto banquete mandou preparar;\nIde, pois, servos seus, ide apressados,\nOs convidados fazei, pois, entrar."}, {"label": "Estrofe 2", "text": "Ide, pois, servos seus, ide apressados!\nCristo os famintos quer hoje fartar."}, {"label": "Estrofe 3", "text": "Se eles recusam vir, oh, com paciência\nNovos convites a eles levai!\nSede animosos, ainda que zombem,\nVosso convite de amor renovai!"}, {"label": "Estrofe 4", "text": "Cristo vos manda ir pelas estradas,\nMancos e cegos à ceia trazer;\nIde, pois, servos seus, ide apressados!\nCristo nas bodas a todos quer ver."}], "reviewed": false}, {"number": 449, "title": "Ousados Proclamai", "page": 245, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ousados, com firmeza,\nÓ crentes, proclamai\nAs novas salvadoras\nDo amor do eterno Pai,\nQue, pra salvar rebeldes,\nSeu Filho ofereceu,\nO qual sofreu a morte\nPra resgatar o réu.\nÓ crentes, proclamai a salvação!\nO mundo libertai da escravidão!\nCrentes, proclamai de Jesus a cruz;\nA graça, amor e seu perdão,\nÓ crentes, sem cessar apregoai!\nO seu amor sem par anunciai;\nCom zelo e com ardor, até raiar o alvor,\nPor Cristo e o reino seu lutai!"}, {"label": "Estrofe 2", "text": "Oh, nada de desculpas,\nObreiros de Jesus!\nEis, o inimigo afoito\nQuer derrubar a cruz;\nJesus, porém, garante\nVencê-lo e ao seu poder,\nSe firmes persistirmos\nNa senda do dever."}, {"label": "Estrofe 3", "text": "À luta, pois, ó crentes,\nPor Cristo Redentor,\nSeu estandarte erguendo,\nDo eterno, imenso amor;\nAs trevas combatendo,\nO vício, a corrupção,\nPregando as boas-novas\nDe luz e salvação."}], "reviewed": false}, {"number": 450, "title": "Igreja, Alerta", "page": 246, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "É tempo, é tempo, o mestre está chamando já!\nMarchar! Marchar! Confiando em seu amor!\nPartir! Partir! A salvação a proclamar,\nCom a palavra santa do bom Salvador!"}, {"label": "Estrofe 2", "text": "Sim, marchar avante!\nTodos seguindo a divinal bandeira!\nSim, marchar avante!\nUnidos, firmes sempre no avançar!\nGlória, glória, eis que canta a multidão!\nConsagrai-lhe todo o vosso coração\nPra Jesus obedecer!\nE ao cumprir o seu querer\nEntoai louvores altos! Avançai!"}, {"label": "Estrofe 3", "text": "\"Queremos luz\" - é o grito das nações pagãs,\nQue vem atravessando o imenso mar.\nIr já, sim, já, levando as novas com amor,\nSem esquecer também aqui de semear.\nDesperta, igreja! O teu poder vem exercer;\nA todos faze Cristo conhecer;\nA tua mão estende com paciente amor,\nDa morte eterna esforça-te para os deter."}, {"label": "Estrofe 4", "text": "Igreja, alerta! O dia prometido vem,\nQuando aclamado o Salvador será;\nPor toda parte o bem amado Redentor\nEterna glória, honra com louvor terá."}], "reviewed": false}, {"number": 451, "title": "Os Que Confiam", "page": 247, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ceifeiros da seara santa\nSois poucos, débeis sois;\nPorém, é forte vosso Mestre;\nAvante! Avante, pois!"}, {"label": "Estrofe 2", "text": "Os que confiam no Senhor\nObterão vigor,\nForças novas hão de ter,\nSubirão até as alturas,\nAndarão alegres sempre\nCorrerão sem se cansar. (bis)\nCorrerão e sem fadiga,\nComo águias voarão."}, {"label": "Estrofe 3", "text": "Cansados, tristes, sem alento,\nDeixai de lamentar;\nPor vós está Jesus, o Mestre;\nPor que desanimar?"}, {"label": "Estrofe 4", "text": "Jesus está conosco sempre\nNa luta contra o mal;\nCoragem, pois, irmãos, avante\nNa obra sem igual!"}], "reviewed": false}, {"number": 452, "title": "Decisão", "page": 247, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quem está ao lado do bom Salvador,\nPronto a dedicar-se, agora, ao seu Senhor?\nTudo abandonando pra Jesus seguir,\nEncarando tudo quanto possa vir?\nQuem de Cristo ao lado sempre quer andar\nQuem quer ajudá-lo outros a chamar?\nPela tua graça, pelo teu amor,\nEis-nos a teu lado, somos teus, Senhor."}, {"label": "Estrofe 2", "text": "Não ambicionando glórias ou poder,\nNos erguemos firmes para combater;\nQuem o amor de Cristo logra conhecer,\nHá de constrangido do seu lado ser!"}, {"label": "Estrofe 3", "text": "Não com ouro ou prata, ó Jesus, Senhor,\nFomos redimidos, mas por teu amor;\nFoi com teu precioso sangue remidor\nQue nos resgataste; somos teus, Senhor!"}, {"label": "Estrofe 4", "text": "A peleja dura sempre tem de ser;\nInimigos fortes hemos nós de ter;\nMas onipotente é Cristo, o Rei dos reis.\nA vitória é certa para os seus fiéis."}], "reviewed": false}, {"number": 453, "title": "À Peleja", "page": 248, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sois vós, irmãos, campeões da cruz?\nPara a campanha vos alistai;\nIde, briosos, levar a luz;\nCheios de ardor, pelejai!"}, {"label": "Estrofe 2", "text": "Oh, com valor, irmãos,\nComo leais cristãos,\nPelo Mestre combatendo,\nNa peleja entrai!"}, {"label": "Estrofe 3", "text": "Quantos procuram vencer o bem\nCom sementeiras de joio vil!\nSão inimigos que com desdém\nMovém-nos guerra sutil!"}, {"label": "Estrofe 4", "text": "Bem preparados, oh, resisti\nCom a Palavra de Deus na mão;\nPra combater contra o mal, segui\nSempre o fiel Capitão!"}], "reviewed": false}, {"number": 454, "title": "Vitória Nas Lutas", "page": 248, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Temos por lutas passado,\nUmas temíveis, cruéis;\nMas o Senhor tem livrado\nDelas seus servos fiéis.\nForça e poder nos tem dado;\nEle nos tem sustentado,\nDando-nos sua mão,\nVida de paz, perdão,\nSalvação!"}, {"label": "Estrofe 2", "text": "Sim, Deus nos tem prometido\nUma vitória cabal;\nNão se tem ele esquecido\nQue na palavra real\nEle nos tem protegido,\nTudo nos tem garantido\nGraça e favor sem-par,\nSim, todo o bem-estar\nQuer nos dar!"}, {"label": "Estrofe 3", "text": "Sim, Deus é por nós!\nQuem nos vencerá?\nDar-nos-á poder real;\nDeus nos guardará\nDefender-nos-á,\nLivrará do mal;\nVamos, irmãos, cantar,\nNosso Senhor louvar,\nExaltar!"}], "reviewed": false}, {"number": 455, "title": "Heróis", "page": 249, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Erguei-vos, cristãos! O clarim já soou;\nÀ guerra vos chama quem vos libertou.\nOs lombos cingidos, nas armas pegai;\nÀ sombra da cruz, corajosos, lutai!"}, {"label": "Estrofe 2", "text": "Oh, sede heróis! (bis)\nSim, sede heróis,\nE por Cristo lutai!"}, {"label": "Estrofe 3", "text": "Das hostes do mal não tenhais mais temor;\nCom zelo segui vosso bom Salvador!\nNa santa peleja, formados, entrai;\nÀ sombra da cruz, corajosos, lutai!"}, {"label": "Estrofe 4", "text": "As forças do mal ide já enfrentar;\nDas suas prisões os cativos livrar!\nValentes, a vossa firmeza mostrai;\nÀ sombra da cruz, corajosos, lutai!"}], "reviewed": false}, {"number": 456, "title": "O Estandarte", "page": 250, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "O estandarte desta igreja\nLevantemos sem temor!\nEla é a muito amada esposa\nDo bendito Salvador.\nÉ Jesus o comandante\nVerdadeiro, que a conduz.\nSomos nós os seus soldados,\nNesta igreja de Jesus."}, {"label": "Estrofe 2", "text": "Resolutos, avançai,\nTrabalhando por Jesus!\nO estandarte levantai,\nEspalhando a sua luz!"}, {"label": "Estrofe 3", "text": "Ó igreja, dediquemos\nNossos corpos ao Senhor!\nNão devemos ser escravos\nDo sagaz enganador.\nAs riquezas são-nos dadas\nPela terna mão real,\nE o Senhor do céu observa\nSe fazemos bem ou mal."}, {"label": "Estrofe 4", "text": "Graça e glória a Ti pertencem,\nÓ esposa do Senhor!\nSê então um instrumento\nDe salvar o pecador;\nPois até os fins do mundo\nCristo mesmo reinará,\nE o domínio do evangelho\nToda a terra abrangerá."}], "reviewed": false}, {"number": 457, "title": "Confiança Em Deus", "page": 250, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Confia sempre, ó crente,\nNa luta por Jesus,\nEm Deus, pois que à vitória\nCom glória nos conduz."}, {"label": "Estrofe 2", "text": "Confia em Deus,\nNa luta por Jesus;\nConfia em Deus,\nQue sempre nos conduz."}, {"label": "Estrofe 3", "text": "No meio dos perigos,\nSofrendo tentações,\nConfia em Deus, que sempre\nVê tuas aflições."}, {"label": "Estrofe 4", "text": "Jesus é poderoso,\nAmigo sem igual;\nConfia nele, ó crente,\nAté o dia final."}], "reviewed": false}, {"number": 458, "title": "Cristo Vos Conduz", "page": 251, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eia, ó soldados, crentes em Jesus!\nIde, avante! À guerra Cristo vos conduz.\nEis que à vossa frente vai o General!\nIde, pois, avante, contra todo o mal.\nProntos, ó soldados, crentes em Jesus!\nEis que à vossa frente Cristo vos conduz."}, {"label": "Estrofe 2", "text": "Tendo os pés calçados de divina paz,\nPonde a veste santa, única e eficaz,\nE cingi os lombos de verdade e luz,\nProtegendo o peito pela fé na cruz.\nProntos, ó soldados, crentes em Jesus!\nContra as potestades Cristo vos conduz."}, {"label": "Estrofe 3", "text": "Contra vós pelejam hostes infernais,\nMas, em vendo a Cristo, não resistem mais\nDe Jesus ao nome, que lhes dá pavor.\nIde avante, ó crentes, não tenhais temor.\nJuntos, ó soldados, crentes em Jesus!\nSede sempre unidos! Cristo voz conduz."}, {"label": "Estrofe 4", "text": "Deste mundo os reinos caem como a flor,\nMas de Cristo a Igreja dura em esplendor.\nOndas ímpias nunca prevalecerão\nContra a Rocha viva, base de Sião.\nFortes, pois, soldados, crentes em Jesus!\nPara a pátria eterna Cristo vos conduz."}, {"label": "Estrofe 5", "text": "Ide avante, ó crentes! Nesta vocação\nPelejai ousados, sempre em oração.\nDeclarai ao mundo: 'Crê e deixa o mal,\nQuem deseja a glória, siga o General.'\nSede, pois, soldados, crentes em Jesus!\nQuem deseja a glória tome a sua cruz."}], "reviewed": false}, {"number": 459, "title": "Companheiras", "page": 251, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sempre unidas, companheiras,\nDeclaremos por Jesus\nGuerra santa contra as trevas,\nZelo puro pela luz."}, {"label": "Estrofe 2", "text": "Vamos todas, vamos todas,\nSempre unidas pelo amor,\nComo esposas, mães ou filhas,\nA servir ao Salvador."}, {"label": "Estrofe 3", "text": "Somos fracos, bem sabemos,\nMas havemos de vencer,\nSe tivermos confiança\nE cumprirmos o dever."}, {"label": "Estrofe 4", "text": "Sempre firmes na esperança\nE na fé do Salvador,\nImploremos sua graça,\nPra vivermos em amor."}], "reviewed": false}, {"number": 460, "title": "Vitória", "page": 252, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eia, avante, crentes, já na guerra entrai;\nLombos bem cingidos, fortes pelejai!\nA Jesus seguindo, pela cruz lutai,\nE seu estandarte hoje desfraldai!"}, {"label": "Estrofe 2", "text": "Eia, avante, crentes, caminhai na luz;\nA vitória é certa, ganha por Jesus."}, {"label": "Estrofe 3", "text": "Grande e forte sempre vos será Jesus;\nNunca foi vencida sua santa cruz.\nE, seguindo a Ele, tudo vencereis,\nMais que vencedores todos vós sereis!"}, {"label": "Estrofe 4", "text": "Reis e potestades desfalecerão;\nReinos deste mundo cedo passarão;\nSempre triunfante Cristo marchará;\nSeu bendito reino nunca findará!"}], "reviewed": false}, {"number": 461, "title": "Fujamos da Tentação", "page": 252, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sempre combatamos toda tentação,\nPois infelicita nosso coração;\nSempre dominemos toda vil paixão,\nA Jesus seguindo sempre em união.\nEm Jesus procuremos\nForça, auxílio e graça;\nEle está nos ouvindo,\nEle no-los quer dar."}, {"label": "Estrofe 2", "text": "Das más companhias não queirais saber,\nA Jesus não ouvem, querem vos perder.\nSede fervorosos, com bom coração,\nA Jesus seguindo sempre em união."}, {"label": "Estrofe 3", "text": "Cristo galardoa só a quem vencer;\nIde, pois, avante, nada há que temer.\nOh, volvei pra Cristo vossa atenção,\nA Jesus seguindo sempre em união."}], "reviewed": false}, {"number": 462, "title": "Unidos", "page": 253, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Irmãos fiéis, uni-vos já\nPra trabalhar por nosso Deus,\nE combater, com todo ardor,\nO rei do mal e os servos seus!"}, {"label": "Estrofe 2", "text": "Unidos vamos já, pois Deus conosco está\nEm combater o mal! Vitória nos dará!\nFirmados no Senhor, lutemos com ardor,\nSeguindo sempre a Cristo, o forte Redentor."}, {"label": "Estrofe 3", "text": "Vitória, pois, com Cristo, o Rei,\nOs seus fiéis alcançarão;\nEm seu poder, os guiará!\nAvante, pois, em união!"}, {"label": "Estrofe 4", "text": "Ó Salvador, teu reino aqui\nAjuda-nos a promover!\nDá-nos fervor e inspiração\nPra executar o teu querer!"}], "reviewed": false}, {"number": 463, "title": "Triunfo", "page": 253, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu triunfarei pelo sangue de Jesus;\nSim, triunfarei pela sua cruz."}], "reviewed": false}, {"number": 464, "title": "Sempre Fiéis", "page": 253, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sempre fiéis, sim, a Ti nós seremos,\nPor tua graça, por teu grande amor!\nSempre fiéis, sim, por Ti lutatemos,\nSob teu pendão, ó Jesus Salvador!"}, {"label": "Estrofe 2", "text": "Sempre fiéis, irmãos! Irmãos, sejamos\nSempre fiéis a Cristo Jesus!\nEle por nós prosseguiu té a morte\nE libertou-nos, morrendo na cruz!"}, {"label": "Estrofe 3", "text": "Por Ti viver, ó bendito Cordeiro,\nQuem não deseja, se te conhecer?\nQuem que se diga cristão verdadeiro\nNão se disponha por Ti a sofrer?"}, {"label": "Estrofe 4", "text": "Mas Salvador, se imperfeitos nós somos,\nComo podemos deixar de cair,\nSe por Ti mesmo guardados não formos?\nQuem té a morte te pode seguir?"}, {"label": "Estrofe 5", "text": "Sempre fiéis!\nSim, mesmo até à morte!\nSempre fiéis!\nTomemos a cruz!\nEis a divisa que a nos nos pertence,\nOs libertados por Cristo Jesus!"}], "reviewed": false}, {"number": 465, "title": "Igual a Daniel", "page": 254, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Meu irmão, procura ser\nIgual a Daniel!\nResoluto em combater\nO usurpador cruel!"}, {"label": "Estrofe 2", "text": "Faze com o Daniel!\nServe o eterno Deus;\nEntre os infiéis, fiel,\nMarcha para os céus!"}, {"label": "Estrofe 3", "text": "Em coragem singular,\nLeal sê tu ao Rei!\nSempre ousado em proclamar\nJesus a sua lei!"}, {"label": "Estrofe 4", "text": "Fortalece o coração,\nE deixa a timidez!\nMuitos males cairão\nPerante a intrepidez!"}], "reviewed": false}, {"number": 466, "title": "Lutai Por Cristo", "page": 254, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Lutai, irmãos, por Cristo\nSoldados, sois da luz;\nAlçai seu estandarte,\nLidai por Sua cruz!\nVencei os inimigos,\nAs hostes derrotai;\nOh, sede destemidos,\nÀ frente Cristo vai!"}, {"label": "Estrofe 2", "text": "Estai bem preparados,\nAo toque do clarim;\nSegui de perto a Cristo\nAté da luta o fim!\nAs armas empunhando,\nCobertos de valor,\nDispostos, bem ousados,\nMarchai, pois, sem temor!"}, {"label": "Estrofe 3", "text": "Oh, confiai em Cristo,\nNa sua proteção,\nPois, confiando em outro,\nSó lutareis em vão!\nDa santa vestidura\nDe Deus vos revesti;\nNa brecha, no perigo,\nFirmai-vos, resisti!"}, {"label": "Estrofe 4", "text": "A luta já travada\nEm pouco findará,\nE o grito da vitória\nBem cedo soará;\nEntão a recompensa\nTerá o vencedor,\nDaquele Rei da glória,\nDo forte Redentor."}, {"label": "Estrofe 5", "text": "Marchai, ó crentes,\nSoldados de Jesus!\nAlçai seu estandarte,\nUnidos, lutai por Sua cruz!"}], "reviewed": false}, {"number": 467, "title": "Avante com Alegria", "page": 255, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eia, avante, sempre alegres,\nVai conosco o Salvador;\nEle nunca deixará,\nNunca desamparará,\nQuem confia no seu grande amor!"}], "reviewed": false}, {"number": 468, "title": "Testemunhas", "page": 256, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eia, crentes destemidos!\nDa verdade convencidos,\nPara a luta apercebidos,\nNo combate entrai!\nEis que surgem, aleivosos,\nErros grandes, perniciosos;\nNestes tempos perigosos,\nVossa fé mostrai!\nO dever vos chama.\nVosso Deus proclama\nA santa lei de Cristo Rei,\nQue vosso ardor reclama.\nConfessai, pois, resolutos,\nFervorosos, incorruptos,\nE com lábios impolutos:\nDeus, verdade e fé!"}, {"label": "Estrofe 2", "text": "Vós, por Cristo libertados,\nNão sejais escravizados!\nOs direitos alcançados\nFirmes conservai!\nSalvação por homens dada,\nPaz fingida, paz comprada,\nLei de Deus falsificada,\nTudo rejeitai!\nLei de Deus não muda.\nO Senhor ajuda\nAo que a cumprir sem desistir,\nE seu preceito estuda.\nAvançai, pois, exultando,\nSempre em Cristo confiando,\nVosso testemunho dando:\nDeus, verdade e fé!"}], "reviewed": false}, {"number": 469, "title": "Corajosos", "page": 256, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Um pendão real vos entregou o Rei,\nA vós, soldados seus;\nCorajosos, pois, de tudo o defendei,\nMarchando para os céus."}, {"label": "Estrofe 2", "text": "Com valor, sem temor,\nPor Cristo prontos a sofrer,\nBem alto erguei o seu pendão,\nFirmes sempre até morrer!\nEis formados já malignos batalhões,\nDo grande usurpador!\nRevelai-vos hoje bravos campeões;\nAvante sem temor!"}, {"label": "Estrofe 3", "text": "Oh, sejamos todos a Jesus leais,\nE a seu real pendão!\nOs que na batalha sempre são fiéis\nCom Ele reinarão."}], "reviewed": false}, {"number": 470, "title": "O Combate", "page": 257, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo vos chama, crentes fiéis,\nPra obedecerdes às suas leis;\nFirmes na causa, sim, combater,\nSempre cumprindo vosso dever."}, {"label": "Estrofe 2", "text": "Eia, avante, dando combate ao pecado,\nAtendendo ao mando do bom Salvador!\nFirmes, crentes, sempre fiéis, bem unidos;\nA vitória é do bom Redentor!"}, {"label": "Estrofe 3", "text": "Cristo vos chama; dai-lhe atenção!\nVinde dispostos, em união;\nVossa armadura logo tomai;\nPor sua causa sempre lutai!"}, {"label": "Estrofe 4", "text": "Logo o conflito terminará;\nCristo, com glória, cedo virá;\nCrentes, lutai, pois, com santo ardor\nPor Cristo, o Mestre, Rei vencedor!"}], "reviewed": false}, {"number": 471, "title": "Vitorioso", "page": 257, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sempre vencendo, mui valoroso,\nCristo Jesus, o Senhor!\nChefe bendito, Chefe glorioso,\nEm tudo Ele é vencedor.\nEi-lo supremo, guiando\nCom seu poder e valor!\nTodos unidos, avante,\nTodos seguindo o Senhor!"}, {"label": "Estrofe 2", "text": "Não é dos fortes a vitória,\nNem dos que correm melhor!\nMas dos fiéis e sinceros,\nComo nos diz o Senhor!\nSempre vencendo, mui valoroso,\nCristo Jesus, o Senhor!\nEis suas hostes inumeráveis,\nVindo com muito valor!\nCristo, que é nosso Monarca\nE tem a glória do Pai,\nSempre nos ama e nos guarda,\nSempre conosco Ele vai!"}, {"label": "Estrofe 3", "text": "Sempre vencendo, mui valoroso,\nCristo Jesus, o Senhor!\nReis e monarcas, príncipes fortes\nBuscam também seu favor.\nE humildemente lhe peço\nQue me permita lutar\nSó ao seu lado, invencível,\nTé minha vida findar!"}], "reviewed": false}, {"number": 472, "title": "Frente Ousada", "page": 258, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eia, às armas, camaradas!\nPrestos já formai!\nDestras firmes nas espadas,\nSem temor marchai!"}, {"label": "Estrofe 2", "text": "O combate já ferido\nCom furor, sem dó!\nTropas, tudo jaz sumido\nEm bulcões de pó."}, {"label": "Estrofe 3", "text": "Contra nós a lança, irado,\nSatanás brandiu,\nUm dos nossos, alcançado,\nVacilou, caiu!"}, {"label": "Estrofe 4", "text": "Não ouvis no céu brilhante\nToques de clarim?\nVem Jesus, vem triunfante!\nVenceremos, sim!"}, {"label": "Estrofe 5", "text": "Frente ousada aos inimigos;\nÉ por nós Jesus!\nQuer livrar-nos dos perigos\nQuem morreu na cruz."}], "reviewed": false}, {"number": 473, "title": "Firmes Na Fé", "page": 258, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Campeões da peleja sagrada\nO clarim chama à luta os fiéis!\nVamos nós, nessa arena bendita,\nConquistar os celestes lauréis!"}, {"label": "Estrofe 2", "text": "Sim, a luta do bem é suprema,\nQuando, sob o comando de Deus,\nA vitória é completa e segura,\nPorque temos a ajuda dos céus."}, {"label": "Estrofe 3", "text": "Se o labor desta causa altaneira\nTem espinhos que podem ferir,\nÉ nos céus compensado mil vezes\nPela paz do celeste porvir."}, {"label": "Estrofe 4", "text": "E, se o mundo atear os seus ódios\nContra nós, com maldoso desdém,\nNão importa, isso nunca enfraquece\nOs heróis da conquista do bem."}, {"label": "Estrofe 5", "text": "Vamos já, com Jesus,\nArvorando o glorioso pendão!\nContra as trevas lutemos com Deus,\nSempre juntos do bom Capitão!"}], "reviewed": false}, {"number": 474, "title": "Eia, Ao Combate", "page": 259, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eia, ao combate! Em vibrações constantes, já\nVos chama o toque do clarim a ir!\nNa grande luta, Cristo triunfante, sim,\nTerá de contra o rei do mal sair."}, {"label": "Estrofe 2", "text": "Eia, ao combate, vós, ó crentes;\nOs inimigos destroçar!\nEm cada dia, o que confia\nAo lado de Jesus lutar!\nEia, ao combate, firmes, fortes\nE corajosos, avançar!\nO Onipotente é suficiente\nPara à vitória nos guiar!"}, {"label": "Estrofe 3", "text": "Eia, avançar! Unidos todos em Jesus\nTriunfaremos; Deus conosco está!\nE com as armas preparadas pelo Rei,\nNa liça combatamos por Jeová!"}, {"label": "Estrofe 4", "text": "Eia, avançar! Pois Cristo as trevas vai vencer;\nNão tardará a vir aniquilar\nAs hostes do maligno e todo o seu poder,\nE, com seu povo, em paz irá reinar!"}], "reviewed": false}, {"number": 475, "title": "Lutar", "page": 260, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vamos batalhar, juntos pelejar,\nTodos guerrear, vamos já!\nO inimigo que com as hostes vem\nTão feroz e mau, quem vencerá?"}, {"label": "Estrofe 2", "text": "Vamos, crentes, vamos já avante,\nFirmes sempre contra Satanás!\nJesus Cristo é nosso Comandante,\nVai conosco o General capaz."}, {"label": "Estrofe 3", "text": "Vamos avançar, sem temor alçar\nE fazer brilhar nossa luz!\nTrevas vão fugir, glórias hão de vir,\nVenham todos proclamar Jesus!"}, {"label": "Estrofe 4", "text": "Ó glorioso Pai, o fiel não cai,\nSempre avante vai, vencedor!\nQuando o fim chegar desse batalhar,\nVem nos coroar, por teu amor!"}], "reviewed": false}, {"number": 476, "title": "Brilho Celeste", "page": 260, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Peregrinando vou pelos montes\nE pelos vales, sempre na luz!\nCristo promete nunca deixar-me;\n'Eis-me convosco', disse Jesus."}, {"label": "Estrofe 2", "text": "Brilho celeste! Brilho celeste!\nEnche a minha alma a glória de Deus!\nCom aleluias, sigo cantando,\nCanto louvores, indo pra os céus!"}, {"label": "Estrofe 3", "text": "Sombras à roda, nuvens em cima\nO Salvador não hão de ocultar;\nEle é a luz que nunca se apaga,\nJunto a seu lado sempre hei de andar."}, {"label": "Estrofe 4", "text": "Vão me guiando raios benditos,\nQue me conduzem para a mansão;\nMais e mais perto, o Mestre seguindo,\nCanto os louvores da salvação."}], "reviewed": false}, {"number": 477, "title": "Como Andar", "page": 260, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Peregrinos, quais estrangeiros,\nNós seguimos pelo mundo a viajar;\nAqui há trevas e iniquidade,\nAqui há lutas contra a maldade;\nPeregrinos, quais estrangeiros,\nNós seguimos pelo mundo a viajar."}, {"label": "Estrofe 2", "text": "Do adversário aqui é o reino,\nÉ com Ele que nós temos de lutar.\nAstucioso, e também malvado,\nE nos incita para o pecado.\nQuais bons servos, quais bons soldados,\nNosso Rei nos manda sempre pelejar."}, {"label": "Estrofe 3", "text": "E na pátria, para onde vamos,\nNem ciladas nem contendas haverá:\nSó alegria, só caridade\nE só descanso na santidade.\nAnimosos e esperançosos,\nNós seguimos pelo mundo a transitar."}, {"label": "Estrofe 4", "text": "Quão glorioso o lugar ditoso,\nOnde vamos nós estar com Cristo, o Rei,\nPra seu semblante na luz fitarmos\nE da presença de Deus gozarmos!\nCidadãos, pois, daquela pátria,\nNós seguimos pelo mundo a caminhar."}], "reviewed": false}, {"number": 478, "title": "O Peregrino", "page": 261, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu sou um peregrino,\nDa estrada pouco sei;\nE dizem que perigos\nEu sempre encontrarei,\nApertos e trabalhos,\nPenosos para mim;\nMas quero andar com Cristo\nAté da vida o fim."}, {"label": "Estrofe 2", "text": "Os gozos e tristezas\nQue posso aqui provar\nAo meu querido Mestre\nEu logo vou contar.\nJesus dará conforto,\nE cuidará de mim.\nSe nele vou confiado\nAté da vida o fim."}, {"label": "Estrofe 3", "text": "Com Ele, nunca os males\nMe poderão vencer;\nCom Ele, nem perigos\nPrecisarei temer;\nE mesmo quando a noite\nEu enfrentar, no fim,\nAlém da morte, a glória\nEncontrarei, enfim."}], "reviewed": false}, {"number": 479, "title": "Vou À Pátria", "page": 262, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vou à pátria, eu, peregrino,\nA viver eternamente com Jesus,\nQue me marcava feliz destino\nNo dia quando por mim morreu na cruz."}, {"label": "Estrofe 2", "text": "Vou à pátria, eu, peregrino, (bis)\nA viver eternamente com Jesus."}, {"label": "Estrofe 3", "text": "Dor e pena, tristeza e morte\nNunca mais conseguirão ferir-me, lá,\nPois Jesus Cristo será meu norte,\nE ao Deus bendito minha alma louvará."}, {"label": "Estrofe 4", "text": "Terra santa, formosa e pura,\nSalvo por Jesus, eu cantarei em ti;\nFelicidade, paz e doçura,\nTerei na glória! Ah, quando irei daqui?"}], "reviewed": false}, {"number": 480, "title": "Favor", "page": 262, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Deus de paz, aos peregrinos\nOuve com benigno amor,\nE protege os pequininos,\nDando-lhes favor."}, {"label": "Estrofe 2", "text": "Jesus Cristo, luz divina,\nBênçãos dá ao pecador;\nTraze-o à fonte cristalina,\nDá-lhe teu favor."}, {"label": "Estrofe 3", "text": "Verbo eterno, Deus bondoso,\nAo cansado viajor\nManifesta-te amoroso,\nDando-lhe favor."}, {"label": "Estrofe 4", "text": "Rei divino, Rei amado,\nSê o nosso protetor;\nGuarda-nos do vil pecado;\nDá-nos teu favor."}], "reviewed": false}, {"number": 481, "title": "Ao Lar Celestial", "page": 263, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "À Pátria abençoada vou\nAnsioso peregrino sou,\nEm busca do feliz lugar\nNo qual eu hei de descansar."}, {"label": "Estrofe 2", "text": "Oh, bela terra de esplendor,\nQuerida herança do Senhor;\nOlhando, vejo, além do mar,\nQue breve eu hei de atravessar,\nA praia áurea, perenal,\nDo lindo lar celestial."}, {"label": "Estrofe 3", "text": "Comigo vai o meu Senhor,\nDo mal me guarda com amor,\nDe paz inunda o coração\nE dá-me eterna salvação."}, {"label": "Estrofe 4", "text": "Na vastidão celestial\nRessoa o canto angelical\nDa triunfante multidão\nFeliz por sua redenção."}], "reviewed": false}, {"number": 482, "title": "Guia, Ó Deus", "page": 263, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Guia, ó Deus, a minha sorte\nNesta peregrinação;\nFrágil sou, mas tu és forte,\nNão me largue a tua mão!"}, {"label": "Estrofe 2", "text": "Nesta terra de inimigos\nAndo às vezes com pavor;\nPelo meio dos perigos\nGuia-me meu Salvador."}, {"label": "Estrofe 3", "text": "Nutre com maná celeste\nMeu faminto coração;\nO meu ser de paz reveste,\nLivra-me da tentação."}, {"label": "Estrofe 4", "text": "Fonte cristalina abriste,\nDe onde as vivas águas vêm;\nNesta luta amarga e triste,\nFaz-me aproveitá-las bem."}, {"label": "Estrofe 5", "text": "E, chegando ao fim da estrada,\nO Jordão hei de passar,\nE acharei no céu morada,\nQue Jesus foi preparar."}], "reviewed": false}, {"number": 483, "title": "Pátria Celestial", "page": 264, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Pátria minha, por ti suspiro;\nQuando no teu bom descanso chegarei?\nOs patriarcas, de Deus amigos,\nE os bons profetas, fieis, antigos,\nJá entraram na tua glória,\nContemplando, em esplendor, o grande Rei."}, {"label": "Estrofe 2", "text": "Os remidos, tão perseguidos,\nPelo sangue já venceram o Dragão;\nPor Jesus Cristo são vencedores,\nE agora cantam os seus louvores\nPátria santa, desejo ver-te,\nVer com Cristo a redimida multidão."}, {"label": "Estrofe 3", "text": "Lá, o rio das águas vivas\nSai do trono do Cordeiro e do Senhor:\nÉ iluminoso desde a nascente,\nCom o cristal é resplandecente;\nPela margem daquele rio\nAndam os remidos com o Salvador."}, {"label": "Estrofe 4", "text": "Não há pranto na minha pátria,\nNela nunca se dará separação;\nAli o trono de Deus descansa;\nAli teremos real bonança;\nOs remidos da minha pátria\nCom Jesus eternamente reinarão."}], "reviewed": false}, {"number": 484, "title": "Saudade", "page": 264, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Da linda pátria estou mui longe,\nTriste eu estou;\nEu tenho de Jesus saudade;\nQuando será que vou?\nPassarinhos, belas flores\nQuerem me encantar.\nOh, vão terrestres esplendores,\nNão quero aqui ficar!"}, {"label": "Estrofe 2", "text": "Jesus me deu fiel promessa,\nVem me buscar;\nMeu coração está com pressa,\nEu quero ao céu voar.\nMeus pecados são mui grandes,\nE culpado sou,\nMas o seu sangue põe-me limpo,\nE para a pátria vou."}, {"label": "Estrofe 3", "text": "Qual filho, de seu lar saudoso,\nEu quero ir;\nQual passarinho para o ninho,\nEu quero ao céu subir.\nSua vinda ao mundo é certa,\nQuando, não o sei;\nMas ele me achará alerta,\nE para o céu irei."}], "reviewed": false}, {"number": 485, "title": "Livro da Vida", "page": 265, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "As riquezas do mundo\nPouco valem pra mim,\nPois Jesus, no teu reino,\nDás-me vida sem fim;\nE no livro da vida,\nQue conservas aí,\nCerto estou que meu nome\nFoi escrito por ti."}, {"label": "Estrofe 2", "text": "Foi escrito por ti\nO meu nome no céu;\nSim, no livro da vida\nFoi escrito por ti."}, {"label": "Estrofe 3", "text": "Meus pecados são muitos,\nComo areia no mar;\nMas Jesus mem revela\nSua graça sem-par;\nVeio para salvar-me,\nO seu sangue verteu,\nE as delícias eternas\nEle me prometeu."}, {"label": "Estrofe 4", "text": "Ó cidade festiva,\nRefulgante de luz,\nÉs morada dos santos\nE fiéis de Jesus!\nSó verá tua glória\nO que crer no Senhor,\nCuja vida foi salva\nPelo seu Redentor."}], "reviewed": false}, {"number": 486, "title": "Doce Porvir", "page": 266, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Após as lutas desta vida,\nCom o Senhor eu estarei;\nApós vitória decidida,\nCom o Senhor eu estarei."}, {"label": "Estrofe 2", "text": "Doce porvir, meu doce lar!\nVem, ó Senhor, sim, vem sem demora!"}, {"label": "Estrofe 3", "text": "Depois de dores e gemidos,\nCom o Senhor eu estarei;\nApós meus dias concluídos,\nNa companhia dos remidos,\nCom o Senhor eu estarei."}, {"label": "Estrofe 4", "text": "Depois do termo da jornada,\nCom o Senhor eu estarei;\nApós as urzes desta estrada,\nApós a vida atribulada.\nCom o Senhor eu estarei."}], "reviewed": false}, {"number": 487, "title": "Precioso É Jesus", "page": 266, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Anelo por Cristo, meu Rei Salvador;\nAs honras a ele darei com louvor,\nPorque sempre achei nele graça e favor;\nPrecioso é Jesus para mim!"}, {"label": "Estrofe 2", "text": "Precioso é Jesus para mim!\nPrecioso é Jesus para mim!\nCeleste prazer é Jesus conhecer!\nPrecioso é Jesus para mim!"}, {"label": "Estrofe 3", "text": "Firmado em Jesus eu alcanço afinal\nFuturo de glória na vida eternal,\nSem uma desdita, nem nuvem de mal;\nPrecioso é Jesus para mim!"}, {"label": "Estrofe 4", "text": "Na glória, minha alma deseja gozar,\nE mais com o Amado se identificar;\nCom todos os salvos servir e adorar;\nPrecioso é Jesus para mim!"}], "reviewed": false}, {"number": 488, "title": "Cada Vez Mais", "page": 267, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "É grato relembrar\nQue cada dia estou\nMais perto do celeste lar\nEm que morar eu vou."}, {"label": "Estrofe 2", "text": "Cada vez mais,\nCada vez mais,\nPerto estou do eterno lar\nEm que morar eu vou."}, {"label": "Estrofe 3", "text": "Mais perto estou dos céus,\nMeu lar, meu ideal;\nMais perto dos amados meus,\nNa casa paternal."}, {"label": "Estrofe 4", "text": "Em breve vou partir\nPara onde não há dor;\nPrazer infindo vou fruir\nCom Cristo, meu Senhor."}, {"label": "Estrofe 5", "text": "Oh, quando ali chegar\nSerei, então, feliz!\nDescanso e paz irei gozar\nNaquele bom país."}, {"label": "Estrofe 6", "text": "Eu sempre quero estar\nAo lado teu, Senhor,\nAté que possa descansar\nNaquele lar de amor."}], "reviewed": false}, {"number": 489, "title": "Céu pra Mim", "page": 267, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Não sei quando Cristo Jesus há de vir,\nE nem qual o dia em que eu hei de partir;\nMas eu sei que, notando o seu rosto luzir,\nSerá grande glória pra mim!"}, {"label": "Estrofe 2", "text": "Será grande glória pra mim!\nMas eu sei que, notando o seu rosto luzir, (bis)\nSerá grande glória pra mim!"}, {"label": "Estrofe 3", "text": "O canto dos anjos ainda não sei,\nNem que sinfonias eu lá ouvirei;\nMas eu sei que o falar de Jesus, o meu Rei,\nSerá sinfonia pra mim!"}, {"label": "Estrofe 4", "text": "Não sei que morada Jesus me vai dar,\nE nem qual o nome que eu hei de ganhar;\nMas eu sei que o 'bem-vindo' dele hei de escutar!\nSó isso será céu pra mim!"}, {"label": "Estrofe 5", "text": "Só isso será céu pra mim!\nMas eu sei que o 'bem-vindo' dele hei de escutar! (bis)\nSó isso será céu pra mim!"}], "reviewed": false}, {"number": 490, "title": "Com Cristo É Céu", "page": 268, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Depois que Cristo me salvou,\nEm céu o mundo se tornou;\nAté no meio do sofrer\nÉ céu a Cristo conhecer."}, {"label": "Estrofe 2", "text": "Oh! Aleluia! Sim, é céu\nFruir perdão que concedeu!\nEm terra ou mar, seja onde for,\nÉ céu andar com o Senhor."}, {"label": "Estrofe 3", "text": "Pra mim muito longe estava o céu,\nMas, quando Cristo me valeu,\nFeliz, senti meu coração\nEntrar no céu da retidão."}, {"label": "Estrofe 4", "text": "Bem pouco importa eu ir morar\nEm alto monte, à beira-mar,\nEm casa ou gruta, boa ou ruim,\nCom Cristo aí é céu pra mim."}], "reviewed": false}, {"number": 491, "title": "Como Há de Ser", "page": 268, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Como há de ser, conclusa a longa lida,\nFinda a peleja da paixão mortal,\nQuando, avistando além da escura vida\nA porta do prazer celestial,\nDos pés varrida a última poeira,\nDo rosto enxuto seu final suor,\nDeixarmos esta cena passageira,\nEntrando ao santo lar de eterno amor?"}, {"label": "Estrofe 2", "text": "Como há de ser, nos céus por Deus banhados\nDos raios da divina e excelsa luz,\nOh, que alegria! Isentos de pecados,\nEstarmos nós diante de Jesus!\nE pela vez primeira em harmonia\nCom os santos cidadãos dos altos céus,\nUnindo-nos, sem medo, à companhia\nQue cerca o trono do supremo Deus?"}, {"label": "Estrofe 3", "text": "Como há de ser, com sentimento ouvindo\nO coro dos remidos do Senhor,\nAs áureas harpas, sempre retinindo\nLouvores ao Cordeiro, ao Salvador;\nE quando, dentro de átrios espaçosos,\nEntoarmos gratos salmos, sem cessar,\nE, como incenso, os hinos fervorosos\nSubirem junto ao celeste altar?"}, {"label": "Estrofe 4", "text": "Como há de ser, quando o Juiz chamar-nos:\n\"Benditos, vinde, para os céus entrai!\"\nE o Salvador dignar-se revelar-nos\nA glória em que ele habita com o Pai?\nAli, não tem, jamais, a morte entrada,\nNem dor nem pranto estorvam o prazer.\nA vista não se ofusca, e em volta nada\nPode a ditosa festa entristecer?"}, {"label": "Estrofe 5", "text": "Como há de ser, quando a pasmosa história\nDa triste e indigna vida que findou,\nCom lucidez se espelhe na memória\nTodo pecado ou mal que então passou,\nO nosso apreço de Jesus aumente,\nE da clemência deste Benfeitor;\nE de contínuo a gratidão se alente\nPor seu insigne e milagroso amor?"}, {"label": "Estrofe 6", "text": "Como há de ser? Oh, nunca foi pensado,\nPor mente ou coração humano aqui,\nO bem-estar por Deus determinado\nPara os que entrarem com triunfo ali!\nAvante, irmãos! Avante no caminho\nQue nos conduz ao gozo tão real!\nSe aqui nós temos um quinhão mesquinho.\nMarchamos para a glória divinal."}], "reviewed": false}, {"number": 492, "title": "Meu Canto Celestial", "page": 269, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Já muitas vezes eu pensei\nQual há de ser o canto meu,\nIndo eu saudar Jesus, meu Rei,\nQuando eu chegar ali no céu.\nOh, que alegria irei gozar\nAssim que o seu \"bem-vindo\" ouvir!\nQue canto alegre há de emanar\nDo impulso que eu então sentir!"}, {"label": "Estrofe 2", "text": "Ali, eu cantarei do amor\nDo meu Jesus, o qual sofreu\nPor mim, tão grande pecador,\nA quem a vida concedeu."}, {"label": "Estrofe 3", "text": "E quando, enfim, eu penetrar\nNo céu de eterno gozo e luz,\nOs anjos vão preludiar\nO meu cantar ao bom Jesus.\nQuando eu, feliz, me apresentar,\nSeu rosto eu hei de ver então,\nE ecoará o meu cantar\nDe um salvo e puro coração."}, {"label": "Estrofe 4", "text": "Oh, quão mavioso ali será\nMeu canto! Sim, meu coração\nTransbordará, exultará\nPor ter completa salvação!\nEncontrarei palavras que\nExprimam minha dita ali?\nSer dos remidos! Oh, eu sei\nQue nunca tal eu mereci!"}], "reviewed": false}, {"number": 493, "title": "No Paraíso", "page": 270, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "No paraíso do cristão,\nPrazeres santos há;\nE muitos meus queridos lá estão,\nOs quais me esperam já."}, {"label": "Estrofe 2", "text": "Às portas de Jerusalém\nMeu Salvador está;\nSeus ternos braços sempre abertos tem,\nOs quais me esperam lá."}, {"label": "Estrofe 3", "text": "Coroa linda eu lá terei\nQue nunca murchará,\nA qual do meu Senhor receberei\nE que me espera lá."}, {"label": "Estrofe 4", "text": "Naquele belo e doce lar,\nMeu coração já está.\nOh, como almejo os rostos contemplar\nDos que me esperam lá!\nEsperam lá, esperam lá,\nMeus queridos lá no céu me esperam já;\nEsperam lá, esperam lá,\nMeus queridos lá no céu me esperam já."}], "reviewed": false}, {"number": 494, "title": "Além", "page": 271, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Uma cidade mui feliz existe\nAlém das brumas e da cerração;\nSomente as almas por Jesus remidas\nCom regozijo ali penetrarão."}, {"label": "Estrofe 2", "text": "Da nossa vista além, além\nDo mundo e dos gemidos,\nEis a morada que Deus tem\nPra todos os remidos!"}, {"label": "Estrofe 3", "text": "Habitação no céu receberemos,\nQue para nós Jesus já preparou;\nLá, resplandece a luz, a glória, a vida;\nLá, cantam hinos a quem nos salvou."}, {"label": "Estrofe 4", "text": "Doridas almas de aflições terrenas,\nAo céu de luz o vosso olhar erguei;\nDeixai o mundo, que vos turba a calma,\nE, enfim, ao lar do céu vos recolhei."}], "reviewed": false}, {"number": 495, "title": "Redenção", "page": 271, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Nós iremos com Cristo Jesus gozar\nUma vida de eterno prazer e amor,\nOnde nunca perigo qualquer há de entrar,\nVida gloriosa na graça do Redentor!"}, {"label": "Estrofe 2", "text": "Salvos por Jesus, cantaremos nós no céu:\nGlória, glória, paz, salvação do Senhor!\nEis que todos, anjos e santos, sem véu,\nHemos de o ver coroado Rei e do céu Senhor."}, {"label": "Estrofe 3", "text": "Todos nós, os remidos, com gratidão,\nJuntos, num regozijo eternal com Deus,\nLouvaremos a quem nos deu tal salvação!\nSim, ao Cordeiro de Deus e Senhor dos céus."}, {"label": "Estrofe 4", "text": "Oh, sim, livrou-nos do justo rigor da lei!\nPaz, favor, redenção, alegria, amor,\nTudo, tudo nos vem, pela morte na cruz,\nDesse Cordeiro de Deus, divinal Senhor."}, {"label": "Estrofe 5", "text": "Pela fé no Senhor recebemos paz,\nDom gracioso de Cristo Jesus, o Rei.\nDeu-nos, pois, salvação, que é completa e veraz!\nOh, sim, livrou-nos do justo rigor da lei!"}, {"label": "Estrofe 6", "text": "Tão alegres seremos na vida ali,\nPois veremos Jesus que na cruz venceu!\nProvas ele nos deu já, por ter vindo aqui,\nOh, que ditosa esperança do povo seu!"}], "reviewed": false}, {"number": 496, "title": "Rio da Vida", "page": 272, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Há um rio cristalino\nOnde os santos viverão,\nNasce no divino trono\nPara gozo do cristão."}, {"label": "Estrofe 2", "text": "Esse gozo nós teremos,\nPor Jesus, o bom Senhor;\nPara sempre viveremos\nCom o nosso Redentor."}, {"label": "Estrofe 3", "text": "Junto às margens desse rio\nOs remidos andarão,\nSempre a Cristo ali servindo,\nCom sincera devoção."}, {"label": "Estrofe 4", "text": "Nós veremos breve o rio,\nFinda a peregrinação,\nE louvores sempiternos\nNossos lábios cantarão."}], "reviewed": false}, {"number": 497, "title": "Tantos Remidos", "page": 272, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tantos remidos vejo nos céus,\nTendo coroas, ricos troféus;\nSalvos, mercê de Cristo, já estão;\nSempre felizes eles serão."}, {"label": "Estrofe 2", "text": "Tendo vencido o mundo falaz,\nTranses penosos e Satanás,\nForam então morada fazer\nOnde só há perfeito prazer."}, {"label": "Estrofe 3", "text": "Fome nem sede nunca terão,\nDores ou mágoas não sofrerão;\nVida perene, vida real\nGozam sem fim, libertos do mal."}, {"label": "Estrofe 4", "text": "Cristo \"bem-vindo\" aos salvos vai dar,\nNesse tão belo e santo lugar\nAos que em seu sangue limpos estão,\nBrancos, mui brancos no coração."}, {"label": "Estrofe 5", "text": "Juntos na glória, vivem em luz,\nGozam da santa paz de Jesus;\nBelas canções de grato louvor\nCantam, sem fim, a seu Redentor."}], "reviewed": false}, {"number": 498, "title": "A Bela Cidade", "page": 273, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Tenho lido da bela cidade,\nConstruída por Cristo nos céus;\nÉ murada de jaspe luzente\nE juncada com áureos troféus.\nE, no meio da praça, eis o rio\nDo vigor e da vida eternal;\nMas metade da glória celeste\nJamais se contou ao mortal."}, {"label": "Estrofe 2", "text": "Jamais se contou ao mortal;\nJamais se contou ao mortal;\nMetade da glória celeste (bis)\nJamais se contou ao mortal."}, {"label": "Estrofe 3", "text": "Tenho lido das belas moradas\nQue Jesus foi no céu preparar,\nOnde os crentes fiéis para sempre,\nMui felizes irão habitar.\nNem tristeza, nem dor, nem gemidos\nEntrarão na mansão paternal;\nMas metade do gozo celeste\nJamais se contou ao mortal."}, {"label": "Estrofe 4", "text": "Tenho lido das vestes brilhantes,\nDas coroas que os santos terão\nQuando o Pai os chamar e disser-lhes:\n\"Recebei o eternal galardão.\"\nTenho lido que os santos na glória\nPisarão ruas de ouro e cristal;\nMas metade da glória celeste\nJamais se contou ao mortal."}], "reviewed": false}, {"number": 499, "title": "Tudo Feliz", "page": 274, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Se infeliz nos corre a vida terreal,\nTemos de deixá-la um dia,\nPara irmos logo ao lar celestial,\nOnde tudo é mui feliz."}, {"label": "Estrofe 2", "text": "Muitos são os males nesta vida aqui;\nTemos de deixá-la um dia;\nAlegria plena vamos ter ali,\nOnde tudo é mui feliz."}, {"label": "Estrofe 3", "text": "A vitória certa que Jesus nos dá,\nHemos de gozá-la um dia;\nA peleja finda, calma nos virá\nOnde tudo é mui feliz."}, {"label": "Estrofe 4", "text": "Todos os remidos se conhecerão,\nSim, ali no céu, um dia;\nNa alegria santa sempre viverão,\nOnde tudo é mui feliz."}, {"label": "Estrofe 5", "text": "Vamos ver Jesus ali,\nSua santa paz fluir,\nE com ele estar,\nSeu rosto contemplar,\nGrande gozo desfrutar."}], "reviewed": false}, {"number": 500, "title": "Glória pra Mim", "page": 274, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quando meu tempo de lutas passar,\nQuando meu Deus para si me chamar,\nGrato, perante Jesus hei de estar;\nGlória perene será para mim!"}, {"label": "Estrofe 2", "text": "Sim, há de ser glória pra mim!\nGlória pra mim! Glória pra mim!\nQuando puder o seu rosto mirar,\nOh, há de ser grande glória pra mim!"}, {"label": "Estrofe 3", "text": "Quando, por graça do seu grande amor,\nEu alcançar o infinito favor\nDe ir para perto do meu Salvador,\nGlória perene será pra mim!"}, {"label": "Estrofe 4", "text": "Muitos amigos ali hei de achar,\nPaz, alegria, eternal bem-estar;\nMas quando meu Salvador me saudar,\nGlória perene será pra mim!"}], "reviewed": false}, {"number": 501, "title": "O Nosso Lar", "page": 275, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Querido lar tenho eu no céu,\nAlém do mundo, além do véu;\nViver ali será prazer,\nPor isso tanto o almejo ver!"}, {"label": "Estrofe 2", "text": "Querido lar, oh, doce lar,\nOnde eu pra sempre irei morar!\nUm pouco mais e eu partirei,\nE com Jesus descansarei."}, {"label": "Estrofe 3", "text": "Querido lar, alegre lar!\nAli ninguém vai mais chorar;\nTristeza e dor e tentação\nNaquele lar não entrarão."}, {"label": "Estrofe 4", "text": "Irão gozar no lar de luz\nSó teus remidos, ó Jesus,\nE eu sei que Cristo, meu Senhor,\nMe espera ali no lar de amor."}], "reviewed": false}, {"number": 502, "title": "Um Pouco Mais", "page": 275, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Um pouco mais, e partirei\nPara onde não há dor;\nUm pouco mais, e viverei\nCom Cristo, o Salvador."}, {"label": "Estrofe 2", "text": "Um pouco mais, e eu entrarei\nNo gozo além do véu;\nCom os remidos estarei\nPra sempre ali no céu.\nUm pouco mais, e encontrarei\nAmados fiéis;\nCom eles sempre entoarei\nLouvor ao Rei dos reis."}, {"label": "Estrofe 3", "text": "Um pouco mais, e eu ouvirei\nA voz do Salvador:\n\"Fiel, bom servo, vem entrar\nNo gozo do Senhor.\""}, {"label": "Estrofe 4", "text": "Um pouco mais, eu vou saudar\nNo céu o meu Senhor;\nE ali sem fim hei de exaltar\nA graça e seu amor."}], "reviewed": false}, {"number": 503, "title": "Face a Face", "page": 276, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Em breve a vida vai findar;\nAqui não mais eu cantarei,\nPorque no céu irei morar,\nLá na presença do meu Rei."}, {"label": "Estrofe 2", "text": "Chegando o dia de esplendor,\nQuando Jesus me vier buscar,\nBem certo estou de que o Senhor\nNo céu a mim dará lugar."}, {"label": "Estrofe 3", "text": "Ali a voz me soará\nDe Cristo, eterno Redentor;\n\"Fiel, bom servo, bem está;\nDesfruta o gozo do Senhor.\""}, {"label": "Estrofe 4", "text": "Por meu Jesus eu vou viver,\nFazer a minha luz brilhar,\nE cada dia vou fazer\nAquilo que ao Senhor honrar."}, {"label": "Estrofe 5", "text": "E face a face vê-lo-ei (bis)\nDe graça salvo, cantarei!"}], "reviewed": false}, {"number": 504, "title": "Lá No Céu", "page": 276, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Há um lar mui feliz lá no céu,\nOnde não há tristeza nem dor,\nOnde os salvos irão habitar,\nNa presença do seu Salvador."}, {"label": "Estrofe 2", "text": "Lá no céu, lá no céu,\nHá um lar mui feliz lá no céu. (bis)"}, {"label": "Estrofe 3", "text": "Tenho amigos fiéis lá no céu,\nQue desfrutam o gozo na luz;\nJá venceram os males daqui\nE lá cantam louvor a Jesus."}, {"label": "Estrofe 4", "text": "Lá no céu, lá no céu;\nTenho amigos fiéis lá no céu! (bis)"}, {"label": "Estrofe 5", "text": "Eu também vou viver lá no céu,\nE hei de ver quem me deu salvação.\nNão demora o momento de eu ir\nE morar lá naquela mansão."}, {"label": "Estrofe 6", "text": "Lá no céu, lá no céu;\nEu também vou viver lá no céu! (bis)"}, {"label": "Estrofe 7", "text": "Nesse lar tão feliz, lá no céu,\nNunca o mal poderá penetrar;\nSó há gloria, pureza e prazer\nOnde os salvos por Cristo hão de entrar."}, {"label": "Estrofe 8", "text": "Lá no céu. lá no céu;\nNesse lar tão feliz lá no céu! (bis)"}], "reviewed": false}, {"number": 505, "title": "Jerusalém", "page": 277, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jerusalém excelsa,\nGloriamo-nos em ti,\nAfável esperança\nDe todo crente aqui.\nRadiante é tua porta,\nQue ao longe já se vê,\nPor onde tem entrada\nO que no Cristo crê."}, {"label": "Estrofe 2", "text": "A cruz e sua glória\nE o grande Redentor\nEm ti são exaltados\nEm cantos de louvor.\nQue gozo tu me inspiras,\nEterna habitação,\nPois sei que em ti se finda\nA peregrinação!"}, {"label": "Estrofe 3", "text": "Ó doce lar amado,\nDescanso meu serás,\nQuando eu tiver herdado\nTeu bem e tua paz.\nÓ coração, que gemes\nNa dor que te desfaz,\nCom Deus, que te redime,\nFeliz, então, serás."}], "reviewed": false}, {"number": 506, "title": "Junto Ao Trono", "page": 278, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Junto ao trono de Deus preparado\nTens, cristão, um lugar dado a ti;\nHá prazeres, há gozo exaltado,\nHá delícias profusas ali;\nSim, ali, sim, ali,\nDe seus anjos fiéis rodeado\nE cercado de glória e de luz,\nJunto a Deus já te espera Jesus."}, {"label": "Estrofe 2", "text": "Não nos podem da terra os encantos\nDar idéia do gozo dali;\nSe no mundo os prazeres são tantos,\nSão prazeres que cessam aqui;\nMas ali, mas ali,\nAs venturas eternas concorrem,\nNa existência perpétua da luz,\nPra tornar-te feliz com Jesus."}, {"label": "Estrofe 3", "text": "Conservemos em nossa lembrança\nAs riquezas do lindo país,\nE guardemos conosco a esperança\nDe uma vida melhor, mais feliz;\nPois dali, pois dali,\nUma voz verdadeira não cansa\nDe chamar-nos ao reino da luz;\nÉ a voz divinal de Jesus."}, {"label": "Estrofe 4", "text": "Se quisermos gozar da ventura\nQue no belo país haverá,\nE somente pedir de alma pura,\nQue Jesus sua graça nos dá;\nPois ali, pois ali,\nTodo cheio de amor, de ternura,\nDesse amor demonstrado na cruz,\nNos escuta e recebe Jesus."}], "reviewed": false}, {"number": 507, "title": "Minha Coroa", "page": 279, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Meu deleite é pensar numa terra de além,\nOnde irei, finda a luta de aquém;\nQuando por meu Jesus conseguir já chegar,\nNa coroa eu estrelas terei?"}, {"label": "Estrofe 2", "text": "Na coroa as estrelas preciosas terei,\nQuando o dia de glória raiar?\nQuando Deus me acordar\nE da tumba me erguer,\nNa coroa eu estrelas terei?"}, {"label": "Estrofe 3", "text": "No poder de Jesus vou orar e lutar,\nPara ao céu muitas almas guiar;\nQuero, pois, merecer, nesse dia final,\nA coroa de glória a brilhar."}, {"label": "Estrofe 4", "text": "Oh, que gozo será o seu rosto mirar,\nE, prostrado aos seus pés, o adorar!\nNa cidade celeste de Cristo, meu Rei,\nA coroa da vida terei."}], "reviewed": false}, {"number": 508, "title": "Terra Feliz", "page": 279, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eu avisto uma terra feliz,\nOnde irei para sempre morar;\nHá mansões nesse lindo país,\nQue Jesus foi pra nós preparar."}, {"label": "Estrofe 2", "text": "Vou morar, vou morar\nNessa terra, celeste porvir! (bis)"}, {"label": "Estrofe 3", "text": "Cantarei nesse lindo país\nBelis hinos ao meu Salvador,\nPois ali viverei bem feliz,\nSem angústias, tristezas, nem dor."}, {"label": "Estrofe 4", "text": "Vou cantar, vou cantar\nNessa terra, celeste porvir! (bis)"}, {"label": "Estrofe 5", "text": "Deixarei este mundo afinal\nPara ir a Jesus adorar;\nNessa linda cidade real,\nMil venturas sem fim vou gozar."}, {"label": "Estrofe 6", "text": "Vou gozar, vou gozar\nNessa terra, celeste porvir! (bis)"}], "reviewed": false}, {"number": 509, "title": "Verei Meu Redentor", "page": 280, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Finda a lida terreal.\nQuando já do rio além,\nNessa vida tão gloriosa me encontrar,\nSei que lá meu redentor\nFinalmente eu hei de ver.\nE com hinos de louvor hei de o saudar."}, {"label": "Estrofe 2", "text": "Oh, que enlevo divinal;\nO seu rosto a contemplar,\nDesde a aurora desse dia perenal;\nComo então meu coração\nHaverá de o exaltar,\nPela graça e compaixão celestial!"}, {"label": "Estrofe 3", "text": "Nessa pátria de esplendor,\nHei de amigos encontrar,\nMeus irmãos em Cristo lá hei de rever;\nMas primeiro que os irmãos,\nQuando ali no céu chegar,\nMeu Jesus é quem eu mais anseio ver."}, {"label": "Estrofe 4", "text": "Pelas portas de Sião,\nCom as vestes a brilhar,\nOnde a noite e o pranto nunca chegarão,\nLá no lindo céu de luz\nHá de Cristo me guiar,\nE mui perto, sim, eu hei de vê-lo então."}, {"label": "Estrofe 5", "text": "Hei de ver meu Redentor;\nRedimido, junto dele eu hei de estar;\nHei de ver meu Salvador;\nOs sinais dos cravos hei de contemplar."}], "reviewed": false}, {"number": 510, "title": "Fonte de Amor", "page": 281, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Fonte de amor perene,\nÉ manancial de luz;\nÁgua da vida corre\nDo trono de Jesus.\nCalmo rio, belo rio,\nQuero estar também\nOnde as águas sempre correm,\nDesse rio além!"}, {"label": "Estrofe 2", "text": "Muitos cantar já foram\nCelestes melodias\nAo som de santas harpas,\nEm lindas harmonias!\nSanto rio! Junto ao rio\nVou cantar também,\nOnde as vozes nunca cessam,\nNa Jerusalém!"}, {"label": "Estrofe 3", "text": "Límpida fonte jorra,\nBrilhante como a luz,\nÁgua que dessedenta\nQuem crer em meu Jesus.\nCorre rio, calmo corre -\nCorra assim a paz\nEm minha alma para sempre -\nCorra mais e mais!"}], "reviewed": false}, {"number": 511, "title": "Com Jesus", "page": 281, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Quando terminar a minha vida terreal,\nEu terei de Cristo a linda vida perenal,\nSim, irei gozar no céu o amor dos seus fiéis,\nNuma luz infinda, sob os eternais docéis."}, {"label": "Estrofe 2", "text": "Vou viver com o Senhor,\nLá no céu em santa luz;\nGlória, glória cantarei a quem morreu na cruz.\nGozo e paz terei,\nSó por ver meu Deus e Rei;\nGlória cantarei com os remidos de Jesus."}, {"label": "Estrofe 3", "text": "Hei de ter as mais profundas e reais visões\nDesse Deus que me salvou de tristes condições;\nSeu amor e sua compaixão verei ali,\nComo nunca pude vê-los nesta vida aqui."}, {"label": "Estrofe 4", "text": "Vou gozar da companhia dos fiéis em luz,\nSalvos para sempre pela fé em meu Jesus;\nForam, sim, morar no céu com seu bendito Rei,\nNum prazer eterno que desfruta a santa grei."}], "reviewed": false}, {"number": 512, "title": "O Doce Lar", "page": 282, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Na pátria celeste, de Deus doce lar,\nPrepara Jesus para os seus um lugar,\nPois longe do mal, do pecado e da dor,\nConsigo pra sempre os quer ter seu Senhor."}, {"label": "Estrofe 2", "text": "Ó doce , doce lar!\nAí com Jesus vou pra sempre morar."}, {"label": "Estrofe 3", "text": "No lar sacrossanto de paz e de amor\nVerei sobre o trono eternal meu Senhor,\nO meigo Cordeiro, reinando na luz,\nPor todos louvado, bendito Jesus."}, {"label": "Estrofe 4", "text": "Que puras delícias se encontram em ti,\nQue gozos eternos me esperam ali;\nÀqueles que Deus junto a si quis trazer,\nAgora e pra sempre vai satisfazer."}, {"label": "Estrofe 5", "text": "Mas desses prazeres que anseio gozar,\nO que eu mais espero é com Cristo ficar,\nSem mais contristá-lo, sem mais ofender\nA quem, pra salvar-me, por mim quis morrer."}], "reviewed": false}, {"number": 513, "title": "Triunfo", "page": 282, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Milhares de milhares\nEu vejo em santa luz;\nSão os guerreiros salvos,\nMilícia de Jesus!\nE tendo já completa\nA longa luta aqui,\nCom Cristo, seu Senhor e Rei,\nVão descansar ali."}, {"label": "Estrofe 2", "text": "Aleluia! Aleluia\nA Cristo, seu Senhor!\nAleluia! Aleluia!\nVão ver seu Salvador."}, {"label": "Estrofe 3", "text": "Que doces sinfonias,\nEnchendo a terra e o céu!\nQue coros de aleluias,\nRompendo além do véu!\nÉ que chegou o dia,\nO dia triunfal,\nDe Cristo, o Mestre, enfim, reinar,\nEm glória divinal."}, {"label": "Estrofe 4", "text": "Então não há mais choro,\nNão há mais tentação;\nAs dores, as tristezas,\nPra sempre fugirão.\nEis que os remidos todos\nVerão seu Salvador,\nE, transformados todos, sim,\nIrão com o Senhor."}], "reviewed": false}, {"number": 514, "title": "Paz Real", "page": 283, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, quando o momento chegar\nDe eu ir com Jesus habitar,\nEm paz eu verei meu Senhor\nEm todo o seu esplendor."}, {"label": "Estrofe 2", "text": "Excelsa paz\nHei de gozar afinal,\nQuando eu com Jesus me encontrar\nNo reino celestial."}, {"label": "Estrofe 3", "text": "Que graça real, eficaz,\nA qual me outorgou plena paz,\nMercê que me bom Salvador\nMe dispensou com amor."}, {"label": "Estrofe 4", "text": "Em Cristo há perfeito perdão,\nHá nele real salvação,\nHá nele também essa paz\nQue agora me satisfaz."}], "reviewed": false}, {"number": 515, "title": "Na Glória", "page": 284, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, vai me encontrar na glória\nDa Jerusalém do céu,\nLá na habitação notória\nQue Jesus nos prometeu!\nLá encontrarás amigos,\nQue serão, em Cristo, irmãos;\nCantaremos belos hinos;\nVai de todo o coração!"}, {"label": "Estrofe 2", "text": "Sim, te encontrarei na glória,\nNa brilhante glória além!\nSim, te encontrarei na glória\nDa feliz Jerusalém!"}, {"label": "Estrofe 3", "text": "Oh, vai me encontrar na glória,\nPois eu te conhecerei\nPelo brilho da vitória\nQue Alcançares com teu Rei!\nHei de achar mais harmonia\nNo cantar que ali ouvir,\nQuando à santa companhia\nTua voz também se unir."}, {"label": "Estrofe 4", "text": "Oh, vai me encontrar na glória;\nMuito anseio ver-te lá,\nPois da vida a triste história\nA ninguém perturbará!\nVai com fé e de alma pura\nÀ feliz Jerusalém;\nGozo eterno, paz, ventura,\nTu terás na glória além."}], "reviewed": false}, {"number": 516, "title": "Além da Morte", "page": 284, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Há uma terra de prazer,\nMorada dos que crêem;\nO dia eterno reina ali,\nTristezas nunca têm."}, {"label": "Estrofe 2", "text": "É primavera sempre ali,\nE as flores durarão;\nAlegres campos, verdes, bons,\nNa linda terra estão."}, {"label": "Estrofe 3", "text": "Porém à entrada do País\nHá um profundo mar;\nPor suas águas, nós, mortais,\nHavemos de passar."}, {"label": "Estrofe 4", "text": "Os viajantes, com temor,\nÀ vista desse mar,\nTransidos, tremem de terror\nE querem recuar."}, {"label": "Estrofe 5", "text": "Mas o Senhor caminho abriu,\nTirou da morte o horror;\nCom gozo, os salvos hão de entrar\nNaquela lar de amor."}], "reviewed": false}, {"number": 517, "title": "Querido Lar", "page": 285, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "De todas as terras irão chegar\nUm a um! Um a um!\nNa eterna mansão, para ali morar,\nSim, um a um!\nVestidos de trajes celestiais,\nBem longe do mundo e dos tristes ais,\nDesfrutam com Cristo a perfeita paz,\nGozando uma vida que satisfaz."}, {"label": "Estrofe 2", "text": "No eterno lar, querido lar,\nEi-los entrando um a um!\nNo eterno lar, no lindo lar,\nSim, um a um!"}, {"label": "Estrofe 3", "text": "Também nós havemos de ali chegar,\nUm a um! Um a um!\nDa glória dos salvos compartilhar,\nSim, um a um!\nIrão uns entrar nesse lar de além\nSem muito sofrer no viver de aquém,\nMas outros terão de lutar, sofrer,\nPorém hão de entrar sem desfalecer."}, {"label": "Estrofe 4", "text": "Humildes, submissos a ti, Senhor,\nTodos nós! Todos nós!\nQueremos viver sob o teu favor,\nSim, todos nós!\nContigo almejamos participar\nDa vida gloriosa do eterno lar.\nÓ tu, que dominas a terra e os céus,\nTransporta-nos todos nos braços teus!"}], "reviewed": false}, {"number": 518, "title": "Glória", "page": 286, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Há um lugar de paz no mundo além,\nDos salvos a feliz Jerusalém.\nOh, como dão louvor\nA Cristo, o seu Senhor,\nCantando, com amor,\nSempre, sem fim!"}, {"label": "Estrofe 2", "text": "Cristo vos quer salvar; vinde e vereis!\nOh, vinde sem tardar, não hesiteis!\nCom ele ireis morar,\nPaz com Jesus gozar,\nE nunca mais pecar,\nSempre, sem fim!"}, {"label": "Estrofe 3", "text": "Gozando a salvação do bom Jesus,\nOs que no céu estão, brilham na luz;\nAo lar dos santos vêm\nSó os que nele crêem,\nE muita glória têm,\nSempre, sem fim!"}], "reviewed": false}, {"number": 519, "title": "Perante o Rei", "page": 286, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Estarei perante o Rei,\nCom os anjos cantarei,\nNo porvir, no porvir;\nCom Jesus irei aos céus,\nDando sempre glória a Deus.\nNo porvir, no porvir."}, {"label": "Estrofe 2", "text": "Estarei perante o Rei,\nCom os anjos cantarei\nGlória, glória a Cristo, o Rei!\nAleluia! Aleluia!\nEstarei perante o Rei."}, {"label": "Estrofe 3", "text": "Novos hinos cantarei,\nNa presença do meu Rei,\nNo porvir, no porvir;\nOnde não há pranto e dor,\nSó há gozo, paz e amor,\nNo porvir, no porvir."}, {"label": "Estrofe 4", "text": "Quando então eu acordar,\nE no paraíso entrar\nNo porvir, no porvir;\nCom os santos cantarei,\nNa presença do meu Rei,\nNo porvir, no porvir."}], "reviewed": false}, {"number": 520, "title": "Canaã Celeste", "page": 287, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Há uma terra de prazer,\nDe gozo e de fulgor,\nOnde os remidos hão de ver\nJesus, seu Benfeitor.\nA noite não existe lá,\nNem dores, nem pavor;\nMas só venturas haverá\nCom Cristo, o Redentor."}, {"label": "Estrofe 2", "text": "Em breve havemos de passar\nAs águas do Jordão,\nE, extasiados, contemplar\nA eterna habitação;\nAh, que prazer será ouvir\nDe Cristo a saudação!\nE tudo nos irá sorrir\nEm brilho e exultação."}], "reviewed": false}, {"number": 521, "title": "A Cidade Santa", "page": 287, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Em sonho encantador,\nUm dia eu vi Jerusalém\nE o templo do Senhor.\nOuvi cantar crianças,\nE em meio a seu cantar\nRompeu a voz dos anjos,\nDo céu a proclamar: (bis)\nJerusalém! Jerusalém!\nCantai, ó santa grei!\nHosana! Hosana!\nHosana ao vosso Rei!"}, {"label": "Estrofe 2", "text": "Então o sonho se alterou,\nNão mais o som feliz\nOuvia das hosanas\nDos coros infantis.\nO ar em torno se esfriou,\nDo sol faltava a luz,\nE num alto e tosco monte vi\nO vulto de uma cruz! (bis)\nJerusalém! Jerusalém!\n(Aos anjos escutei)\nHosana! Hosana!\nHosana ao vosso Rei!"}, {"label": "Estrofe 3", "text": "Ainda a cena se mudou;\nSurgia em resplendor\nA divinal cidade,\nMorada do Senhor.\nDa lua não brilhava a luz,\nNem sol nascia lá,\nMas só fulgia a luz de Deus,\nMui pura em seu brilhar.\nE todos que queriam, sim,\nPodiam logo entrar\nNa mui feliz Jerusalém,\nQue nunca passará. (bis)\nJerusalém! Jerusalém!\nTeu dia vai raiar!\nHosana! Hosana! (bis)\nHosana sem cessar!"}], "reviewed": false}, {"number": 522, "title": "Um Bom Amigo", "page": 288, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Há um bom amigo acima\nDo céu azul, sem-par;\nE mora nas alturas\nQuem sabe bem amar;\nAmigo mui constante,\nNão tem igual aqui;\nJesus é meu abrigo,\nE chama-me pra si."}, {"label": "Estrofe 2", "text": "Há descanso lá acima\nDo céu azul, sem-par;\nE todos quantos amam\nA Cristo o vão gozar.\nPecados e perigos\nDesconhecidos são,\nPois Cristo reina firme,\nCom poderosa mão."}, {"label": "Estrofe 3", "text": "Há morada lá acima\nDo céu azul, sem-par;\nMeninos e meninas,\nQuereis ir lá morar?\nO gozo deste mundo\nNão é pra comparar\nAo gozo que há com Cristo\nAli no eterno lar."}, {"label": "Estrofe 4", "text": "Há coroa lá acima\nDo céu azul, sem-par;\nE se eu, que sou criança,\nA meu Jesus amar,\nTerei no céu coroa,\nPois Deus de graça dá\nCoroa de vitória,\nQua nunca murchará."}, {"label": "Estrofe 5", "text": "Há um hino lá acima\nDo céu azul, sem-par;\nUm hino mui glorioso,\nPra sempre se cantar.\nÉ hino o qual os anjos\nNão sabem entoar;\nPertence aos pequeninos\nSeu Salvador louvar."}, {"label": "Estrofe 6", "text": "Há vestidos acima\nDo céu azul, sem-par;\nHá harpas afinadas,\nE infantes a louvar,\nCom todos os remidos,\nNo lar de resplendor,\nAo Salvador divino,\nSeu Rei e seu Senhor."}], "reviewed": false}, {"number": 523, "title": "Cordeirinhos", "page": 289, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Amigo dos meninos,\nBenigno Salvador,\nConosco sê presente,\nÓ meigo e bom Pastor!\nConduz os cordeirinhos\nCom grande compaixão;\nA graça excelsa dá-nos\nDe um reto coração."}, {"label": "Estrofe 2", "text": "Teus santos mandamentos\nEnsina-nos a amar,\nE tudo que te ofenda,\nDe pronto a desprezar;\nEm todos os estudos,\nQue temos hoje aqui,\nSejamos instruídos,\nÓ grande Deus, por ti!"}], "reviewed": false}, {"number": 524, "title": "Jóias Preciosas", "page": 290, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eis que Cristo vem à terra,\nBuscar suas jóias,\nSuas jóias mui preciosas,\nDe muito valor."}, {"label": "Estrofe 2", "text": "Como estrelas da aurora,\nBrilhando na fronte\nDe Jesus, lá na glória,\nAdorno serão."}, {"label": "Estrofe 3", "text": "Vem buscá-las, vai levá-las\nAo reino celeste,\nSuas jóias resplendentes,\nDe muito valor."}, {"label": "Estrofe 4", "text": "Os meninos e as meninas\nQue servem a Cristo\nSão-lhe jóias, ricas jóias,\nDe muito valor."}], "reviewed": false}, {"number": 525, "title": "Vinde, Meninos", "page": 290, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vinde, meninos, vinde a Jesus;\nEle ganhou-vos, bênçãos na cruz!\nOs pequeninos ele conduz;\nOh! vinde ao Salvador!"}, {"label": "Estrofe 2", "text": "Que alegria, sem pecado ao mal,\nReunir-nos todos, afinal,\nJuntos na pátria celestial,\nPerto do Salvador!"}, {"label": "Estrofe 3", "text": "Já, sem demora, a todos convém\nIr caminhando à glória de além;\nCristo vos chama, quer vosso bem,\nOh, vinde ao Salvador!\nQue ama os meninos, Cristo voz diz,\nEle quer dar-vos vida feliz.\nPara habitar no lindo país,\nOh, vinde ao Salvador!"}, {"label": "Estrofe 4", "text": "Eis a chamada:\n\"Vinde hoje a Mim!\"\nOutro não há que nos ame assim;\nSeu é amor que nunca tem fim,\nOh! Vinde ao Salvador!"}], "reviewed": false}, {"number": 526, "title": "Os Meninos", "page": 291, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Venham, venham os meninos\nAo bendito Salvador;\nCristo mesmo quer salvá-los,\nQuer mostrar-lhes seu favor.\nJesus Cristo! (bis)\nOh, quão grande é seu amor!"}, {"label": "Estrofe 2", "text": "Venham, venham os meninos,\nPois Jesus os convidou;\nEle todos os pecados\nNa cruenta cruz pagou.\nJesus Cristo (bis)\nSeu amor leal provou."}, {"label": "Estrofe 3", "text": "Venham, venham os meninos,\nVenham a Jesus servir,\nSujeitar-se a seus preceitos,\nSeus conselhos bons seguir,\nJesus Cristo (bis)\nOs seus rogos quer ouvir!"}], "reviewed": false}, {"number": 527, "title": "A Bênção", "page": 291, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A Jesus crianças vinham\nSuas bênçãos suplicar;\nPois a mim, que sou criança,\nOh, não há de recusar!"}, {"label": "Estrofe 2", "text": "Das crianças de outro tempo\nEle teve compaixão;\nOh, não há de despedir-me\nSem me dar a salvação!"}, {"label": "Estrofe 3", "text": "Não mais anda neste mundo,\nMas na glória Cristo está.\nQue as crianças inda venham:\nEle as abençoará."}, {"label": "Estrofe 4", "text": "Minhas mãos tão pequeninas\nTe suplicam, ó Senhor:\nDá-me, pois, a tua bênção,\nTua graça e teu amor!"}], "reviewed": false}, {"number": 528, "title": "Aspiração Infantil", "page": 292, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Aqui no mundo branda luz,\nÓ Deus, desejo ser -\nFiel reflexo de Jesus\nQue mostre seu poder."}, {"label": "Estrofe 2", "text": "Em minhas casa, bela flor\nQue praza a meus bons pais\nE agrade a Deus, o Criador\nDe plantas imortais."}, {"label": "Estrofe 3", "text": "Em minha escola, pronta mão,\nQue tome com prazer\nO pão do ensino e da instrução,\nQue aumente o meu saber."}, {"label": "Estrofe 4", "text": "No culto, sempre doce voz\nQue louve a meu Senhor,\nEm companhia, ou mesmo a sós,\nCom viva fé e ardor."}, {"label": "Estrofe 5", "text": "Eu, em qualquer lugar\nEm que me possa achar,\nÓ Deus, desejo te servir\nE teu amor sentir."}], "reviewed": false}, {"number": 529, "title": "Vai Buscar", "page": 292, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ouço o clamor do bom Pastor\nPelo deserto abrasador,\nSeus cordeirinhos a chamar,\nMui desejoso de os salvar."}, {"label": "Estrofe 2", "text": "Vai buscar! Vai buscar!\nMeus cordeirinhos vai buscar!\nVai buscar! Vai buscar!\nPara que os possa abençoar."}, {"label": "Estrofe 3", "text": "Quem não deseja auxiliar\nSeus cordeirinhos a guardar\nE encaminhá-los a Jesus.\nFonte de vida, amor e luz?"}, {"label": "Estrofe 4", "text": "Pelo deserto a padecer,\nPelas estradas a morrer,\nSeus cordeirinhos vai buscar,\nPara que os possa abençoar."}], "reviewed": false}, {"number": 530, "title": "Soldado Infantil", "page": 293, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sou um soldado de Jesus Cristo,\nNa luta insisto e tenho valor;\nEu sou pequeno, mas a meu lado\nVai meu amado Rei, meu Senhor."}, {"label": "Estrofe 2", "text": "Hostes ferozes dos inimigos,\nEu as persigo e posso vencer;\nLuto por Cristo, o Rei poderoso,\nNele acharei a força e poder."}, {"label": "Estrofe 3", "text": "Para o combate vou preparado,\nE meu escudo carrego já;\nSua Palavra serve de espada.\nFoi-me doada por Deus, Jeová."}, {"label": "Estrofe 4", "text": "Marcho ditoso com estas armas,\nPois a vitória eu alcançarei;\nE são e salvo, cheio de vida,\nNa santa causa me gastarei."}, {"label": "Estrofe 5", "text": "Todos marchemos para a peleja,\nTendo em combate trombeta e luz;\nFirmes, avante, pois que a vitória\nÉ para a glória do Rei Jesus."}], "reviewed": false}, {"number": 531, "title": "Teu Cantinho", "page": 294, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo é que nos manda como luz brilhar,\nPara o pecador ao céu encaminhar.\nÉ um privilégio que Jesus nos deu;\nTu no teu cantinho e eu no meu."}, {"label": "Estrofe 2", "text": "Cheio o mundo todo está de escuridão.\nMas as nossas luzes trevas desfarão,\nElas são benditas, Cristo no-las deu,\nTu no teu cantinho e eu no meu."}, {"label": "Estrofe 3", "text": "Cada pequenino tem o seu dever\nDe Jesus amar e sempre obedecer;\nEssa luz alcemos, que Jesus nos deu,\nTu no teu cantinho e eu no meu"}], "reviewed": false}, {"number": 532, "title": "Ó Meninos, Vinde", "page": 294, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó meninos, vinde agora\nA Jesus, Salvador,\nO qual vos espera;\nQuer-vos dar seu amor."}, {"label": "Estrofe 2", "text": "Vinde todos sem demora,\nVinde já sem temer;\nJesus vos aceita\nCom imenso prazer."}, {"label": "Estrofe 3", "text": "Ele chama com ternura:\n\"Vinde todos a mim,\nGozar no meu seio\nSegurança sem fim.\""}, {"label": "Estrofe 4", "text": "Sim, Jesus nós, pequeninos,\nPressa temos de vir\nA teus braços fortes,\nTeu amor possuir."}], "reviewed": false}, {"number": 533, "title": "Pequenos Guerreiros", "page": 294, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eia, guerreirinhos, por Jesus lutai;\nConfiando nele, ide, batalha!\nCristo comandando, vos protegerá,\nE vitória certa sempre vos dará.\nEia guerreirinhos, luz, pois, difundi;\nSim, a espada santa sem temor brandi;\nFirmes nas fileiras, cheios de fervor,\nIde proclamando as novas do Senhor."}, {"label": "Estrofe 2", "text": "Eia, guerreirinhos, com intrepidez,\nAvançando, firmes, todos de uma vez,\nPois tereis vitória como galardão;\nSede lutadores de alta distinção."}], "reviewed": false}, {"number": 534, "title": "Cantam Glória", "page": 295, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Perante o trono do Senhor,\nNa glória de Jesus,\nCrianças aos milhares há,\nBrilhando em santa luz."}, {"label": "Estrofe 2", "text": "Cantam: 'Glória, glória,\nGlória ao Salvador Jesus!'"}, {"label": "Estrofe 3", "text": "Dos seus pecados o perdão\nJesus lhes concedeu,\nE agora, em sempiterna paz,\nCom ele estão no céu."}, {"label": "Estrofe 4", "text": "Na eterna habitação feliz,\nDe glória, brilho e amor,\nInfantes, salvos por Jesus,\nEntoam seu louvor."}, {"label": "Estrofe 5", "text": "Quem, na cruenta, amarga cruz,\nSeu sangue derramou,\nAs criancinhas já remiu,\nE o céu lhes outorgou."}, {"label": "Estrofe 6", "text": "Na vida amavam a Jesus,\nBuscavam seu amor;\nAgora face a face estão\nCom ele em seu fulgor."}], "reviewed": false}, {"number": 535, "title": "Hosana Infantil", "page": 295, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Num sonho vi em resplendor\nO céu de glória e luz;\nVi multidões, lá junto a Deus,\nDe salvos por Jesus.\nPor entre a multidão feliz\nSurgir crianças vi.\nCantando um coro angelical\nQue ecoava até aqui:"}, {"label": "Estrofe 2", "text": "Hosana! Hosana!\nAo nosso Salvador!\nHosana! Hosana!\nRendemos-te louvor!"}, {"label": "Estrofe 3", "text": "Depois, a doce voz ouvi\nDe Cristo, o Salvador,\nQue assim dizia aos servos seus,\nCom puro e santo amor:\n'Não impeçais de vir a mim\nOs seres infantis,\nPorque dos tais é o santo céu,\nMorada tão feliz.'"}, {"label": "Estrofe 4", "text": "E, despertando, compreendi\nQue infantes devem ser\nLevados a Jesus, o Rei,\nO que lhe dá prazer;\nE sempre o sirvam com fervor,\nNa terra aqui também,\nE o louvem, como fazem lá,\nNaquele coro além."}], "reviewed": false}, {"number": 536, "title": "A Lição", "page": 296, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus amado, escuta\nA nossa petição,\nE dá-nos teu auxílio\nNas horas da lição;\nNo tempo dos estudos,\nEnsina-nos a estar,\nCom grande diligência,\nCada um em seu lugar."}, {"label": "Estrofe 2", "text": "Concede-nos cuidado,\nE dá-nos mansidão,\nOuvindo nosso Mestre\nCom dócil atenção.\nAmemos uns aos outros\nCom verdadeiro amor\nE sempre obedeçamos\nAo grande Salvador."}], "reviewed": false}, {"number": 537, "title": "Desejo Infantil", "page": 297, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sou um infantil, gosto de brincar,\nMas o mundo vil quero desprezar;\nSempre a Cristo honrar, seu querer fazer,\nSua lei amar, eis o meu prazer!"}, {"label": "Estrofe 2", "text": "Aleluia! Aleluia!\nAmo a meu Jesus!\nAleluia! Aleluia!\nQuero andar na luz!"}, {"label": "Estrofe 3", "text": "Sou um infantil, quase nada sei,\nMas meu ser gentil eu ao Mestre dei.\nAmo a meu Jesus, ele me remiu,\nBusco a sua luz, minha voz ouviu!"}, {"label": "Estrofe 4", "text": "Sou um infantil, tenho pouca fé,\nMas o meu Brasil quero ver de pé,\nTenho fé em Deus, salvo por Jesus,\nSendo os filhos seus campeões da cruz!"}], "reviewed": false}, {"number": 538, "title": "Oh, Vinde, Meninos", "page": 297, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Oh, vinde, meninos!\nCantai a linda história\nDo bom Messias dos juDeus,\nJesus, o Salvador!\nE repeti, com gratidão,\nA doce e terna exclamação:\n'Dexai os meninos,\nQue venham a mim!'"}, {"label": "Estrofe 2", "text": "Pais crentes, devotos,\nTraziam os filhinhos,\nBuscando a bênção e oração\nDe Cristo-Emanuel.\nMas com palavras de rigor\nSão afastados do Senhor:\n'Levai os meninos,\nTirai-os daqui!'"}, {"label": "Estrofe 3", "text": "Mas, eis que o bom Mestre,\nCom voz suave e meiga,\nOs pequeninos chama a si,\nE aos circunstantes diz:\n'Sobre eles minhas mãos porei,\nE pelo tais eu orarei;\nDeixai os meninos\nQue venham a mim!'"}, {"label": "Estrofe 4", "text": "Oh, vinde, meninos!\nJesus vos deu seu sangue\nE vos convida para os céus.\nBuscai a salvação!\nOuvi a voz do Redentor,\nEle é o vosso bom Pastor:\n'Dexai os meninos\nQue venham a mim!'"}], "reviewed": false}, {"number": 539, "title": "Brilhando", "page": 298, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vejo no céu resplendente\nDo sol a clara luz;\nQuero viver tão-somente\nBrilhando por Jesus."}, {"label": "Estrofe 2", "text": "Brihando, brilhando,\nQuero brilhar como a luz!\nBrihando, brilhando,\nSempre brilhar por Jesus!"}, {"label": "Estrofe 3", "text": "Eu quero em tudo exaltá-lo,\nNa escola e no estudar;\nNunca também olvidá-lo\nEm casa e no brincar."}, {"label": "Estrofe 4", "text": "Com um viver diligente,\nAssim me quer Jesus;\nSempre com rosto contente,\nBrilhando como a luz."}, {"label": "Estrofe 5", "text": "Do feio e triste pecado,\nSenhor, vem-me guardar;\nSempre por ti amparado\nDesejo, ó Deus, andar."}, {"label": "Estrofe 6", "text": "Se esta é a tua vontade,\nBrilhando viverei,\nE pela tua bondade\nAo lindo céu irei."}], "reviewed": false}, {"number": 540, "title": "Oração de Criança", "page": 298, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Jesus escuta o rogar terninho\nDa criancinha na petição;\nTmbém conhece seus bons intentos,\nOs pensamentos do coração."}, {"label": "Estrofe 2", "text": "Não é bastante quando ajoelhamos\nQue pareçamos a Deus orar;\nCom a nossa boca também devia\nEm harmonia nossa alma estar."}, {"label": "Estrofe 3", "text": "Jesus sem falta valer-nos pode,\nE proteger-nos sempre ele quer;\nQualquer menino que a Cristo peça\nTerá auxílio que lhe é mister."}, {"label": "Estrofe 4", "text": "A Deus contemos as nossas mágoas,\nBem confiandos no seu amor;\nO que convenha receberemos,\nSe fé nós temos no Salvador."}, {"label": "Estrofe 5", "text": "Jesus escuta o rogar terninho\nDa criancinha na petição;\nTambém conhece seus bons intentos,\nOs pensamentos do coração."}], "reviewed": false}, {"number": 541, "title": "Pequenos Raios", "page": 299, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Deus dá às criancinhas,\nPor onde ele as conduz,\nO encargo tão glorioso:\nBrilhar por seu Jesus.\nSejamos lindos raios\nDa luz do Deus de amor,\nPra dissipar as trevas\nDispersas ao redor."}, {"label": "Estrofe 2", "text": "Pequenos raios somos\nDa verdadeira luz;\nEm todos ao lugares\nBrilhemos por Jesus. ( bis )"}, {"label": "Estrofe 3", "text": "As nuvens tão escuras\nEscondem nossa luz;\nA vida tem tristezas,\nPesada é nossa cruz.\nMas, como belos raios,\nCumpramos a missão\nDe dar sempre alegria\nA cada coração.\nQue grande privilégio,\nBrilhar, sim, por Jesus\nE desfazer as trevas,\nPra dar lugar à luz.\nCom pensamentos puros\nVivamos em amor;\nSejamos raiozinhos\nQue brilhem sem temor."}], "reviewed": false}, {"number": 542, "title": "Jesus e as Crianças", "page": 300, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Cristo tem amor por mim,\nCom certeza creio assim;\nPor amor de mim morreu,\nVivo está por mim no céu."}, {"label": "Estrofe 2", "text": "Sim, Jesus me tem amor,\nPois se fez meu Salvador;\nHoje ainda tem prazer\nDe crianças receber."}, {"label": "Estrofe 3", "text": "Pra gozar seu rico amor,\nHei de amar meu Salvador,\nE desejo anunciar\nSeu amor tão singular."}, {"label": "Estrofe 4", "text": "Meu Senhor Jesus está\nAo meu lado e levará,\nAfinal, ao céu de luz,\nOs que resgatou na cruz."}, {"label": "Estrofe 5", "text": "Ama os meninos, ama as meninas,\nAma os meninos, Jesus, o Salvador. ( bis )"}], "reviewed": false}, {"number": 543, "title": "Cântico Escolar", "page": 300, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Alerta, meninos! Tenhamos viveza,\nTenhamos coragem, também decisão!\nPois tudo é custoso para o preguiçoso,\nQue a nada se dá com leal coração!"}, {"label": "Estrofe 2", "text": "Alerta, meninos! Devemos mostrar\nQue a Deus, nosso Pai, procuramos honrar."}, {"label": "Estrofe 3", "text": "Em breve esperamos, aos pais ajudando,\nPagar-lhes um pouco do seu muito amor.\nAgora estudamos e assim agradamos\nAos caros parentes e ao bom professor.\nNo fim dos estudos, dispostos e alegres,\nPra casa voltamos com muito prazer;\nCom zelo estudando, com gosto brincando,\nBusquemos em tudo por Cristo viver."}], "reviewed": false}, {"number": 544, "title": "Avante, Mocidade", "page": 301, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mocidade cristã, eia, avante!\nVossas forças uni pra lutar!\nO inimigo potente se mostra,\nMas com Cristo sois fortes: Marchar!"}, {"label": "Estrofe 2", "text": "Mocidade cristã, eia, avante!\nContra o mal, contra o erro lutai!\nTendo o santo evangelho por arma,\nA verdade da cruz proclamai!"}, {"label": "Estrofe 3", "text": "Mocidade cristã, vede o abismo,\nOnde muitos estão a cair!\nPor faltar-lhes a luz do evangelho,\nNão procuram a Cristo seguir."}, {"label": "Estrofe 4", "text": "Eia, jovens, ativos obreiros,\nPela causa do bem pelejai!\nIde aos povos levar o evangelho,\nPara a glória de Deus trabalhai!"}], "reviewed": false}, {"number": 545, "title": "Vamos À Escola", "page": 301, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vamos, jovens alunos, à escola,\nA Palavra de Deus estudar,\nBoas-novas ouvirmos de Cristo,\nE favores reais alcançar."}, {"label": "Estrofe 2", "text": "Oh, vem, sim, vem à escola comigo\nOuvir boas-novas dos céus;\nBoas coisas ali aprendemos\nDa bendita Palavra de Deus."}, {"label": "Estrofe 3", "text": "Vamos, jovens alunos, à escola,\nPois queremos louvar ao Senhor,\nSeus conselhos ouvir com respeito,\nQue se ensinam ali com amor."}, {"label": "Estrofe 4", "text": "Ó Jesus, sê presente na escola,\nInspirando-nos santo poder,\nE que sempre, do estudo aqui feito,\nMuito fruto possamos colher."}], "reviewed": false}, {"number": 546, "title": "Mocidade, Avante", "page": 302, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Eia, avante, mocidade,\nVamos por Jesus lutar!\nA peleja é mui gloriosa,\nDeus nos há de auxiliar.\nEia, avante, camaradas,\nOlhos fitos em Jesus!\nCaminhemos destemidos,\nAvancemos para a luz!"}, {"label": "Estrofe 2", "text": "Por Jesus, com zelo santo,\nVinde, jovens, combater!\nA mensagem do evangelho\nProclamai até morrer!"}, {"label": "Estrofe 3", "text": "Eia, avante, mocidade,\nNunca, nunca recuar!\nSó há um caminho certo,\nEia, jovens, avançar!\nEia, avante, camaradas,\nProclamai como um clarim\nAs palavras do convite:\n\"Vinde todos, vinde a mim!\""}, {"label": "Estrofe 4", "text": "Eia, avante, mocidade,\nConfiando no Senhor!\nOnde há fé ninguém vacila!\nPois há vida, luz, vigor!\nEia, avante, camaradas,\nSempre unidos a lutar,\nSempre unidos na esperança,\nSempre unidos no avançar!"}], "reviewed": false}, {"number": 547, "title": "Semeando e Segando", "page": 302, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Semente lançada na terra\nGermina e seu fruto produz:\nAs nossas ações e palavras\nDão ceifa de trevas ou luz."}, {"label": "Estrofe 2", "text": "O Joio do mal espalhado,\nColheita maldita dará;\nO trigo do bem semeado,\nColheita de bêçãos trará."}, {"label": "Estrofe 3", "text": "Que queres, ó jovem, segar?\nA morte ou a vida será!\nO fruto decerto se colhe\nDe tudo que se semear."}, {"label": "Estrofe 4", "text": "Se, pois, tu semeias na carne,\nA morte eternal tu terás;\nPorém se no Espírito andares,\nDa vida do céu gozarás."}, {"label": "Estrofe 5", "text": "Semente do bem, pois, semeia,\nBondade e palavras de amor;\nFeliz tu serás para sempre\nCom Cristo Jesus, o Senhor."}], "reviewed": false}, {"number": 548, "title": "Jovens Lutadores", "page": 303, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó jovens, acudi ao brilhante pavilhão\nQue Jesus há desfraldado na nação!\nA todos Cristo quer nas fileiras receber.\nE mui firmes nos levar o mal a combater."}, {"label": "Estrofe 2", "text": "Vamos com Jesus e marchemos sem temor!\nVamos ao combate, inflamados de valor!\nCom coragem, vamos todos contra o mal!\nEm Jesus teremos nosso General! ( bis )"}, {"label": "Estrofe 3", "text": "Ó jovens, acudi ao divino Vencedor;\nQuer juntar-vos todos hoje a seu redor!\nDispostos a lutar, vinde, pois, sem vacilar;\nVamos prontos, companheiros, vamos a lutar!"}, {"label": "Estrofe 4", "text": "Quem nesta guerra entrar sua voz escutará,\nCristo então vitória lhe concederá!\nSaiamos, meus irmãos, invistamos mui fiéis;\nCom Jesus conquistaremos imortais lauréis!"}], "reviewed": false}, {"number": 549, "title": "Alerta, Mocidade", "page": 303, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Alerta, mocidade!\nÀ guerra vos chamou\nJesus, que sua vida\nPor vós sacrificou."}, {"label": "Estrofe 2", "text": "Alerta, mocidade!\nA Cristo obedecei!\nOlhando para Cristo,\nA causa defendei."}, {"label": "Estrofe 3", "text": "Alerta, mocidade!\nE sede campeões;\nTomados de coragem,\nVencei as tentações."}, {"label": "Estrofe 4", "text": "Alerta, mocidade!\nAvante, sem temor!\nPois certa é a vitória\nDos crentes no Senhor."}, {"label": "Estrofe 5", "text": "Leais, entrai\nNa guerra contra o mal!\nJamais canseis\nNa luta sem igual. ( bis )"}], "reviewed": false}, {"number": 550, "title": "Juventude", "page": 304, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Levantai-vos, moços crentes,\nPara anunciar Jesus\nComo Salvador do mundo,\nVerdadeiro guia e luz."}, {"label": "Estrofe 2", "text": "Despertai-vos! Levantai-vos!\nNão há tempo que perder.\nSe quereis servir a Cristo,\nTendes muito que fazer.\nMeditai no seu amor,\nMeditai no que ele fez:\nPela morte no Calvário,\nResgatou-nos de uma vez! ( bis )"}, {"label": "Estrofe 3", "text": "Sim, ele é 'a luz do mundo'!\nEle poderá dizer:\n'Só eu dou a vida eterna\nA qualquer que queira crer.'"}, {"label": "Estrofe 4", "text": "Pois se nós estamos certos\nDe que Cristo é Salvador,\nVamos publicá-lo a todos\nCom coragem e fervor."}, {"label": "Estrofe 5", "text": "E se nós, sinceramente,\nJá servimos nosso Deus,\nExultamos na certeza\nDe encontrá-lo lá nos céus."}], "reviewed": false}, {"number": 551, "title": "Mocidade", "page": 305, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mocidade, deixa o mundo,\nCom seu mal e seu pesar,\nE procura o amor fecundo\nQue Jesus quer te ofertar;\nNo aconchego dos seus braços,\nTu terás consolo e amor;\nMocidade, nos teus passos,\nSegue os passos do Senhor!"}, {"label": "Estrofe 2", "text": "Mocidade, a vida é bela\nQuando em bênçãos se traduz,\nQuando na alma um céu estrela\nAs promessas de Jesus;\nVê que o mundo se debate\nEntre as ondas da paixão;\nMocidade, nesse embate,\nAnuncia a salvação."}, {"label": "Estrofe 3", "text": "Mocidade, ergue a bandeira\nContra o mundo e seus ardis;\nMocidade brasileira,\nCom Jesus serás feliz! ( bis )"}], "reviewed": false}, {"number": 552, "title": "Mocidade Crente", "page": 305, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Levantai-vos, jovens crentes,\nFirmes pela cruz!\nCombatei os inimigos\nDo Senhor Jesus!"}, {"label": "Estrofe 2", "text": "Lealdade, ó jovens crentes,\nA Jesus Senhor!\nFirmes sempre nas doutrinas\nDo bom Redentor. ( bis )"}, {"label": "Estrofe 3", "text": "Vede as hostes temerárias,\nCheias de furor;\nOh, unidos combatamos\nSempre, sem temor!"}, {"label": "Estrofe 4", "text": "Avançai com lealdade,\nFirmes em Jesus!\nSeja a Bíblia vosso guia,\nSeja vossa luz."}], "reviewed": false}, {"number": 553, "title": "Lealdade a Cristo", "page": 306, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mocidade, estais amando\nA Jesus e seu pendão?\nJá marchais sob seu comando,\nDe abrasado coração?\nDedicai-vos, sem reserva,\nAo serviço de Jesus.\nPois o inferno se conserva\nEm combate contra a luz!"}, {"label": "Estrofe 2", "text": "Defendei a sã doutrina;\nProclamai com grande ardor\nTudo quanto nos ensina\nA palavra do Senhor.\nCombatei a vil mentira,\nAvançai em união,\nTenho sempre em vossa mira\nJesus Cristo e seu pendão!"}, {"label": "Estrofe 3", "text": "Despertai-vos já e vede\nQuantas almas há sem luz,\nTão cansadas e com sede\nDo descanso de Jesus;\nApontai-lhes a água viva\nQue dimana do Senhor;\nEla torna rediviva\nA alma opressa, sem vigor."}, {"label": "Estrofe 4", "text": "Transmiti o dom eterno\nQue lograstes alcançar;\nDeus, em seu amor paterno,\nOs perdidos quer salvar.\nSim, de vós é que se espera\nQue ao Brasil a luz leveis,\nOnde o erro tanto impera\nContra Cristo e suas leis."}], "reviewed": false}, {"number": 554, "title": "Agora", "page": 306, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ó moços, que ventura\nVos é servir a Deus!\nCom vida santa e pura\nCorrer caminho aos céus;\nChegai-vos sem demora\nA Cristo, o Salvador;\nAproveitai agora,\nFugi da eterna dor.\nPor que só na velhice\nServir a Deus quereis?\nTambém, quem foi que disse\nQue lá vós chegareis?\nNão dura a mocidade\nMais que mimosa flor;\nCorrei com brevidade\nA dar-vos ao Senhor."}, {"label": "Estrofe 2", "text": "Que pobre sacrifício\nA Deus oferecer:\nDeixar pecado e vício\nSó ao envelhecer!\nSe endureceis vossa alma\nÀ santa vocação,\nLembrai que Deus condena\nA vossa dilação."}], "reviewed": false}, {"number": 555, "title": "Alerta, Jovens", "page": 307, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vinde, ó mocidade,\nDedicar com todo o amor,\nSim, com ansiedade,\nVossa vida ao Salvador.\nEle vos convida\nPara virdes trabalhar;\nNessa santa lida,\nVinde com prazer entrar."}, {"label": "Estrofe 2", "text": "Trabalhar com todo o ardor,\nVinde vós, ó moços,\nPor Jesus, Senhor! ( bis )"}, {"label": "Estrofe 3", "text": "Contemplai as almas\nLonge do Senhor Jesus;\nComo vivem calmas\nSem saber do amor da cruz!\nAndam enganadas,\nSem pensar no triste fim;\nSem Jesus, coitadas,\nÉ um triste estado, sim!"}, {"label": "Estrofe 4", "text": "Oh, levai a nova\nQue Jesus lhes dá perdão!\nIde dar a prova\nDesse amor da salvação!\nVede como as gentes,\nAfastadas do bom Deus,\nTodas descontentes,\nClamam pela luz dos céus."}], "reviewed": false}, {"number": 556, "title": "Oração para a Noite", "page": 308, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Finda-se este dia que meu Pai me deu;\nSombras vespertinas cobrem já o céu.\nÓ Jesus bendito, se comigo estás\nEu não temo a noite, vou dormir em paz."}, {"label": "Estrofe 2", "text": "Com os meus pecados eu te entristeci,\nMas perdão te peço por amor de ti.\nSou humano e fraco, livra-me do mal,\nE em sossego tenho sono e paz real."}, {"label": "Estrofe 3", "text": "Guarda o marinheiro no violento mar,\nE ao que sofre dores queiras confortar;\nAo tentado estende tua mão, Senhor;\nManda ao triste e aflito teu Consolador."}, {"label": "Estrofe 4", "text": "Pelos pais e amigos, pela santa lei,\nPelo amor divino graças te darei.\nÓ Jesus, aceita minha petição,\nE seguro durmo sem perturbação."}], "reviewed": false}, {"number": 557, "title": "O Anoitecer", "page": 308, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vai fugindo o dia, breve a noite vem,\nVespertina estrela já se avista além."}, {"label": "Estrofe 2", "text": "Ao que mui cansado na tristeza jaz,\nDá, Jesus bendito, teu descanso e paz."}, {"label": "Estrofe 3", "text": "Noite de sossego vimos te pedir;\nQue por ti guardados, vamos nós dormir."}, {"label": "Estrofe 4", "text": "Quando despertarmos, seja, bom Senhor,\nPara te servirmos com maior vigor."}], "reviewed": false}, {"number": 558, "title": "Hino Vespertino", "page": 308, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Salvador, por ti guardados,\nDesejamos descansar.\nOs defeitos e os pecados\nTu nos podes perdoar.\nSe de noite algum perigo\nContra nós puder surgir,\nTeu amor nos dê abrigo\nE nos deixe em paz dormir."}, {"label": "Estrofe 2", "text": "Dos teus olhos trevas densas\nNão nos podem ocultar;\nTeu cuidado nos dispensas\nNum constante vigiar.\nSe esta noite adormecemos\nPara o nosso fim mortal,\nCom certeza acordaremos\nNa mansão celestial."}], "reviewed": false}, {"number": 559, "title": "Fim do Ano", "page": 309, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Já termina o ano velho;\nDamos a Jesus louvor,\nQue do mal nos tem guardado\nTodo este ano com amor."}, {"label": "Estrofe 2", "text": "Cristo eterno, te rogamos\nQue na eternidade além,\nDe teu Pai, no trono excelso,\nNós gozemos todo bem."}, {"label": "Estrofe 3", "text": "A verdade em nós conserva;\nTem nossa alma em proteção;\nDe doutrina falsa e ímpia\nLivra nosso coração."}, {"label": "Estrofe 4", "text": "Do pecado nos afasta,\nNossos passos vem guiar,\nE, esquecidas nossas culpas,\nUm bom ano vem nos dar."}, {"label": "Estrofe 5", "text": "Dá-nos vida santa e justa,\nEm teus passos sempre andar,\nE, no dia derradeiro,\nJunto a ti feliz lugar."}], "reviewed": false}, {"number": 560, "title": "Ano Novo", "page": 309, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Rompe a aurora, vai-se embora\nMais um ano de labor;\nNão temamos, prossigamos\nA lutar com mais ardor.\nCada dia Cristo, o Guia,\nNos renove o coração;\nTemos gozo, bom repouso,\nConfiando em sua mão."}, {"label": "Estrofe 2", "text": "Do pecado resgatados,\nPertencemos a Jesus;\nNova vida, santa lida,\nTemos nós por sua cruz."}, {"label": "Estrofe 3", "text": "Hinos santos entoemos\nE louvemos ao Senhor!\nVem do arcano mais um ano\nQue anuncia seu favor!"}, {"label": "Estrofe 4", "text": "O ano findo nunca mais veremos;\nO ano novo hoje recebemos!\nVê, vê, o belo dom que Deus nos dá!"}], "reviewed": false}, {"number": 561, "title": "Salve, Ano Novo", "page": 310, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Grande, Senhor, é tua compaixão,\nAlta, veraz, é tua salvação;\nNo decorrer deste ano que findou\nFoi teu amor que nossas vidas conservou."}, {"label": "Estrofe 2", "text": "Com prazer todos nós rendemos-te louvor,\nA ti, o nosso Deus e grande Benfeitor."}, {"label": "Estrofe 3", "text": "Grande Pastor, nos meses a correr,\nNa retidão queremos nós viver,\nSer-te fiéis na dura provação\nE te servir com verdadeira gratidão."}, {"label": "Estrofe 4", "text": "Ano feliz queremos, pois, gozar,\nNosso labor queremos ver vingar;\nFaze, Senhor, teu povo progredir,\nE ao Salvador sedentas almas atrair."}, {"label": "Estrofe 5", "text": "Olha, Senhor, a terra do Brasil,\nVem conceder-lhe tuas bênçãos mil,\nDando ao país durável proteção;\nAtende, pois, ó Mestre, a nossa petição."}], "reviewed": false}, {"number": 562, "title": "Templo Novo", "page": 310, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "A ti, ó Deus, louvores altos damos,\nAo ser divino, com intenso ardor!\nConcerto divinal aqui firmamos,\nTeu culto celebramos com fervor.\nHoje, dedica-se este templo novo,\nMarco altaneiro do favor de Deus;\nVem, ó Senhor, contempla aqui teu povo,\nSim, vem abençoá-lo lá dos céus!"}, {"label": "Estrofe 2", "text": "Mui fervorosas graças te rendemos\nPor esta casa de oração aqui,\nPois nela, ó Deus, o culto a ti daremos,\nUngidos com ardente fé em ti.\nSeja teu evangelho aqui pregado\nAos pecadores com tão santo amor,\nQue busquem o perdão do seu pecado\nAos pés do nosso amado Redentor!"}, {"label": "Estrofe 3", "text": "Oh, todos quantos nesta casa entrarem\nInstruam-se de Deus na santa lei!\nE possam, Pai, também se consolarem\nAtribulados desta tua grei!\nFaze que nesta casa sempre habitem\nOs teus fiéis em plena comunhão,\nQue tuas ricas bênçãos os incitem\nA tua casa amar de coração!"}], "reviewed": false}, {"number": 563, "title": "Consagração de Templo", "page": 311, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Entoemos hinos de louvor a Deus\nPelas bênçãos que ele deu aos filhos seus,\nPois podemos consagrar ao Salvador\nEste templo em sua honra e em seu louvor."}, {"label": "Estrofe 2", "text": "Louvai, cantai hinos de alegria!\nLouvai, cantai sempre em harmonia!\nSim, louvemos com fervor\nA Jesus, o Salvador,\nPelas bênçãos que ele deu a todos nós! ( bis )"}, {"label": "Estrofe 3", "text": "Qual farol em densas trevas a raiar,\nMostra ao viajor o rumo em alto mar;\nDesta casa a luz celeste há de luzir,\nPara à salvação errantes conduzir."}, {"label": "Estrofe 4", "text": "Nesta casa os crentes vêm, com devoção,\nTributar ao Deus supremo adoração;\nNovas forças para a luta vêm buscar,\nE em conjunto todos vêm a Deus louvar."}], "reviewed": false}, {"number": 564, "title": "Mais Um Templo", "page": 312, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Hoje, inaugura-se aqui, santo Deus,\nMais um padrão de teu amor;\nUm novo templo, fanal para os céus,\nCausa de mais louvor!"}, {"label": "Estrofe 2", "text": "Casa de cultos e fonte de luz,\nOnde o Senhor dá salvação\nPelo evangelho que trouxe Jesus\nCom tanta compaixão!"}, {"label": "Estrofe 3", "text": "Marco sublime da proclamação\nDo teu amor, do teu querer;\nOs pecadores aqui ouvirão\nQual é o seu dever."}, {"label": "Estrofe 4", "text": "Seja esta casa lugar de oração,\nHabitação certa de Deus,\nPorta do céu e lugar de perdão,\nVida de paz dos céus!"}, {"label": "Estrofe 5", "text": "Glória a Deus, glória a Deus!\nCantem os filhos teus!\nGlória a Deus, glória a Deus!\nGlória nos altos céus! ( bis )"}], "reviewed": false}, {"number": 565, "title": "Separação", "page": 312, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Deus vos guarde pelo seu poder,\nProtegidos e velados,\nDesfrutando os seus cuidados,\nDeus vos guarde pelo seu poder!"}, {"label": "Estrofe 2", "text": "Deus vos guarde bem no seu amor,\nConsolados e contentes,\nAchegados sempre aos crentes,\nDeus vos guarde bem no seu amor!"}, {"label": "Estrofe 3", "text": "Deus vos guarde do poder do mal,\nDa ruína, do pecado,\nDo temor de todo lado,\nDeus vos guarde do poder do mal!"}, {"label": "Estrofe 4", "text": "Deus vos guarde para seu louvor,\nPara seu divino gozo,\nSeu serviço tão glorioso,\nDeus vos guarde para seu louvor!\nPelo seu poder e no seu amor,\nTé nos encontrarmos com Jesus!\nPelo seu poder e no seu amor,\nOh, que Deus vos guarde em sua luz! ( bis )"}], "reviewed": false}, {"number": 566, "title": "Saudação", "page": 313, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Saudamo-vos, irmãos em Cristo,\nLembrando do que temos visto;\nNesses anos pelas lutas, tentações,\nForam atendidas nossas petições.\nToda glória seja ao nome do Senhor;\nVinde a ele todos entoar louvor!"}, {"label": "Estrofe 2", "text": "Bem alto agora vamos nós cantar,\nQue terra e céus virão nos ajudar.\nAté aqui Deus mesmo nos guiou,\nE com a sua mão nos ajudou. ( bis )"}, {"label": "Estrofe 3", "text": "Um dia tão glorioso temos,\nE ao nosso Pai agradecemos;\nPois é ele quem nos dá real prazer\nE é fiel em nos guardar e proteger.\nVinde vós, irmãos, conosco a Deus cantar;\nDeste gozo vinde, pois, participar!"}, {"label": "Estrofe 4", "text": "Alegres hoje jubilemos,\nAo nosso Salvador cantemos;\nEle como filhos seus nos escolheu,\nRicas bênçãos ele já nos concedeu.\nSeja 'Avante!' O nosso lema triunfal,\nPois seguimos para o lar celestial!"}], "reviewed": false}, {"number": 567, "title": "União Vital", "page": 313, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Duas vidas, Senhor, se unem num só ser,\nDuas almas e dois nobres corações;\nPelo amor e afeição mútua assim viver\nQuerem, juntos na paz ou nas aflições."}, {"label": "Estrofe 2", "text": "Abençoa, Senhor, esta santa união,\nDando graça e favor; faze-a prosperar\nNa alegria, na fé, na consagração:\nQue ambos sempre só queiram contigo andar!"}, {"label": "Estrofe 3", "text": "Mais um lar que se faz cheio do vigor\nDo caráter cristão, base principal\nDuma vida feliz numa união de amor,\nQue abençoa e mantém a paz conjugal."}, {"label": "Estrofe 4", "text": "Preparaste, Senhor, para o gozo e paz\nDo teu povo que habita esta terra aqui,\nEssa união tão feliz, que amplas bênçãos traz.\nGratos, pois, entoamos louvor a ti!"}], "reviewed": false}, {"number": 568, "title": "Casamento", "page": 314, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Benigno Salvador, com tua aprovação,\nConsagra em doce amor teus servos nesta união;\nE sobre os noivos faz descer\nA graça que lhes é mister."}, {"label": "Estrofe 2", "text": "Em paz os faze andar, unidos no Senhor,\nE a vida aqui passar em terno e santo amor;\nLigados no temor de Deus,\nCaminhem juntos para os céus."}, {"label": "Estrofe 3", "text": "Oh, vem reger seu lar, em que serás o Rei!\nSeus corações mantém fiéis à tua lei;\nSocorre-os, pois, na tentação,\nConsola-os na tribulação."}], "reviewed": false}, {"number": 569, "title": "O Ministério Santo", "page": 314, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Senhor da ceifa, atende\nÀ nossa petição,\nQue o teu trabalho siga\nCom mais animação.\nOs campos já branquejam,\nConvidam a ceifar,\nE mui preciosos frutos\nNa igreja arrecadar."}, {"label": "Estrofe 2", "text": "Somente a ti compete\nCeifeiros escolher;\nQue façam o serviço\nConforme o teu querer.\nAs mentes, pois, prepara,\nInflama os corações\nE manda bons obreiros\nPregar às multidões."}, {"label": "Estrofe 3", "text": "Se aquele que nos veio\nPra trabalhar aqui\nNo ministério santo\nMandado foi por ti,\nConfirma seu trabalho\nCom bênçãos especiais\nE dá-lhe, em ricos frutos,\nDivinas credenciais."}, {"label": "Estrofe 4", "text": "Alenta-lhe a esperança,\nAumenta nele a fé;\nNa lida não permitas\nQue lhe vacile o pé.\nE, cada vez mais forte,\nMais cheio de fervor,\nA todos manifeste\nA graça do Senhor."}], "reviewed": false}, {"number": 570, "title": "Mais Um Obreiro", "page": 315, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Mais um obreiro escuta\nA tua voz, Jesus,\nE quer entrar na luta,\nSeguindo tua luz;\nTem força diminuta,\nMas, crendo em tua cruz,\nOs planos executa,\nQue teu amor produz!"}, {"label": "Estrofe 2", "text": "Senhor, desperta e chama\nCeifeiros mais e mais;\nPois tua vinha clama\nPor servos mui leais,\nQue levem tua fama\nDe amor, perdão e paz\nAo mundo que Deus ama\nCom graça e amor veraz!"}, {"label": "Estrofe 3", "text": "Ao servo teu dá graça\nE vida de poder;\nQue a tua obra faça,\nVisando o teu querer.\nProtege-o da desgraça\nDe sua fé perder;\nReveste-o da couraça\nDo teu real poder."}, {"label": "Estrofe 4", "text": "Concede-lhe justiça\nE um nobre coração;\nQue escape à vil cobiça\nEm toda ocasião;\nQue tenha fé submissa,\nContigo em comunhão,\nFiel na santa liça,\nVencendo a tentação."}], "reviewed": false}, {"number": 571, "title": "Morte do Crente", "page": 316, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Para o crente o morrer é cessar\nDo trabalho, cessar de gemer;\nÉ com Cristo Jesus repousar,\nSim, é principiar a viver."}, {"label": "Estrofe 2", "text": "Pra gozar com Jesus,\nÀ morada de Deus eu irei;\nVou viver com Jesus,\nE a coroa da vida terei."}, {"label": "Estrofe 3", "text": "O morrer é do mundo voar;\nO morrer é pra Cristo subir;\nO morrer é com Cristo habitar;\nO morrer é pra a glória partir."}, {"label": "Estrofe 4", "text": "É sentir uma dita sem-par,\nÉ ter parte na bênção dos céus,\nÉ prazeres celestes gozar,\nÉ chegar à morada de Deus."}], "reviewed": false}, {"number": 572, "title": "Dormir Em Cristo", "page": 316, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Dormir em Cristo é muito bom,\nJá livre de perturbação,\nFruindo, assim, ditoso dom:\nDo mundo ter libertação."}, {"label": "Estrofe 2", "text": "Dormindo em Cristo o nosso irmão,\nJá livre está de todo mal;\nNão sofre dor nem tentação,\nJá goza a vida perenal."}, {"label": "Estrofe 3", "text": "Dormindo em Cristo o nosso irmão,\nBem junto está do Salvador;\nJá goza a santa comunhão\nCom os remidos do Senhor."}, {"label": "Estrofe 4", "text": "Dormir em Cristo é estar em paz;\nO despertar, supremo bem,\nPois ele transportar-nos faz\nAo gozo divinal de além."}], "reviewed": false}, {"number": 573, "title": "Dormindo No Senhor", "page": 317, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Dormindo no Senhor,\nBendito é nosso irmão;\nPerante o trono, vencedor,\nDesfruta a salvação."}, {"label": "Estrofe 2", "text": "Dormindo no Senhor,\nLiberto já do mal,\nDeixando o mundo e seu labor,\nDescansa em paz real."}, {"label": "Estrofe 3", "text": "Dormindo no Senhor -\nOh, santa e calma paz! -\nO gozo do divino amor\nSua alma satisfaz."}, {"label": "Estrofe 4", "text": "Dormindo no Senhor -\nÉ doce assim morrer!\nDo crente a morte é sem terror,\nÉ ir com Deus viver."}, {"label": "Estrofe 5", "text": "Os mortos no Senhor\nHão de ressuscitar;\nOh, vem, bendito Salvador!\nTeus santos acordar!"}, {"label": "Estrofe 6", "text": "Os mortos viverão;\nE os vivos, com fulgor,\nAo teu encontro subirão.\nNão tardes, ó Senhor!"}], "reviewed": false}, {"number": 574, "title": "Pátria Brasileira", "page": 317, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Do meu país Brasil, ó terra varonil,\nÉ meu cantar.\nQue matas virginais, que rios sem rivais\nE lindos litorais tu tens sem par!"}, {"label": "Estrofe 2", "text": "Tu, minha Pátria, tens maravilhosos bens\nNo seio teu;\nTão belos laranjais e ricos cafezais,\nRiquezas naturais, orgulho meu!"}, {"label": "Estrofe 3", "text": "Sê livre, meu país, sê forte, sê feliz\nSob justas leis;\nAos filhos da nação concede proteção\nDo crime e da traição, ó Rei dos reis!"}, {"label": "Estrofe 4", "text": "E faze-a prosperar, e sempre caminhar\nNa tua luz;\nQue sempre com favor e com excelso amor\nTe cerque o bom Senhor e Rei, Jesus."}], "reviewed": false}, {"number": 575, "title": "Hino da Proclamação da República do Brasil", "page": 318, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Seja um pálio de luz desdobrado\nSob a larga amplidão destes céus\nEste canto rebel, que o passado\nVem remir dos mais torpes labéus!\nSeja um hino de glória que fale\nDe esperanças de um novo porvir!\nCom visões de triunfos embale\nQuem por ele lutando surgir."}, {"label": "Estrofe 2", "text": "Liberdade! Liberdade!\nAbre as asas sobre nós!\nDas lutas na tempestade\nDá que ouçamos tua voz!"}, {"label": "Estrofe 3", "text": "Nós nem cremos que escravos outrora\nTenha havido em tão nobre país...\nHoje, o rubro lampejo da aurora\nAcha irmãos, não tiranos hostis.\nSomos todos iguais! Ao futuro\nSaberemos, unidos, levar\nNosso augusto estandarte que, puro,\nBrilha, ovante, da Pátria no altar!"}, {"label": "Estrofe 4", "text": "Se é mister que de peitos valentes\nHaja sangue no nosso pendão,\nSangue vivo do herói Tiradentes\nBatizou este audaz pavilhão!\nMensageiro de paz, paz queremos,\nÉ de amor nossa força e poder,\nMas da guerra nos transes supremos\nHeis de ver-nos lutar e vencer!"}, {"label": "Estrofe 5", "text": "Do Ipiranga é preciso que o brado\nSeja um grito soberbo de fé!\nO Brasil já surgiu libertado,\nSobre as púrpuras régias de pé!\nEia, pois, brasileiros, avante!\nVerdes louros colhamos louçãos!\nSeja o nosso país, triunfante,\nLivre terra de livres irmãos!"}], "reviewed": false}, {"number": 576, "title": "Hino À Bandeira Nacional", "page": 319, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Salve, lindo pendão da esperança!\nSalve, símbolo augusto da paz!\nTua nobre presença à lembrança\nA grandeza da Pátria nos traz."}, {"label": "Estrofe 2", "text": "Em teu seio formoso retratas\nEste céu de puríssimo azul,\nA verdura sem-par destas matas,\nE o esplendor do Cruzeiro do Sul."}, {"label": "Estrofe 3", "text": "Contemplando teu vulto sagrado,\nCompreendemos o nosso dever,\nE o Brasil, por seus filhos amado,\nPoderoso e feliz há de ser."}, {"label": "Estrofe 4", "text": "Sobre a imensa nação brasileira,\nNos momentos de festa ou de dor,\nPaira sempre, sagrada bandeira,\nPavilhão da justiça e do amor!"}, {"label": "Estrofe 5", "text": "Recebe o afeto que se encerra\nEm nosso peito juvenil,\nQuerido símbolo da terra,\nDa amada terra do Brasil."}], "reviewed": false}, {"number": 577, "title": "Hino Nacional Brasileiro", "page": 319, "flags": ["Trecho longo: confira a divisão das estrofes", "Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ouviram do Ipiranga às margens plácidas\nDe um povo heróico o brado retumbante,\nE o sol da liberdade, em raios fúlgidos,\nBrilhou no céu da Pátria nesse instante.\nSe o penhor dessa igualdade\nConseguimos conquistar com braço forte,\nEm teu seio, ó liberdade,\nDesafia o nosso peito a própria morte!\nÓ Pátria amada, idolatrada, salve! salve!\nBrasil, um sonho intenso, um raio vívido\nDe amor e de esperança à terra desce,\nSe em teu formoso céu, risonho e límpido,\nA imagem do Cruzeiro resplandece."}, {"label": "Estrofe 2", "text": "Gigante pela própria natureza,\nÉs belo, és forte, impávido, colosso,\nE o teu futuro espelha essa grandeza.\nTerra adorada,\nEntre outras mil, és tu, Brasil, ó Pátria amada!\nDos filhos deste solo és mãe gentil,\nPátria amada, Brasil!"}, {"label": "Estrofe 3", "text": "Deitado eternamente em berço esplêndido,\nAo som do mar e à luz do céu profundo,\nFulguras, ó Brasil, florão da América,\nIluminado ao sol do Novo Mundo!\nDo que a terra mais garrida\nTeus risonhos, lindos campos têm mais flores;\n'Nossos bosques têm mais vida,\nNossa vida', no teu seio, 'mais amores'.\nÓ Pátria amada, idolatrada, salve! salve!"}, {"label": "Estrofe 4", "text": "Brasil, de amor eterno seja símbolo\nO lábaro que verde-louro desta flâmula:\n'Paz no futuro e glória no passado.'\nMas, se ergues da justiça a clava forte,\nVerás que um filho teu não foge à luta,\nNem teme, quem te adora, a própria morte.\nTerra adorada,\nEntre outras mil, és tu, Brasil, ó Pátria amada!\nDos filhos deste solo és mãe gentil,\nPátria amada, Brasil!"}], "reviewed": false}, {"number": 578, "title": "Sonda-me, Ó Deus", "page": 320, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Sonda-me, ó Deus, pois vês meu coração;\nProva-me, ó Pai, te peço em oração.\nDe todo mal liberta-me, Senhor,\nTambém da transgressão que oculta for."}, {"label": "Estrofe 2", "text": "Vem me limpar dos vis pecados meus,\nConforme prometeste, meu bom Deus.\nFaze-me arder e consumir de amor,\nPois quero te magnificar, Senhor."}, {"label": "Estrofe 3", "text": "Todo o meu ser, que já não chamo meu,\nQuero gastá-lo no serviço teu.\nMinhas paixões tu podes dominar:\nÓ santo Deus, vem sempre em mim estar!"}, {"label": "Estrofe 4", "text": "Lá do alto céu o avivamento vem,\nA começar em mim e indo além.\nO teu poder, as bênçãos, teu favor,\nConcede aos que são teus, ó Pai de amor."}], "reviewed": false}, {"number": 579, "title": "Olhando para Cristo", "page": 321, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Ruge forte, contundente, a guerra do pecado,\nMas os seus clangores vis não podem me afligir.\nSei em quem confio, pois na Rocha estou firmado,\nE celestes bênçãos irei fruir."}, {"label": "Estrofe 2", "text": "Olhando para Cristo, grande autor da salvação,\nProssigo, pois avisto soberano galardão.\nDe Deus ministro, me revisto do poder do meu Senhor\nPara servi-lo com todo ardor."}, {"label": "Estrofe 3", "text": "Vejo ao longe campos vastos, prontos pra colheita:\nMultidões, sem luz, sem Deus, aguardam salvação!\nVem, ó Deus, desperta o amor da geração eleita,\nPara os teus obreiros concede unção."}, {"label": "Estrofe 4", "text": "Desprezando deste mundo as sendas ardilosas,\nVolto o meu olhar pra a cruz de quem me resgatou;\nDele tenho na alma, então, as bênçãos mui gloriosas,\nE, feliz, com Cristo, cantando vou!"}], "reviewed": false}, {"number": 580, "title": "Vem, Visita Tua Igreja", "page": 321, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Vem! Visita a tua igreja,\nÓ bendito Salvador!\nSem tua graça ela murcha\nFicará e sem vigor.\nVivifica, vivifica (bis)\nNossas almas, ó Senhor!"}], "reviewed": false}, {"number": 581, "title": "A Única Esperança", "page": 321, "flags": ["Divisões e coro inferidos: conferir com o PDF"], "sections": [{"label": "Estrofe 1", "text": "Do Amapá ao Rio Grande,\nDo Recife a Cuiabá,\nGrita a angústia que se expande:\nA verdade onde estará?\nEm São Paulo, no Acre ou Minas,\nEm Brasília ou Salvador,\nProclamemos as divinas\nBoas-novas do Senhor!"}, {"label": "Estrofe 2", "text": "Cristo é a única esperança\nNeste mundo tão hostil,\nPara a santa liderança\nDo Evangelho no Brasil!"}, {"label": "Estrofe 3", "text": "Nossa Pátria amada e imensa,\nNosso povo humilde e bom,\nTem por meta a recompensa\nDo celeste e eterno dom;\nDo Oriente ao Ocidente\nE do Norte so Sul, feliz,\nCada qual se torne um crente\nPara a bênção do país."}, {"label": "Estrofe 4", "text": "Na campanha brasileira\nPara evangelização\nSeja a fé nossa bandeira,\nNossa espada, a salvação;\nE por lema da porfia\nQue garante o céu, além:\n'Trabalhar enquanto é dia,\nPois a noite perto vem!'"}], "reviewed": false}]}};